    internal sealed partial class Companion
    {
        // Smoke checks call the handlers themselves. Input arriving while they pump messages belongs to whoever is using the PC.
        private sealed class SmokeInput : IMessageFilter
        {
            public bool PreFilterMessage(ref Message message)
            {
                return (message.Msg >= 0x0100 && message.Msg <= 0x0109) || (message.Msg >= 0x0200 && message.Msg <= 0x020E)
                    || (message.Msg >= 0x00A0 && message.Msg <= 0x00AD) || message.Msg == 0x0312;
            }
        }

        // A made-up game that hides the real cursor and only looks at where it is when mouse movement comes in, like Cyberpunk 2077.
        private static void SmokeSteering(System.Collections.Generic.List<string> checks)
        {
            Action<int, int> nudgeWas = Computer.Nudge;
            Action<Point> putWas = Computer.PutCursor;
            Func<Point> cursorWas = Computer.CursorAt;
            Func<bool> hiddenWas = Computer.CursorHidden;
            Func<Point, bool> gameUnderWas = Computer.GameUnder;
            Func<bool> escapeWas = Computer.Escape;
            Action haltedWas = Computer.Halted;
            Action<int, int> mouseWas = Computer.SendMouse;
            Action<Point> tappedWas = Computer.Tapped, trackedWas = Computer.Track;
            Action<bool> lendingWas = Computer.Lending;
            Point real = new Point(50, 50), game = new Point(700, 500);
            int moves = 0;
            try
            {
                Computer.Escape = delegate { return false; };
                Computer.Halted = delegate { };
                Computer.Tapped = delegate { };
                Computer.Track = delegate { };
                Computer.Lending = delegate { };
                Computer.Arm();
                Computer.Nudge = delegate(int dx, int dy) { moves++; game = real; real.Offset(dx, dy); };
                Computer.PutCursor = delegate(Point to) { real = to; };
                Computer.CursorAt = delegate { return real; };
                Computer.CursorHidden = delegate { return true; };
                Point goal = new Point(1300, 750);
                Computer.Borrow(goal);
                if (Math.Abs(game.X - goal.X) > 2 || game.Y != goal.Y) throw new Exception("Her click didn't reach a game's own cursor: it stayed at " + game + ".");
                if (real != goal) throw new Exception("Rocking the cursor left it " + (real.X - goal.X) + " away.");
                Computer.GiveBack();
                if (real != new Point(50, 50)) throw new Exception("Steering a game's cursor didn't hand the real one back.");
                moves = 0;
                Computer.CursorHidden = delegate { return false; };
                Computer.GameUnder = delegate { return false; };
                Computer.Borrow(new Point(300, 300));
                Computer.GiveBack();
                if (moves != 0) throw new Exception("She rocked the mouse with the real cursor showing.");
                // Like Roblox: the real cursor shows, but the game only goes by real movement.
                Point roblox = new Point(900, 400);
                Computer.GameUnder = delegate(Point at) { return at == roblox; };
                Computer.Borrow(roblox);
                if (moves == 0 || Math.Abs(game.X - roblox.X) > 2 || game.Y != roblox.Y || real != roblox) throw new Exception("Her click didn't reach a game that shows the real cursor but goes by real movement, like Roblox: it saw " + game + ".");
                Computer.GiveBack();
                checks.Add("PASS her clicks reach a game that draws its own cursor or only goes by real movement, like Roblox, and leave the real cursor where it was");
                int stoppedPresses = 0;
                Computer.SendMouse = delegate(int flags, int amount) { if ((flags & 0x002A) != 0) stoppedPresses++; };
                Computer.CursorHidden = delegate { return true; };
                Computer.Nudge = delegate { Computer.Interrupt(Computer.Escaped); };
                Computer.Arm();
                string stoppedClick = Computer.Member("left_click", new ToolArguments(), null);
                if (stoppedClick != Computer.Escaped || stoppedPresses != 0 || real != new Point(50, 50)) throw new Exception("Esc during steering still sent a click or kept the cursor.");
                Computer.Arm();
                Computer.Click(new Point(90, 90), "double");
                if (!Computer.Interrupted || stoppedPresses != 0 || real != new Point(50, 50)) throw new Exception("The plain click path ignored Esc during steering.");
                checks.Add("PASS Esc during cursor steering cancels member and plain clicks and returns the borrowed cursor");
                Computer.Finish();
                Job cursorClicks = new Job("synthetic clicks");
                if (cursorClicks.Again("left_click", new ToolArguments()) != "" || cursorClicks.Again("left_click", new ToolArguments()) != "" || !cursorClicks.Again("left_click", new ToolArguments()).Contains("3 times")) throw new Exception("Coordinate-free clicks were not counted at her pointer.");
                real = new Point(500, 500);
                if (cursorClicks.Again("left_click", new ToolArguments()) != "") throw new Exception("Moving her pointer kept the old click run.");
                checks.Add("PASS repeated left clicks without coordinates count at her cursor and reset when it moves");
            }
            finally
            {
                Computer.Finish();
                Computer.Arm();
                Computer.Escape = escapeWas;
                Computer.Halted = haltedWas;
                Computer.SendMouse = mouseWas;
                Computer.Tapped = tappedWas;
                Computer.Track = trackedWas;
                Computer.Lending = lendingWas;
                Computer.Nudge = nudgeWas;
                Computer.PutCursor = putWas;
                Computer.CursorAt = cursorWas;
                Computer.CursorHidden = hiddenWas;
                Computer.GameUnder = gameUnderWas;
            }
        }

        // #106: her sign is up whenever anything of hers has their mouse or keys, on the screen she's working on, even while
        // she's hidden, with the line on it, out of her own screenshots, through overlapping uses, and gone once the last one
        // lets go. Every press here is faked, so nothing reaches the real desktop.
        private void SmokeControlSign(System.Collections.Generic.List<string> checks)
        {
            Action<int, int> mouseWas = Computer.SendMouse, nudgeWas = Computer.Nudge;
            Action<short, bool, bool> keyWas = Computer.SendKey;
            Action<Point> putWas = Computer.PutCursor, tappedWas = Computer.Tapped, trackWas = Computer.Track;
            Func<Point> cursorWas = Computer.CursorAt;
            Func<bool> cursorHiddenWas = Computer.CursorHidden, escapeWas = Computer.Escape;
            Func<Point, bool> gameUnderWas = Computer.GameUnder;
            Action haltedWas = Computer.Halted;
            Action<bool> lendingWas = Computer.Lending;
            Func<Rectangle, byte[]> grayWas = Computer.GrayFrame;
            Func<Rectangle?, Picture> shootWas = Computer.Shoot;
            Func<Sight> glimpseWas = Computer.Glimpse, lookWas = Computer.Look;
            Func<Target> focusWas = Computer.Focus;
            Func<Point, Target> underWas = Computer.Under;
            Func<string, ToolArguments, Picture, string> useWas = Computer.Use;
            Func<IntPtr> frontWas = Computer.Front;
            Func<string> gameWas = Computer.GameOpen;
            Func<System.Collections.Generic.List<Tune>> mediaWas = Computer.ExploreMedia;
            bool flinchedWas = Computer.Flinched;
            Action<byte, byte, int> keyEventWas = Hands.KeyEvent;
            Func<Rectangle> workingWas = ControlGlow.Working;
            int lingerWas = InControl.Linger;
            bool hiddenWas = hidden, manualWas = manualHidden, exploringWas = exploring, clonesWere = cloneWindow != null;
            System.Reflection.FieldInfo excludedField = typeof(ControlGlow).GetField("excluded", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            bool excludedWas = controlGlow.Excluded;
            // Lets her window run what other threads sent it until done says so, for at most ms.
            Func<Func<bool>, int, bool> until = delegate(Func<bool> done, int ms)
            {
                Stopwatch waited = Stopwatch.StartNew();
                while (!done())
                {
                    if (waited.ElapsedMilliseconds > ms) return false;
                    Application.DoEvents();
                    Thread.Sleep(5);
                }
                return true;
            };
            Func<bool> never = delegate { return false; };
            Func<bool> up = delegate { return InControl.On && controlGlow.Visible; };
            Func<bool> down = delegate { return !InControl.On && !controlGlow.Visible && InControl.Holds == 0; };
            Point real = new Point(40, 40);
            int sent = 0, blind = 0, most = 0;
            bool escNow = false;
            // Each faked press counts, and one that went out with the sign down counts against it.
            Action saw = delegate
            {
                Interlocked.Increment(ref sent);
                if (!InControl.On || !controlGlow.Visible) Interlocked.Increment(ref blind);
                most = Math.Max(most, InControl.Holds);
            };
            Action reset = delegate { sent = 0; blind = 0; most = 0; };
            try
            {
                Computer.Escape = delegate { return escNow; };
                Computer.Halted = delegate { };
                Computer.Tapped = delegate { };
                Computer.Track = delegate { };
                Computer.Lending = delegate { };
                Computer.CursorAt = delegate { return real; };
                Computer.PutCursor = delegate(Point to) { real = to; };
                Computer.CursorHidden = delegate { return false; };
                Computer.GameUnder = delegate { return false; };
                Computer.SendMouse = delegate(int flags, int data) { saw(); };
                Computer.SendKey = delegate(short code, bool released, bool extended) { saw(); };
                Computer.Nudge = delegate(int dx, int dy) { saw(); real.Offset(dx, dy); };
                Computer.GrayFrame = delegate(Rectangle area) { return new byte[Computer.GrayWidth * Computer.GrayHeight]; };
                Hands.KeyEvent = delegate(byte key, byte scan, int flags) { saw(); };
                Computer.Finish();
                Computer.Arm();
                InControl.Linger = 120;
                if (!until(down, 2000)) throw new Exception("Her sign was up before anything of hers held their mouse: " + InControl.Holds + " holds, shown " + controlGlow.Visible + ".");

                // The sign itself: up at once on her window's thread, on the screen her keys go to, the size of that screen.
                InControl.Begin();
                Rectangle keysScreen = Computer.Display();
                Bitmap drawn = controlGlow.Image;
                if (!up() || controlGlow.Area != keysScreen || controlGlow.Bounds != keysScreen || drawn == null || drawn.Size != keysScreen.Size)
                    throw new Exception("Her sign didn't come up round the screen her keys go to: shown " + controlGlow.Visible + " at " + controlGlow.Area + " for " + keysScreen + ".");
                int style = Native.GetWindowLong(controlGlow.Handle, -20);
                bool through = (style & 0x20) != 0 && (style & 0x80000) != 0 && (style & 0x80) != 0 && (style & 0x08000000) != 0 && (style & 0x8) != 0;
                Point rimAt = new Point(controlGlow.Area.Left + 1, controlGlow.Area.Top + controlGlow.Area.Height / 2);
                bool passes = Native.GetAncestor(Native.WindowFromPoint(new Native.Point(rimAt.X, rimAt.Y)), 2) != controlGlow.Handle;
                bool unfocused = Native.GetForegroundWindow() != controlGlow.Handle && !controlGlow.ContainsFocus && Form.ActiveForm != controlGlow;
                if (!through || !passes || !unfocused) throw new Exception("Her sign could take a click or the focus: styles " + style.ToString("X") + ", click goes through " + passes + ", unfocused " + unfocused + ".");
                // A pink edge with a cyan line just inside it, and nothing over the middle of the screen.
                int pinkAt = -1, cyanAt = -1;
                for (int x = 0; x < Math.Min(24, drawn.Width); x++)
                {
                    Color pixel = drawn.GetPixel(x, drawn.Height / 2);
                    if (pinkAt < 0 && pixel.A >= 200 && pixel.R > 200 && pixel.G < 120 && pixel.B > 80) pinkAt = x;
                    if (pinkAt >= 0 && cyanAt < 0 && pixel.A >= 180 && pixel.R < 150 && pixel.G > 150 && pixel.B > 180) cyanAt = x;
                }
                if (pinkAt != 0 || cyanAt <= 0 || drawn.GetPixel(drawn.Width / 2, drawn.Height / 2).A != 0) throw new Exception("Her sign's edge isn't pink with a cyan line inside it, or it covers the middle of the screen: pink at " + pinkAt + ", cyan at " + cyanAt + ".");
                // The line, read back off the badge at the bottom by Windows' own OCR.
                float dpi;
                using (Graphics screen = Graphics.FromHwnd(IntPtr.Zero)) dpi = Math.Max(1f, screen.DpiX / 96f);
                Rectangle work = Screen.FromRectangle(controlGlow.Area).WorkingArea;
                work.Offset(-controlGlow.Area.X, -controlGlow.Area.Y);
                int bandWide = Math.Min(work.Width, (int)Math.Ceiling(640 * dpi)), bandTall = Math.Min(work.Bottom, (int)Math.Ceiling(56 * dpi));
                Rectangle band = new Rectangle(work.Left + (work.Width - bandWide) / 2, work.Bottom - bandTall, bandWide, bandTall);
                string read = "";
                int ink = 0;
                using (Bitmap strip = new Bitmap(band.Width, band.Height, PixelFormat.Format24bppRgb))
                {
                    using (Graphics paint = Graphics.FromImage(strip))
                    {
                        paint.Clear(Color.Black);
                        paint.DrawImage(drawn, new Rectangle(Point.Empty, band.Size), band, GraphicsUnit.Pixel);
                    }
                    for (int y = 0; y < strip.Height; y++)
                        for (int x = 0; x < strip.Width; x++)
                        {
                            Color pixel = strip.GetPixel(x, y);
                            if (pixel.R > 200 && pixel.G < 110 && pixel.B > 90) ink++;
                        }
                    System.Threading.Tasks.Task<System.Collections.Generic.List<string>> reading = System.Threading.Tasks.Task.Run(new Func<System.Collections.Generic.List<string>>(delegate { return Ocr.Lines(strip, 3, 8000); }));
                    until(delegate { return reading.IsCompleted; }, 9000);
                    if (reading.IsCompleted && !reading.IsFaulted && reading.Result != null) read = string.Join(" ", reading.Result.ToArray());
                }
                string plain = Regex.Replace(read.ToLowerInvariant(), "[^a-z]+", " ");
                if (ink < 20) throw new Exception("Her sign has no badge with pink writing above the bottom of the screen.");
                // OCR can miss a letter of her small mono font (it read "•ouse" once), so most of the line's words will do.
                string[] lineWords = { "capri", "using", "your", "mouse", "esc", "stops", "her" };
                int wordsRead = 0;
                foreach (string word in lineWords) if (Regex.IsMatch(plain, @"\b" + word + @"\b")) wordsRead++;
                bool readBack = wordsRead >= lineWords.Length - 2;
                if (read.Trim().Length > 0 && !readBack) throw new Exception("Her sign's badge doesn't say the line: OCR read \"" + read + "\".");
                if (InControl.Line != "Capri's using your mouse. Esc stops her.") throw new Exception("Her sign's line changed: " + InControl.Line);
                if (!readBack) checks.Add("LIMIT her sign's line: Windows' OCR couldn't read here, so only the badge's pink writing was checked");

                // While she's hidden it still comes up.
                InControl.End();
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after she let go of their keys.");
                manualHidden = hidden = true;
                InControl.Begin();
                bool hiddenUp = up();
                InControl.End();
                manualHidden = manualWas;
                hidden = hiddenWas;
                if (!hiddenUp) throw new Exception("Her sign didn't come up while she was hidden.");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after a hold while she was hidden.");

                // The screen she put their mouse on, and the next one when she moves it there.
                Screen[] screens = Screen.AllScreens;
                Rectangle firstScreen = screens[0].Bounds, lastScreen = screens[screens.Length - 1].Bounds;
                Point onFirst = new Point(firstScreen.Left + 12, firstScreen.Top + 12), onLast = new Point(lastScreen.Right - 12, lastScreen.Bottom - 12);
                InControl.Begin(onFirst);
                bool firstRight = up() && controlGlow.Area == firstScreen && InControl.At == onFirst;
                InControl.Near(onLast);
                bool followed = up() && controlGlow.Area == lastScreen && InControl.At == onLast;
                InControl.End();
                if (!firstRight || !followed) throw new Exception("Her sign wasn't on the screen she put their mouse on: " + controlGlow.Area + " for " + firstScreen + " then " + lastScreen + ".");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after she moved their mouse.");
                // And it follows the screen she's working on by itself while it's up.
                Rectangle fakeA = new Rectangle(firstScreen.X + 40, firstScreen.Y + 30, 800, 600), fakeB = new Rectangle(firstScreen.X + 120, firstScreen.Y + 90, 640, 480), wanted = fakeA;
                ControlGlow.Working = delegate { return wanted; };
                InControl.Begin();
                bool onA = up() && controlGlow.Area == fakeA;
                wanted = fakeB;
                bool onB = until(delegate { return controlGlow.Area == fakeB; }, 1500) && up();
                InControl.End();
                ControlGlow.Working = workingWas;
                if (!onA || !onB) throw new Exception("Her sign didn't follow her to another screen while it was up: " + controlGlow.Area + ".");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after following her.");
                checks.Add("PASS her sign comes up round the screen she's working on, the one with their mouse or the window her keys go to, follows her to another screen, has \"" + InControl.Line + "\" on a badge above the bottom" + (readBack ? " (read back by OCR)" : "") + ", a pink edge with a cyan line inside it, lets clicks through, never takes the focus, and shows while she's hidden" + (screens.Length > 1 ? ", across " + screens.Length + " screens" : ""));
                if (screens.Length == 1) checks.Add("LIMIT her sign on a second screen: this PC has one, so only a made-up second screen was checked");

                // Out of her own screenshots: Windows keeps it out of them, and where it can't, it hides for the moment she takes one.
                InControl.Begin();
                bool kept = controlGlow.Excluded && controlGlow.Affinity == 0x11;
                excludedField.SetValue(controlGlow, false);
                PanelUnseen(true);
                bool hidFor = !controlGlow.Visible && InControl.On;
                controlGlow.Sync();
                bool stayedHid = !controlGlow.Visible;
                PanelUnseen(false);
                bool cameBack = up();
                excludedField.SetValue(controlGlow, excludedWas);
                InControl.End();
                if (!hidFor || !stayedHid || !cameBack) throw new Exception("Where Windows can't keep her sign out of screenshots, it didn't hide for her own and come back: hid " + hidFor + ", stayed hidden " + stayedHid + ", back " + cameBack + ".");
                if (excludedWas && !kept) throw new Exception("Windows was told to keep her sign out of screenshots but reports affinity " + controlGlow.Affinity + ".");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after the screenshot check.");
                checks.Add(kept ? "PASS her sign stays out of screenshots: Windows keeps it out of every capture (display affinity 0x11), and on Windows that can't, it hides for the moment she takes her own and comes back after"
                    : "PASS her sign hides for the moment she takes her own screenshot and comes back after, where Windows can't keep it out of captures");
                if (!kept) checks.Add("LIMIT her sign and captures: Windows wouldn't keep it out of captures here (affinity " + controlGlow.Affinity + "), so her own screenshots hide it instead");

                // Overlapping uses keep it up until the last lets go, a quick press in its last moment keeps it up with no gap, and
                // it goes a moment after.
                InControl.Linger = 300;
                InControl.Begin();
                InControl.Begin();
                IDisposable once = InControl.Hold();
                once.Dispose();
                once.Dispose();
                InControl.End();
                bool keptByOther = up() && InControl.Holds == 1;
                until(never, 450);
                bool stillUp = up();
                InControl.End();
                bool lingered = up() && InControl.Holds == 0;
                until(never, 180);
                using (InControl.Hold()) { }
                bool noGap = up();
                until(never, 200);
                bool pushedBack = up();
                bool gone = until(down, 1500);
                bool forgot = controlGlow.Image == null;
                InControl.End();
                InControl.End();
                bool unbroken = InControl.Holds == 0 && !InControl.On;
                if (!keptByOther || !stillUp || !lingered || !noGap || !pushedBack || !gone || !forgot || !unbroken)
                    throw new Exception("Her sign didn't keep up through overlapping uses and go after: kept by the other " + keptByOther + ", still up " + stillUp + ", lingered " + lingered + ", no gap " + noGap + ", pushed back " + pushedBack + ", gone " + gone + ", picture let go " + forgot + ", extra lets-go ignored " + unbroken + ".");
                checks.Add("PASS her sign stays up while uses overlap and through a quick press in its last moment, goes a moment after the last one lets go and lets go of its picture, and a hold let go twice only counts once");
                InControl.Linger = 120;

                // A job: up while she thinks, for every press, key and scroll, and for buttons and keys she holds down until she lets go.
                reset();
                string clicked = Computer.Member("left_click", new ToolArguments(), null);
                bool clickRight = controlGlow.Area == Screen.FromPoint(real).Bounds;
                if (clicked != "Clicked." || sent != 2 || blind != 0 || InControl.Holds != 0 || !clickRight) throw new Exception("A job's click went out without her sign, or left it held: " + clicked + ", " + sent + " sent, " + blind + " with no sign, " + InControl.Holds + " holds.");
                reset();
                string keyed = Computer.Member("key", new ToolArguments { Text = "ctrl+a" }, null);
                if (sent != 4 || blind != 0 || most < 2 || InControl.Holds != 0) throw new Exception("A job's keys went out without her sign, or a held key didn't hold it: " + keyed + ", " + sent + " sent, " + blind + " with no sign, " + most + " holds at most.");
                reset();
                string scrolled = Computer.Member("scroll", new ToolArguments { Way = "down", Amount = 2 }, null);
                if (sent != 2 || blind != 0 || InControl.Holds != 0) throw new Exception("A job's scroll went out without her sign: " + scrolled + ", " + sent + " sent, " + blind + " with no sign.");
                reset();
                Computer.Member("left_mouse_down", new ToolArguments(), null);
                bool heldDown = up() && InControl.Holds >= 2;
                until(never, 300);
                bool heldOn = up();
                Computer.Member("left_mouse_up", new ToolArguments(), null);
                if (!heldDown || !heldOn || sent != 2 || blind != 0 || InControl.Holds != 0) throw new Exception("A held mouse button didn't keep her sign up until she let go: held " + heldDown + ", kept " + heldOn + ", " + InControl.Holds + " holds after.");
                reset();
                Computer.Member("hold_key", new ToolArguments { Text = "shift", Duration = 0.3 }, null);
                if (sent != 2 || blind != 0 || most < 2 || InControl.Holds != 0) throw new Exception("A held key didn't keep her sign up: " + sent + " sent, " + blind + " with no sign, " + most + " holds at most.");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after a job's presses.");
                // Games: walking, holding a button, rocking a game's own cursor and turning the camera.
                Sight game = new Sight { Program = "capri-sign-check", Bounds = new Rectangle(firstScreen.X, firstScreen.Y, 1280, 720) };
                reset();
                Computer.Walk("w", "0.2", "no", game);
                Computer.MouseHold("right", "0.2", null, "no", game);
                int gameHolds = sent;
                Computer.CursorHidden = delegate { return true; };
                Computer.Borrow(new Point(firstScreen.X + 300, firstScreen.Y + 300));
                Computer.GiveBack();
                Computer.CursorHidden = delegate { return false; };
                int rocked = sent - gameHolds;
                Computer.TurnView(new ToolArguments { Right = 30 }, game);
                int turned = sent - gameHolds - rocked;
                if (gameHolds < 4 || rocked < 4 || turned < 1 || blind != 0 || InControl.Holds != 0) throw new Exception("A game's input went out without her sign: " + gameHolds + " walk and hold presses, " + rocked + " rocks, " + turned + " turns, " + blind + " with no sign, " + InControl.Holds + " holds after.");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after a game's input.");
                // A whole job on her worker thread, thinking included, with a real click through her hands.
                Computer.Shoot = delegate { return new Picture { Jpeg = new byte[] { 1, 2, 3 }, Size = new Size(1280, 720), Area = new Rectangle(firstScreen.X, firstScreen.Y, 1280, 720) }; };
                Computer.Glimpse = Computer.Look = delegate { return new Sight { Window = new IntPtr(9), Title = "Notepad", Program = "notepad", Bounds = new Rectangle(firstScreen.X, firstScreen.Y, 1280, 720) }; };
                Computer.Focus = delegate { return null; };
                Computer.Under = delegate { return null; };
                Computer.Front = delegate { return new IntPtr(9); };
                Computer.GameOpen = delegate { return null; };
                Computer.Use = delegate(string name, ToolArguments args, Picture picture) { return Computer.Member(name, args, picture); };
                bool firstUp = false;
                Thread riser = new Thread(delegate() { InControl.Begin(); firstUp = controlGlow.Visible; InControl.End(); }) { IsBackground = true };
                riser.Start();
                until(delegate { return !riser.IsAlive; }, 3000);
                if (!firstUp) throw new Exception("Her sign wasn't up yet when a hold from another thread started.");
                reset();
                int turns = 0;
                bool thoughtUnder = true;
                string ended = null;
                Exception jobError = null;
                Job clicking = new Job("click the corner");
                clicking.Drive = delegate(string system, string tools, string messages)
                {
                    thoughtUnder &= InControl.On && controlGlow.Visible;
                    if (++turns > 1) return Brain.Parsed("{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"Clicked the corner.\"}]}");
                    return Brain.Parsed("{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"c1\",\"name\":\"left_click\",\"toolset_name\":\"computer\",\"input\":{\"coordinate\":[5,5]}}]}");
                };
                Thread worker = new Thread(delegate() { try { ended = clicking.Run(); } catch (Exception problem) { jobError = problem; } }) { IsBackground = true };
                worker.Start();
                if (!until(delegate { return !worker.IsAlive; }, 20000)) throw new Exception("A faked job didn't finish.");
                if (jobError != null) throw new Exception("A faked job failed: " + jobError.Message);
                if (ended != "Clicked the corner." || turns != 2 || !thoughtUnder || sent != 2 || blind != 0 || InControl.Holds != 0) throw new Exception("A job on her worker didn't keep her sign up while it thought and clicked: " + ended + ", " + turns + " turns, thinking under it " + thoughtUnder + ", " + sent + " sent, " + blind + " with no sign, " + InControl.Holds + " holds after.");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after a job.");
                // Esc mid-click stops her, and the sign goes with her.
                reset();
                Computer.SendMouse = delegate(int flags, int data) { saw(); if ((flags & 0x2A) != 0) escNow = true; };
                string escaped = Computer.Member("left_click", new ToolArguments(), null);
                escNow = false;
                Thread.Sleep(70);
                Computer.Finish();
                Computer.Arm();
                Computer.SendMouse = delegate(int flags, int data) { saw(); };
                if (escaped != Computer.Escaped || blind != 0 || InControl.Holds != 0 || !until(down, 1500)) throw new Exception("Esc mid-click didn't stop her and take her sign down: " + escaped + ", " + InControl.Holds + " holds, shown " + controlGlow.Visible + ".");
                checks.Add("PASS her sign is up through a whole job on any thread, while she thinks and for every click, key and scroll, for buttons and keys she holds down until she lets go, for a game's walks, holds, cursor rocks and camera turns, and Esc mid-click stops her and takes it down");

                // Her quick shortcuts and Discord keys, media keys and closing a tab.
                reset();
                Hands.Chord(new byte[] { 0x11, 0x10, 0x4D });
                Hands.Press(0xB3);
                int quick = sent;
                bool tabFronted;
                using (Form tabs = new Form())
                {
                    tabs.Text = "Capri sign check";
                    tabs.StartPosition = FormStartPosition.Manual;
                    tabs.ShowInTaskbar = false;
                    tabs.Bounds = new Rectangle(screens[0].WorkingArea.Left + 40, screens[0].WorkingArea.Top + 40, 320, 200);
                    tabs.Show();
                    Application.DoEvents();
                    tabFronted = Hands.Steer(new OpenWindow(tabs.Handle, tabs.Text, "capri"), "close_tab");
                }
                if (quick != 8 || (tabFronted && sent != 12) || blind != 0 || InControl.Holds != 0) throw new Exception("Her shortcuts, media keys or tab closing went out without her sign: " + quick + " shortcut and media presses, " + (sent - quick) + " tab presses, " + blind + " with no sign.");
                if (!until(down, 1500)) throw new Exception("Her sign stayed up after her shortcuts.");
                checks.Add("PASS her sign is up for her quick shortcuts, Discord keys and media keys" + (tabFronted ? ", and for closing a tab" : ""));
                if (!tabFronted) checks.Add("LIMIT her sign for closing a tab: a test window couldn't come to the front here, so its Ctrl+W wasn't sent");

                // Exploring while they're away: each scroll, and the whole time she's at it until she stops.
                reset();
                Computer.ExploreMedia = delegate { return new System.Collections.Generic.List<Tune>(); };
                Sight page = new Sight { Window = new IntPtr(7), Program = "chrome", Title = "Geography - Wikipedia", Bounds = new Rectangle(0, 0, 800, 600) };
                Point readAt = new Point(200, 200);
                bool scrolledAway = Computer.ScrollAway(page, page.Bounds, page, readAt, readAt, page.Window, false, delegate { return true; });
                if (!scrolledAway || sent != 1 || blind != 0 || InControl.Holds != 0) throw new Exception("Her scroll while exploring went out without her sign: scrolled " + scrolledAway + ", " + sent + " sent, " + blind + " with no sign.");
                exploring = true;
                ExploreHold(true);
                bool exploreUp = up() && InControl.Holds == 1;
                until(never, 300);
                bool exploreKept = up();
                StopExplore();
                bool exploreLet = InControl.Holds == 0 && !exploreHeld;
                if (!exploreUp || !exploreKept || !exploreLet || !until(down, 1500)) throw new Exception("Her sign wasn't up the whole time she explored, or stayed after: up " + exploreUp + ", kept " + exploreKept + ", let go " + exploreLet + ".");
                checks.Add("PASS her sign is up the whole time she explores while they're away and for each scroll she sends, and goes once she stops");

                // A clone with their cursor.
                Clone("spawn", 1);
                CloneWindow clones = cloneWindow;
                if (clones == null) throw new Exception("No clone came out for the cursor check.");
                Point grabbed = new Point(firstScreen.X + 220, firstScreen.Y + 180), dragged = new Point(lastScreen.Right - 220, lastScreen.Bottom - 180);
                clones.PutCursor = delegate(Point to) { real = to; };
                clones.Nab(grabbed);
                bool nabUp = up() && clones.Nabbing && real == grabbed && InControl.At == grabbed && controlGlow.Area == firstScreen;
                clones.Nab(dragged);
                bool nabFollowed = real == dragged && InControl.At == dragged && controlGlow.Area == lastScreen && InControl.Holds == 1;
                clones.Nab(null);
                bool nabLet = InControl.Holds == 0 && !clones.Nabbing;
                clones.Nab(grabbed);
                ClonesOff();
                bool nabOff = InControl.Holds == 0;
                if (!nabUp || !nabFollowed || !nabLet || !nabOff || !until(down, 1500)) throw new Exception("Her sign wasn't up while a clone had their cursor, or stayed after: up " + nabUp + ", followed " + nabFollowed + ", let go " + nabLet + ", put away " + nabOff + ".");
                checks.Add("PASS her sign is up while a clone has their cursor, follows it where it's dragged, and goes when the clone lets go or they're put away");
            }
            finally
            {
                escNow = false;
                Computer.Finish();
                Computer.SendMouse = mouseWas;
                Computer.SendKey = keyWas;
                Computer.Nudge = nudgeWas;
                Computer.PutCursor = putWas;
                Computer.Tapped = tappedWas;
                Computer.Track = trackWas;
                Computer.CursorAt = cursorWas;
                Computer.CursorHidden = cursorHiddenWas;
                Computer.GameUnder = gameUnderWas;
                Computer.Halted = haltedWas;
                Computer.Lending = lendingWas;
                Computer.GrayFrame = grayWas;
                Computer.Shoot = shootWas;
                Computer.Glimpse = glimpseWas;
                Computer.Look = lookWas;
                Computer.Focus = focusWas;
                Computer.Under = underWas;
                Computer.Use = useWas;
                Computer.Front = frontWas;
                Computer.GameOpen = gameWas;
                Computer.ExploreMedia = mediaWas;
                Computer.Flinched = flinchedWas;
                Computer.Arm();
                Computer.Escape = escapeWas;
                Hands.KeyEvent = keyEventWas;
                ControlGlow.Working = workingWas;
                excludedField.SetValue(controlGlow, excludedWas);
                manualHidden = manualWas;
                hidden = hiddenWas;
                if (exploring && !exploringWas) StopExplore();
                if (cloneWindow != null && !clonesWere) ClonesOff();
                // Whatever a failed check left held lets go, so her sign isn't up for the sections after.
                while (InControl.Holds > 0) InControl.End();
                until(down, 1500);
                InControl.Linger = lingerWas;
                controlGlow.Sync();
            }
        }

        private static void SmokeJobProblems(System.Collections.Generic.List<string> checks)
        {
            Action<string> runWas = Hands.Run;
            try
            {
                foreach (Exception error in new Exception[] { new Exception(""), new BrainException(""), new WebException(""), new IOException(" \r\n\t"), new UnauthorizedAccessException("") })
                {
                    string expected = "That didn't work: no error details came back.";
                    Hands.Run = delegate { throw error; };
                    string result = Hands.Do("open_website", new ToolArguments { Site = "https://example.invalid" });
                    if (result != expected || Hands.Problem(error) != expected || !Hands.Failed(result) || !Computer.Failed(result)) throw new Exception("An empty tool error lost its failure or showed no explanation.");
                }
                Hands.Run = delegate { throw new IOException("catalog offline"); };
                if (Hands.Do("open_website", new ToolArguments { Site = "https://example.invalid" }) != "That didn't work: catalog offline") throw new Exception("A tool error lost the reason it supplied.");
                checks.Add("PASS tool and job errors keep their supplied reason, explain missing details and still count as failures");
            }
            finally { Hands.Run = runWas; }
        }

        private static void SmokeSetupFiles(System.Collections.Generic.List<string> checks, string output)
        {
            if (SetupFiles.Mode(new string[0]) != 0 || SetupFiles.Mode(new[] { "--uninstall" }) != 0 || SetupFiles.Mode(new[] { "--silent" }) != 1 || SetupFiles.Mode(new[] { "--uninstall", "--silent" }) != 2 || SetupFiles.Mode(new[] { "--silent", "--uninstall" }) != 2) throw new Exception("Silent setup flags chose the wrong path.");
            foreach (string flag in new[] { "--update", "--remove-files", "--verify", "--unknown" })
            {
                bool refused = false;
                try { SetupFiles.Mode(new[] { "--silent", flag }); }
                catch (ArgumentException) { refused = true; }
                if (!refused) throw new Exception("Silent setup accepted " + flag + ".");
            }
            checks.Add("PASS silent install and uninstall flags work in either order, reject other commands and leave windowed setup flags alone");
            bool heldSelf;
            using (System.Diagnostics.Process self = System.Diagnostics.Process.GetCurrentProcess())
                if (!string.Equals(SetupFiles.FileOf(self, out heldSelf), Application.ExecutablePath, StringComparison.OrdinalIgnoreCase) || heldSelf) throw new Exception("Setup couldn't name her running file, or thought it couldn't close her.");
            string closeRoot = Path.Combine(Path.GetTempPath(), "capri-close-" + Guid.NewGuid().ToString("N"));
            try
            {
                string closeHere = Path.Combine(closeRoot, "Capri"), closeOther = Path.Combine(closeRoot, "Other");
                Directory.CreateDirectory(closeHere);
                Directory.CreateDirectory(closeOther);
                if (SetupFiles.Closable(closeHere) || SetupFiles.Closable(null) || SetupFiles.Closable(Environment.SystemDirectory)) throw new Exception("Setup's admin close took a folder with no install marker.");
                File.WriteAllText(Path.Combine(closeHere, ".capri-install"), "test");
                File.WriteAllText(Path.Combine(closeOther, ".capri-install"), "test");
                if (!SetupFiles.Closable(closeHere) || !SetupFiles.Closable(closeHere + "\\") || SetupFiles.Closable(closeOther)) throw new Exception("Setup's admin close missed her marked folder or took another one.");
            }
            finally { try { Directory.Delete(closeRoot, true); } catch (IOException) { } catch (UnauthorizedAccessException) { } }
            checks.Add("PASS setup names a running Capri's file even when it can't read her, and its administrator copy only closes things in a marked Capri folder");
            string named;
            if (SetupFiles.Mode(new[] { "--silent", "--package", "winget" }, out named) != 1 || named != "winget" || SetupFiles.Mode(new[] { "--package", "scoop", "--silent" }, out named) != 1 || named != "scoop"
                || SetupFiles.Mode(new[] { "--silent", "--package", "chocolatey" }, out named) != 1 || named != "chocolatey" || SetupFiles.Mode(new[] { "--silent", "--package", "pacman" }, out named) != 1 || named != "pacman"
                || SetupFiles.Mode(new[] { "--silent" }, out named) != 1 || named != null || SetupFiles.Mode(new[] { "--uninstall", "--silent" }, out named) != 2 || named != null)
                throw new Exception("A package manager's silent install wasn't read with its name.");
            foreach (string[] command in new[] { new[] { "--silent", "--package", "apt" }, new[] { "--silent", "--package", "Winget" }, new[] { "--silent", "--package", "0" }, new[] { "--silent", "--package", "-" }, new[] { "--silent", "--package" }, new[] { "--silent", "--package", "winget", "--package", "scoop" }, new[] { "--uninstall", "--silent", "--package", "winget" }, new[] { "--package", "winget" } })
            {
                bool refused = false;
                try { SetupFiles.Mode(command, out named); }
                catch (ArgumentException) { refused = true; }
                if (!refused) throw new Exception("Silent setup accepted " + string.Join(" ", command) + ".");
            }
            checks.Add("PASS --silent --package names winget, scoop, chocolatey or pacman in either order; another or a missing name, a second --package, --package with --uninstall and --package without --silent fail instead of opening a window");
            string folder = Path.Combine(output, "setup-files-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(folder);
            string file = Path.Combine(folder, "Uninstall.exe"), old = file + ".old", marker = Path.Combine(folder, ".capri-install"), other = Path.Combine(folder, "Uninstall-other.old");
            string runWas = Startup.RunKey, approvedWas = Startup.ApprovedKey;
            string startupRoot = "Software\\CapriSmoke\\Setup-" + Guid.NewGuid().ToString("N");
            try
            {
                Startup.RunKey = startupRoot + "\\Run";
                Startup.ApprovedKey = startupRoot + "\\Approved";
                File.WriteAllText(marker, "installed");
                File.WriteAllText(file, "current uninstaller");
                File.WriteAllText(old, "previous uninstaller");
                File.WriteAllText(other, "keep this");
                bool stillThere = false;
                try { SetupFiles.Gone(file); }
                catch (IOException) { stillThere = true; }
                if (!stillThere) throw new Exception("An uninstaller that still exists counted as gone.");
                SetupFiles.Retire(file, true);
                SetupFiles.Gone(file);
                if (File.ReadAllText(old) != "current uninstaller" || File.ReadAllText(other) != "keep this" || !File.Exists(marker)) throw new Exception("Retiring the uninstaller changed another file or lost its contents.");
                SetupFiles.ClearOld(file);
                SetupFiles.Gone(old);
                SetupFiles.Gone(Path.Combine(folder, "missing", "Uninstall.exe"));
                File.WriteAllText(file, "retry uninstaller");
                File.WriteAllText(old, "locked uninstaller");
                bool blocked = false;
                using (FileStream kept = new FileStream(old, FileMode.Open, FileAccess.Read, FileShare.None))
                {
                    try { SetupFiles.Retire(file, true); }
                    catch (IOException) { blocked = true; }
                    catch (UnauthorizedAccessException) { blocked = true; }
                    if (!blocked || !File.Exists(file) || !File.Exists(marker)) throw new Exception("A locked old uninstaller did not leave the install retryable.");
                }
                SetupFiles.Retire(file, true);
                SetupFiles.Gone(file);
                if (File.ReadAllText(old) != "retry uninstaller") throw new Exception("Retrying the uninstaller did not replace its old file.");
                blocked = false;
                using (FileStream kept = new FileStream(old, FileMode.Open, FileAccess.Read, FileShare.None))
                {
                    try { SetupFiles.ClearOld(file); }
                    catch (IOException) { blocked = true; }
                    catch (UnauthorizedAccessException) { blocked = true; }
                    if (!blocked) throw new Exception("Install ignored a locked old uninstaller.");
                }
                SetupFiles.ClearOld(file);
                File.WriteAllText(file, "external uninstaller");
                SetupFiles.Retire(file, false);
                SetupFiles.Gone(file);
                if (File.Exists(old) || File.ReadAllText(other) != "keep this" || !File.Exists(marker)) throw new Exception("Removing an idle uninstaller changed another file.");
                checks.Add("PASS uninstall uses one old filename, verifies the source is gone, keeps locked cleanup retryable, removes the old file on install and leaves other files alone");
                string setup = Path.Combine(folder, "Capri-Setup.exe");
                File.WriteAllText(setup, "running setup");
                File.WriteAllText(file, "entry uninstaller");
                SetupFiles.Retire(file, true);
                SetupFiles.Unretire(file, setup);
                if (!File.Exists(file) || File.ReadAllText(file) != "entry uninstaller" || File.Exists(old)) throw new Exception("A failed removal did not put the retired uninstaller back.");
                SetupFiles.Retire(file, false);
                SetupFiles.Unretire(file, setup);
                if (!File.Exists(file) || File.ReadAllText(file) != "running setup") throw new Exception("A failed removal did not put an uninstaller back for her uninstall entry.");
                File.WriteAllText(file, "kept uninstaller");
                SetupFiles.Unretire(file, setup);
                if (File.ReadAllText(file) != "kept uninstaller" || File.ReadAllText(other) != "keep this") throw new Exception("Putting the uninstaller back replaced one that was still there, or another file.");
                File.Delete(file);
                File.Delete(setup);
                checks.Add("PASS a failed removal puts her uninstaller back under its own name, from its old file or the running setup, so her uninstall entry can run it again");
                string app = Path.Combine(folder, "Capri.exe");
                File.WriteAllText(app, "installed app");
                if (!Startup.Set(app, true) || !Startup.On(app)) throw new Exception("The uninstall check could not make a test startup entry.");
                blocked = false;
                using (FileStream kept = new FileStream(app, FileMode.Open, FileAccess.Read, FileShare.None))
                {
                    try { SetupFiles.RemoveApp(app); }
                    catch (IOException) { blocked = true; }
                    catch (UnauthorizedAccessException) { blocked = true; }
                    if (!blocked || Startup.On(app) || !File.Exists(marker)) throw new Exception("A failed uninstall kept a startup entry for the app it was removing.");
                }
                SetupFiles.RemoveApp(app);
                SetupFiles.Gone(app);
                checks.Add("PASS uninstall clears only its startup entry before removing the app, even when file cleanup fails");
                string package = Path.Combine(folder, SetupFiles.Marker);
                Updater reader = new Updater(folder, app, true);
                SetupFiles.Mark(folder, "winget");
                if (File.ReadAllText(package) != "winget" || reader.Package() != "winget") throw new Exception("A new package marker wasn't written or read back.");
                SetupFiles.Mark(folder, "manual");
                if (File.ReadAllText(package) != "manual" || reader.Package() != null) throw new Exception("A manual install didn't replace the package marker.");
                File.SetAttributes(package, FileAttributes.ReadOnly);
                blocked = false;
                try { SetupFiles.Mark(folder, "scoop"); }
                catch (IOException) { blocked = true; }
                catch (UnauthorizedAccessException) { blocked = true; }
                finally { File.SetAttributes(package, FileAttributes.Normal); }
                if (!blocked || File.ReadAllText(package) != "manual" || Array.Exists(Directory.GetFiles(folder), delegate(string each) { return each.EndsWith(".new", StringComparison.OrdinalIgnoreCase); })) throw new Exception("A failed package marker write changed the old marker or left its new file behind.");
                checks.Add("PASS the package marker is written whole and read back by her updater, a manual install replaces it, and a failed write keeps the old one and leaves no new file behind");
                SetupFiles.Mark(folder, "scoop");
                SetupFiles.Unmark(folder);
                SetupFiles.Unmark(folder);
                if (File.Exists(package) || reader.Package() != null || File.ReadAllText(other) != "keep this" || !File.Exists(marker)) throw new Exception("Removing her didn't take her package marker, or took another file with it.");
                checks.Add("PASS removing her takes her package marker and nothing else, and a missing one is fine");
            }
            finally
            {
                Startup.RunKey = runWas;
                Startup.ApprovedKey = approvedWas;
                Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(startupRoot, false);
                foreach (string each in Directory.GetFiles(folder)) File.Delete(each);
                Directory.Delete(folder);
            }
        }

        // Her package marker: the managers she knows say where to update and anything else she finds still holds her updater
        // back, while "manual" or no marker frees it. With winget's marker in her folder, a check, the update tool and an
        // install never ask GitHub or start her installer, and once a manual install marks it again the old note clears.
        private void SmokePackageMarker(System.Collections.Generic.List<string> checks, string output)
        {
            if (updating || installing || updateFile != null) throw new Exception("The package marker check found an update already under way.");
            string folder = Path.Combine(output, "package-marker-" + Guid.NewGuid().ToString("N"));
            string data = Path.GetDirectoryName(updater.Folder), marker = Path.Combine(data, SetupFiles.Marker);
            string staged = Path.Combine(updater.Folder, "Capri-Setup-99.0.0-package.exe");
            Func<Release> latestWas = updater.Latest;
            Func<string, string> signerWas = updater.Signer;
            Action<ProcessStartInfo> runWas = updater.Run;
            long checkedWas = preferences.UpdateCheckedAt;
            bool startedWas = updateStarted;
            string noteWas = mainframe.UpdateStatus;
            Directory.CreateDirectory(folder);
            try
            {
                Updater reader = new Updater(folder, Path.Combine(folder, "Capri.exe"), true);
                string file = Path.Combine(folder, SetupFiles.Marker);
                if (reader.Package() != null) throw new Exception("A missing package marker was read as a manager.");
                File.WriteAllText(file, "winget\n");
                if (reader.Package() != "winget") throw new Exception("A winget package marker was not read.");
                foreach (string bad in new[] { "Winget!", "package", "apt", "0", "-", "" })
                {
                    File.WriteAllText(file, bad);
                    if (reader.Package() != "your package manager") throw new Exception("A package marker she doesn't know freed her own updater: " + bad);
                }
                File.WriteAllText(file, "manual");
                if (reader.Package() != null) throw new Exception("A manual package marker did not free her updater.");
                File.Delete(file);
                checks.Add("PASS package marker: winget is read, a bad, empty or generic marker still blocks her own updater, and manual or no marker leaves her updater alone");

                if (File.Exists(marker)) throw new Exception("Her smoke folder already had a package marker.");
                int asked = 0, ran = 0;
                updater.Latest = delegate { asked++; throw new Exception("A package-managed Capri asked GitHub for an update."); };
                updater.Run = delegate { ran++; };
                updater.Signer = delegate { return null; };
                SetupFiles.Mark(data, "winget");
                CheckForUpdates(true);
                string checkedNote = mainframe.UpdateStatus;
                string told = UpdateTool(new ToolArguments { Action = "check" });
                string status = UpdateTool(new ToolArguments { Action = "status" });
                updateFile = new UpdateFile { Version = "99.0.0", Path = staged };
                InstallUpdate();
                if (asked != 0 || ran != 0 || updating || installing || updateFile != null || !checkItem.Enabled || checkedNote != "Update through winget." || told != checkedNote || status != checkedNote || mainframe.UpdateStatus != checkedNote)
                    throw new Exception("A package-managed Capri still reached her own updater: asked GitHub " + asked + ", ran " + ran + ", note " + checkedNote + ", tool " + told + " / " + status + ", updating " + updating + ", installing " + installing);
                // Her installer's last guard: a checked update still won't start while the marker is there.
                byte[] bytes = System.Text.Encoding.ASCII.GetBytes("MZ a package-managed update");
                Directory.CreateDirectory(updater.Folder);
                File.WriteAllBytes(staged, bytes);
                string hash;
                using (SHA256 sha = SHA256.Create()) hash = BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", "");
                string refused = null;
                try { updater.Install(new UpdateFile { Version = "99.0.0", Path = staged, Hash = hash, Size = bytes.Length }, 1, 1); }
                catch (BrainException error) { refused = error.Message; }
                if (refused != checkedNote || ran != 0) throw new Exception("A checked update started with a package marker there: " + (refused ?? "it was allowed"));
                SetupFiles.Mark(data, "manual");
                string freed = UpdateTool(new ToolArguments { Action = "status" });
                if (updater.Package() != null || freed == checkedNote || mainframe.UpdateStatus.StartsWith("Update through ", StringComparison.Ordinal)) throw new Exception("A stale package status stayed after a manual install: " + freed);
                checks.Add("PASS with winget's marker in her folder, an update check, the update tool's check and status, an install and a checked installer all say to update through winget without asking GitHub or starting her installer; a manual install's marker clears the note");
            }
            finally
            {
                updater.Latest = latestWas;
                updater.Signer = signerWas;
                updater.Run = runWas;
                updateFile = null;
                updateInstallAsked = false;
                preferences.UpdateCheckedAt = checkedWas;
                updateStarted = startedWas;
                mainframe.UpdateNote(noteWas, false);
                if (File.Exists(marker)) File.Delete(marker);
                if (File.Exists(staged)) File.Delete(staged);
                Directory.Delete(folder, true);
            }
        }

        // The Store copy, with no package to run in. Outside a package nothing changes. With a stand-in package name, her updater
        // is off whatever a website install left, her data folder is the real one for a fresh install and the website's for someone
        // moving over, she starts with Windows through her startup task and never the Run key, and Get VB-CABLE starts no setup.
        private void SmokePackaged(System.Collections.Generic.List<string> checks, string output)
        {
            const string standIn = "Capri.Test_1.8.5.0_x64__abcdefghjkmnp", family = "Capri.Test_abcdefghjkmnp";
            const string desktopMic = "Windows is blocking the mic. Turn on Microphone access and Let desktop apps access your microphone in Settings > Privacy & security > Microphone.";
            if (Packaged.Is) throw new Exception("The smoke test runs outside a package, but Windows named one: " + Packaged.FullName);
            if (updating || installing || updateFile != null) throw new Exception("The package check found an update already under way.");
            string folder = Path.Combine(output, "packaged-" + Guid.NewGuid().ToString("N")), local = Path.Combine(folder, "Local"), usual = Path.Combine(local, "Capri");
            string staged = Path.Combine(updater.Folder, "Capri-Setup-99.0.0-store.exe"), exe = Application.ExecutablePath;
            string runKeyWas = Startup.RunKey, approvedKeyWas = Startup.ApprovedKey, startupRoot = "Software\\Capri smoke " + Guid.NewGuid().ToString("N");
            Func<Release> latestWas = updater.Latest;
            Func<string, string> signerWas = updater.Signer;
            Action<ProcessStartInfo> runWas = updater.Run;
            Func<bool> startupOnWas = Packaged.StartupOn;
            Func<bool, string> setStartupWas = Packaged.SetStartup;
            Action<string> browseWas = Browse;
            Func<string, Process> setupWas = CableSetup.Start;
            long checkedWas = preferences.UpdateCheckedAt;
            bool startedWas = updateStarted, startupSetWas = preferences.StartupSet;
            string noteWas = mainframe.UpdateStatus, cableLineWas = cableSetupLine;
            Directory.CreateDirectory(local);
            try
            {
                if (Packaged.Family != null || Packaged.Home(local) != usual || Directory.Exists(usual) || Packaged.Launcher(exe) != exe || !Ears.MicSwitch.EndsWith("\\microphone\\NonPackaged", StringComparison.Ordinal) || Dictation.MicBlocked != desktopMic)
                    throw new Exception("Outside a package her data folder, her path, her mic switch or her mic line changed.");
                checks.Add("PASS outside a package her data folder, her own path, the mic switch she reads and her mic line stay as they were");

                Packaged.FullName = standIn;
                if (!Packaged.Is || Packaged.Family != family) throw new Exception("The package family read wrong: " + Packaged.Family);
                string alias = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Microsoft", "WindowsApps", "Capri.exe");
                if (Packaged.Launcher(exe) != alias || !Ears.MicSwitch.EndsWith("\\microphone\\" + family, StringComparison.Ordinal) || Dictation.MicBlocked.IndexOf("Let desktop apps", StringComparison.Ordinal) >= 0)
                    throw new Exception("A Store copy's alias, mic switch or mic line is wrong: " + Packaged.Launcher(exe) + " | " + Ears.MicSwitch + " | " + Dictation.MicBlocked);

                // Moving from the website: her folder is real and stays hers, with everything in it. A fresh install gets the private
                // folder by its real name, which other programs can open.
                Directory.CreateDirectory(usual);
                File.WriteAllText(Path.Combine(usual, "settings.json"), "kept");
                if (Packaged.Home(local) != usual || File.ReadAllText(Path.Combine(usual, "settings.json")) != "kept") throw new Exception("A Store copy left the website's data folder behind.");
                Directory.Delete(usual, true);
                string kept = Path.Combine(local, "Packages", family, "LocalCache", "Local", "Capri");
                Directory.CreateDirectory(kept);
                if (Packaged.Home(local) != kept) throw new Exception("A fresh Store copy didn't use the real path of her private folder: " + Packaged.Home(local));
                checks.Add("PASS a Store copy keeps a website install's data folder and uses a fresh install's private folder by its real path");

                string reading = Path.Combine(folder, "reader");
                Directory.CreateDirectory(reading);
                Updater reader = new Updater(reading, exe, true);
                if (reader.Package() != Packaged.Store) throw new Exception("A Store copy with no marker didn't say the Store updates her.");
                File.WriteAllText(Path.Combine(reading, SetupFiles.Marker), "manual");
                if (reader.Package() != Packaged.Store) throw new Exception("A manual marker from a website install freed a Store copy's updater.");
                int asked = 0, ran = 0;
                updater.Latest = delegate { asked++; throw new Exception("A Store copy asked GitHub for an update."); };
                updater.Run = delegate { ran++; };
                updater.Signer = delegate { return null; };
                CheckForUpdates(true);
                string checkedNote = mainframe.UpdateStatus, told = UpdateTool(new ToolArguments { Action = "check" }), status = UpdateTool(new ToolArguments { Action = "status" });
                updateFile = new UpdateFile { Version = "99.0.0", Path = staged };
                InstallUpdate();
                const string storeNote = "Update through the Microsoft Store.";
                if (asked != 0 || ran != 0 || updating || installing || updateFile != null || !checkItem.Enabled || checkedNote != storeNote || told != storeNote || status != storeNote)
                    throw new Exception("A Store copy reached her own updater: asked GitHub " + asked + ", ran " + ran + ", note " + checkedNote + ", tool " + told + " / " + status);
                byte[] bytes = System.Text.Encoding.ASCII.GetBytes("MZ a Store copy's update");
                Directory.CreateDirectory(updater.Folder);
                File.WriteAllBytes(staged, bytes);
                string hash, refused = null;
                using (SHA256 sha = SHA256.Create()) hash = BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", "");
                try { updater.Install(new UpdateFile { Version = "99.0.0", Path = staged, Hash = hash, Size = bytes.Length }, 1, 1); }
                catch (BrainException error) { refused = error.Message; }
                if (refused != storeNote || ran != 0) throw new Exception("A checked update started in a Store copy: " + (refused ?? "it was allowed"));
                checks.Add("PASS a Store copy never asks GitHub or starts her installer: a check, the update tool, an install and a checked update all say to update through the Microsoft Store, even over a website install's manual marker");

                Startup.RunKey = startupRoot + "\\Run";
                Startup.ApprovedKey = startupRoot + "\\StartupApproved";
                bool taskOn = false;
                string answer = null;
                int sets = 0;
                Packaged.StartupOn = delegate { return taskOn; };
                Packaged.SetStartup = delegate(bool on) { sets++; if (answer == null) taskOn = on; return answer; };
                preferences.StartupSet = false;
                DefaultStartup(Installed());
                if (StartsWithWindows || preferences.StartupSet || sets != 0) throw new Exception("A Store copy turned starting with Windows on by herself.");
                ToggleStartup();
                bool turnedOn = StartsWithWindows && sets == 1 && preferences.StartupSet;
                ToggleStartup();
                bool turnedOff = !StartsWithWindows && sets == 2;
                answer = Packaged.StartupRefused;
                ToggleStartup();
                bool stayedOff = !StartsWithWindows && sets == 3;
                using (Microsoft.Win32.RegistryKey wroteRun = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(Startup.RunKey))
                    if (!turnedOn || !turnedOff || !stayedOff || wroteRun != null) throw new Exception("A Store copy's startup switch didn't go through her startup task: on " + turnedOn + ", off " + turnedOff + ", refused " + stayedOff + ", Run key " + (wroteRun != null));
                checks.Add("PASS a Store copy starts off, and starting with Windows goes through her startup task, never the Run key, and survives Windows refusing it");

                string opened = null;
                int setups = 0;
                Browse = delegate(string page) { opened = page; };
                CableSetup.Start = delegate { setups++; return null; };
                SetUpCable();
                if (opened != CableSetup.Page || setups != 0 || CableSetupOpen || cableSetupLine != cableLineWas) throw new Exception("A Store copy's Get VB-CABLE reached a setup: " + opened + ", " + setups + " setups.");
                opened = null;
                OpenPage(IssuesPage);
                if (opened != IssuesPage) throw new Exception("Report a problem didn't open the issues page.");
                OpenPage(ModRulesPage);
                if (opened != ModRulesPage) throw new Exception("Mod rules didn't open their page.");
                checks.Add("PASS a Store copy's Get VB-CABLE opens VB-Audio's page and starts no driver setup, and Report a problem and Mod rules open their pages");
            }
            finally
            {
                Packaged.FullName = null;
                Packaged.StartupOn = startupOnWas;
                Packaged.SetStartup = setStartupWas;
                Browse = browseWas;
                CableSetup.Start = setupWas;
                Startup.RunKey = runKeyWas;
                Startup.ApprovedKey = approvedKeyWas;
                Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(startupRoot, false);
                updater.Latest = latestWas;
                updater.Signer = signerWas;
                updater.Run = runWas;
                updateFile = null;
                updateInstallAsked = false;
                preferences.UpdateCheckedAt = checkedWas;
                preferences.StartupSet = startupSetWas;
                updateStarted = startedWas;
                mainframe.UpdateNote(noteWas, false);
                if (File.Exists(staged)) File.Delete(staged);
                Directory.Delete(folder, true);
                mainframe.Sync();
            }
        }

        // A made-up game: a view into a big patterned world that slides as the mouse moves, to prove her camera finds any game's mouse.
        private static void SmokeCamera(System.Collections.Generic.List<string> checks)
        {
            const int worldWidth = 2400, worldHeight = 1600;
            byte[] world = new byte[worldWidth * worldHeight];
            Random speckle = new Random(77);
            byte[] coarse = new byte[(worldWidth / 16 + 2) * (worldHeight / 16 + 2)];
            speckle.NextBytes(coarse);
            for (int wy = 0; wy < worldHeight; wy++)
                for (int wx = 0; wx < worldWidth; wx++)
                    world[wy * worldWidth + wx] = coarse[(wy / 16) * (worldWidth / 16 + 2) + wx / 16];
            Rectangle area = new Rectangle(0, 0, 1280, 720);
            Func<Rectangle, byte[]> frameWas = Computer.GrayFrame;
            Action<int, int> nudgeWas = Computer.Nudge;
            double cameraX = 0, cameraY = 0, truth = 0;
            int sent = 0;
            bool upside = false, fixedView = false, blank = false, round = false;
            Func<Rectangle, byte[]> seenWorld = delegate(Rectangle part)
            {
                byte[] gray = new byte[Computer.GrayWidth * Computer.GrayHeight];
                if (blank) { for (int fill = 0; fill < gray.Length; fill++) gray[fill] = 200; return gray; }
                for (int gy = 0; gy < Computer.GrayHeight; gy++)
                    for (int gx = 0; gx < Computer.GrayWidth; gx++)
                    {
                        int sampleX = (int)(cameraX + gx * (double)part.Width / Computer.GrayWidth) + 600;
                        if (round) sampleX = ((sampleX % worldWidth) + worldWidth) % worldWidth;
                        int sampleY = (int)(cameraY + gy * (double)part.Height / Computer.GrayHeight) + 400;
                        gray[gy * Computer.GrayWidth + gx] = world[Math.Max(0, Math.Min(worldHeight - 1, sampleY)) * worldWidth + Math.Max(0, Math.Min(worldWidth - 1, sampleX))];
                    }
                return gray;
            };
            Action<int, int> mouse = delegate(int dx, int dy)
            {
                sent += Math.Abs(dx) + Math.Abs(dy);
                if (fixedView) return;
                cameraX += dx * truth;
                cameraY += (upside ? -dy : dy) * truth;
                if (round) cameraY = Math.Min(cameraY, 400);
            };
            Sight game = new Sight { Program = "smoke-a", Bounds = area };
            try
            {
                Computer.GrayFrame = seenWorld;
                Computer.Nudge = mouse;
                foreach (double speed in new[] { 0.3, 1.7, 7.0 })
                {
                    game.Program = "smoke-" + speed;
                    truth = speed;
                    cameraX = cameraY = 0;
                    Computer.TurnView(new ToolArguments { Right = 20 }, game);
                    double wanted = 540 * 20 * Math.PI / 180;
                    if (Math.Abs(cameraX - wanted) > 30 || Math.Abs(cameraY) > 12) throw new Exception("Her camera missed a 20 degree turn at mouse speed " + speed + ": went " + cameraX + ", " + cameraY + ", wanted " + wanted + ".");
                    Computer.TurnView(new ToolArguments { Up = -5 }, game);
                    if (Math.Abs(cameraY - 540 * 5 * Math.PI / 180) > 30) throw new Exception("Her camera missed looking down at mouse speed " + speed + ": went " + cameraY + ".");
                }
                game.Program = "smoke-upside";
                truth = 1.7;
                upside = true;
                cameraX = cameraY = 0;
                Computer.TurnView(new ToolArguments { Up = -8 }, game);
                Computer.TurnView(new ToolArguments { Up = -8 }, game);
                if (Math.Abs(cameraY - 2 * 540 * 8 * Math.PI / 180) > 40) throw new Exception("Her camera didn't work out a game that looks the other way: went " + cameraY + ".");
                upside = false;
                game.Program = "smoke-plain";
                blank = true;
                sent = 0;
                string plain = Computer.TurnView(new ToolArguments { Up = -60 }, game);
                if (sent < 100 || plain.IndexOf("didn't move", StringComparison.Ordinal) >= 0) throw new Exception("Her camera refused to turn away from open sky: " + plain);
                blank = false;
                fixedView = true;
                game.Program = "smoke-menu";
                string menu = Computer.TurnView(new ToolArguments { Right = 30 }, game);
                if (menu.IndexOf("didn't move", StringComparison.Ordinal) < 0) throw new Exception("Her camera didn't notice a view that stayed still: " + menu);
                fixedView = false;
                round = true;
                foreach (double roundSpeed in new[] { 0.6, 1.7, 4.0 })
                {
                    game.Program = "smoke-round-" + roundSpeed;
                    truth = roundSpeed;
                    cameraX = cameraY = 0;
                    Computer.TurnView(new ToolArguments { Right = 90 }, game);
                    if (Math.Abs((cameraX % worldWidth + worldWidth) % worldWidth - worldWidth / 4.0) > 24) throw new Exception("Her camera missed a quarter turn in a game whose view comes round at mouse speed " + roundSpeed + ": went " + cameraX + ".");
                    Computer.TurnView(new ToolArguments { Level = "yes" }, game);
                    if (Math.Abs(cameraY - (400 - worldWidth / 4.0)) > 24) throw new Exception("Her camera didn't level out at mouse speed " + roundSpeed + ": ended at " + cameraY + ".");
                    string flatGame = "smoke-flat-" + roundSpeed;
                    Computer.NoLevel[flatGame] = DateTime.UtcNow.AddMinutes(2);
                    if (Computer.TurnView(new ToolArguments { Level = "yes" }, new Sight { Program = flatGame, Bounds = area }) != Computer.NoCamera) throw new Exception("A game with no camera kept hunting for one.");
                    Computer.NoLevel[flatGame] = DateTime.UtcNow.AddMinutes(-1);
                    if (Computer.TurnView(new ToolArguments { Level = "yes" }, new Sight { Program = flatGame, Bounds = area }) == Computer.NoCamera) throw new Exception("A game stayed marked as having no camera after that wore off.");
                    Computer.NoLevel.Remove(flatGame);
                }
                round = false;
                checks.Add("PASS her camera learns any game's mouse from slow to fast, measures a full turn at any field of view, looks level, lands turns within a few pixels, works out games that look the other way, always turns away from open sky, and says when a view stays still");
                Action<int, int> sendWas = Computer.SendMouse;
                Action<Point> putWas = Computer.PutCursor;
                Func<Point> cursorWas = Computer.CursorAt;
                Func<bool> hiddenWas = Computer.CursorHidden, escapeWas = Computer.Escape;
                Func<Point, bool> underWas = Computer.GameUnder;
                Func<IntPtr> frontWas = Computer.Front;
                Action<bool> lendingWas = Computer.Lending;
                Action haltedWas = Computer.Halted;
                bool streamWas = Computer.Streaming, rightHeld = false;
                int downs = 0, ups = 0;
                Point cursor = new Point(-200, 80), original = cursor;
                IntPtr front = new IntPtr(123);
                try
                {
                    Computer.Streaming = false;
                    Computer.Escape = delegate { return false; };
                    Computer.Halted = delegate { };
                    Computer.Arm();
                    Computer.PutCursor = delegate(Point at) { cursor = at; };
                    Computer.CursorAt = delegate { return cursor; };
                    Computer.CursorHidden = delegate { return false; };
                    Computer.GameUnder = delegate { return false; };
                    Computer.Front = delegate { return front; };
                    Computer.Lending = delegate { };
                    Computer.SendMouse = delegate(int flags, int amount)
                    {
                        if (flags == 0x0008) { rightHeld = true; downs++; }
                        if (flags == 0x0010) { rightHeld = false; ups++; }
                    };
                    Computer.Nudge = delegate(int dx, int dy)
                    {
                        if (!rightHeld || cursor != new Point(area.X + area.Width / 2, area.Y + area.Height / 2)) throw new Exception("Roblox's camera moved without holding right over the game.");
                        mouse(dx, dy);
                    };
                    game.Program = "RobloxPlayerBeta";
                    game.Window = front;
                    truth = 1.7;
                    cameraX = cameraY = 0;
                    round = true;
                    Computer.TurnView(new ToolArguments { Right = 90 }, game);
                    if (Math.Abs((cameraX % worldWidth + worldWidth) % worldWidth - worldWidth / 4.0) > 24 || rightHeld || downs != 1 || ups != 1 || cursor != original) throw new Exception("Roblox's camera did not turn or let go of the mouse.");
                    Computer.TurnView(new ToolArguments { Level = "yes" }, game);
                    if (Math.Abs(cameraY - (400 - worldWidth / 4.0)) > 24 || rightHeld || downs != 2 || ups != 2 || cursor != original) throw new Exception("Roblox's camera did not level or let go of the mouse.");
                    bool failed = false;
                    Computer.Nudge = delegate { throw new IOException("camera failed"); };
                    try { Computer.TurnView(new ToolArguments { Right = 20 }, game); }
                    catch (IOException) { failed = true; }
                    if (!failed || rightHeld || downs != 3 || ups != 3 || cursor != original) throw new Exception("A failed Roblox turn held the mouse.");
                    Computer.Nudge = delegate { Computer.Interrupt(Computer.Escaped); };
                    string stopped = Computer.TurnView(new ToolArguments { Right = 20 }, game);
                    if (stopped != Computer.Escaped || rightHeld || downs != 4 || ups != 4 || cursor != original) throw new Exception("Esc did not release Roblox's camera.");
                    Computer.TurnView(new ToolArguments { Right = 20 }, game);
                    if (downs != 4) throw new Exception("A stopped Roblox turn pressed the mouse again.");
                    Computer.Arm();
                    front = new IntPtr(124);
                    Computer.TurnView(new ToolArguments { Right = 20 }, game);
                    if (downs != 4 || cursor != original) throw new Exception("Roblox's camera took the mouse with another window in front.");
                    Computer.Nudge = mouse;
                    game.Program = "smoke-round-1.7";
                    game.Window = IntPtr.Zero;
                    Computer.TurnView(new ToolArguments { Right = 20 }, game);
                    if (downs != 4 || ups != 4) throw new Exception("Another game's camera pressed Roblox's mouse button.");
                    checks.Add("PASS Roblox camera turns and levels with right held over the game, returns the cursor, releases on failure or Esc, leaves other windows alone and keeps other games' controls");
                }
                finally
                {
                    Computer.Arm();
                    Computer.SendMouse = sendWas;
                    Computer.PutCursor = putWas;
                    Computer.CursorAt = cursorWas;
                    Computer.CursorHidden = hiddenWas;
                    Computer.GameUnder = underWas;
                    Computer.Front = frontWas;
                    Computer.Lending = lendingWas;
                    Computer.Halted = haltedWas;
                    Computer.Escape = escapeWas;
                    Computer.Streaming = streamWas;
                }
            }
            finally
            {
                Computer.GrayFrame = frameWas;
                Computer.Nudge = nudgeWas;
            }
        }

        // Asks to play or use a game reach her hands in any language, whatever her brain's chat reply says.
        private sealed class MiniDice : Random
        {
            public override int Next(int maximum) { return 0; }
        }

        private static int MinisUnbeaten(int[] cells, int turn)
        {
            int result = MiniGame.Outcome(cells, false);
            if (result == 1) throw new Exception("Her perfect tic-tac-toe lost.");
            if (result != 0) return 1;
            int games = 0;
            if (turn == 2)
            {
                int move = MiniGame.TicMove(cells, false, null);
                cells[move] = 2;
                games = MinisUnbeaten(cells, 1);
                cells[move] = 0;
            }
            else for (int choice = 0; choice < 9; choice++)
            {
                if (cells[choice] != 0) continue;
                cells[choice] = 1;
                games += MinisUnbeaten(cells, 2);
                cells[choice] = 0;
            }
            return games;
        }

        private static void SmokeChess(System.Collections.Generic.List<string> checks)
        {
            Action<bool, string> must = delegate(bool okay, string why) { if (!okay) throw new Exception(why); };
            string[] positions = { ChessPosition.Start, "r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq -", "8/2p5/3p4/KP5r/1R3p1k/8/4P1P1/8 w - -" };
            long[][] totals = { new long[] { 20, 400, 8902, 197281 }, new long[] { 48, 2039, 97862 }, new long[] { 14, 191, 2812, 43238 } };
            for (int fixture = 0; fixture < positions.Length; fixture++)
            {
                ChessPosition board = new ChessPosition(positions[fixture]);
                string before = board.Fen();
                for (int depth = 1; depth <= totals[fixture].Length; depth++)
                {
                    long nodes = board.Perft(depth);
                    must(nodes == totals[fixture][depth - 1] && board.Fen() == before && board.History.Count == 1, "Chess perft or restoration failed at fixture " + fixture + " depth " + depth + ": " + nodes);
                    checks.Add("PASS chess perft " + fixture + " depth " + depth + " = " + nodes);
                }
            }
            // Easy thinks for 250 ms, and the first search also compiles the engine: on a slow PC that can run out before its
            // first ply is done, so it hasn't chosen anything (the public Windows runner, 5 Nov). Such a search is asked again;
            // one that finished a ply and still got it wrong fails.
            Func<ChessPosition, string, int, ChessChoice> settled = delegate(ChessPosition position, string strength, int seed)
            {
                ChessChoice chosen = null;
                for (int tries = 0; tries < 3 && (chosen == null || chosen.Depth == 0); tries++) chosen = new ChessSearch(position, strength, new Random(seed), null).Run();
                must(chosen.Depth > 0, "Chess on " + strength + " ran out of time three times before finishing one ply (" + chosen.Milliseconds + " ms).");
                return chosen;
            };
            foreach (string level in new[] { "easy", "normal", "hard" })
                foreach (string mateFen in new[] { "7k/5Q2/6K1/8/8/8/8/8 w - -", "8/8/8/8/8/6k1/5q2/7K b - -" })
                {
                    ChessPosition mate = new ChessPosition(mateFen);
                    ChessChoice choice = settled(mate, level, 8);
                    must(choice.Move.From >= 0 && mate.Play(choice.Move.Text) && mate.Ending() == "Checkmate", "Chess missed mate in one on " + level);
                }
            checks.Add("PASS chess finds white and black mate in one at easy, normal and hard");
            foreach (string tacticLevel in new[] { "easy", "normal", "hard" })
            {
                ChessPosition tactic = new ChessPosition("4k3/8/8/8/4q3/8/4R3/4K3 w - -");
                ChessChoice tacticMove = settled(tactic, tacticLevel, 2);
                must(tacticMove.Move.Text == "e2e4", "Chess left a free queen on " + tacticLevel);
            }
            checks.Add("PASS chess at every level takes an undefended queen instead of choosing an arbitrary legal move");
            must(new ChessPosition("7k/5Q2/6K1/8/8/8/8/8 b - -").Ending() == "Stalemate", "Chess missed stalemate.");
            must(new ChessPosition("7k/6Q1/6K1/8/8/8/8/8 b - - 100 1").Ending() == "Checkmate", "A draw clock replaced checkmate.");
            foreach (int promotion in new[] { 5, 4, 3, 2 })
                foreach (int promoteSide in new[] { 1, -1 })
                {
                    ChessPosition promoted = new ChessPosition(promoteSide == 1 ? "7k/P7/6K1/8/8/8/8/8 w - -" : "8/8/8/8/8/6k1/p7/7K b - -");
                    string promoteBefore = promoted.Fen();
                    ChessMove promoteMove = promoted.Find((promoteSide == 1 ? "a7a8" : "a2a1") + " pnbrqk"[promotion]);
                    must(promoteMove.From >= 0, "A promotion choice was missing.");
                    ChessUndo promoteUndo = promoted.Push(promoteMove, true);
                    must(promoted.Cells[promoteMove.To] == promoteSide * promotion && promoted.Half == 0, "Promotion used the wrong piece.");
                    promoted.Pop(promoteUndo);
                    must(promoted.Fen() == promoteBefore && promoted.History.Count == 1, "Promotion undo lost the pawn.");
                }
            ChessPosition ep = new ChessPosition("7k/8/8/3pP3/8/8/8/K7 w - d6 0 1");
            string epBefore = ep.Fen();
            ChessUndo epUndo = ep.Push(ep.Find("e5d6"), true);
            must(ep.Cells[ChessPosition.At("d5")] == 0 && ep.Cells[ChessPosition.At("d6")] == 1 && ep.Ep == -1 && ep.Half == 0, "En passant failed.");
            ep.Pop(epUndo);
            must(ep.Fen() == epBefore && ep.Key() == ep.History[0], "En passant undo failed.");
            ChessPosition pinnedEp = new ChessPosition("k3r3/8/8/3pP3/8/8/8/4K3 w - d6");
            must(pinnedEp.Find("e5d6").From < 0 && pinnedEp.Key() == new ChessPosition("k3r3/8/8/3pP3/8/8/8/4K3 w - -").Key(), "A pinned en passant capture changed legal moves or repetition identity.");
            must(ep.Key() != new ChessPosition("7k/8/8/3pP3/8/8/8/K7 w - -").Key(), "A legal en passant right was lost from repetition identity.");
            must(new ChessPosition("8/8/8/r4pPK/8/8/8/7k w - f6").Find("g5f6").From < 0, "En passant exposed its own king on a rank.");
            foreach (string castle in new[] { "e1g1", "e1c1", "e8g8", "e8c8" })
            {
                bool white = castle[1] == '1';
                ChessPosition castled = new ChessPosition("r3k2r/8/8/8/8/8/8/R3K2R " + (white ? "w" : "b") + " KQkq -");
                string castleBefore = castled.Fen();
                ChessMove castleMove = castled.Find(castle);
                must(castleMove.From >= 0, "A legal castle was missing.");
                ChessUndo castleUndo = castled.Push(castleMove, true);
                must(castled.Cells[(castleMove.From + castleMove.To) / 2] == (white ? 4 : -4) && (castled.Rights & (white ? 3 : 12)) == 0, "Castling lost its rook or rights.");
                castled.Pop(castleUndo);
                must(castled.Fen() == castleBefore, "Castling undo failed.");
            }
            must(new ChessPosition("4kr2/8/8/8/8/8/8/4K2R w K -").Find("e1g1").From < 0, "Chess castled through check.");
            ChessPosition lostRights = new ChessPosition("4k3/8/8/8/8/8/8/R3K2R w KQ -");
            must(lostRights.Play("h1h2") && lostRights.Play("e8e7") && lostRights.Play("h2h1") && lostRights.Play("e7e8") && lostRights.Find("e1g1").From < 0, "A returned rook regained castling rights.");
            checks.Add("PASS chess stalemate, all eight promotion choices and their undo, en passant and pins, all four castles and rights");
            ChessPosition repeat = new ChessPosition(ChessPosition.Start);
            for (int cycle = 0; cycle < 2; cycle++) foreach (string repeatMove in new[] { "g1f3", "g8f6", "f3g1", "f6g8" }) must(repeat.Play(repeatMove), "Repetition fixture had an illegal move.");
            must(repeat.Repetitions == 3 && repeat.Ending() == "Threefold repetition", "Chess missed threefold repetition.");
            ChessPosition fifty = new ChessPosition("7k/8/8/8/8/8/8/KR6 w - - 99 50");
            must(fifty.Play("b1b2") && fifty.Ending() == "Fifty-move rule", "Chess missed fifty moves.");
            foreach (string dead in new[] { "7k/8/8/8/8/8/8/K7 w - -", "7k/8/8/8/8/8/8/KN6 w - -", "7k/8/8/8/8/8/8/KB6 w - -", "7k/8/8/8/8/3b4/8/KB6 w - -" }) must(new ChessPosition(dead).Insufficient, "Chess missed insufficient material.");
            foreach (string alive in new[] { "7k/8/8/8/8/8/8/KNN5 w - -", "7k/8/8/8/8/8/8/KBN5 w - -", "7k/8/8/8/8/4b3/8/KB6 w - -" }) must(!new ChessPosition(alive).Insufficient, "Chess called a possible mate insufficient material.");
            checks.Add("PASS chess threefold repetition, fifty moves and insufficient material without declaring two knights a dead position");
            MiniScore score = new MiniScore();
            ChessGame scored = new ChessGame(score, "hard", "white");
            scored.Board = new ChessPosition("7k/5Q2/6K1/8/8/8/8/8 w - -");
            must(scored.Move(scored.Board.Find("f7g7"), null) && scored.Result == 1 && score.You == 1 && !scored.Move(new ChessMove(0, 1, 0), null), "Chess did not score mate exactly once.");
            scored.Undo();
            must(score.You == 0 && scored.Result == 0 && scored.Board.Turn == 1, "Undo kept the old chess result.");
            scored.Again(null, "black"); scored.Resign(); scored.Resign();
            must(score.Her == 1 && scored.Result == 2 && scored.You == -1, "Chess resignation or side was wrong.");
            scored.Again("easy", "white");
            must(score.Her == 1 && scored.Level == "easy", "New chess lost session scores.");
            must(scored.Move(scored.Board.Find("e2e4"), null) && scored.Move(scored.Board.Find("e7e5"), new ChessChoice()), "Chess round fixture failed.");
            scored.Undo();
            must(scored.Board.Fen() == ChessPosition.Start, "Chess undo did not return the user's full turn.");
            scored.Move(scored.Board.Find("e2e4"), null); scored.Undo();
            must(scored.Board.Fen() == ChessPosition.Start, "Chess undo while Capri thinks did not restore the position.");
            ChessGame drawn = new ChessGame(score, "normal", "white");
            drawn.Board = new ChessPosition("7k/8/5QK1/8/8/8/8/8 w - -");
            must(drawn.Move(drawn.Board.Find("f6f7"), null) && drawn.Result == 3 && score.Draws == 1, "Chess draw did not reach the session score.");
            drawn.Undo();
            must(score.Draws == 0, "Undo kept a chess draw score.");
            ChessGame moments = new ChessGame(new MiniScore(), "normal", "white");
            moments.Board = new ChessPosition("4k3/8/8/8/4q3/8/4R3/4K3 w - -");
            must(moments.Move(moments.Board.Find("e2e4"), null) && moments.Moment == "her_queen", "Taking her queen did not reach chess commentary.");
            moments.Again(null, "black");
            moments.Board = new ChessPosition("4k3/8/8/8/4q3/8/4R3/4K3 w - -");
            must(moments.Move(moments.Board.Find("e2e4"), new ChessChoice()) && moments.Moment == "your_queen", "Taking their queen did not reach chess commentary.");
            moments.Again(null, "white");
            moments.Move(moments.Board.Find("e2e4"), null); moments.Move(moments.Board.Find("e7e5"), new ChessChoice { Score = 0 });
            moments.Move(moments.Board.Find("g1f3"), null); moments.Move(moments.Board.Find("b8c6"), new ChessChoice { Score = 250 });
            must(moments.Moment == "blunder", "A lost two-pawn evaluation did not reach chess commentary.");
            checks.Add("PASS chess session wins, losses, draws, resign, side selection, new game and full-turn undo including a pending reply");
            Func<string, ToolArguments> inputWas = Hands.MiniInput;
            Func<ToolArguments, string> miniWas = Hands.Mini;
            try
            {
                Hands.MiniInput = delegate { return null; };
                string routed; ToolArguments arguments;
                foreach (string ask in new[] { "capri let's play chess", "play chess with me", "chess", "play chess on hard", "play chess on easy", "play chess on normal", "play chess, i'll be black", "pull up chess", "open chess", "bring up the chess board", "open a game of chess", "show me your chess board" })
                    must(Hands.Heard(ask, out routed, out arguments) && routed == "mini_game" && arguments.Name == "chess" && Hands.Valid(routed, arguments), "Chess wording missed its native board: " + ask);
                Func<System.Collections.Generic.List<OpenWindow>> chessWindows = Hands.Windows;
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow>(); };
                foreach (string chessWords in new[] { "play this chess match with me", "capri play a chess match with me", "let's play this chess match", "play a game of chess with me", "play a round of chess", "play some chess", "play chess against me", "play this chess game on hard" })
                    must(Hands.Heard(chessWords, out routed, out arguments) && routed == "mini_game" && arguments.Name == "chess" && Hands.Valid(routed, arguments), "Chess wording missed its native board: " + chessWords);
                must(Hands.MiniName("play a game of tic tac toe with me") == "tic_tac_toe" && Hands.MiniName("play this connect four match") == "connect_four", "A board wording missed its game.");
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow> { new OpenWindow(new IntPtr(15), "Play Chess Online", "Opera") }; };
                must(Hands.Heard("play this chess match with me", out routed, out arguments) && routed == "use_computer" && arguments.Task == "play this chess match with me", "Her board opened over a chess match on screen.");
                Hands.Windows = chessWindows;
                must(Hands.Heard("play chess on hard", out routed, out arguments) && arguments.Level == "hard", "Chess lost the requested level.");
                Hands.MiniInput = ChessGame.Input;
                foreach (string command in new[] { "take that back", "undo", "new game", "i resign", "hint", "resign", "i'll be black" })
                    must(Hands.Heard(command, out routed, out arguments) && routed == "mini_game" && arguments.Name == "chess" && Hands.Valid(routed, arguments), "An open chess board missed: " + command);
                must(Hands.Heard("i'll be black", out routed, out arguments) && arguments.Side == "black" && arguments.Action == "again", "Chess side selection was lost.");
                foreach (string browser in new[] { "open chess.com", "play chess on chess.com", "play chess online" })
                    must(Hands.Heard(browser, out routed, out arguments) && routed == "open_website", "Chess stole a browser request: " + browser);
                must(ChessGame.Input("nice one") == null && Hands.MiniName("don't play chess") == null && Hands.MiniName("play chess on chess.com") == null, "Chess stole ordinary words.");
                must(Hands.Typed("mini_game{\"name\":\"chess\",\"action\":\"open\",\"level\":\"hard\",\"side\":\"black\"}", out routed, out arguments) && arguments.Level == "hard" && arguments.Side == "black", "Chess tool text lost its level or side.");
                Hands.Mini = delegate(ToolArguments called) { return called.Name + ":" + called.Action; };
                foreach (string action in new[] { "open", "again", "close", "undo", "hint", "resign", "level" }) must(Hands.Do("mini_game", new ToolArguments { Name = "chess", Action = action, Level = "hard", Side = "black" }) == "chess:" + action, "Chess action missed dispatch.");
                must(!Hands.Heard("show me chess openings", out routed, out arguments) || routed != "mini_game", "Talk about chess opened her board.");
                var catalogKept = Hands.Catalog;
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Calculator", "calculator-package!App") }; };
                foreach (string ask in new[] { "pull up a calculator", "open calculator", "bring up the calculator", "show me a calculator", "open calc" })
                    must(Hands.Heard(ask, out routed, out arguments) && routed == "open_app" && arguments.Name == "Calculator", "Calculator wording missed: " + ask);
                Hands.Catalog = catalogKept;
                must(Hands.Tools.Contains("chess") && Hands.ClaudeTools.Contains("chess") && Hands.Listing.Contains("easy|normal|hard") && Agent.Version >= 26, "Chess was missing from a tool schema or agent version.");
                checks.Add("PASS chess typed and spoken requests, board commands, browser exclusions, schema, text parser and action dispatch");
            }
            finally { Hands.MiniInput = inputWas; Hands.Mini = miniWas; }
            int lineCount = 0;
            foreach (string[] group in ChessLines.Lines) lineCount += group.Length;
            must(lineCount >= 30, "Chess needs at least thirty stock lines.");
            MiniChat chatter = new MiniChat();
            scored.Moment = null; chatter.Observe(scored, new Random(1));
            must(chatter.Count == 0, "Chess spoke on a quiet move.");
            foreach (string moment in new[] { "your_queen", "her_queen", "your_check", "her_check", "won", "lost", "blunder", "draw", "resign" })
            {
                scored.Moment = moment;
                chatter.Observe(scored, new Random(2));
                MiniLine line = chatter.Take(8);
                must(line != null && line.Local && line.Said == line.Fallback && line.Said.Length > 0, "A chess moment needed an API line: " + moment);
            }
            checks.Add("PASS chess has " + lineCount + " local stock lines for queens, checks, mate, blunders, draws and resignations; quiet moves stay quiet");
            ChessPosition hardPosition = new ChessPosition(positions[1]);
            string workerBefore = hardPosition.Fen();
            int caller = Thread.CurrentThread.ManagedThreadId;
            Stopwatch elapsed = Stopwatch.StartNew();
            ChessWork hardWork = ChessWork.Start(hardPosition, "hard", 4);
            while (!hardWork.Done && elapsed.ElapsedMilliseconds < 5000) Thread.Sleep(5);
            if (!hardWork.Done) { hardWork.Cancelled = true; checks.Add("LIMIT chess hard worker did not get enough CPU within 5 seconds on this host"); }
            else
            {
                must(hardWork.Error == null && hardWork.Choice != null && hardWork.Choice.Worker != caller && hardPosition.Find(hardWork.Choice.Move.Text).From >= 0 && hardPosition.Fen() == workerBefore && hardPosition.History.Count == 1, "Chess worker failed, used the caller, or changed the live board.");
                checks.Add((elapsed.ElapsedMilliseconds <= 3500 ? "PASS" : "LIMIT") + " chess hard worker: " + hardWork.Choice.Move.Text + ", depth " + hardWork.Choice.Depth + ", " + hardWork.Choice.Nodes + " nodes, " + elapsed.ElapsedMilliseconds + " ms; target 2500 ms search, 3500 ms including scheduling");
            }
            ChessWork cancelledWork = ChessWork.Start(hardPosition, "hard", 5);
            cancelledWork.Cancelled = true;
            Stopwatch cancelWait = Stopwatch.StartNew();
            while (!cancelledWork.Done && cancelWait.ElapsedMilliseconds < 2000) Thread.Sleep(5);
            checks.Add(cancelledWork.Done ? "PASS chess worker cooperatively cancels without touching the live board" : "LIMIT chess cancellation worker could not be scheduled within 2 seconds");
            try
            {
                foreach (float drawScale in new[] { 1f, 1.5f, 2f })
                    foreach (string drawSide in new[] { "white", "black" })
                    {
                        ChessGame picture = new ChessGame(new MiniScore(), "normal", drawSide);
                        using (Bitmap image = ChessBoard.Render(picture, drawScale, ChessPosition.At("e2"), picture.Board.Legal(), new ChessMove(-1, -1, 0), false, ""))
                            must(image.Width == (int)(ChessBoard.Wide * drawScale) && image.Height == (int)(ChessBoard.Tall * drawScale) && image.GetPixel(0, 0).A == 0, "Chess drawing lost its DPI or clipped corners.");
                    }
                must(ChessBoard.Tile(ChessPosition.At("a1"), 1).Y > ChessBoard.Tile(ChessPosition.At("a8"), 1).Y && ChessBoard.Tile(ChessPosition.At("a1"), -1).Y < ChessBoard.Tile(ChessPosition.At("a8"), -1).Y, "Chess did not rotate for black.");
                must(ChessBoard.BoardScale(192, new Rectangle(0, 0, 480, 634)) == 1, "Chess did not fit a small working area.");
                checks.Add("PASS chess draws both sides at 100%, 150%, 200% with shape pieces and fits the monitor");
            }
            catch (System.Runtime.InteropServices.ExternalException) { checks.Add("LIMIT chess bitmap drawing: GDI is unavailable on this host"); }
        }

        private void SmokeChessBoard(System.Collections.Generic.List<string> checks)
        {
            if (!Environment.UserInteractive) { checks.Add("LIMIT chess live board: no interactive desktop for mouse, promotion, commands, cancellation and close checks"); return; }
            Action<bool, string> must = delegate(bool okay, string why) { if (!okay) throw new Exception(why); };
            string brainWas = brain.Model;
            Func<string, string, byte[][], string> headWas = headTest;
            Func<string, byte[]> speakWas = Speak, freeWas = FreeSpeak;
            Action<string> asideWas = asideTest;
            TalkState talkWas = talkState;
            bool topWas = preferences.OnTop;
            int escWas = escAsk;
            double voiceWas = voiceUntil;
            try
            {
                brain.Model = null;
                escAsk = -1;
                headTest = delegate { throw new Exception("Chess asked a brain for a stock line."); };
                Speak = delegate { throw new Exception("Chess asked a paid voice for a line."); };
                FreeSpeak = delegate { return null; };
                string spoken = null;
                asideTest = delegate(string line) { spoken = line; };
                must(HearMini("capri let's play chess"), "Native chess did not open through text without a brain.");
                ChessBoard opened = chess;
                must(opened != null && minis == null && opened.Game.You == 1 && opened.Game.Level == "normal" && Hands.MiniBoard().Contains("CHESS"), "Chess did not use the mini-game opening path.");
                Func<int, Point> middle = delegate(int square)
                {
                    RectangleF tile = ChessBoard.Tile(square, opened.Game.You);
                    return new Point((int)((tile.X + tile.Width / 2) * opened.ScaleShown), (int)((tile.Y + tile.Height / 2) * opened.ScaleShown));
                };
                opened.Command("level", "hard", null);
                opened.ClickAt(middle(ChessPosition.At("e2")));
                opened.ClickAt(middle(ChessPosition.At("e4")));
                ChessWork pending = opened.Pending;
                must(pending != null && opened.Game.Board.Cells[ChessPosition.At("e4")] == 1, "Chess click move did not start a worker.");
                must(VoiceMini("take that back") && pending.Cancelled && opened.Game.Board.Fen() == ChessPosition.Start, "Spoken chess undo did not cancel and restore.");
                Stopwatch unwind = Stopwatch.StartNew();
                while (!pending.Done && unwind.ElapsedMilliseconds < 2000) { Application.DoEvents(); Thread.Sleep(5); }
                Application.DoEvents();
                must(opened.Game.Board.Fen() == ChessPosition.Start && !opened.Busy, "A stale reply landed after undo.");
                opened.DragTo(middle(ChessPosition.At("d2")), middle(ChessPosition.At("d4")));
                must(opened.Game.Board.Cells[ChessPosition.At("d4")] == 1, "Chess drag did not move a pawn.");
                ChessWork beforeNew = opened.Pending;
                must(HearMini("new game") && beforeNew.Cancelled && opened.Game.Board.Fen() == ChessPosition.Start, "New game did not cancel a pending chess reply.");
                must(VoiceMini("i'll be black") && opened.Game.You == -1 && opened.Busy, "Black did not rotate the board and start Capri as white.");
                must(HearMini("new game") && opened.Game.You == -1, "New chess did not keep the user's side.");
                opened.Command("again", "normal", "white");
                opened.Game.Board = new ChessPosition("7k/P7/6K1/8/8/8/8/8 w - -");
                opened.Command("level", "normal", null);
                opened.ClickAt(middle(ChessPosition.At("a7"))); opened.ClickAt(middle(ChessPosition.At("a8")));
                must(opened.Game.Board.Cells[ChessPosition.At("a7")] == 1 && !opened.Busy, "Promotion auto-picked a queen before the user's choice.");
                RectangleF knight = ChessBoard.Button(143);
                opened.ClickAt(new Point((int)((knight.X + knight.Width / 2) * opened.ScaleShown), (int)((knight.Y + knight.Height / 2) * opened.ScaleShown)));
                must(opened.Game.Board.Cells[ChessPosition.At("a8")] == 2 && opened.Game.Result == 3, "The mouse promotion picker lost its knight or insufficient-material draw.");
                opened.Command("again", "normal", "white");
                must(VoiceMini("hint") && opened.Busy, "Spoken hint did not start its own worker.");
                ChessWork beforeResign = opened.Pending;
                must(HearMini("i resign") && beforeResign.Cancelled && opened.Game.Result == 2, "Resign did not finish the game and cancel its hint.");
                miniChat.Last = clock.Elapsed.TotalSeconds - 8; talkState = TalkState.Off; voiceUntil = 0;
                MiniTick(); MiniTick();
                must(spoken != null && miniLine == null, "Chess did not deliver a stock outcome through mini commentary.");
                preferences.OnTop = !topWas; Layer();
                must(opened.Above == preferences.OnTop, "Chess did not follow Always on top.");
                opened.Command("again", "hard", "black");
                ChessWork beforeClose = opened.Pending;
                RectangleF close = ChessBoard.Button(128);
                opened.ClickAt(new Point((int)((close.X + 15) * opened.ScaleShown), (int)((close.Y + 15) * opened.ScaleShown)));
                must(chess == null && opened.IsDisposed && beforeClose.Cancelled && !opened.Ticking && opened.Image == null && miniContext.Length == 0, "Closing chess kept its board, timer, worker or context.");
                checks.Add("PASS chess opens without a brain; mouse click and drag, promotion choice, text and voice commands, local lines, topmost, worker cancellation and immediate close use the mini-game path");
            }
            catch (System.ComponentModel.Win32Exception unavailable) { checks.Add("LIMIT chess live board: Windows could not open it on this desktop (" + unavailable.NativeErrorCode + ")"); }
            finally
            {
                CloseMinis(); miniScores.Remove("chess");
                brain.Model = brainWas; headTest = headWas; Speak = speakWas; FreeSpeak = freeWas; asideTest = asideWas;
                talkState = talkWas; preferences.OnTop = topWas; escAsk = escWas; voiceUntil = voiceWas;
                // Turning Always on top off made her pill, box and typer not-topmost, and Windows takes their owner, her, down with them.
                // Putting them back up doesn't lift her, so Layer lifts her herself.
                if (!topWas && IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                Layer();
            }
        }

        private void SmokeInk(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.List<InkShape> inkGood = Ink.Parse("line 1 2 3 4; arrow(10,20,30,40); circle [10,20,50,60]; box 80 90 20 30; path 0 0 10 20 30 40; text 12 15 \"hi; choom\"");
            if (inkGood.Count != 6 || inkGood[4].Points.Length != 3 || inkGood[5].Text != "hi; choom") throw new Exception("Ink lost a good shape or its text.");
            if (Ink.Parse("line 1 2 3 4; triangle 1 2 3 4; circle 1 1 1 9; path 1 2 3; line NaN 2 3 4; text 10 20 hi; arrow bad; box 10 20 30 40").Count != 3 || Ink.Parse("").Count != 0 || Ink.Parse("[]").Count != 0) throw new Exception("Bad ink spoiled good shapes or an empty list drew something.");
            if (Ink.Parse("LINE -1.5 +2 3e1 4\nbox (1, 2, 3, 4)\npath [1,2], [3,4], [5,6]").Count != 3) throw new Exception("Ink did not read loose numbers and point lists.");
            checks.Add("PASS ink parses all six shapes, loose points, mixed good and bad shapes and empty lists");
            string[,] inkRequests =
            {
                { "draw a circle around the start button", "use_computer" },
                { "circle the start button", "use_computer" },
                { "point at the save button", "use_computer" },
                { "underline that word", "use_computer" },
                { "draw an arrow to the clock", "use_computer" },
                { "show me where to click", "use_computer" },
                { "draw me a cat", "draw" },
                { "draw on my screen", "draw" },
                { "write hi on my screen", "draw" },
                { "clear your drawing", "draw" },
                { "add a circle around the start button", "use_computer" },
                { "draw me a cat, add it", "draw" }
            };
            for (int inkRequestIndex = 0; inkRequestIndex < inkRequests.GetLength(0); inkRequestIndex++)
            {
                string inkHeardTool;
                ToolArguments inkHeardArgs;
                string inkWording = inkRequests[inkRequestIndex, 0];
                if (!Hands.Heard(inkWording, out inkHeardTool, out inkHeardArgs) || inkHeardTool != inkRequests[inkRequestIndex, 1] || !Hands.Wants(inkWording) || !Hands.Valid(inkHeardTool, inkHeardArgs)) throw new Exception("A drawing request missed her hands: " + inkWording);
                if (inkHeardTool == "use_computer" && inkHeardArgs.Task != inkWording) throw new Exception("A drawing job lost their exact words.");
            }
            foreach (string inkChat in new[] { "don't draw on my screen", "I drew a cat", "if you draw a cat", "draw a cat in paint" })
            {
                string inkChatTool;
                ToolArguments inkChatArgs;
                if (Hands.Heard(inkChat, out inkChatTool, out inkChatArgs) && inkChatTool == "draw") throw new Exception("Ink took conversation or another app's job.");
            }
            if (DrawTool(new ToolArguments()) != Ink.Question || Hands.Pulled(Ink.Question) != Ink.Question || Hands.Pulled("Cleared my drawing.") != "Cleared my drawing.") throw new Exception("An empty drawing request or a clear needed another model reply.");
            Func<bool> inkActiveWas = Ink.Active;
            try
            {
                Ink.Active = delegate { return true; };
                foreach (string inkClear in new[] { "clear your drawing", "rub that out", "erase that", "Hey Capri, can you clear your drawing please?", "remove it", "get rid of that", "clear my screen", "delete the diagram", "remove the art from my screen", "take it off my screen", "erase everything", "Capri, can you get rid of the drawing please?" })
                {
                    string inkClearTool;
                    ToolArguments inkClearArgs;
                    if (!Hands.Heard(inkClear, out inkClearTool, out inkClearArgs) || inkClearTool != "draw" || inkClearArgs.Action != "clear" || inkClearArgs.Description != null || Asides.Plain(inkClear, out inkClearTool, out inkClearArgs) != AsideKind.Tool) throw new Exception("Clearing ink needed a brain: " + inkClear);
                }
                foreach (string inkKept in new[] { "remove the song from my playlist", "delete it from my downloads", "clear my history", "get rid of the virus", "take it off", "remove him from the call" })
                {
                    ToolArguments inkKeptArgs = Ink.Request(Hands.Asked(inkKept));
                    if (inkKeptArgs != null && inkKeptArgs.Action == "clear") throw new Exception("Her ink took a wipe that wasn't about it: " + inkKept);
                }
                ToolArguments inkAdd = Ink.Request("add a dog");
                if (inkAdd == null || inkAdd.Action != "add" || inkAdd.Task == null) throw new Exception("Adding to an existing drawing did not look at its placement.");
                if (Ink.Request("add milk to my shopping list") != null || Ink.Request("add a reminder for 5") != null) throw new Exception("Her ink took an add that wasn't about it.");
            }
            finally { Ink.Active = inkActiveWas; }
            if (Ink.Request("erase that") != null || Ink.Request("rub it out") != null || Ink.Request("remove it") != null || Ink.Request("get rid of that") != null || Ink.Request("clear your drawing") == null) throw new Exception("Erase took a request with nothing drawn, or clear your drawing stopped working.");
            foreach (string diagramAsk in new[] { "Capri, can you make a diagram and help me understand linear algebra?", "make me a diagram of how neural networks work", "make a diagram of a vector", "show me a diagram of gradient descent", "draw me a diagram of a matrix", "explain eigenvectors with a diagram", "help me understand linear algebra with a diagram", "help me understand vectors and make a diagram", "make a flowchart of how a bill becomes law", "make me a mind map of machine learning", "create a bar chart of the planets by size", "make a diagram of how data gets to the model", "I'm learning machine learning, can you make a diagram of a neuron?", "so like capri can you make a diagram and help me understand linear algebra" })
            {
                string diagramTool;
                ToolArguments diagramArgs;
                if (!Hands.Heard(diagramAsk, out diagramTool, out diagramArgs) || diagramTool != "draw" || diagramArgs.Task != null || !Ink.Teaches(diagramArgs.Description) || !Hands.Wants(diagramAsk)) throw new Exception("A diagram ask didn't reach her ink: " + diagramAsk + " (" + diagramTool + ")");
            }
            foreach (string notDiagram in new[] { "send the diagram to John", "what's a diagram", "open my diagram", "find the diagram in my downloads", "look at this diagram", "show me the charts", "show me my diagram", "make a diagram in excel", "draw a flowchart in visio", "make a chart in google sheets", "do diagrams help people learn", "help me with this diagram" })
                if (Ink.Request(Hands.Asked(notDiagram)) != null) throw new Exception("Her ink took something that wasn't a diagram to draw: " + notDiagram);
            ToolArguments diagramBare = Ink.Request("make a diagram");
            if (diagramBare == null || diagramBare.Description != null || diagramBare.Task != null) throw new Exception("A bare diagram ask didn't ask what to draw.");
            if (Ink.Teaches("a cat") || Ink.Teaches("write hi") || !Ink.Teaches("diagram of a vector") || !Ink.Teaches("show how a neuron works")) throw new Exception("Her ink told teaching from art wrongly.");
            System.Collections.Generic.List<InkShape> diagramShapes = Ink.Parse("box 10 10 60 60; text 20 20 vector v; text 20 90 matrix A");
            string diagramResult = Ink.Explained("Drew on your screen.", diagramShapes), diagramFailed = Ink.Explained("Couldn't read any shapes to draw.", diagramShapes);
            if (diagramResult != "Drew on your screen: vector v; matrix A." || !Hands.Diagrammed(diagramResult) || Hands.Pulled(diagramResult) != null || diagramFailed != "Couldn't read any shapes to draw." || Hands.Diagrammed(diagramFailed) || Hands.Diagrammed("Drew on your screen.")) throw new Exception("A diagram's result read wrong: " + diagramResult);
            Func<string, string> diagramSays = delegate(string text) { return "{\"message\":{\"role\":\"assistant\",\"content\":" + Voice.Quote(text) + "},\"done_reason\":\"stop\"}"; };
            System.Collections.Generic.List<string> diagramAsked = new System.Collections.Generic.List<string>();
            System.Net.Sockets.TcpListener diagramServer = null;
            string diagramOllama = Brain.Ollama;
            try
            {
                Brain.Ollama = FakeServer(new[] { diagramSays("A vector is an arrow, and the matrix moves it. See how v lands on Av?") }, diagramAsked, out diagramServer);
                Brain teacher = new Brain { Model = "teach-check" };
                teacher.Act = delegate(string name, ToolArguments args) { return name == "draw" && args.Description != null ? diagramResult : "Wrong tool: " + name; };
                string taught = teacher.Ask("Capri, can you make a diagram and help me understand linear algebra?");
                if (taught != "A vector is an arrow, and the matrix moves it. See how v lands on Av?" || diagramAsked.Count != 1 || diagramAsked[0].IndexOf("Help them understand it", StringComparison.Ordinal) < 0 || diagramAsked[0].IndexOf("one short sentence", StringComparison.Ordinal) >= 0 || diagramAsked[0].IndexOf("vector v; matrix A", StringComparison.Ordinal) < 0) throw new Exception("Her reply didn't talk a diagram through: " + taught);
            }
            finally
            {
                Brain.Ollama = diagramOllama;
                if (diagramServer != null) diagramServer.Stop();
            }
            foreach (string inkClaim in new[] { "Done, wiped it!", "Cleared it, choom.", "Cleared!", "Poof, all gone. I erased your drawing.", "I've removed the diagram from your screen.", "Got rid of it!", "On it, clearing it now.", "Let me wipe that off your screen.", "Okay choom, I just deleted the drawing." })
                if (!Hands.Promised(inkClaim)) throw new Exception("She claimed a wipe no tool did and it slipped through: " + inkClaim);
            foreach (string inkTalk in new[] { "Let me clear that up for you.", "Deleted scenes are the best part.", "Cleared for takeoff, choom!", "Wiped out, choom. Long day.", "I'll remove all doubt: pineapple wins.", "Erasing history is a villain move." })
                if (Hands.Promised(inkTalk)) throw new Exception("Plain chat counted as a wipe: " + inkTalk);
            System.Collections.Generic.List<string> wipeAsked = new System.Collections.Generic.List<string>();
            System.Net.Sockets.TcpListener wipeServer = null;
            string wipeOllama = Brain.Ollama;
            Func<string> wipeGameWas = Computer.GameOpen;
            try
            {
                // Her brain says it wiped the ink with no tool call, so her hands get a go and clear it for real.
                Brain.Ollama = FakeServer(new[] { diagramSays("Done, wiped it clean, choom!"), "{\"message\":{\"role\":\"assistant\",\"content\":\"\",\"tool_calls\":[{\"function\":{\"name\":\"draw\",\"arguments\":{\"action\":\"clear\"}}}]},\"done_reason\":\"stop\"}" }, wipeAsked, out wipeServer);
                Computer.GameOpen = delegate { return null; };
                System.Collections.Generic.List<string> wipeDid = new System.Collections.Generic.List<string>();
                Brain wiper = new Brain { Model = "wipe-check" };
