        private void SmokeMinis(System.Collections.Generic.List<string> checks)
        {
            SmokeChess(checks);
            SmokeChessBoard(checks);
            Action<bool, string> must = delegate(bool okay, string why) { if (!okay) throw new Exception(why); };
            int[,] lines = { { 0, 1, 2 }, { 3, 4, 5 }, { 6, 7, 8 }, { 0, 3, 6 }, { 1, 4, 7 }, { 2, 5, 8 }, { 0, 4, 8 }, { 2, 4, 6 } };
            for (int owner = 1; owner <= 2; owner++)
                for (int line = 0; line < 8; line++)
                {
                    int[] won = new int[9];
                    for (int mark = 0; mark < 3; mark++) won[lines[line, mark]] = owner;
                    must(MiniGame.Outcome(won, false) == owner, "A tic-tac-toe winning line was missed.");
                }
            int[] tied = { 1, 2, 1, 1, 2, 2, 2, 1, 1 };
            must(MiniGame.Outcome(tied, false) == 3 && MiniGame.Outcome(new int[9], false) == 0, "Tic-tac-toe draw or empty board was wrong.");
            MiniGame tiedGame = new MiniGame("tic_tac_toe", new MiniScore(), new Random(2));
            Array.Copy(tied, tiedGame.Cells, 9); tiedGame.Cells[8] = 0;
            must(tiedGame.Move(8) && tiedGame.Result == 3 && tiedGame.Score.Draws == 1, "A drawn game didn't reach the session score.");
            int endings = MinisUnbeaten(new int[9], 1);
            int throws = 0;
            for (int seed = 0; seed < 400; seed++)
            {
                MiniGame forgiving = new MiniGame("tic_tac_toe", new MiniScore(), new Random(seed));
                forgiving.Move(0);
                if (MiniGame.TicValue(forgiving.Cells, 1) < 0) throws++;
            }
            must(throws >= 85 && throws <= 115, "Her wrong move wasn't about one game in four: " + throws);
            checks.Add("PASS minis: all tic-tac-toe wins and draws; perfect minimax never loses across " + endings + " user continuations; " + throws + " of 400 seeded games give an opening");

            int[,] fourLines = { { 35, 36, 37, 38 }, { 3, 10, 17, 24 }, { 14, 22, 30, 38 }, { 20, 26, 32, 38 } };
            for (int fourOwner = 1; fourOwner <= 2; fourOwner++)
                for (int fourLine = 0; fourLine < 4; fourLine++)
                {
                    int[] wonFour = new int[42];
                    for (int fourMark = 0; fourMark < 4; fourMark++) wonFour[fourLines[fourLine, fourMark]] = fourOwner;
                    must(MiniGame.Outcome(wonFour, true) == fourOwner, "Connect four missed a direction.");
                }
            int[] filled = new int[42];
            for (int disc = 0; disc < 6; disc++)
            {
                int landing = MiniGame.Landing(filled, 2);
                must(landing == (5 - disc) * 7 + 2, "A disc didn't fall to the bottom.");
                filled[landing] = disc % 2 + 1;
            }
            must(MiniGame.Landing(filled, 2) == -1 && MiniGame.Landing(filled, -1) == -1 && MiniGame.Landing(filled, 7) == -1, "A full or missing column accepted a disc.");
            must(MiniGame.FourMove(filled, new Random(8)) != 2, "She chose a full column.");
            int[] fourDraw = new int[42];
            string drawRows = "112211222112211122112221122111221122211221";
            for (int drawCell = 0; drawCell < 42; drawCell++) fourDraw[drawCell] = drawRows[drawCell] - '0';
            must(MiniGame.Outcome(fourDraw, true) == 3, "Connect four's full draw was wrong.");
            int[] tactical = new int[42];
            tactical[35] = tactical[36] = tactical[37] = 2;
            must(MiniGame.FourMove(tactical, new Random(9)) == 3, "She missed her fourth disc.");
            tactical[35] = tactical[36] = tactical[37] = 1;
            must(MiniGame.FourMove(tactical, new Random(10)) == 3, "She missed the block.");
            int[] wrapped = new int[42];
            wrapped[33] = wrapped[34] = wrapped[35] = wrapped[36] = 1;
            must(MiniGame.Outcome(wrapped, true) == 0, "Connect four wrapped a row into a win.");
            MiniGame fullGame = new MiniGame("connect_four", new MiniScore(), new Random(11));
            Array.Copy(filled, fullGame.Cells, 42);
            must(!fullGame.Move(2) && fullGame.Cells[2] == filled[2], "A full column changed the game.");
            checks.Add("PASS minis: connect four wins in all directions, draws, gravity, full columns, a depth-five win and block, and no row wrapping");

            for (int yourHand = 0; yourHand < 3; yourHand++)
                for (int herHand = 0; herHand < 3; herHand++)
                {
                    int expected = yourHand == herHand ? 0 : (yourHand == 0 && herHand == 2) || (yourHand == 1 && herHand == 0) || (yourHand == 2 && herHand == 1) ? 1 : 2;
                    must(MiniGame.HandResult(yourHand, herHand) == expected, "Rock paper scissors got a pair wrong.");
                }
            MiniScore rpsScore = new MiniScore();
            MiniGame rps = new MiniGame("rock_paper_scissors", rpsScore, new MiniDice());
            rps.Move(0);
            must(rps.You == 0 && rps.Her == 0 && rps.Result == 0, "Tied hands scored a point.");
            rps.Move(1); rps.Move(1);
            must(rps.Result == 0 && rps.You == 2, "Rock paper scissors ended before three.");
            rps.Move(1);
            must(rps.Result == 1 && rpsScore.You == 1 && !rps.Move(2), "First to three did not end exactly once.");
            rps.Again(); rps.Move(2); rps.Move(2); rps.Move(2);
            must(rps.Result == 2 && rpsScore.Her == 1 && rpsScore.You == 1, "A rematch lost the session score.");
            checks.Add("PASS minis: all nine hand pairs, ties, first to three, no moves after the result, and session scores across rematches");

            MiniGame written = new MiniGame("tic_tac_toe", new MiniScore(), new Random(13));
            written.Cells[0] = 1; written.Cells[4] = 2;
            must(written.BoardText().Contains("X . .\n. O .\n. . .\n") && written.BoardText().Contains("User to move") && written.BoardText().Contains("X = user, O = Capri"), "The board text didn't match its cells and turn.");
            must(fullGame.BoardText().Contains("1 2 3 4 5 6 7") && rps.BoardText().Contains("Capri points: 3") && rps.BoardText().Contains("user scissors, Capri rock"), "A board's columns or hands were missing from her context.");
            must(MiniGame.Input("tic_tac_toe", "top left") == 0 && MiniGame.Input("tic_tac_toe", "middle") == 4 && MiniGame.Input("tic_tac_toe", "bottom right") == 8 && MiniGame.Input("connect_four", "column 3") == 2 && MiniGame.Input("connect_four", "column seven") == 6 && MiniGame.Input("rock_paper_scissors", "rock") == 0 && MiniGame.Input("tic_tac_toe", "nice one") == -1, "Board moves stole chat or missed a move.");
            MiniChat chatter = new MiniChat();
            MiniDice rolls = new MiniDice();
            chatter.Observe(written, 0, rolls);
            must(chatter.Count == 0, "She spoke for every move.");
            chatter.Observe(written, 0, rolls);
            must(chatter.Take(0) != null, "An occasional comment was lost.");
            chatter.Last = 0;
            written.Result = 1; chatter.Observe(written, 1, rolls);
            written.Result = 2; chatter.Observe(written, 2, rolls);
            written.Result = 3; chatter.Observe(written, 3, rolls);
            must(chatter.Take(7.99) == null && chatter.Count == 1, "Outcomes built a backlog or broke the eight-second spacing.");
            MiniLine drawLine = chatter.Take(8);
            must(drawLine.Result == 3 && drawLine.Fallback.Length > 0 && drawLine.Board.Contains("Draw") && chatter.Take(16) == null, "The newest outcome or its offline line was lost.");
            for (int quickRound = 0; quickRound < 100; quickRound++) { written.Result = quickRound % 3 + 1; chatter.Observe(written, 9, rolls); }
            must(chatter.Count == 1 && chatter.Take(16).Result == written.Result, "Fast rounds queued stale commentary.");
            checks.Add("PASS fast mini-game rounds keep only the newest waiting result and preserve commentary spacing");
            MiniChat rematchLines = new MiniChat();
            written.Result = 0;
            rematchLines.Observe(written, 0, rolls); rematchLines.Observe(written, 0, rolls);
            rematchLines.NewRound();
            must(rematchLines.Count == 0, "A rematch kept a comment about the previous board.");
            written.Result = 1; rematchLines.Observe(written, 0, rolls); rematchLines.NewRound();
            must(rematchLines.Count == 1, "A rematch dropped the previous result line.");
            checks.Add("PASS minis: exact board text, spoken squares and columns, ordinary chat left alone, occasional lines at least eight seconds apart, and the newest final result queued with an offline line");

            Func<System.Collections.Generic.List<InstalledApp>> catalogBefore = Hands.Catalog;
            Func<System.Collections.Generic.List<OpenWindow>> windowsBefore = Hands.Windows;
            Func<string> gameBefore = Hands.GameOpen;
            try
            {
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Minecraft", "minecraft-smoke") }; };
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow> { new OpenWindow(new IntPtr(15), "Stardew Valley", "Stardew Valley") }; };
                Hands.GameOpen = delegate { return "Stardew Valley"; };
                Hands.Forget();
                string[,] asks = { { "play tic tac toe", "tic_tac_toe" }, { "play tic-tac-toe with me", "tic_tac_toe" }, { "wanna play connect four", "connect_four" }, { "rock paper scissors", "rock_paper_scissors" }, { "play connect 4", "connect_four" } };
                for (int ask = 0; ask < asks.GetLength(0); ask++)
                {
                    string routed; ToolArguments arguments;
                    must(Hands.Direct(asks[ask, 0], out routed, out arguments) && routed == "mini_game" && arguments.Name == asks[ask, 1], "A desktop game was routed wrong: " + asks[ask, 0]);
                    must(Hands.Heard("Hey Capri, " + asks[ask, 0] + " please", out routed, out arguments) && routed == "mini_game" && arguments.Name == asks[ask, 1], "A spoken desktop game was routed wrong.");
                }
                string named; ToolArguments namedArgs;
                must(Hands.Direct("play minecraft", out named, out namedArgs) && named == "use_computer" && namedArgs.Task == "play minecraft", "Minecraft stopped being a job she plays.");
                must(!Hands.Direct("play wasd minigame", out named, out namedArgs) && !Hands.Direct("play Stardew Valley", out named, out namedArgs) && !Hands.Heard("keep playing", out named, out namedArgs), "An external game became a board or a song.");
                must(Hands.Direct("play some music", out named, out namedArgs) && named == "play_music", "Music stopped routing to music.");
                foreach (string notSong in new[] { "play this", "play that", "play tetris", "play solitaire", "play poker", "play a game of sudoku" })
                    must(!Hands.Direct(notSong, out named, out namedArgs), "A game went to Spotify: " + notSong);
                foreach (string titled in new[] { "play bohemian rhapsody", "play stay with me", "play this love", "play poker face", "play tetris on spotify" })
                    must(Hands.Direct(titled, out named, out namedArgs) && named == "play_music", "A song stopped routing to music: " + titled);
                must(Hands.Heard("play tic tac toe online", out named, out namedArgs) && named == "open_website" && namedArgs.Site == "google", "Online tic-tac-toe did not reach the browser.");
                foreach (string left in new[] { "don't play tic tac toe", "if we play tic tac toe", "play checkers", "play tic tac toe on youtube", "play tic tac toe and open discord", "top left", "middle", "column 3", "rock", "nice one", "you're cheating" })
                    must(!Hands.Heard(left, out named, out namedArgs) || named != "mini_game", "A board stole these words: " + left);
                must(Hands.Tools.Contains("mini_game") && Hands.ClaudeTools.Contains("mini_game") && Hands.Listing.Contains("mini_game") && Hands.Valid("mini_game", new ToolArguments { Name = "connect_four" }) && !Hands.Valid("mini_game", new ToolArguments { Name = "checkers" }), "The board tool wasn't registered or accepted another game.");
                must(Hands.Listing.Contains("tic_tac_toe|connect_four|rock_paper_scissors") && Hands.Typed("mini_game{\"name\":\"tic_tac_toe\",\"action\":\"open\"}", out named, out namedArgs) && named == "mini_game" && namedArgs.Name == "tic_tac_toe", "The text-only board tool was missing its arguments or parser.");
                checks.Add("PASS minis: chat and voice routes, registered tool, and Minecraft, WASD minigame, music, an already open game, online play and ordinary words keep their routes");
            }
            finally { Hands.Catalog = catalogBefore; Hands.Windows = windowsBefore; Hands.GameOpen = gameBefore; Hands.Forget(); }

            foreach (string paintedKind in new[] { "tic_tac_toe", "connect_four", "rock_paper_scissors" })
                foreach (float paintedScale in new[] { 1f, 1.5f, 2f })
                    using (Bitmap painted = MiniBoard.Render(new MiniGame(paintedKind, new MiniScore(), new Random(14)), paintedScale, 0, 0))
                    {
                        must(painted.Width == (int)(MiniBoard.Wide * paintedScale) && painted.Height == (int)(MiniBoard.Tall * paintedScale) && painted.GetPixel(0, 0).A == 0, "A board's DPI or clipped corners were wrong.");
                        painted.Save(Path.Combine(Path.GetDirectoryName(Brain.LogPath), "minis-" + paintedKind + "-" + paintedScale.ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + ".png"));
                    }
            checks.Add("PASS minis: all three Neon boards draw at 100%, 150% and 200% with transparent clipped corners");
            must(MiniBoard.BoardScale(144, new Rectangle(0, 0, 1920, 1080)) == 1.5f && MiniBoard.BoardScale(192, new Rectangle(0, 0, 1920, 1080)) == 2f && MiniBoard.BoardScale(192, new Rectangle(0, 0, 372, 486)) == 1f, "Board DPI did not fit its destination monitor.");
            checks.Add("PASS mini boards calculate scale from the destination monitor DPI and fit its work area");
            if (!Environment.UserInteractive) { checks.Add("LIMIT minis: no interactive desktop for board stop, DPI, topmost, clicking and closing checks"); return; }
            bool motionBefore = preferences.Motion;
            bool chatBefore = chatting, localBefore = local, dropBefore = dropping;
            int escBefore = escAsk;
            Func<string, string> thinkBefore = Think;
            TalkState talkBefore = talkState;
            double voiceBefore = voiceUntil;
            string brainBefore = brain.Model;
            Func<string, string, byte[][], string> headBefore = headTest;
            Action<string> asideBefore = asideTest;
            IGameStage stageBefore = Commentary.Stage;
            StageLog boardStage = new StageLog();
            System.Collections.Generic.List<string> linesSaid = new System.Collections.Generic.List<string>();
            string seenBoard = null;
            try
            {
                preferences.Motion = false;
                Think = delegate { throw new Exception("Opening a board called her brain."); };
                escAsk = asking;
                Hear("play tic tac toe");
                must(minis != null && minis.Visible && miniContext.Contains("TIC-TAC-TOE") && !minis.Ticking, "The board didn't open without her brain, or Motion off still ticked.");
                MiniBoard firstBoard = minis;
                bool boardTopWas = preferences.OnTop;
                try
                {
                    ToggleOnTop();
                    must(minis.Above == preferences.OnTop && ((Native.GetWindowLong(minis.Handle, -20) & 8) != 0) == preferences.OnTop, "The open board ignored Always on top.");
                    ToggleOnTop();
                    must(minis.Above == boardTopWas && ((Native.GetWindowLong(minis.Handle, -20) & 8) != 0) == boardTopWas, "The board did not restore its stacking.");
                }
                finally { if (preferences.OnTop != boardTopWas) ToggleOnTop(); }
                checks.Add("PASS an open mini board follows Always on top in both directions");
                try
                {
                    foreach (Screen boardScreen in Screen.AllScreens)
                    {
                        Rectangle boardArea = boardScreen.WorkingArea;
                        firstBoard.Open(new Rectangle(boardArea.Left + boardArea.Width / 2, boardArea.Top + boardArea.Height / 2, 80, 80));
                        Application.DoEvents();
                        must(Math.Abs(firstBoard.ScaleShown - MiniBoard.BoardScale(Native.GetDpiForWindow(firstBoard.Handle), boardArea)) < 0.01f && boardArea.Contains(firstBoard.Bounds), "A board read DPI before reaching its monitor.");
                        foreach (Screen movedScreen in Screen.AllScreens)
                        {
                            Rectangle movedArea = movedScreen.WorkingArea;
                            firstBoard.Location = new Point(movedArea.Left + movedArea.Width / 2, movedArea.Top + movedArea.Height / 2);
                            Application.DoEvents();
                            must(Math.Abs(firstBoard.ScaleShown - MiniBoard.BoardScale(Native.GetDpiForWindow(firstBoard.Handle), movedArea)) < 0.01f && movedArea.Contains(firstBoard.Bounds), "A board did not rescale when its monitor changed.");
                        }
                    }
                    firstBoard.Open(Bounds);
                    checks.Add("PASS mini boards read DPI after opening and rescale when moved across available monitors");
                    if (Screen.AllScreens.Length < 2) checks.Add("LIMIT mini board monitor-change checks: only one monitor is available");
                }
                catch (EntryPointNotFoundException) { checks.Add("LIMIT mini board DPI checks: this Windows has no GetDpiForWindow"); }
                RectangleF firstCell = MiniBoard.Part("tic_tac_toe", 0);
                firstBoard.ClickAt(new Point((int)((firstCell.X + 20) * firstBoard.ScaleShown), (int)((firstCell.Y + 20) * firstBoard.ScaleShown)));
                must(firstBoard.Game.Cells[0] == 1 && Hands.MiniBoard() == firstBoard.Game.BoardText(), "A board click or live brain context was lost.");
                string moveTool; ToolArguments moveArgs;
                must(Hands.Heard("middle", out moveTool, out moveArgs) && moveTool == "mini_game" && moveArgs.Action == "move" && !Hands.Heard("you're cheating", out moveTool, out moveArgs), "An open board didn't distinguish moves from chat.");
                firstBoard.Again(); firstBoard.Key(Keys.D5);
                must(firstBoard.Game.Cells[4] == 1, "The board's keyboard didn't play the middle.");
                firstBoard.Again();
                firstBoard.Game.Cells[0] = firstBoard.Game.Cells[1] = 1;
                firstBoard.Game.Cells[3] = firstBoard.Game.Cells[4] = 2;
                Commentary.Stage = boardStage;
                firstBoard.Key(Keys.D3);
                must(firstBoard.Game.Result == 1 && boardStage.Shown.Contains("mood Hit"), "A user win didn't set her losing mood.");
                int kept = firstBoard.Game.Score.You;
                miniChat.Last = clock.Elapsed.TotalSeconds - 8;
                talkState = TalkState.Off; voiceUntil = 0;
                asideTest = delegate(string lineSaid) { linesSaid.Add(lineSaid); };
                brain.Model = "mini-smoke";
                headTest = delegate(string system, string board, byte[][] pictures) { seenBoard = board; return "You took that whole row, choom."; };
                MiniTick();
                Stopwatch waited = Stopwatch.StartNew();
                while (miniLine != null && miniLine.Said == null && waited.ElapsedMilliseconds < 2000) { Application.DoEvents(); Thread.Sleep(5); }
                must(seenBoard != null && seenBoard.Contains("X X X") && seenBoard.Contains("User wins"), "Her quick head didn't see the actual finished board.");
                MiniTick();
                must(linesSaid.Count == 1 && linesSaid[0] == "You took that whole row, choom.", "Her quick line didn't reach her aside.");
                brain.Model = null;
                miniChat.Last = clock.Elapsed.TotalSeconds - 8;
                firstBoard.Game.Result = 2;
                MiniPlayed();
                must(boardStage.Shown.Contains("mood Happy"), "Her own win didn't set her happy mood.");
                MiniTick(); MiniTick();
                must(linesSaid.Count == 2, "An offline result lost its fallback line.");
                firstBoard.Key(Keys.Escape);
                must(firstBoard.IsDisposed && !firstBoard.IsHandleCreated && firstBoard.Image == null && !firstBoard.Ticking && minis == null && miniContext.Length == 0 && !miniTicks.Enabled && miniLine == null && miniChat.Count == 0, "Closing the board left a window, bitmap, timer, line or context behind.");
                MiniTool(new ToolArguments { Name = "tic_tac_toe" });
                must(minis.Game.Score.You == kept, "Closing the window lost the session score.");
                RectangleF closeBox = MiniBoard.Part("tic_tac_toe", 9);
                MiniBoard reopened = minis;
                reopened.ClickAt(new Point((int)((closeBox.X + 10) * reopened.ScaleShown), (int)((closeBox.Y + 10) * reopened.ScaleShown)));
                must(minis == null && reopened.IsDisposed, "The X did not close the board.");
                MiniTool(new ToolArguments { Name = "connect_four" });
                must(Hands.Heard("column 3", out moveTool, out moveArgs) && moveTool == "mini_game", "A spoken column missed the board.");
                DoTool(moveTool, moveArgs);
                must(minis.Game.Cells[37] == 1, "The spoken column didn't land at the bottom.");
                MiniTool(new ToolArguments { Name = "rock_paper_scissors" });
                must(Hands.Heard("rock", out moveTool, out moveArgs) && moveTool == "mini_game", "A spoken hand missed the board.");
                DoTool(moveTool, moveArgs);
                must(minis.Game.YourHand == 0 && !Hands.Heard("nice one", out moveTool, out moveArgs), "The spoken hand or ordinary chat was wrong.");
                chatting = true; local = false;
                ChatHeard("play tic tac toe");
                ChatHeard("top left");
                must(minis.Game.Cells[0] == 1 && dropping && talkState == TalkState.Off, "A voice move didn't play locally or added a reply for every move.");
                ChatHeard("nice one");
                must(!dropping && talkState == TalkState.Thinking && miniContext.Contains("X"), "Board chat stayed muted after a voice move.");
                Job boardJobWas = job;
                string boardWorkWas = working;
                Action<string> boardStopWas = stopTest;
                int boardStops = 0;
                try
                {
                    job = new Job("synthetic job", "synthetic job");
                    working = "Working";
                    stopTest = delegate { boardStops++; };
                    Hear("stop");
                    must(minis == null && boardStops == 1, "Typed stop closed the board without stopping the job.");
                    MiniTool(new ToolArguments { Name = "rock_paper_scissors" });
                    ChatHeard("stop");
                    must(minis == null && boardStops == 2, "Voice stop closed the board without stopping the job.");
                }
                finally { job = boardJobWas; working = boardWorkWas; stopTest = boardStopWas; }
                checks.Add("PASS typed and spoken stop close the mini board and stop a running computer job");
                chatting = chatBefore; local = localBefore; dropping = dropBefore;
                MiniTool(new ToolArguments { Name = "tic_tac_toe" });
                talkState = TalkState.Off;
                using (ManualResetEvent headStarted = new ManualResetEvent(false))
                using (ManualResetEvent headRelease = new ManualResetEvent(false))
                {
                    brain.Model = "mini-smoke";
                    headTest = delegate { headStarted.Set(); headRelease.WaitOne(2000); return "This late line must be discarded."; };
                    minis.Game.Result = 3; minis.Game.Last = "You played the middle.";
                    MiniPlayed(); miniChat.Last = clock.Elapsed.TotalSeconds - 8;
                    MiniTick();
                    must(headStarted.WaitOne(2000), "The delayed board head didn't start.");
                    int saidBeforeClose = linesSaid.Count;
                    CloseMinis(); headRelease.Set();
                    Stopwatch finishing = Stopwatch.StartNew();
                    while (miniHeadBusy && finishing.ElapsedMilliseconds < 2000) { Application.DoEvents(); Thread.Sleep(5); }
                    must(!miniHeadBusy && linesSaid.Count == saidBeforeClose && miniContext.Length == 0 && miniLine == null, "A delayed head spoke after the board closed.");
                }
                checks.Add("PASS minis: voice moves stay local and quiet, ordinary voice chat resumes, offline outcomes use fallback lines, and closing discards a late brain reply");
                checks.Add("PASS minis: the real window opens without a brain, accepts mouse, keyboard and spoken moves, shares its board with her quick head, sets her mood, keeps scores, and Esc or X disposes the board and bitmap and stops its timers");
            }
            catch (System.ComponentModel.Win32Exception error) { checks.Add("LIMIT minis: Windows could not open the board on this desktop (" + error.NativeErrorCode + ")"); }
            finally
            {
                CloseMinis(); miniScores.Clear();
                preferences.Motion = motionBefore; Think = thinkBefore; talkState = talkBefore; voiceUntil = voiceBefore;
                chatting = chatBefore; local = localBefore; dropping = dropBefore; escAsk = escBefore;
                brain.Model = brainBefore; headTest = headBefore; asideTest = asideBefore; Commentary.Stage = stageBefore;
            }
        }

        private static void SmokeGameAsks(System.Collections.Generic.List<string> checks)
        {
            string[] nope = { "Już, SoChi — odpalamy CS2 i gramy. Nie mam teraz sterowania komputerem, więc nie uruchomię go za ciebie; pokaż mi ekran po włączeniu, a przeprowadzę cię do meczu.", "This time I won't pretend I've already clicked anything — show me the game screen, and I'll guide you straight into a match.", "I can't actually click for you, but I can walk you through it.", "No tengo control de tu PC.", "Je ne peux pas cliquer pour toi.", "Ich kann das nicht klicken.", "Não consigo clicar nisso.", "Non posso cliccare.", "Не могу нажать на это." };
            foreach (string line in nope) if (!Hands.Denied(line)) throw new Exception("Her saying she has no hands wasn't caught: " + line);
            foreach (string line in new[] { "I can't believe you clicked that.", "You can't press that button yet, the round hasn't started.", "Nice shot, choom.", "Nie mam pojęcia, co to za gra.", "I can't play favourites." }) if (Hands.Denied(line)) throw new Exception("Plain chat counted as her having no hands: " + line);
            if (!Hands.Handed("act") || !Hands.Handed(" Act.") || !Hands.Handed("ACT\nOn it") || Hands.Handed("Act natural, choom.") || Hands.Handed("I love this act.")) throw new Exception("Her one-word job answer was misread.");
            string playTool;
            ToolArguments playArgs;
            if (Hands.Direct("play the game", out playTool, out playArgs) || Hands.Direct("play this match", out playTool, out playArgs)) throw new Exception("\"Play the game\" went to " + playTool + " instead of her hands.");
            if (!Hands.Wants("lets play cs") || !Hands.Wants("lets go play some valorant") || !Hands.Wants("go play minecraft")) throw new Exception("\"Lets play\" without its apostrophe missed her hands.");
            if (!Hands.Promised("Już, SoChi — odpalamy CS2.") || !Hands.Promised("Odpalamy!")) throw new Exception("A Polish promise with their name in it was missed.");
            if (Hands.GameNote(null) != "" || Hands.GameNote("Counter-Strike 2").IndexOf("Counter-Strike 2", StringComparison.Ordinal) < 0 || Hands.GameNote("Counter-Strike 2").IndexOf("use_computer", StringComparison.Ordinal) < 0) throw new Exception("Her hands weren't told about the open game.");
            if (Hands.Chat.IndexOf("only the word: act", StringComparison.Ordinal) < 0 || Hands.ChatOnly.IndexOf(": act", StringComparison.Ordinal) >= 0 || Hands.ChatOnly.IndexOf("never say you can't", StringComparison.Ordinal) < 0) throw new Exception("Her chat prompt lost its job word.");
            System.Collections.Generic.List<string> asked = new System.Collections.Generic.List<string>();
            System.Net.Sockets.TcpListener fake;
            string ollamaWas = Brain.Ollama;
            Func<string> openWas = Computer.GameOpen;
            Func<string, string> says = delegate(string text) { return "{\"message\":{\"role\":\"assistant\",\"content\":" + Voice.Quote(text) + "},\"done_reason\":\"stop\"}"; };
            Func<string, string, string> calls = delegate(string name, string json) { return "{\"message\":{\"role\":\"assistant\",\"content\":\"\",\"tool_calls\":[{\"function\":{\"name\":\"" + name + "\",\"arguments\":" + json + "}}]},\"done_reason\":\"stop\"}"; };
            Brain.Ollama = FakeServer(new string[]
            {
                says("act"), calls("open_app", "{\"name\":\"Counter-Strike 2\"}"), says("Otworzyłam CS2."),
                says("chat"), says(nope[1]), says("Już gram."),
                calls("use_computer", "{\"task\":\"kliknij deathmatch\"}"), says("Kliknęłam."),
                says("chat"), says("Clean shot, choom."),
                says("act"), says("chat"), says("chat"), says("Hah, you wish."),
                says(nope[0]), says("chat"), says("chat")
            }, asked, out fake);
            try
            {
                System.Collections.Generic.List<string> did = new System.Collections.Generic.List<string>();
                Brain playing = new Brain();
                playing.Model = "play-test";
                playing.Act = delegate(string name, ToolArguments args) { did.Add(name + ":" + (args.Name ?? args.Task)); return "Done."; };
                Computer.GameOpen = delegate { return null; };
                playing.Ask("dobra odpalaj csa i gramy");
                if (did.Count != 1 || did[0] != "open_app:Counter-Strike 2") throw new Exception("Her job word didn't reach her hands: " + string.Join(",", did.ToArray()));
                playing.Ask("Let's play CS");
                if (did.Count != 2 || did[1] != "use_computer:Let's play CS") throw new Exception("\"I won't pretend\" stopped a job: " + string.Join(",", did.ToArray()));
                Computer.GameOpen = delegate { return "Counter-Strike 2"; };
                playing.Ask("kliknij deathmatch");
                if (did.Count != 3 || did[2] != "use_computer:kliknij deathmatch") throw new Exception("A job in the open game didn't reach her hands: " + string.Join(",", did.ToArray()));
                bool told = false;
                foreach (string body in asked) if (body.IndexOf("The game open on their PC right now is", StringComparison.Ordinal) >= 0) told = true;
                if (!told) throw new Exception("Her hands weren't told which game is open.");
                string banter = playing.Ask("nice shot");
                if (did.Count != 3 || banter != "Clean shot, choom.") throw new Exception("Chat in a game turned into a job: " + banter);
                Computer.GameOpen = delegate { return null; };
                string talkAgain = playing.Ask("wanna hear a secret");
                if (did.Count != 3 || talkAgain != "Hah, you wish.") throw new Exception("Her job word leaked or ran with nothing to do: " + talkAgain);
                checks.Add("PASS asks to play reach her hands in any language: her brain's job word, \"I can't click\" and \"show me the screen\" in nine languages, Polish promises with their name, the open game's name for her hands, and chat in a game stays chat");
            }
            finally
            {
                Brain.Ollama = ollamaWas;
                Computer.GameOpen = openWas;
                fake.Stop();
            }
        }

        // Lachy, 7 Nov: with Listen for Capri on, "Hey Capri" got a reply and the next line, said with no name, went nowhere with no
        // sign. Everything here is a stand-in, and 20 seconds passing is her chat's end moved back, so nothing waits for it.
        private void SmokeNameChat(System.Collections.Generic.List<string> checks, string output)
        {
            bool listenWas = preferences.ListenCapri, toldWas = preferences.ListenCapriTold, freeToldWas = preferences.FreeChatTold, quietWas = preferences.Quiet, silentWas = preferences.Silent, heyWas = preferences.HeyCapri, freeChatWas = FreeChatOn, keepingWas = Brain.Keeping, closedWas = earsClosed;
            int typingWas = preferences.Typing;
            bool? ownWas = ownEarsTest;
            Func<Dictation> dictationWas = Dictation.Make;
            Func<short[], string> hearingWas = Hearing.Run;
            Func<string, string> thinkWas = Think;
            Func<string, byte[]> speakWas = Speak, freeSpeakWas = FreeSpeak;
            Func<string, string, byte[][], string> headWas = headTest;
            Action<string> asideWas = asideTest, stopWas = stopTest;
            Func<int, Func<bool>, PcSound> captureWas = PcEars.Capture;
            Func<bool> pcSpeakingWas = PcEars.Speaking;
            WatchAlong watchWas = watchAlong;
            Brain keeperWas = Brain.Keeper;
            Job runningWas = job;
            string workingWas = working, transcriptWas = Brain.TranscriptPath;
            TalkState talkWas = talkState;
            const string answered = "Heard the whole line.";
            System.Collections.Generic.List<string> reached = new System.Collections.Generic.List<string>();
            ManualResetEvent slow = new ManualResetEvent(true);
            string decoded = "";
            int decodedLines = 0, asides = 0;
            Func<double> at = delegate { return clock.Elapsed.TotalSeconds; };
            Func<int> reachedCount = delegate { lock (reached) return reached.Count; };
            Func<int, short[]> wave = delegate(int amplitude)
            {
                short[] samples = new short[Ears.Chunk];
                for (int sample = 0; sample < samples.Length; sample++) samples[sample] = (short)(Math.Sin(sample * Math.PI / 40) * amplitude);
                return samples;
            };
            Action<int, int> sound = delegate(int amplitude, int chunks) { for (int chunk = 0; chunk < chunks; chunk++) Gather(wave(amplitude)); };
            Action<int> talk = delegate(int chunks) { for (int chunk = 0; chunk < chunks; chunk++) Gather(wave(chunk % 2 == 0 ? 14000 : 20000)); };
            Action<Func<bool>> wait = delegate(Func<bool> done)
            {
                Stopwatch waited = Stopwatch.StartNew();
                while (!done() && waited.ElapsedMilliseconds < 4000) { Application.DoEvents(); Thread.Sleep(5); }
            };
            Action reopen = delegate
            {
                slow.Set();
                wait(delegate { return !transcribing; });
                if (chatting) StopChat();
                ToggleChat();
                if (!local || !chatting || !earsReady) throw new Exception("Her ears didn't open for the name chat check.");
                CloseTalk();
                heard = "";
            };
            // What it takes for a line to count: it reaches her whole and she answers. After it she's quiet again.
            Action<string, Action> reaches = delegate(string words, Action say)
            {
                int before = reachedCount();
                say();
                wait(delegate { return reachedCount() > before && reply == answered; });
                bool whole;
                lock (reached) whole = reached.Count == before + 1 && reached[before] == words;
                if (!whole) throw new Exception("\"" + words + "\" didn't reach her: chat open " + NameChatOpen + ", talk " + talkState + ", reply " + reply + ".");
                CloseTalk();
            };
            Action<string> counts = delegate(string words) { reaches(words, delegate { HeardLocally(chatTicket, asking, words, null); }); };
            // And for one to be dropped: nothing about her changes.
            Action<string, Action> stays = delegate(string what, Action say)
            {
                int askedBefore = asking, reachedBefore = reachedCount(), bargesSeen = bargeIns;
                string heardBefore = heard;
                say();
                if (asking != askedBefore || heard != heardBefore || bargeIns != bargesSeen || reachedCount() != reachedBefore) throw new Exception(what + " reached her: chat open " + NameChatOpen + ", heard " + heard + ".");
            };
            Action<string> dropped = delegate(string words) { stays("\"" + words + "\"", delegate { HeardLocally(chatTicket, asking, words, null); }); };
            Action<string> shut = delegate(string what) { if (nameChatUntil >= 0 || NameChatOpen || InChat && local || pill.ListenForName != (chatting && local)) throw new Exception(what + " left her name's chat open: until " + nameChatUntil + ", chatting " + chatting + ", pill " + pill.ListenForName + "."); };
            try
            {
                StopChat();
                CloseTalk();
                job = null;
                working = null;
                Brain.TranscriptPath = Path.Combine(output, "name-chat");
                Directory.CreateDirectory(Brain.TranscriptPath);
                Brain.Keeping = true;
                Brain.Keeper = null;
                preferences.ListenCapri = preferences.ListenCapriTold = preferences.FreeChatTold = true;
                preferences.Quiet = preferences.Silent = true;
                preferences.HeyCapri = false;
                preferences.Typing = 2;
                FreeChatOn = true;
                ownEarsTest = true;
                Speak = FreeSpeak = delegate { return null; };
                stopTest = delegate { };
                headTest = delegate { return "Got it."; };
                asideTest = delegate { Interlocked.Increment(ref asides); };
                Think = delegate(string words) { lock (reached) reached.Add(words); return answered; };
                Hearing.Run = delegate { Interlocked.Increment(ref decodedLines); slow.WaitOne(5000); return decoded; };
                reopen();

                dropped("what's for dinner");
                if (NameChatOpen || InChat || !pill.ListenForName || mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("Listen for Capri wasn't name-only before her name: chat open " + NameChatOpen + ", note " + mainframe.VoiceNoteText + ".");
                counts("hey capri");
                double left = nameChatUntil - at();
                if (!NameChatOpen || !InChat || pill.ListenForName || left > 20 || left < 15 || mainframe.VoiceNoteText != NameChatNote) throw new Exception("Her name didn't open a chat: chat open " + NameChatOpen + ", " + left + " s left, pill " + pill.ListenForName + ", note " + mainframe.VoiceNoteText + ".");
                counts("what's for dinner");
                reaches("i love pasta", delegate { HeardDictation("i love pasta"); });
                decoded = "what about tomorrow";
                slow.Reset();
                reaches(decoded, delegate
                {
                    sound(100, 6); talk(8); sound(100, 12);
                    wait(delegate { return transcribing && mainframe.VoiceNoteText == "Hearing you..."; });
                    if (mainframe.VoiceNoteText != "Hearing you...") throw new Exception("Her name's chat didn't say she was hearing them: " + mainframe.VoiceNoteText);
                    slow.Set();
                });
                if (mainframe.VoiceNoteText != NameChatNote) throw new Exception("Her name's chat lost its note: " + mainframe.VoiceNoteText);
                // The line that went nowhere: she's finished and her bubble's still up.
                Action finished = delegate { reply = "Hi."; replyStart = at() - 60; replyDone = at(); talkState = TalkState.Online; voiceUntil = at() - 0.1; };
                finished();
                counts("i love pasta");
                finished();
                reaches("i love pasta", delegate { HeardDictation("i love pasta"); });
                checks.Add("PASS Listen for Capri stays name-only until her name, which opens a chat for 20 seconds: lines without it then reach her whole through a recognised line, Windows speech and real audio, and the pill and VOICE show it (Lachy, 7 Nov)");

                nameChatUntil -= 19;
                counts("what's for dinner");
                if (nameChatUntil - at() < 15) throw new Exception("A line for her didn't start the 20 seconds again.");
                foreach (TalkState busy in new[] { TalkState.Thinking, TalkState.Talking })
                {
                    nameChatUntil = at() + 1;
                    talkState = busy;
                    CheckNameChat(at() + 0.5);
                    if (nameChatUntil - at() < 15) throw new Exception("Her " + busy + " didn't hold her name's chat.");
                    CloseTalk();
                }
                nameChatUntil = at() + 1;
                voiceUntil = at() + 5;
                CheckNameChat(at() + 0.5);
                if (nameChatUntil - at() < 15) throw new Exception("Her voice didn't hold her name's chat.");
                CloseTalk();
                nameChatUntil = at() + 1;
                pushing = true;
                CheckNameChat(at() + 0.5);
                pushing = false;
                if (nameChatUntil - at() < 15) throw new Exception("Holding push to talk didn't hold her name's chat.");
                nameChatUntil = at() - 0.5;
                CheckNameChat(at());
                if (NameChatOpen || InChat || !pill.ListenForName || mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("20 seconds of quiet didn't end her name's chat: pill " + pill.ListenForName + ", note " + mainframe.VoiceNoteText + ".");
                dropped("what's for dinner");
                double ended = nameChatUntil;
                voiceUntil = at() + 5;
                talkState = TalkState.Talking;
                CheckNameChat(at());
                if (nameChatUntil != ended) throw new Exception("Her speaking brought an ended chat back.");
                CloseTalk();
                counts("hey capri");
                mainframe.VoiceNote("Hearing you...", false);
                nameChatUntil = at() - 0.5;
                CheckNameChat(at());
                if (mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("Her name's chat ending left VOICE saying she was hearing them: " + mainframe.VoiceNoteText);
                counts("hey capri");
                nameChatUntil = at() - 0.5;
                lineBegan = nameChatUntil - 1;
                counts("what's for dinner");
                if (!NameChatOpen) throw new Exception("A line begun in time didn't keep her name's chat.");
                nameChatUntil = at() - 0.5;
                lineBegan = nameChatUntil + 0.2;
                dropped("i love pasta");
                counts("hey capri");
                decoded = "what about tomorrow";
                reaches(decoded, delegate
                {
                    sound(100, 6); talk(8);
                    Thread.Sleep(5);
                    nameChatUntil = at();
                    sound(100, 12);
                });
                checks.Add("PASS her name's chat ends after 20 seconds of quiet: at 19 s a line still counts and starts them again, her thinking and speaking hold it open, a line begun in time counts however late its words come back, one begun after doesn't, and she can't bring it back herself");

                counts("hey capri");
                Job running = new Job("stand-in job");
                job = running;
                JobOn(running);
                shut("A job starting");
                if (mainframe.VoiceNoteText == NameChatNote) throw new Exception("A job starting left VOICE saying no name is needed.");
                dropped("what's for dinner");
                if (!VoiceCounts("stop")) throw new Exception("A stop word needed her name mid-job.");
                int asidesBefore = asides;
                HeardLocally(chatTicket, asking, "capri how's it going", null);
                wait(delegate { return asides > asidesBefore; });
                if (heard != "capri how's it going") throw new Exception("A line with her name lost its job: " + heard);
                shut("A line with her name mid-job");
                dropped("what's for dinner");
                JobOff(running, "done", "Done.");
                job = null;
                taskPanel.Stop();
                HoldPanel();
                heard = "";
                dropped("what's for dinner");
                counts("hey capri");
                Job waiting = new Job("waiting for an answer");
                waiting.Waiting = new System.Collections.Generic.KeyValuePair<string, ToolArguments>("click", new ToolArguments());
                job = waiting;
                if (!waiting.Asking || NameChatOpen) throw new Exception("A job waiting on them left her name's chat open.");
                dropped("what's for dinner");
                job = null;
                CloseNameChat();
                checks.Add("PASS a job starting closes her name's chat, and until it ends only lines with her name reach her, with no chat after; one waiting on their answer stays name-only too");

                counts("hey capri");
                talkState = TalkState.Talking;
                voiceUntil = at() + 30;
                double voiceEnds = voiceUntil;
                dropped("i love pasta");
                stays("Windows speech over her voice", delegate { HeardDictation("i love pasta"); });
                if (voiceUntil != voiceEnds) throw new Exception("A line without her name cut her voice off in her name's chat.");
                HeardLocally(chatTicket, asking, "stop", null);
                if (voiceUntil != 0 || talkState != TalkState.Off) throw new Exception("A stop word needed her name in her name's chat.");
                talkState = TalkState.Talking;
                voiceUntil = at() + 30;
                int bargesBefore = bargeIns;
                counts("capri wait a second");
                if (bargeIns != bargesBefore + 1) throw new Exception("A line with her name didn't stop her in her name's chat.");
                nameOver = true;
                dropped("i love pasta");
                nameOver = true;
                stays("Windows speech begun over her voice", delegate { HeardDictation("i love pasta"); });
                if (nameOver) throw new Exception("A talk-over line stayed marked after it was dropped.");
                decoded = "i love pasta";
                Action overHer = delegate
                {
                    talkState = TalkState.Talking;
                    voiceUntil = at() + 30;
                    spokenAt = at();
                    spokenLevels = new double[400];
                    for (int level = 0; level < spokenLevels.Length; level++) spokenLevels[level] = 0.1;
                    talkOver.Reset();
                    nameOver = false;
                    room = -1;
                    lineAt = -100;
                    noiseHold = false;
                    CheckEars(at());
                    sound(1200, 6); talk(8); sound(1200, 12);
                };
                foreach (bool finishes in new[] { false, true })
                {
                    int decodedBefore = decodedLines, reachedBefore = reachedCount();
                    bargesBefore = bargeIns;
                    overHer();
                    if (finishes) CloseTalk();
                    wait(delegate { return decodedLines == decodedBefore + 1 && !transcribing; });
                    if (decodedLines != decodedBefore + 1 || reachedCount() != reachedBefore || bargeIns != bargesBefore) throw new Exception("Talking over her reached her without her name" + (finishes ? ", once she'd finished" : "") + ": decoded " + (decodedLines - decodedBefore) + ", reached " + (reachedCount() - reachedBefore) + ", name over " + nameOver + ".");
                    CloseTalk();
                }
                checks.Add("PASS in her name's chat a line over her voice still needs her name, even if she finishes before its words come back, through a recognised line, Windows speech and real audio; a stop word still stops her with no name");

                reopen();
                counts("hey capri");
                StopChat();
                shut("Her ears closing");
                reopen();
                dropped("what's for dinner");
                counts("hey capri");
                ToggleChat();
                shut("Her talk key");
                earsClosed = false;
                reopen();
                dropped("what's for dinner");
                counts("hey capri");
                ToggleMic();
                shut("Muting her");
                ToggleMic();
                dropped("what's for dinner");
                if (mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("Unmuting said her name's chat was still on: " + mainframe.VoiceNoteText);
                counts("hey capri");
                earsReady = false;
                CheckNameChat(at());
                earsReady = true;
                shut("Her ears dropping out");
                counts("hey capri");
                ToggleListenCapri();
                ToggleListenCapri();
                shut("Turning Listen for Capri off");
                dropped("what's for dinner");
                checks.Add("PASS her name's chat closes with her ears, her talk key, a mute and Listen for Capri, and doesn't come back with them");

                PcEars.Speaking = delegate { return false; };
                PcEars.Capture = delegate
                {
                    if (NameChatOpen) throw new Exception("PC sound left her name's chat open.");
                    dropped("what's for dinner");
                    CheckNameChat(at());
                    return new PcSound();
                };
                counts("hey capri");
                PcEars.Text(1, null);
                PcEars.Capture = captureWas;
                shut("PC sound");
                counts("hey capri");
                watchAlong = new WatchAlong();
                if (NameChatOpen) throw new Exception("Watch Along left her name's chat open.");
                dropped("what's for dinner");
                CheckNameChat(at());
                EndWatchAlong();
                shut("Watch Along");
                counts("hey capri");
                callSession.Change(true);
                if (NameChatOpen) throw new Exception("Call mode left her name's chat open.");
                CheckNameChat(at());
                callSession.Change(false);
                shut("Call mode");
                checks.Add("PASS PC sound, Watch Along and call mode stay name-only and close her name's chat");

                counts("hey capri");
                nameChatUntil -= 10;
                double unbrokenUntil = nameChatUntil;
                earsWarned = -10;
                int beforeUnbroken = reachedCount();
                HeardLocally(chatTicket, asking, "i love pasta", null, null, -1, true);
                if (reachedCount() != beforeUnbroken || nameChatUntil != unbrokenUntil || reply != NoPause || mainframe.VoiceNoteText != NoPause) throw new Exception("15 seconds without a pause counted as a line in her name's chat, or said nothing: " + reply + " / " + mainframe.VoiceNoteText);
                CheckNameChat(at());
                if (nameChatUntil != unbrokenUntil) throw new Exception("A note about her ears held her name's chat open.");
                CloseTalk();
                reaches("capri are you there", delegate { HeardLocally(chatTicket, asking, "capri are you there", null, null, -1, true); });
                decoded = "i love pasta";
                int beforeEndless = reachedCount(), endlessDecoded = decodedLines;
                earsWarned = at();
                talk(160);
                wait(delegate { return !transcribing && decodedLines > endlessDecoded; });
                if (decodedLines != endlessDecoded + 1 || reachedCount() != beforeEndless || noiseHold) throw new Exception("A sound that never pauses wasn't checked for her name, reached her in her name's chat or held her ears: decoded " + (decodedLines - endlessDecoded) + ", reached " + (reachedCount() - beforeEndless) + ", holding " + noiseHold + ".");
                reopen();
                counts("hey capri");
                earsWarned = -10;
                HeardLocally(chatTicket, asking, "", null);
                if (reply != NoWords || mainframe.VoiceNoteText != NoWords) throw new Exception("Words she couldn't make out in her name's chat went nowhere: " + reply + " / " + mainframe.VoiceNoteText);
                CloseTalk();
                CloseNameChat();
                earsWarned = -10;
                stays("Words she couldn't make out with no chat going", delegate { HeardLocally(chatTicket, asking, "", null); });
                checks.Add("PASS in her name's chat 15 seconds without a pause still gets its words checked but needs her name, so a game's sound can't reach her, and her ears say so when they miss a line; those notes don't hold the chat open");

                StopChat();
                ownEarsTest = false;
                StandInDictation stand = new StandInDictation();
                Dictation.Make = delegate { return stand; };
                reopen();
                if (dictation != stand) checks.Add("LIMIT Windows speech's late lines in her name's chat: her default mic is CABLE Output here");
                else
                {
                    reaches("hey capri", delegate { stand.Heard("hey capri"); });
                    talkState = TalkState.Talking;
                    voiceUntil = at() + 30;
                    stand.Partial("she had a long day");
                    Thread.Sleep(5);
                    CheckNameChat(at());
                    CloseTalk();
                    stays("Her own voice handed back late", delegate { stand.Heard("she had a long day"); });
                    stand.Partial("what's for dinner");
                    reaches("what's for dinner", delegate { stand.Heard("what's for dinner"); });
                    checks.Add("PASS her own voice that Windows speech hands back after she's stopped doesn't count as a line in her name's chat, and the line they say next does");
                }
                checks.Add("LIMIT her name's chat with a real mic, a real room and real recognisers needs a live voice check");
            }
            finally
            {
                pushing = false;
                slow.Set();
                wait(delegate { return !transcribing; });
                if (working != null || pointing) JobOff(job ?? new Job("stand-in job"), "done", "Done.");
                taskPanel.Stop();
                LeavePanel(true);
                outro = null;
                homeTrip = null;
                StopChat();
                CloseTalk();
                PcEars.Capture = captureWas;
                PcEars.Speaking = pcSpeakingWas;
                EndWatchAlong();
                watchAlong = watchWas;
                if (CallModeOn) callSession.Change(false);
                earsClosed = closedWas;
                preferences.ListenCapri = listenWas;
                preferences.ListenCapriTold = toldWas;
                preferences.FreeChatTold = freeToldWas;
                preferences.Quiet = quietWas;
                preferences.Silent = silentWas;
                preferences.HeyCapri = heyWas;
                preferences.Typing = typingWas;
                FreeChatOn = freeChatWas;
                ownEarsTest = ownWas;
                Dictation.Make = dictationWas;
                Hearing.Run = hearingWas;
                Think = thinkWas;
                Speak = speakWas;
                FreeSpeak = freeSpeakWas;
                headTest = headWas;
                asideTest = asideWas;
                stopTest = stopWas;
                job = runningWas;
                working = workingWas;
                talkState = talkWas;
                Brain.TranscriptPath = transcriptWas;
                Brain.Keeping = keepingWas;
                Brain.Keeper = keeperWas;
                mainframe.Sync();
                SavePreferences();
            }
        }

        // Lachy, 6 Nov: "Hey Capri while she was working didn't work at all". A dozen lines with her name, over the last 35 seconds of a
        // 15-minute Roblox job, never reached it, and nothing about them was logged. Her own ears lost lines three ways in a game: the
        // game's steady sound held them shut waiting for a pause that never came, a line said while the one before was still turning
        // into words was thrown away, and a line was dropped if she said anything before its words came back.
        private void SmokeJobEars(System.Collections.Generic.List<string> checks, string output)
        {
            bool listenWas = preferences.ListenCapri, toldWas = preferences.ListenCapriTold, freeToldWas = preferences.FreeChatTold, quietWas = preferences.Quiet, silentWas = preferences.Silent, heyWas = preferences.HeyCapri, freeChatWas = FreeChatOn, keepingWas = Brain.Keeping;
            bool? ownWas = ownEarsTest;
            Func<short[], string> hearingWas = Hearing.Run;
            Func<string, byte[]> speakWas = Speak, freeSpeakWas = FreeSpeak;
            Func<string, string, byte[][], string> headWas = headTest;
            Action<string> asideWas = asideTest, stopWas = stopTest;
            Job runningWas = job;
            string workingWas = working, transcriptWas = Brain.TranscriptPath;
            TalkState talkWas = talkState;
            const string said = "Hey Capri, you're kinda just mindlessly mining in the exact same spot.";
            ManualResetEvent slow = new ManualResetEvent(true), entered = new ManualResetEvent(false);
            int asides = 0;
            Func<int, short[]> wave = delegate(int amplitude)
            {
                short[] samples = new short[Ears.Chunk];
                for (int at = 0; at < samples.Length; at++) samples[at] = (short)(Math.Sin(at * Math.PI / 40) * amplitude);
                return samples;
            };
            Action<int, int> sound = delegate(int amplitude, int chunks) { for (int at = 0; at < chunks; at++) Gather(wave(amplitude)); };
            Action<int> voice = delegate(int chunks) { for (int at = 0; at < chunks; at++) Gather(wave(at % 2 == 0 ? 14000 : 20000)); };
            // Roblox's digging: two loud hits, then three quiet chunks, and never the 0.9 s pause that ends a line.
            Action<int> dig = delegate(int chunks) { for (int at = 0; at < chunks; at++) Gather(wave(at % 5 < 2 ? 3000 : 400)); };
            Action<Func<bool>, int> pump = delegate(Func<bool> done, int limit)
            {
                Stopwatch waited = Stopwatch.StartNew();
                while (!done() && waited.ElapsedMilliseconds < limit) { Application.DoEvents(); Thread.Sleep(5); }
            };
            Job running = new Job("play the game until I tell you to stop");
            Action reopen = delegate
            {
                slow.Set();
                pump(delegate { return !transcribing; }, 3000);
                if (chatting) StopChat();
                ToggleChat();
                if (!local || !chatting || !earsReady) throw new Exception("Her own ears didn't open for the job check.");
                talkState = job != null ? TalkState.Thinking : TalkState.Off;
                heard = "";
            };
            System.Collections.Generic.List<string> lost = new System.Collections.Generic.List<string>();
            int barges = 0, asidesBefore = 0;
            Action listen = delegate { barges = bargeIns; asidesBefore = asides; };
            Action<string> reached = delegate(string how)
            {
                pump(delegate { return heard == said && asides > asidesBefore; }, 5000);
                if (heard != said || bargeIns == barges) lost.Add(how);
            };
            try
            {
                StopChat();
                CloseTalk();
                Brain.TranscriptPath = Path.Combine(output, "job-ears");
                Directory.CreateDirectory(Brain.TranscriptPath);
                Brain.Keeping = true;
                preferences.ListenCapri = preferences.ListenCapriTold = preferences.FreeChatTold = true;
                preferences.Quiet = preferences.Silent = true;
                preferences.HeyCapri = false;
                FreeChatOn = true;
                ownEarsTest = true;
                Speak = FreeSpeak = delegate { return null; };
                stopTest = delegate { };
                headTest = delegate { return "Got it."; };
                asideTest = delegate { Interlocked.Increment(ref asides); };
                Hearing.Run = delegate(short[] samples)
                {
                    entered.Set();
                    slow.WaitOne(5000);
                    int loudest = 0;
                    foreach (short sample in samples) loudest = Math.Max(loudest, Math.Abs((int)sample));
                    // Only their voice has words in it: the game's sound and the other lines don't.
                    return loudest >= 19000 ? said : "";
                };
                job = running;
                working = "Holding left click. Esc stops me.";

                reopen();
                listen();
                sound(100, 6); voice(8); sound(100, 12);
                reached("a line in a quiet moment");

                reopen();
                listen();
                dig(160); voice(8); dig(160);
                bool held = noiseHold;
                reached("a line over the game's steady sound" + (held ? ", with her ears holding for a pause" : ""));

                reopen();
                listen();
                slow.Reset();
                entered.Reset();
                sound(100, 6); sound(9000, 3); sound(12000, 3); sound(100, 12);
                pump(delegate { return entered.WaitOne(0); }, 3000);
                sound(100, 4); voice(8); sound(100, 12);
                slow.Set();
                reached("a line said while the one before was still turning into words");

                reopen();
                listen();
                sound(100, 6); voice(8); sound(100, 12);
                asking++;
                reached("a line she spoke after, before its words were made out");

                reopen();
                listen();
                slow.Reset();
                entered.Reset();
                sound(100, 6); voice(8); sound(100, 12);
                pump(delegate { return entered.WaitOne(0); }, 3000);
                asking++;
                slow.Set();
                reached("a line she spoke after while its words were made out");
                if (lost.Count > 0) throw new Exception("Mid-job her own ears lost " + string.Join("; ", lost.ToArray()) + ".");

                reopen();
                listen();
                dig(320);
                pump(delegate { return false; }, 500);
                if (noiseHold || utterance == null || heard == said || bargeIns != barges) throw new Exception("Roblox's digging held her ears or reached the job: holding " + noiseHold + ", listening " + (utterance != null) + ", heard " + heard + ".");
                checks.Add("PASS mid-job her own ears hear a line with her name in a quiet moment, over Roblox's never-pausing digging, while the line before is still turning into words, and when she speaks before its words come back; the game's sound alone reaches nothing and doesn't hold them (Lachy, 6 Nov)");

                job = null;
                working = null;
                preferences.ListenCapri = false;
                reopen();
                dig(160);
                pump(delegate { return false; }, 300);
                if (!noiseHold) throw new Exception("Free voice chat stopped holding for a pause after 15 seconds of sound.");
                checks.Add("PASS free voice chat without Listen for Capri still takes 15 seconds without a pause as the room and holds for a pause");
            }
            finally
            {
                slow.Set();
                pump(delegate { return !transcribing; }, 3000);
                StopChat();
                CloseTalk();
                preferences.ListenCapri = listenWas;
                preferences.ListenCapriTold = toldWas;
                preferences.FreeChatTold = freeToldWas;
                preferences.Quiet = quietWas;
                preferences.Silent = silentWas;
                preferences.HeyCapri = heyWas;
                FreeChatOn = freeChatWas;
                ownEarsTest = ownWas;
                Hearing.Run = hearingWas;
                Speak = speakWas;
                FreeSpeak = freeSpeakWas;
                headTest = headWas;
                asideTest = asideWas;
                stopTest = stopWas;
                job = runningWas;
                working = workingWas;
                talkState = talkWas;
                Brain.TranscriptPath = transcriptWas;
                Brain.Keeping = keepingWas;
            }
        }

        // Lachy, 6 Nov: "pull up Roblox and just play whatever the hell you want" stopped at Roblox's "Enter: skip tutorial" to ask
        // "Should I send that?", since Roblox has a chat, and her reply wrapped up over the question. A game's own Enter is a game
        // key on both her hands, Enter straight after typing in its chat still asks under Trusted, and a held job's reply is what
        // ran and its question, with no wrap-up.
        private static void SmokeGameEnter(System.Collections.Generic.List<string> checks)
        {
            Sight roblox = new Sight { Window = new IntPtr(7), Title = "Roblox", Program = "RobloxPlayerBeta" };
            Sight discord = new Sight { Window = new IntPtr(7), Title = "#general - Discord", Program = "Discord" };
            ToolArguments enter = new ToolArguments { Keys = "enter" };
            if (Computer.Risk("press", enter, roblox) != null || Computer.Risk("press", enter, roblox, true) != "send" || Computer.Risk("type", new ToolArguments { Text = "gg", Enter = "yes" }, roblox) != "send" || Computer.Risk("press", enter, discord) != "send")
                throw new Exception("Enter in a game or a chat app read wrong.");
            const string play = "pull up roblox and just play whatever the hell you want";
            string securityWas = Security.Saved;
            Func<Sight> lookWas = Computer.Look, glimpseWas = Computer.Glimpse;
            Func<string, ToolArguments, Sight, string> actWas = Computer.Act;
            Func<IntPtr> frontWas = Computer.Front;
            Func<Rectangle?, Picture> shootWas = Computer.Shoot;
            Func<Target> focusWas = Computer.Focus;
            Func<Point, Target> underWas = Computer.Under;
            Func<string, ToolArguments, Picture, string> useWas = Computer.Use;
            try
            {
                Security.Jobs(false);
                System.Collections.Generic.List<string> acts = new System.Collections.Generic.List<string>();
                Computer.Look = delegate { return roblox; };
                Computer.Glimpse = delegate { return roblox; };
                Computer.Front = delegate { return new IntPtr(7); };
                Computer.Act = delegate(string name, ToolArguments a, Sight s) { acts.Add(name + ":" + (a.Keys ?? a.Text ?? a.Name ?? "")); return "Did it."; };
                string[] script = null;
                int line = 0;
                Func<string, string, System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>, string> think = delegate(string system, string user, System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> calls) { return script[Math.Min(line++, script.Length - 1)]; };
                script = new[] { "press{\"keys\": \"enter\"}", "done{\"text\": \"Skipped the tutorial.\"}" };
                Job skipping = new Job(play);
                skipping.Think = think;
                string skipped = skipping.Run();
                if (skipped != "Skipped the tutorial." || skipping.Asking || string.Join(",", acts.ToArray()) != "press:enter") throw new Exception("Her own hands asked about a game's Enter: " + skipped + " / " + string.Join(",", acts.ToArray()));
                acts.Clear();
                line = 0;
                script = new[] { "press{\"keys\": \"/\"}", "type{\"text\": \"gg\"}", "press{\"keys\": \"enter\"}", "done{\"text\": \"Said gg.\"}" };
                Job chatting = new Job(play);
                chatting.Think = think;
                string chatAsk = chatting.Run();
                bool chatHeld = chatAsk == "Should I send \"gg\"?" && chatting.Asking && string.Join(",", acts.ToArray()) == "press:/,type:gg";
                string chatSaid = chatting.Run();
                if (!chatHeld || chatSaid != "Said gg." || chatting.Asking || string.Join(",", acts.ToArray()) != "press:/,type:gg,press:enter") throw new Exception("Her own hands sent a line in a game's chat without asking, or lost it after yes: " + chatAsk + " / " + chatSaid + " / " + string.Join(",", acts.ToArray()));
                // Claude's hands, which Lachy's run used.
                Computer.Shoot = delegate(Rectangle? part) { return new Picture { Jpeg = new byte[] { 1, 2, 3 }, Size = new Size(1280, 720), Area = new Rectangle(0, 0, 2560, 1440) }; };
                Computer.Focus = delegate { return null; };
                Computer.Under = delegate(Point at) { return null; };
                System.Collections.Generic.List<string> moves = new System.Collections.Generic.List<string>();
                Computer.Use = delegate(string name, ToolArguments a, Picture seen) { moves.Add(name + (a.Text == null ? "" : " " + a.Text)); return "Done."; };
                string[] driveScript = null;
                int turn = 0;
                Func<string, string, string, ClaudeReply> drive = delegate(string system, string tools, string messages) { return Brain.Parsed(driveScript[Math.Min(turn++, driveScript.Length - 1)]); };
                driveScript = new[]
                {
                    "{\"content\":[{\"type\":\"tool_use\",\"id\":\"k1\",\"name\":\"key\",\"toolset_name\":\"computer\",\"input\":{\"text\":\"Return\"}}],\"stop_reason\":\"tool_use\"}",
                    "{\"content\":[{\"type\":\"text\",\"text\":\"Skipped the tutorial.\"}],\"stop_reason\":\"end_turn\"}"
                };
                Job driveSkip = new Job(play);
                driveSkip.Drive = drive;
                string driveSkipped = driveSkip.Run();
                if (driveSkipped != "Skipped the tutorial." || driveSkip.Asking || string.Join(",", moves.ToArray()) != "key Return") throw new Exception("Claude's hands asked about a game's Enter: " + driveSkipped + " / " + string.Join(",", moves.ToArray()));
                moves.Clear();
                turn = 0;
                driveScript = new[]
                {
                    "{\"content\":[{\"type\":\"tool_use\",\"id\":\"t1\",\"name\":\"type\",\"toolset_name\":\"computer\",\"input\":{\"text\":\"gg\"}},{\"type\":\"tool_use\",\"id\":\"k2\",\"name\":\"key\",\"toolset_name\":\"computer\",\"input\":{\"text\":\"Return\"}}],\"stop_reason\":\"tool_use\"}",
                    "{\"content\":[{\"type\":\"text\",\"text\":\"Said gg.\"}],\"stop_reason\":\"end_turn\"}"
                };
                Job driveChat = new Job(play);
                driveChat.Drive = drive;
                string driveAsk = driveChat.Run();
                if (driveAsk != "Should I send \"gg\"?" || !driveChat.Asking || string.Join(",", moves.ToArray()) != "type gg") throw new Exception("Claude's hands sent a line in a game's chat without asking: " + driveAsk + " / " + string.Join(",", moves.ToArray()));
            }
            finally
            {
                Security.Load(securityWas);
                Computer.Look = lookWas;
                Computer.Glimpse = glimpseWas;
                Computer.Act = actWas;
                Computer.Front = frontWas;
                Computer.Shoot = shootWas;
                Computer.Focus = focusWas;
                Computer.Under = underWas;
                Computer.Use = useWas;
            }
            Func<string, string, string> toolCall = delegate(string name, string json) { return "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":null,\"tool_calls\":[{\"id\":\"c1\",\"type\":\"function\",\"function\":{\"name\":\"" + name + "\",\"arguments\":" + Voice.Quote(json) + "}}]}}]}"; };
            System.Collections.Generic.List<string> asked = new System.Collections.Generic.List<string>();
            System.Net.Sockets.TcpListener fake;
            string openAiWas = Brain.OpenAi;
            Func<string> openWas = Computer.GameOpen;
            Brain.OpenAi = FakeServer(new string[]
            {
                toolCall("open_app", "{\"name\":\"Roblox\"}"), toolCall("use_computer", "{\"task\":\"buy the cat hat in the shop\"}"),
                "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"I opened Roblox and I'm in the shop with the tutorial running.\"}}]}"
            }, asked, out fake);
            try
            {
                const string held = "Should I press \"Buy now\"?";
                Hands.Held(held);
                if (!Hands.Holds(held) || Hands.Holds("Should I press \"Send\"?") || Hands.Holds(null)) throw new Exception("A held job's question was matched wrong.");
                Brain working = new Brain();
                working.Remote = new Cloud("sk-proj-test", "gpt-5-mini");
                working.Model = "gpt-5-mini";
                working.OwnSteps = true;
                working.Act = delegate(string name, ToolArguments args)
                {
                    if (name != "use_computer") return "Opened " + args.Name + ".";
                    Hands.Held(held);
                    return held;
                };
                Computer.GameOpen = delegate { return null; };
                string reply = working.Ask("open roblox and buy me the cat hat");
                int calledBrain;
                lock (asked) calledBrain = asked.Count;
                if (Regex.Replace(reply ?? "", @"\s+", " ") != "Opened Roblox. " + held || calledBrain != 2) throw new Exception("A held job's question didn't end her reply, or her brain wrapped up over it: " + reply + " after " + calledBrain + " brain calls");
            }
            finally
            {
                Hands.Held(null);
                Brain.OpenAi = openAiWas;
                Computer.GameOpen = openWas;
                fake.Stop();
            }
            checks.Add("PASS a game's own Enter is a game key: \"pull up Roblox and play\" skips Roblox's tutorial with Enter on her own and on Claude's hands without asking; Enter straight after typing in a game's chat still asks under Trusted, quoting what it would send, and goes on after yes; a held job's reply is what ran and its question, word for word, with no wrap-up from her brain");
        }

        // F57: a strong brain works a job out itself. CS isn't open, so it opens it, hands the match to a job and only then says so;
        // a promise with no tool behind it gets one reminder, then her line that nothing's happened yet; chat stays chat.
        private static void SmokeWorkingOut(System.Collections.Generic.List<string> checks)
        {
            Func<string, string> says = delegate(string text) { return "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":" + Voice.Quote(text) + "}}]}"; };
            Func<string, string, string> calls = delegate(string name, string json) { return "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":null,\"tool_calls\":[{\"id\":\"c1\",\"type\":\"function\",\"function\":{\"name\":\"" + name + "\",\"arguments\":" + Voice.Quote(json) + "}}]}}]}"; };
            System.Collections.Generic.List<string> asked = new System.Collections.Generic.List<string>();
            System.Net.Sockets.TcpListener fake;
            string openAiWas = Brain.OpenAi;
            Func<string> openWas = Computer.GameOpen;
            Brain.OpenAi = FakeServer(new string[]
            {
                calls("open_app", "{\"name\":\"Counter-Strike 2\"}"), calls("use_computer", "{\"task\":\"start matchmaking\"}"), says("Queued you up, choom."),
                says("On it, opening CS now!"), calls("open_app", "{\"name\":\"Counter-Strike 2\"}"), says("CS is up."),
                says("On it, opening Spotify!"), says("Opening it now!"),
                says("Cyberpunk, obviously."),
                says("open_app{\"name\":\"Steam\"}"), says("Steam's open."),
                calls("use_computer", "{\"task\":\"start ranked in valorant for me\"}"), calls("use_computer", "{\"task\":\"start ranked in valorant for me\"}"), says("Queued ranked, choom.")
            }, asked, out fake);
            try
            {
                System.Collections.Generic.List<string> did = new System.Collections.Generic.List<string>();
                Brain working = new Brain();
                working.Remote = new Cloud("sk-proj-test", "gpt-5-mini");
                working.Model = "gpt-5-mini";
                working.Act = delegate(string name, ToolArguments args)
                {
                    did.Add(name + ":" + (args.Name ?? args.Task));
                    return name == "open_app" ? "Opened " + args.Name + "." : name == "use_computer" ? "Job: clicked PLAY, then MATCHMAKING. Searching for a match." : "Done.";
                };
                Computer.GameOpen = delegate { return null; };
                if (working.WorksOut() || new Brain { OwnSteps = true }.WorksOut()) throw new Exception("A brain worked jobs out itself with the switch off, or with no cloud brain.");
                working.OwnSteps = true;
                if (!working.WorksOut()) throw new Exception("A cloud brain with tools didn't work jobs out itself.");
                string matched = working.Ask("start matchmaking in cs");
                if (matched != "Queued you up, choom." || string.Join(",", did.ToArray()) != "open_app:Counter-Strike 2,use_computer:start matchmaking") throw new Exception("She didn't open CS and then start the match: " + matched + " / " + string.Join(",", did.ToArray()));
                working.Forget();
                string reminded = working.Ask("open cs");
                if (reminded != "CS is up." || did.Count != 3 || did[2] != "open_app:Counter-Strike 2") throw new Exception("A promise with no tool behind it wasn't sent back for the tool: " + reminded + " / " + string.Join(",", did.ToArray()));
                working.Forget();
                string unkept = working.Ask("open spotify");
                if (unkept != Hands.Unpromised || did.Count != 3) throw new Exception("Two promises with no tool still reached them as done: " + unkept);
                working.Forget();
                string chatted = working.Ask("what's your favourite game?");
                if (chatted != "Cyberpunk, obviously." || did.Count != 3) throw new Exception("Chat turned into a job: " + chatted);
                working.Forget();
                string copied = working.Ask("get steam up");
                if (copied != "Steam's open." || did.Count != 4 || did[3] != "open_app:Steam") throw new Exception("A call written out as text didn't run: " + copied + " / " + string.Join(",", did.ToArray()));
                // A brain that goes straight to use_computer in a game that isn't open gets the game opened first.
                Func<System.Collections.Generic.List<InstalledApp>> catalogWas = Hands.Catalog;
                Func<System.Collections.Generic.List<OpenWindow>> windowsWas = Hands.Windows;
                string ranked;
                try
                {
                    Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("VALORANT", "valorant-id") }; };
                    Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow>(); };
                    Hands.Forget();
                    working.Forget();
                    ranked = working.Ask("start ranked in val");
                }
                finally
                {
                    Hands.Catalog = catalogWas;
                    Hands.Windows = windowsWas;
                    Hands.Forget();
                }
                if (ranked != "Queued ranked, choom." || did.Count != 6 || did[4] != "open_app:valorant" || did[5] != "use_computer:start ranked in valorant for me")
                    throw new Exception("A game that wasn't open wasn't opened before the job, or the same job ran twice: " + ranked + " / " + string.Join(",", did.ToArray()));
                if (!Hands.Promised("Play some lofi for you while you study.") || Hands.Promised("Play the long game, it's worth it.")) throw new Exception("\"Play some lofi for you\" with no tool behind it wasn't caught as a promise, or chat was.");
                string[] sent;
                lock (asked) sent = asked.ToArray();
                if (sent.Length != 14) throw new Exception("Working it out made " + sent.Length + " brain calls, not 14.");
                string[][] wanted =
                {
                    new[] { "\"tools\":[{\"type\":\"function\",\"function\":{\"name\":\"open_app\"", "You hold these tools yourself", "They won't always spell it out", "Nobody tells you what's open on their PC", "{\"name\":\"list_windows\"", "start matchmaking in cs" },
                    new[] { "\"tools\":[", "What your tools just did", "Opened Counter-Strike 2.", "You called open_app{" },
                    new[] { "\"tools\":[", "Searching for a match.", "You called use_computer{" },
                    new[] { "open cs" },
                    new[] { "You said you'd do it, but no tool ran" },
                    new[] { "Opened Counter-Strike 2." },
                    new[] { "open spotify" },
                    new[] { "You said you'd do it, but no tool ran" }
                };
                for (int i = 0; i < wanted.Length; i++)
                    foreach (string part in wanted[i])
                        if (sent[i].IndexOf(part, StringComparison.Ordinal) < 0) throw new Exception("Brain call " + i + " is missing " + part + ": " + sent[i].Substring(0, Math.Min(400, sent[i].Length)));
                foreach (string body in sent) if (body.IndexOf("You are the hands of Capri", StringComparison.Ordinal) >= 0 || body.IndexOf("only the word: act", StringComparison.Ordinal) >= 0) throw new Exception("A strong brain still went through her hands' one-shot pick.");
                foreach (string body in sent) if (body.IndexOf("No game is open", StringComparison.Ordinal) >= 0 || body.IndexOf("The game open on their PC right now", StringComparison.Ordinal) >= 0) throw new Exception("A strong brain was told about their game before it asked.");
                checks.Add("PASS a strong brain works jobs out itself: with CS closed, \"start matchmaking\" opens CS, sees it opened, then starts the match as a job; a promise with no tool gets one reminder and then \"I haven't actually done that yet\"; calls copied as text still run; chat stays chat; a brain that goes straight to the job in a game that isn't open gets the game opened first, and the same job called twice runs once; \"play some lofi for you\" with no tool behind it counts as a promise; brains with the switch off or no cloud keep her hands' shortcuts");
            }
            finally
            {
                Brain.OpenAi = openAiWas;
                Computer.GameOpen = openWas;
                fake.Stop();
            }
        }

