                string[,] toggles =
                {
                    { "keep_awake", "keepAwake", "NoKeepAwake" }, { "player_full_screen", "playerFullScreen", "PlayerFullScreen" }, { "explore_away", "exploreAway", "ExploreAway" },
                    { "fast_hands", "fastHands", "SlowHands" }, { "cursor", "cursor", "QuickHands" }, { "discord_presence", "discord", "NoDiscord" }, { "listen_for_capri", "listenCapri", "ListenCapri" }
                };
                for (int i = 0; i < toggles.GetLength(0); i++)
                {
                    string name = toggles[i, 0];
                    foreach (bool on in new[] { true, false })
                    {
                        string line = Hands.Do("capri_settings", new ToolArguments { Action = on ? "on" : "off", Name = name });
                        bool real = SettingOn(name) == true;
                        bool persisted = (bool)saved(LoadPreferences(), toggles[i, 2]);
                        if (name == "keep_awake" || name == "fast_hands" || name == "cursor" || name == "discord_presence") persisted = !persisted;
                        if (real != on || ((CheckBox)shown(toggles[i, 1])).Checked != on || persisted != on || !line.EndsWith(on ? "on." : "off.", StringComparison.Ordinal)) throw new Exception("Setting switch disagreed with Mainframe or disk: " + name + " / " + line);
                    }
                    checks.Add("PASS setting " + name + " uses Mainframe's switch, saves and reads back both ways");
                }
                foreach (bool on in new[] { true, false })
                {
                    string line = Hands.Do("capri_settings", new ToolArguments { Action = on ? "on" : "off", Name = "startup" });
                    if (StartsWithWindows != on || ((CheckBox)shown("startup")).Checked != on || !LoadPreferences().StartupSet || !line.EndsWith(on ? "on." : "off.", StringComparison.Ordinal)) throw new Exception("Start at login did not use the shared Run entry: " + line);
                    Hands.Do("capri_settings", new ToolArguments { Action = on ? "on" : "off", Name = "show_advanced" });
                    mainframe.ShowSettings(true);
                    if (preferences.AdvancedSettings != on || LoadPreferences().AdvancedSettings != on || mainframe.AdvancedShown != on) throw new Exception("Advanced settings did not change its view and save.");
                    Hands.Do("capri_settings", new ToolArguments { Action = on ? "on" : "off", Name = "voice_layers" });
                    if (VoiceLayers.On != on || LoadPreferences().VoiceLayers != on || mainframe.LayersKeyShown.Contains("(lit)") != on) throw new Exception("Voice layers switch did not reach Mainframe and disk.");
                }
                checks.Add("PASS start at login, advanced view and voice layers use the same state as Mainframe and save");
                preferences.CheckIns = true;
                mainframe.Sync();
                for (int i = 0; i < Hands.CareSettings.Length; i++)
                {
                    CareKind kind = (CareKind)i;
                    string name = Hands.CareSettings[i];
                    foreach (bool on in new[] { true, false })
                    {
                        string line = Hands.Do("capri_settings", new ToolArguments { Action = on ? "on" : "off", Name = name });
                        if (CareOn(kind) != on || mainframe.CareShown(kind) != on || LoadPreferences().CareOn(kind) != on || !line.EndsWith(on ? "on." : "off.", StringComparison.Ordinal)) throw new Exception("Care switch did not read, change and save: " + name);
                    }
                    string[] steps = Hands.StepsOf(name);
                    int[] times = Hands.ValuesFor(name);
                    for (int step = 0; step < steps.Length; step++)
                    {
                        string line = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = name, Level = steps[step] });
                        if (CareTime(kind) != times[step] || LoadPreferences().CareTime(kind) != times[step] || mainframe.CareTimeShown(kind) != steps[step] || LevelOf(name) != step || !line.Contains(steps[step])) throw new Exception("Care time did not match Mainframe: " + name + " / " + line);
                    }
                    SetLevel(name, int.MinValue);
                    if (CareTime(kind) != times[0]) throw new Exception("Care time did not clamp low: " + name);
                    SetLevel(name, int.MaxValue);
                    if (CareTime(kind) != times[times.Length - 1]) throw new Exception("Care time did not clamp high: " + name);
                    checks.Add("PASS setting " + name + " uses its care switch and every Mainframe time, clamps, saves and reads back");
                }
                string[,] sliders =
                {
                    { "explore_after", "exploreAfter", "ExploreAfter" }, { "glance_gap", "gap", "GlanceGap" }, { "watch_memory", "watchMemory", "WatchMemory" },
                    { "voice_pitch", "pitchSlider", "VoicePitch" }, { "voice_robot", "robotSlider", "VoiceRobot" }, { "voice_glitch", "glitchSlider", "VoiceGlitch" },
                    { "sounds", "sounds", "Sounds" }, { "mainframe_size", "frameSize", "MainframeSize" }, { "mainframe_colours", "frameColours", "MainframeColours" }, { "perch_fps", "perchFps", "PerchFps" },
                    { "power_saver", "powerSaver", "PowerSaver" }, { "reply_limit", "replyLength", "ReplyLength" }, { "game_comments", "comments", "CommentPace" },
                    { "clip_length", "clipLength", "ClipSeconds" }, { "clip_fps", "clipRate", "ClipFps" }, { "clip_resolution", "clipSize", "ClipResolution" }, { "clip_bitrate", "clipBits", "ClipMbps" }
                };
                for (int i = 0; i < sliders.GetLength(0); i++)
                {
                    string name = sliders[i, 0];
                    object slider = shown(sliders[i, 1]);
                    Func<int> sliderValue = delegate { return (int)slider.GetType().GetProperty("Value", fields).GetValue(slider, null); };
                    string[] choices = (string[])slider.GetType().GetProperty("Choices", fields).GetValue(slider, null);
                    string[] steps = Hands.StepsOf(name);
                    if (string.Join("|", choices) != string.Join("|", steps)) throw new Exception("Tool steps differ from Mainframe: " + name);
                    foreach (int step in new[] { 0, steps.Length / 2, steps.Length - 1 })
                    {
                        string line = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = name, Level = steps[step] });
                        if (sliderValue() != step || LevelOf(name) != step || !object.Equals(saved(LoadPreferences(), sliders[i, 2]), saved(preferences, sliders[i, 2])) || !line.Contains(steps[step])) throw new Exception("Setting slider did not show, save or read back: " + name + " / " + line);
                    }
                    SetLevel(name, int.MinValue);
                    if (sliderValue() != 0) throw new Exception("Setting did not clamp low: " + name);
                    SetLevel(name, int.MaxValue);
                    if (sliderValue() != steps.Length - 1) throw new Exception("Setting did not clamp high: " + name);
                    checks.Add("PASS setting " + name + " matches Mainframe's steps, clamps, saves and reports the value afterwards");
                }
                foreach (bool hd in new[] { true, false })
                {
                    preferences.HdVoice = hd;
                    preferences.ServerVoice = !hd;
                    Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = "voice_robot", Level = "40%" });
                    Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = "voice_glitch", Level = "60%" });
                    Preferences loaded = LoadPreferences();
                    if (VoiceRobot != 40 || VoiceGlitch != 60 || (hd ? loaded.HdRobot : loaded.ServerRobot) != 40 || (hd ? loaded.HdVoiceGlitch : loaded.ServerGlitch) != 60 || mainframe.VoiceStyleStatus.IndexOf(hd ? "40% · HD | 60% · HD" : "40% · server | 60% · server", StringComparison.Ordinal) < 0) throw new Exception("Effects did not use the active voice's setters: " + mainframe.VoiceStyleStatus);
                }
                preferences.HdVoice = preferences.ServerVoice = false;
                mainframe.ShowLayersWindow();
                foreach (string name in new[] { "layer_1_pitch", "layer_1_delay", "layer_2_pitch", "layer_2_delay" })
                {
                    string[] steps = Hands.StepsOf(name);
                    foreach (int step in new[] { 0, steps.Length / 2, steps.Length - 1 })
                    {
                        string line = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = name, Level = steps[step] });
                        string expected = (VoiceLayers.On ? "On" : "Off") + " | " + Hands.StepsOf("voice_pitch")[LevelOf("voice_pitch")] + " | " + VoiceFx.Layering.PitchName(VoiceLayers.Pitch1) + ", " + VoiceFx.Layering.DelayName(VoiceLayers.Delay1) + " | " + VoiceFx.Layering.PitchName(VoiceLayers.Pitch2) + ", " + VoiceFx.Layering.DelayName(VoiceLayers.Delay2);
                        if (LevelOf(name) != step || mainframe.LayersShown != expected || LayersOf(LoadPreferences()).Shown != VoiceLayers.Shown || !line.Contains(steps[step])) throw new Exception("Layer did not match its panel and saved value: " + name + " / " + line);
                    }
                    SetLevel(name, int.MinValue);
                    if (LevelOf(name) != 0) throw new Exception("Layer did not clamp low.");
                    SetLevel(name, int.MaxValue);
                    if (LevelOf(name) != steps.Length - 1) throw new Exception("Layer did not clamp high.");
                    checks.Add("PASS setting " + name + " matches the layers panel, clamps, saves and reads back");
                }
                foreach (string name in new[] { "language", "typing_sound" })
                {
                    string[] steps = Hands.StepsOf(name);
                    // The top step first, since a language that follows Windows already reads as English and saves nothing.
                    foreach (int step in new[] { steps.Length - 1, 0, 1 })
                    {
                        string line = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = name, Level = steps[step] });
                        Preferences loaded = LoadPreferences();
                        if (LevelOf(name) != step || !line.Contains(steps[step]) || (name == "language" ? loaded.Language != steps[step] || Language != steps[step] || !mainframe.LanguageIs(steps[step]) : loaded.Typing != step || preferences.Typing != step || mainframe.TypingShown != TypingSound)) throw new Exception("Language or typing mode did not read, show and save: " + line);
                    }
                    SetLevel(name, int.MinValue);
                    if (LevelOf(name) != 0) throw new Exception("Language or typing mode did not clamp low.");
                    SetLevel(name, int.MaxValue);
                    if (LevelOf(name) != steps.Length - 1) throw new Exception("Language or typing mode did not clamp high.");
                    checks.Add("PASS setting " + name + " matches Mainframe, clamps, saves and reads back");
                }
                string refused = Hands.Do("capri_settings", new ToolArguments { Action = "on", Name = "voice_in_mic" });
                if (!refused.Contains("VB-CABLE") || preferences.VoiceInMic || micMix != null || LoadPreferences().VoiceInMic || setups != 0) throw new Exception("A missing cable was enabled or installed: " + refused);
                devices.CableThere = new MixDevice("settings-cable", "CABLE Input (VB-Audio Virtual Cable)", "settings-cable-out");
                cableLooked = -10;
                string enabled = Hands.Do("capri_settings", new ToolArguments { Action = "on", Name = "voice_in_mic" });
                if (!VoiceInMic || micMix == null || !LoadPreferences().VoiceInMic || !mainframe.VoiceInMicStatus.StartsWith("on |", StringComparison.Ordinal) || !enabled.StartsWith("Turned", StringComparison.Ordinal)) throw new Exception("A ready cable did not enable the existing mix.");
                Hands.Do("capri_settings", new ToolArguments { Action = "off", Name = "voice_in_mic" });
                if (VoiceInMic || micMix != null || LoadPreferences().VoiceInMic || setups != 0) throw new Exception("The mic mix did not turn off.");
                checks.Add("PASS voice_in_mic refuses a missing cable with setup steps, never installs it, and uses the existing mix when ready");
                string folder = Path.Combine(Path.GetDirectoryName(settingsPath), "settings-clips");
                Directory.CreateDirectory(folder);
                int probes = 0;
                ClipSettings.CheckFolder = delegate { probes++; };
                string picked = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = "clip_folder", Path = folder });
                if (ClipOptions.Folder != folder || LoadPreferences().ClipFolder != folder || !picked.Contains(folder) || ((Label)shown("clipPath")).Text != folder || probes != 1) throw new Exception("Clips folder skipped the shared checks or readback.");
                ClipSettings.CheckFolder = delegate { probes++; throw new IOException("no write"); };
                string denied = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = "clip_folder", Path = Path.GetDirectoryName(settingsPath) });
                string missing = Hands.Do("capri_settings", new ToolArguments { Action = "set", Name = "clip_folder", Path = Path.Combine(folder, "missing") });
                if (!Hands.Failed(denied) || !Hands.Failed(missing) || ClipOptions.Folder != folder || probes != 2) throw new Exception("A bad clips folder replaced the saved folder.");
                checks.Add("PASS clip_folder uses the existing folder and write checks, saves and reports the resulting folder");
                string editor = null;
                Hands.Run = delegate(string line) { editor = line; };
                string opened = Hands.Do("capri_settings", new ToolArguments { Action = "edit_check_in_lines" });
                string carePath = Path.Combine(Path.GetDirectoryName(settingsPath), "check-ins.md");
                if (editor != "\"" + Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "notepad.exe") + "\" \"" + carePath + "\"" || !File.Exists(carePath) || opened != "Opened your check-in lines.") throw new Exception("The check-in editor was not opened through its existing action.");
                preferences.Silent = false;
                FreeSpeak = delegate { return Voice.Wave(new short[24000], 24000); };
                string provider = preferences.ServerUrl, voiceId = preferences.VoiceId;
                styleCheckDue = false;
                string preview = Hands.Do("capri_settings", new ToolArguments { Action = "preview_voice" });
                if (!styleCheckDue || asking != askingWas || preferences.ServerUrl != provider || preferences.VoiceId != voiceId || preview != "I'll play my current voice after this reply.") throw new Exception("Voice preview changed the service or interrupted its own brain turn.");
                styleCheckDue = false;
                checks.Add("PASS preview_voice queues the existing current-voice preview without interrupting its tool turn or changing service settings; edit_check_in_lines opens their editor");
            }
            finally
            {
                styleCheckDue = false;
                listenChangeDue = false;
                foreach (System.Collections.Generic.KeyValuePair<string, bool> pair in switches) SetSetting(pair.Key, pair.Value);
                foreach (System.Collections.Generic.KeyValuePair<string, int> pair in levels) SetLevel(pair.Key, pair.Value);
                mainframe.CloseLayers();
                simpleTest = simpleWas;
                mainframe.ShowSettings(pageWas);
                Startup.RunKey = runWas;
                Startup.ApprovedKey = approvedWas;
                Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(testKey, false);
                preferences = preferencesWas;
                Brain.Language = languageWas;
                preferences.StartupSet = startupWas;
                preferences.ClipFolder = folderWas;
                clips.Configure(ClipOptions);
                preferences.Quiet = quietWas;
                preferences.HdVoice = hdWas;
                preferences.ServerVoice = serverWas;
                preferences.Silent = silentWas;
                preferences.HdRobot = VoiceFx.HdRobot = hdRobotWas;
                preferences.HdVoiceGlitch = VoiceFx.HdGlitch = hdGlitchWas;
                preferences.ServerRobot = VoiceFx.ServerRobot = serverRobotWas;
                preferences.ServerGlitch = VoiceFx.ServerGlitch = serverGlitchWas;
                styleCheckDue = styleWas;
                styleAsked = styleTicketWas;
                listenChangeDue = listenWas;
                MicMix.Devices = devicesWas;
                cableLooked = -10;
                CableSetup.Start = setupWas;
                Hands.Run = run;
                ClipSettings.CheckFolder = folderCheckWas;
                Sfx.TypeOut = typeWas;
                FreeSpeak = freeWas;
                Presence.AppId = discordAppWas;
                SavePreferences();
                mainframe.Sync();
            }
        }

        // Her settings tool flips her real switches the way her Mainframe, menu and keys do, and reads them back, without a line of
        // her own that would cut off the reply her brain is writing.
        private void SmokeOwnSettings(System.Collections.Generic.List<string> checks)
        {
            bool clipsWas = preferences.ClipGames, momentsWas = preferences.ClipMoments, reactionsWas = preferences.NoReactions, checkInsWas = preferences.CheckIns, wanderWas = preferences.Wander, silentWas = preferences.Silent, hologramWas = preferences.Hologram, shushWas = shushed;
            int askingWas = asking;
            try
            {
                preferences.ClipGames = preferences.ClipMoments = false;
                if (preferences.NoReactions) ToggleReactions();
                if (!preferences.CheckIns) ToggleCheckIns();
                if (preferences.Wander) ToggleWander();
                if (preferences.Silent) Unsilence();
                if (preferences.Hologram) SetHologram(false);
                if (shushed) ToggleShush(false);
                askingWas = asking;
                Func<string, string, string> set = delegate(string name, string way) { return Hands.Do("capri_settings", new ToolArguments { Action = way, Name = name }); };
                string listed = Hands.Do("capri_settings", new ToolArguments { Action = "list" });
                System.Collections.Generic.List<string> said = new System.Collections.Generic.List<string>();
                foreach (string step in new[] { "clip_my_games on", "save_big_moments on", "clip_my_games off", "live_reactions off", "check_ins off", "wander on", "quiet on", "quiet off", "voice off", "voice on", "hologram on", "hologram off" })
                    said.Add(set(step.Split(' ')[0], step.Split(' ')[1]));
                // Her voice chat mic only has a setting during voice chat, which the smoke test isn't in.
                bool calling = chatting;
                if (!calling) said.Add(set("mic", "off"));
                string wanted = "Turned Clip my games on. | Turned Save big moments on. | Turned Clip my games off. | Turned Live reactions off. | Turned Check in on me off. Every check-in is paused; your care switches and times stay saved. | Turned Wander on. | Turned Quiet on. | Turned Quiet off. | Turned my voice off. | Turned my voice on. | "
                    + "Turned Hologram mode on. Hologram mode on. Clicks go through me. Turn it off from my tray icon, or say hologram off. | Turned Hologram mode off. Hologram mode off. You can click me again." + (calling ? "" : " | Couldn't change my voice chat mic: voice chat isn't on.");
                string joined = string.Join(" | ", said.ToArray());
                // Her other switches and sliders have their own check (SmokeOwnSliders).
                if (!listed.StartsWith("How my settings are right now: my voice on; Quiet off; my voice chat mic" + (calling ? (ears.Muted ? " off" : " on") : ": no voice chat on") + "; Check in on me on; Clip my games off; Save big moments off; Live reactions on; Gaming Mode " + (GamingWanted ? "on" : "off") + "; Hologram mode off; Watch my screen " + (preferences.Watch ? "on" : "off") + "; Game comments " + (CommentPace != Commentary.Off ? "on" : "off") + "; ", StringComparison.Ordinal)
                    || !listed.Contains("; Wander: Off; ") || !listed.EndsWith(".", StringComparison.Ordinal) || joined != wanted || preferences.ClipGames || preferences.ClipMoments || !preferences.NoReactions || preferences.CheckIns || !preferences.Wander || shushed || preferences.Silent || preferences.Hologram || asking != askingWas)
                    throw new Exception("Her settings tool didn't flip her real switches quietly: " + listed + " / " + joined + " / asking moved " + (asking - askingWas));
                checks.Add("PASS her settings tool flips Clip my games, Save big moments, live reactions, Check in on me, Wander, Quiet, her voice and hologram mode the way their own switches do, says her voice chat mic needs voice chat, reads each one back, and never cuts off the reply her brain is writing");
            }
            finally
            {
                preferences.ClipGames = clipsWas;
                preferences.ClipMoments = momentsWas;
                if (preferences.NoReactions != reactionsWas) ToggleReactions();
                if (preferences.CheckIns != checkInsWas) ToggleCheckIns();
                if (preferences.Wander != wanderWas) ToggleWander();
                if (preferences.Silent != silentWas) { if (silentWas) Silence(false); else Unsilence(); }
                if (preferences.Hologram != hologramWas) SetHologram(hologramWas);
                if (shushed != shushWas) ToggleShush(false);
                clips.Enable(!testing && preferences.ClipGames);
                SavePreferences();
                mainframe.Sync();
            }
        }

        // She can't say "I'll remember that", "reminder set" or "clipped it" without the tool running, before or after other tools ran
        // that turn, and her planner's last line can't say a failed step worked (F69, pass 4).
        private static void SmokeClaims(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> none = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>();
            Func<string, System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>> ran = delegate(string tool) { return new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> { new System.Collections.Generic.KeyValuePair<string, ToolArguments>(tool, new ToolArguments()) }; };
            string[,] claims =
            {
                { "Got it, I'll remember that!", "remember" }, { "Saved that to my notes.", "remember" }, { "I'll remember this day forever.", "" },
                { "Reminder set for 5pm.", "remind" }, { "I'll remind you at 5.", "remind" }, { "Should I set a reminder?", "" },
                { "I'll let you know when it's done.", "watch_for" }, { "I'll tell you when I think of one.", "" }, { "I'll keep an eye on it.", "watch_for" },
                { "We're watching it together now.", "watch_along" }, { "Here come my clones!", "clone" }, { "*dances* Let's go!", "animate" }, { "*grins* Nice one.", "" },
                { "I'm going to sleep, night!", "nap" }, { "Are you going to sleep?", "" }, { "I'm on my way over.", "move_yourself" }, { "Clipped it!", "clip" },
                { "I've circled the button.", "draw" }, { "Took a screenshot for you.", "shortcut" }, { "Gaming Mode activated!", "gaming_mode" }, { "Gaming Mode is on.", "" },
                { "Routine saved.", "routine" }, { "Opened Spotify for you.", "" }, { "You should put that in your notes.", "" },
                { "Turned off live reactions, choom.", "capri_settings" }, { "My voice is now off.", "capri_settings" }, { "I switched my voice off.", "capri_settings" }, { "Live reactions are on by default.", "" },
                { "You can turn off live reactions in Settings.", "" }, { "Should I turn my voice off?", "" }
            };
            for (int i = 0; i < claims.GetLength(0); i++)
                if ((Hands.Claimed(claims[i, 0], none) ?? "") != claims[i, 1]) throw new Exception("\"" + claims[i, 0] + "\" read as a claim for " + (Hands.Claimed(claims[i, 0], none) ?? "nothing") + " instead of " + (claims[i, 1].Length == 0 ? "nothing" : claims[i, 1]));
            if (Hands.Claimed("Got it, I'll remember that!", ran("remember")) != null || Hands.Claimed("Clipped it!", ran("shortcut")) != null || Hands.Claimed("Opened Spotify and set a reminder for 5.", ran("open_app")) != "remind"
                || Hands.Unclaimed("Blue's elite. I'll remember that, choom.", none) != "Blue's elite." || Hands.Unclaimed("*dances* Let's go!", none) != "Let's go!" || Hands.Unclaimed("Reminder set!", none) != null
                || Hands.NotYet("remember", Hands.KitFor()) != "I haven't saved that to my notes yet, choom. Say remember and what to keep." || Hands.NotYet("open_app", null) != Hands.Unpromised
                || Hands.Claimed("Turned off live reactions.", ran("capri_settings")) != null || Hands.NotYet("capri_settings", Hands.KitFor()) != "That setting hasn't changed yet. It's in Capri Mainframe > Settings."
                || !Hands.Admits("Couldn't open it, choom.") || Hands.Admits("Queued you up, choom."))
                throw new Exception("Her claims weren't checked against the tools that ran.");
            System.Collections.Generic.List<string> asked = new System.Collections.Generic.List<string>();
            System.Net.Sockets.TcpListener fake = null;
            Func<string, string> says = delegate(string text) { return "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":" + Voice.Quote(text) + "}}]}"; };
            Func<string, string, string> calls = delegate(string name, string json) { return "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":null,\"tool_calls\":[{\"id\":\"c1\",\"type\":\"function\",\"function\":{\"name\":\"" + name + "\",\"arguments\":" + Voice.Quote(json) + "}}]}}]}"; };
            Func<System.Collections.Generic.List<OpenWindow>> windowsWas = Hands.Windows;
            Func<string> openWas = Computer.GameOpen;
            string openAiWas = Brain.OpenAi, notesWas = Brain.MemoryPath, memoriesWas = Brain.MemoriesPath, transcriptsWas = Brain.TranscriptPath, logWas = Brain.LogPath;
            bool keepingWas = Brain.Keeping;
            Func<System.Collections.Generic.List<InstalledApp>> catalogWas = Hands.Catalog;
            try
            {
                // "Open spotify" goes to the app only where Spotify is installed, which GitHub's test machines don't have.
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Spotify", "spotify") }; };
                Hands.Forget();
                Brain.OpenAi = FakeServer(new[]
                {
                    says("Blue's elite. I'll remember that, choom."), calls("remember", "{\"text\":\"Their favourite colour is blue.\"}"), says("Saved it, choom."),
                    says("Octopuses have three hearts. I'll remember that."), says("chat"),
                    says("Opened Spotify and set a reminder for later, choom."),
                    calls("open_app", "{\"name\":\"Discord\"}"), says("Discord's up and I set a reminder to stretch."), says("Discord's up, choom."),
                    calls("open_app", "{\"name\":\"Spotify\"}"), says("Spotify's open, choom!"),
                    calls("open_app", "{\"name\":\"Discord\"}"), says("")
                }, asked, out fake);
                Brain.MemoryPath = Brain.MemoriesPath = Brain.TranscriptPath = Brain.LogPath = null;
                Brain.Keeping = false;
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow>(); };
                Computer.GameOpen = delegate { return null; };
                System.Collections.Generic.List<string> did = new System.Collections.Generic.List<string>();
                Brain chat = new Brain { Model = "gpt-5-mini", Remote = new Cloud("sk-proj-test", "gpt-5-mini") };
                chat.Act = delegate(string name, ToolArguments args) { did.Add(name); return name == "remember" ? "I'll remember: " + args.Text : name == "open_app" ? "Opened " + args.Name + "." : "Done."; };
                string saved = chat.Ask("my favourite colour is blue");
                string stripped = chat.Ask("say something cool");
                string opened = chat.Ask("open spotify");
                Brain planner = new Brain { Model = "gpt-5-mini", Remote = new Cloud("sk-proj-test", "gpt-5-mini"), OwnSteps = true };
                planner.Act = delegate(string name, ToolArguments args) { did.Add(name); return args.Name == "Spotify" ? "No app called Spotify is installed on this PC." : "Opened " + args.Name + "."; };
                string discord = planner.Ask("open discord");
                string failed = planner.Ask("open spotify");
                // A planner that ends with no words after its step worked says what she did, not "My brain sent an empty reply" (Nox, 3 Nov).
                string wordless = planner.Ask("bring discord up");
                string[] sent;
                lock (asked) sent = asked.ToArray();
                if (saved != "Saved it, choom." || stripped != "Octopuses have three hearts." || opened != "Opened spotify." || discord != "Discord's up, choom." || failed != "No app called Spotify is installed on this PC." || wordless != "Opened Discord."
                    || string.Join(",", did.ToArray()) != "remember,open_app,open_app,open_app,open_app" || sent.Length != 13 || !sent[8].Contains("You said you did something that needs remind"))
                    throw new Exception("A claim with no tool behind it reached them: " + saved + " / " + stripped + " / " + opened + " / " + discord + " / " + failed + " / " + wordless + " / " + string.Join(",", did.ToArray()) + " / " + sent.Length + " calls");
                checks.Add("PASS claims: \"I'll remember that\", reminders, watches, watching along, clones, dancing, naps, moving, clips, drawing, screenshots, Gaming Mode, routines and switching her own settings count as claims, questions, chat and how a setting starts out don't; a claim with no tool gives her hands a go and comes out of her reply when they find nothing, a claim after other tools ran comes out too, her planner gets one reminder for it, and her planner's last line can't say a failed step worked");
            }
            finally
            {
                Hands.Catalog = catalogWas;
                Hands.Forget();
                Hands.Windows = windowsWas;
                Computer.GameOpen = openWas;
                Brain.OpenAi = openAiWas;
                Brain.MemoryPath = notesWas;
                Brain.MemoriesPath = memoriesWas;
                Brain.TranscriptPath = transcriptsWas;
                Brain.LogPath = logWas;
                Brain.Keeping = keepingWas;
                if (fake != null) fake.Stop();
            }
        }

        private void SmokeGameWatch(System.Collections.Generic.List<string> checks)
        {
            Func<Sight> glimpseBefore = Computer.Glimpse;
            Job jobBefore = job;
            bool quittingBefore = quitting;
            int paceBefore = Commentary.Pace, watchPasses = 0;
            string logBefore = Brain.LogPath;
            string watchLog = Path.Combine(Path.GetTempPath(), "capri-watch-" + Guid.NewGuid().ToString("N") + ".log");
            Thread watchCheck = null;
            try
            {
                job = new Job("play minecraft");
                Brain.LogPath = watchLog;
                Computer.Glimpse = delegate
                {
                    if (++watchPasses == 1) throw new InvalidOperationException("missing game window");
                    if (watchPasses >= 5) quitting = true;
                    return new Sight { Window = new IntPtr(-12345), Title = "Minecraft", Program = "javaw" };
                };
                watchCheck = new Thread(GameWatching) { IsBackground = true };
                watchCheck.Start();
                if (!watchCheck.Join(5000) || watchPasses < 5) throw new Exception("One failed pass ended the game watcher.");
                if (!File.Exists(watchLog) || Array.FindAll(File.ReadAllLines(watchLog), watchLine => watchLine.Contains("| game watch |")).Length != 1) throw new Exception("A window without an owner reached game audio.");
                checks.Add("PASS the game watcher continues after a failed pass and skips windows without an owner");
            }
            finally
            {
                quitting = true;
                if (watchCheck != null) watchCheck.Join(1500);
                Computer.Glimpse = glimpseBefore; job = jobBefore; quitting = quittingBefore; Commentary.Pace = paceBefore; Brain.LogPath = logBefore;
                if (File.Exists(watchLog)) File.Delete(watchLog);
            }
        }

        // Her live reactions in games (F67), fed a synthetic stream of moments on a clock moved by hand, each part on its own so one
        // that fails never hides the rest: quick lines from her brain go up at once and stack to four; the feed sits on the game's
        // screen in her Mainframe's look and never takes focus; lines fade, and her brain is asked in her mood; a quick line is her
        // brain's or nothing, never a fixed one or a repeat; her brain's look follows only in time; Mute her, her quiet key and
        // reduced motion are kept; the switch is saved; banners are read.
        private void SmokeReactions(System.Collections.Generic.List<string> checks)
        {
            Section(checks, "SmokeReactQuick", delegate { ReactCheck(checks, SmokeReactQuick); });
            Section(checks, "SmokeReactFeed", delegate { ReactCheck(checks, SmokeReactFeed); });
            Section(checks, "SmokeReactFade", delegate { ReactCheck(checks, SmokeReactFade); });
            Section(checks, "SmokeReactMoods", delegate { ReactCheck(checks, SmokeReactMoods); });
            Section(checks, "SmokeReactWritten", delegate { ReactCheck(checks, SmokeReactWritten); });
            Section(checks, "SmokeReactBrain", delegate { ReactCheck(checks, SmokeReactBrain); });
            Section(checks, "SmokeReactVoice", delegate { ReactCheck(checks, SmokeReactVoice); });
            Section(checks, "SmokeReactMotion", delegate { ReactCheck(checks, SmokeReactMotion); });
            Section(checks, "SmokeReactSwitch", delegate { ReactCheck(checks, SmokeReactSwitch); });
            Section(checks, "SmokeReactBanners", delegate { ReactCheck(checks, SmokeReactBanners); });
        }

        // The stand-ins her live reactions' checks share: a full-screen game she doesn't know by name, a clock moved by hand, a
        // brain that says what it's told for her look and writes her quick lines, and ears on what goes up in the feed and what
        // she says. What they change goes back after.
        private sealed class ReactRig
        {
            // Her stand-in brain's own quick lines, which never share a word, so none reads as a repeat of another.
            internal static readonly string[] Lines = { "alpha!!", "bravo!!", "charlie!!", "echo!!", "foxtrot!!", "hotel!!", "india!!", "juliet!!", "kilo!!", "lima!!", "mike!!", "oscar!!", "papa!!", "quebec!!", "romeo!!", "sierra!!", "tango!!", "victor!!", "yankee!!", "zulu!!" };
            internal int Now = 50000000;
            internal string Brain = "SKIP";
            internal int BrainWait;
            // A quick line it's told to write instead, how long it takes, what it was asked and with which rules.
            internal Func<string, string> Quick;
            internal int QuickWait, Next;
            internal readonly System.Collections.Generic.List<string> Asks = new System.Collections.Generic.List<string>();
            internal string Rules;
            internal byte[] Frame;
            internal Rectangle GameArea;
            internal readonly System.Collections.Generic.List<string> Fed = new System.Collections.Generic.List<string>();
            internal readonly System.Collections.Generic.List<string> Said = new System.Collections.Generic.List<string>();
            internal Func<bool> On, Sees, Free, Moments, Full;
            internal Func<int> Clock, CommentClock;
            internal Action<string, bool> Show;
            internal Func<string> Game;
            internal Func<string, string, byte[][], string> See;
            internal Func<string, string, string> Ask;
            internal Func<Sight> Glimpse;
            internal int Pace, Late, Mic;
            internal bool Motion, Off, Silent, Shush, Hidden, Manual, Nap, NapAsked, Push, Hear;
            internal Job Job;
            internal string Working;
        }

        private void ReactCheck(System.Collections.Generic.List<string> checks, Action<System.Collections.Generic.List<string>, ReactRig> part)
        {
            ReactRig rig = new ReactRig();
            rig.On = Reactions.On; rig.Clock = Reactions.Clock; rig.Show = Reactions.Show; rig.Late = Reactions.BrainLate; rig.Ask = Reactions.Ask;
            rig.Sees = Commentary.Sees; rig.Free = Commentary.Free; rig.Moments = Commentary.Moments; rig.CommentClock = Commentary.Clock;
            rig.Game = Commentary.Game; rig.See = Commentary.See; rig.Pace = Commentary.Pace; rig.Glimpse = Computer.Glimpse; rig.Full = FullScreen;
            rig.Motion = preferences.Motion; rig.Off = preferences.NoReactions; rig.Silent = preferences.Silent; rig.Shush = shushed;
            rig.Hidden = hidden; rig.Manual = manualHidden; rig.Nap = napping; rig.NapAsked = napAsked; rig.Push = pushing; rig.Hear = transcribing;
            rig.Mic = micTalked; rig.Job = job; rig.Working = working;
            try
            {
                CloseTalk();
                job = null;
                working = null;
                voiceUntil = 0;
                micTalked = Environment.TickCount - 5000;
                hidden = manualHidden = napping = napAsked = shushed = pushing = transcribing = false;
                preferences.Silent = preferences.NoReactions = false;
                preferences.Motion = true;
                Reactions.Reset();
                Banners.Reset();
                Commentary.Reset();
                Reactions.On = ReactionsWatch;
                Reactions.Clock = delegate { return rig.Now; };
                Commentary.Clock = delegate { return rig.Now; };
                Commentary.Pace = Commentary.Events;
                Commentary.Sees = delegate { return true; };
                Commentary.Moments = delegate { return false; };
                Rectangle area = Screen.PrimaryScreen.Bounds;
                rig.GameArea = area;
                ReactionGame = area;
                // Any full-screen game, not just one she knows by name.
                FullScreen = delegate { return true; };
                Computer.Glimpse = delegate { return new Sight { Window = new IntPtr(7), Title = "Hollow Abyss", Program = "HollowAbyss", Bounds = area }; };
                Commentary.Game = GameAhead;
                Commentary.See = delegate(string system, string ask, byte[][] frames) { if (rig.BrainWait > 0) Thread.Sleep(rig.BrainWait); return rig.Brain; };
                Reactions.Ask = delegate(string system, string ask)
                {
                    Func<string, string> told;
                    int wait, next;
                    lock (rig.Asks)
                    {
                        rig.Asks.Add(ask);
                        rig.Rules = system;
                        told = rig.Quick;
                        wait = rig.QuickWait;
                        next = rig.Next++;
                    }
                    if (wait > 0) Thread.Sleep(wait);
                    return told != null ? told(ask) : ReactRig.Lines[next % ReactRig.Lines.Length];
                };
                reactTest = delegate(string line, bool brain) { lock (rig.Fed) rig.Fed.Add((brain ? "brain|" : "quick|") + line); };
                reactVoiceTest = delegate(string line) { lock (rig.Said) rig.Said.Add(line); };
                if (feed == null || feed.IsDisposed) feed = new ReactionFeed();
                feed.Clear();
                feed.Clock = delegate { return rig.Now / 1000.0; };
                using (Bitmap blank = new Bitmap(640, 360)) rig.Frame = Jpeg(blank, 640);
                part(checks, rig);
            }
            finally
            {
                // Her brain's last look and quick lines finish on the stand-in brain before anything goes back.
                ReactSettle(0);
                Reactions.On = rig.On;
                Reactions.Clock = rig.Clock;
                Reactions.Show = rig.Show;
                Reactions.BrainLate = rig.Late;
                Reactions.Ask = rig.Ask;
                Reactions.Reset();
                Banners.Reset();
                Commentary.Clock = rig.CommentClock;
                Commentary.Game = rig.Game;
                Commentary.See = rig.See;
                Commentary.Sees = rig.Sees;
                Commentary.Free = rig.Free;
                Commentary.Moments = rig.Moments;
                Commentary.Pace = rig.Pace;
                Commentary.Reset();
                Computer.Glimpse = rig.Glimpse;
                FullScreen = rig.Full;
                reactTest = null;
                reactVoiceTest = null;
                ReactionGame = Rectangle.Empty;
                if (feed != null) { feed.Dispose(); feed = null; }
                preferences.Motion = rig.Motion;
                preferences.NoReactions = rig.Off;
                preferences.Silent = rig.Silent;
                shushed = rig.Shush;
                hidden = rig.Hidden;
                manualHidden = rig.Manual;
                napping = rig.Nap;
                napAsked = rig.NapAsked;
                pushing = rig.Push;
                transcribing = rig.Hear;
                micTalked = rig.Mic;
                job = rig.Job;
                working = rig.Working;
                voiceUntil = 0;
                CloseTalk();
                SavePreferences();
                mainframe.Sync();
            }
        }

        private static void ReactMust(bool fine, string why) { if (!fine) throw new Exception(why); }

        // Pumps her window until that many lines have gone up in the feed, for at most 3 s.
        private static bool ReactFed(ReactRig rig, int count)
        {
            Stopwatch waited = Stopwatch.StartNew();
            while (waited.ElapsedMilliseconds < 3000)
            {
                lock (rig.Fed) if (rig.Fed.Count >= count) break;
                Application.DoEvents();
                Thread.Sleep(2);
            }
            lock (rig.Fed) return rig.Fed.Count >= count;
        }

        // A moment's quick line, put up in the feed at the time it happened.
        private static bool ReactUp(ReactRig rig, string kind)
        {
            int before;
            lock (rig.Fed) before = rig.Fed.Count;
            return Reactions.React(kind) && ReactFed(rig, before + 1);
        }

        // Pumps her window for a while, and on until her brain's look and quick lines are over, for at most 5 s. A line handed to her
        // window just before goes up too, so it can't land in the next check.
        private static void ReactSettle(int milliseconds)
        {
            Stopwatch waited = Stopwatch.StartNew();
            while ((waited.ElapsedMilliseconds < milliseconds || Commentary.Thinking || Reactions.Pending > 0) && waited.ElapsedMilliseconds < 5000)
            {
                Application.DoEvents();
                Thread.Sleep(2);
            }
            Application.DoEvents();
        }

        private static string ReactShown(ReactRig rig) { lock (rig.Fed) return string.Join(" / ", rig.Fed.ToArray()); }

        // A kill's quick line from her brain goes up within a second in a full-screen game she doesn't know by name, and a run of
        // big moments stacks to four with the newest at the bottom.
        private void SmokeReactQuick(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            ReactMust(GameAhead() == "Hollow Abyss", "A full-screen game she doesn't know by name wasn't taken for one: " + GameAhead());
            Stopwatch quick = Stopwatch.StartNew();
            ReactMust(Commentary.Moment("kill", null, rig.Frame, rig.Frame), "A kill in a game she doesn't know didn't get her brain's look.");
            ReactMust(ReactFed(rig, 1), "A kill's quick line never went up.");
            long took = quick.ElapsedMilliseconds;
            ReactMust(took < 1000 && rig.Fed[0] == "quick|" + ReactRig.Lines[0] && feed.Count == 1 && feed.Visible,
                "A kill's quick line was slow or wasn't her brain's: " + took + " ms, " + ReactShown(rig));
            foreach (string kind in new[] { "death", "advancement", "win", "loss" })
            {
                rig.Now += 300;
                ReactMust(ReactUp(rig, kind), "A " + kind + " didn't get a quick line: " + ReactShown(rig));
            }
            ReactSettle(50);
            string[] stack = feed.Texts;
            float[] slots = feed.Slots;
            ReactMust(feed.Count == Reactions.Most && stack[Reactions.Most - 1] == rig.Fed[4].Substring(6) && stack[0] == rig.Fed[1].Substring(6) && slots[0] < slots[1] && slots[1] < slots[2] && slots[2] < slots[3],
                "The feed didn't stack to four with the newest at the bottom: " + string.Join(" / ", stack) + " at " + string.Join(", ", Array.ConvertAll(slots, slot => slot.ToString("0"))));
            checks.Add("PASS live reactions: a moment in a full-screen game she doesn't know by name gets her brain's quick line in the feed in " + took + " ms, and a run of big moments stacks to four with the newest at the bottom and the oldest pushed out");
        }

        // The feed sits on the right of the game's screen a third of the way down, clear of the top-right corner, never takes a
        // click or focus, and is painted out of what her game watching sees. Each plate is in her Mainframe's look.
        private void SmokeReactFeed(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            IntPtr front = Native.GetForegroundWindow();
            ReactMust(ReactUp(rig, "kill") && ReactUp(rig, "death") && feed.Count == 2, "Two moments didn't put two lines up: " + ReactShown(rig));
            Rectangle screen = rig.GameArea, at = feed.Bounds;
            float scale = feed.Scaling;
            ReactMust(screen.Contains(at) && at.Left > screen.Left + screen.Width / 2 && at.Right >= screen.Right - (int)(80 * scale) && at.Top >= screen.Top + screen.Height / 4 && at.Top <= screen.Top + screen.Height / 2 && at.Contains(feed.Area),
                "The feed isn't on the right of the game's screen a third of the way down: " + at + " on " + screen + ", lines at " + feed.Area);
            Rectangle second = new Rectangle(screen.Right, screen.Top, 2560, 1440);
            Rectangle there = ReactionFeed.Spot(second, second, ReactionFeed.CanvasSize(1.5f), 1.5f);
            Rectangle windowed = new Rectangle(second.Left + 200, second.Top + 100, 1280, 720);
            Rectangle beside = ReactionFeed.Spot(windowed, second, ReactionFeed.CanvasSize(1f), 1f);
            Rectangle hanging = ReactionFeed.Spot(new Rectangle(second.Right - 300, second.Top, 1280, 720), second, ReactionFeed.CanvasSize(1f), 1f);
            ReactMust(second.Contains(there) && there.Left > second.Left + second.Width / 2 && there.Top >= second.Top + second.Height / 4 && windowed.Contains(beside) && beside.Left > windowed.Left + windowed.Width / 2 && second.Contains(hanging),
                "The feed left the game's own screen: " + there + ", " + beside + ", " + hanging);
            int point = ((at.Top + at.Height / 2) << 16) | ((at.Left + at.Width / 2) & 0xFFFF);
            bool through = Native.SendMessage(feed.Handle, 0x0084, IntPtr.Zero, new IntPtr(point)) == new IntPtr(-1) && Native.SendMessage(feed.Handle, 0x0021, IntPtr.Zero, IntPtr.Zero) == new IntPtr(3);
            ReactMust(feed.ClickThrough && through && Native.GetForegroundWindow() == front && Form.ActiveForm != feed && !feed.ContainsFocus,
                "The feed took a click or focus: click-through " + feed.ClickThrough + ", hit test " + through + ", front kept " + (Native.GetForegroundWindow() == front));
            using (Bitmap seen = new Bitmap(480, 270, PixelFormat.Format32bppArgb))
            {
                using (Graphics paper = Graphics.FromImage(seen)) paper.Clear(Color.White);
                Rectangle lines = feed.Area;
                PaintOut(seen, screen, lines);
                int x = (lines.Left + lines.Width / 2 - screen.Left) * seen.Width / screen.Width, y = (lines.Top + lines.Height / 2 - screen.Top) * seen.Height / screen.Height;
                ReactMust(seen.GetPixel(x, y).ToArgb() == Color.Black.ToArgb() && seen.GetPixel(10, 10).ToArgb() == Color.White.ToArgb(), "Her own feed wasn't painted out of what her game watching sees.");
            }
            Color quickBar, brainBar, ground;
            bool inked = false;
            using (Bitmap quickPlate = ReactionFeed.Plate("did you SEE that??", false, 1))
            using (Bitmap brainPlate = ReactionFeed.Plate("That sniper had your number.", true, 1))
            using (Bitmap leftward = ReactionFeed.Plate("مذهل جدا", true, 1))
            {
                int rim = ReactionFeed.Rim(1);
                quickBar = quickPlate.GetPixel(rim + 11, quickPlate.Height / 2);
                brainBar = brainPlate.GetPixel(rim + 11, brainPlate.Height / 2);
                ground = quickPlate.GetPixel(rim + 5, quickPlate.Height / 2);
                for (int row = rim + 10; row < leftward.Height - rim - 10 && !inked; row++)
                    for (int column = rim + 22; column < leftward.Width - rim - 14 && !inked; column++)
                        if (leftward.GetPixel(column, row).R > 150) inked = true;
            }
            ReactMust(quickBar.ToArgb() == Neon.Hot.ToArgb() && brainBar.ToArgb() == Neon.Cyan.ToArgb() && ground.A == 255 && ground.R < 48 && ground.G < 32 && ground.B < 48 && inked,
                "A plate isn't in her Mainframe's look: bars " + quickBar + " and " + brainBar + ", ground " + ground + ", a right-to-left line drawn " + inked);
            checks.Add("PASS live reactions feed: on the right of the game's screen a third of the way down and clear of the top-right corner, on the game's own screen with two screens and beside a windowed game, click-through, never active and never taking focus, painted out of what her game watching sees, and each line on a plate in her Mainframe's look, right-to-left lines too");
        }

        // Each line fades after about 4 s, the oldest first, and the feed goes once they have.
        private void SmokeReactFade(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            ReactMust(ReactionFeed.Fade(1) == 1 && ReactionFeed.Fade(3.8) > 0 && ReactionFeed.Fade(3.8) < 1 && ReactionFeed.Fade(4) == 0, "A line's fade is off: " + ReactionFeed.Fade(3.8));
            string[] kinds = { "kill", "death", "advancement", "win" };
            for (int i = 0; i < kinds.Length; i++)
            {
                if (i > 0) rig.Now += 300;
                ReactMust(ReactUp(rig, kinds[i]), "A " + kinds[i] + " didn't get a quick line: " + ReactShown(rig));
            }
            rig.Now += 3200;
            feed.Step();
            ReactMust(feed.Count == 3 && feed.Texts[0] == rig.Fed[1].Substring(6) && feed.Visible, "Lines left before their time, or the oldest stayed: " + feed.Count + " " + string.Join(" / ", feed.Texts));
            rig.Now += 1200;
            feed.Step();
            ReactMust(feed.Count == 0 && !feed.Visible && feed.Area.IsEmpty, "The feed didn't fade away: " + feed.Count + " left");
            checks.Add("PASS live reactions fade after 4 s, the oldest first, and the feed goes once they have");
        }

        // Her brain is asked in the mood the run of the game has put her in: each kind of moment comes with three of its own lines
        // as examples, and a run of deaths or kills is told with its count.
        private void SmokeReactMoods(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            Func<string, int, string> asked = delegate(string kind, int advance)
            {
                rig.Now += advance;
                int before;
                lock (rig.Asks) before = rig.Asks.Count;
                bool asking = Reactions.React(kind);
                ReactSettle(0);
                lock (rig.Asks) return asking && rig.Asks.Count > before ? rig.Asks[rig.Asks.Count - 1] : "(not asked)";
            };
            Func<string, string[], int, int> shown = delegate(string ask, string[] pool, int count)
            {
                int found = 0;
                foreach (string line in pool) if (ask.IndexOf("\n- " + string.Format(line, count) + "\n", StringComparison.Ordinal) >= 0) found++;
                return found;
            };
            string[] kinds = { "kill", "death", "hit", "flash", "sound", "scene", "dark", "win", "loss", "advancement" };
            string[][] pools = { Reactions.Kills, Reactions.Deaths, Reactions.Hits, Reactions.Flashes, Reactions.Sounds, Reactions.Scenes, Reactions.Darks, Reactions.Wins, Reactions.Losses, Reactions.Unlocks };
            string wrong = null;
            for (int i = 0; i < kinds.Length; i++)
            {
                string ask = asked(kinds[i], 11000);
                if (shown(ask, pools[i], 0) != 3) wrong = wrong ?? "a " + kinds[i] + " wasn't asked with three of its own lines: " + ask;
            }
            ReactMust(wrong == null, "Her brain wasn't shown the right examples: " + wrong);
            Reactions.Reset();
            string firstDeath = asked("death", 3000);
            asked("death", 3000);
            string third = asked("death", 3000);
            string comeback = asked("kill", 3000);
            asked("kill", 3000);
            string onFire = asked("kill", 3000);
            string ended = asked("death", 3000);
            bool kindsRight = Reactions.MoodOf("kill") == GameMood.Happy && Reactions.MoodOf("death") == GameMood.Hit && Reactions.MoodOf("flash") == GameMood.Surprise;
            bool died = shown(firstDeath, Reactions.Deaths, 0) == 3 && firstDeath.Contains("They just died.");
            bool teased = shown(third, Reactions.Again, 3) == 3 && third.Contains("that's 3 deaths in a row");
            bool relief = shown(comeback, Reactions.Comebacks, 0) == 3 && comeback.Contains("after dying 3 times in a row");
            bool streak = shown(onFire, Reactions.Streaks, 0) == 3 && onFire.Contains("that's 3 in a row");
            bool stung = shown(ended, Reactions.Ended, 0) == 3 && ended.Contains("ended their streak of 3");
            ReactMust(kindsRight && died && teased && relief && streak && stung,
                "Her brain wasn't asked in her mood: kinds " + kindsRight + ", first death " + died + ", third " + teased + ", comeback " + relief + ", streak " + streak + ", ended " + stung + ": " + third);
            checks.Add("PASS live reactions ask her brain in her mood: each kind of moment comes with three of its own lines as examples, a third death in a row is told with its count and teased, a kill after deaths is a comeback, a third kill a streak, and a death after it stings");
        }

        // A quick line is her brain's or nothing (Lachy, 3 Nov: "Premade ones? fr? Remove that"): its line goes up as it wrote it,
        // asked with her safety lines, the game, what happened, three examples and her last lines; a line that repeats one of hers,
        // nearly does or copies an example is dropped; a slow or failing brain puts nothing up, never a fixed line; and a brain late
        // three times running is only asked every 30 s until it's quick again.
        private void SmokeReactWritten(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            Reactions.BrainLate = 400;
            Func<string, string, int, Func<string, string>, bool> up = delegate(string kind, string detail, int advance, Func<string, string> write)
            {
                rig.Now += advance;
                rig.Quick = write;
                int before;
                lock (rig.Fed) before = rig.Fed.Count;
                bool asking = Reactions.React(kind, detail);
                ReactSettle(0);
                ReactSettle(150);
                lock (rig.Fed) return asking && rig.Fed.Count > before;
            };
            Func<string> lastAsk = delegate { lock (rig.Asks) return rig.Asks[rig.Asks.Count - 1]; };
            bool written = up("kill", null, 0, ask => "that boss just FOLDED");
            string first = lastAsk(), rules = rig.Rules;
            int examples = 0;
            foreach (string line in Reactions.Kills) if (first.IndexOf("\n- " + line + "\n", StringComparison.Ordinal) >= 0) examples++;
            bool banner = up("win", "The screen says VICTORY", 2000, ask => "dub secured, no notes");
            string won = lastAsk();
            ReactMust(written && banner && feed.Texts[feed.Count - 1] == "dub secured, no notes" && rules.Contains(Brain.Safety) && rules.Contains("about 6 words")
                && first.Contains("(They're playing Hollow Abyss. They just took someone down.") && won.Contains("They just won. This just happened: \"The screen says VICTORY\"."),
                "Her brain's line didn't go up as it wrote it, or it wasn't asked with her safety lines, the game and what happened: " + ReactShown(rig) + " / " + first);
            checks.Add("PASS live reactions come from her brain: its quick line goes up as it wrote it, asked with her safety lines, the game, what happened and what the screen said");
            bool repeated = up("death", null, 2000, ask => "That boss just folded!");
            string seen = lastAsk();
            bool near = up("death", null, 2000, ask => "that boss just folded again");
            bool copied = up("death", null, 2000, ask => Regex.Match(ask, @"word for word:\n- ([^\n]+)").Groups[1].Value);
            bool fresh = up("death", null, 2000, ask => "who even taught them to aim");
            ReactMust(examples == 3 && seen.Contains("\n- that boss just FOLDED\n- dub secured, no notes\n"),
                "Her brain wasn't shown three examples and her last lines: " + examples + " examples in " + first + " / " + seen);
            checks.Add("PASS live reactions show her brain three of her lines for the moment as examples, and her last lines over the game");
            ReactMust(!repeated && !near && !copied && fresh, "A repeat or a copied example went up, or a fresh line didn't: " + repeated + " " + near + " " + copied + " " + fresh + ", " + ReactShown(rig));
            checks.Add("PASS live reactions drop a line from her brain that repeats one of her last lines, nearly repeats one or copies an example, and keep a fresh one");
            rig.QuickWait = 700;
            bool slow = up("kill", null, 2000, ask => "way too late for this one");
            rig.QuickWait = 0;
            bool failed = up("kill", null, 2000, ask => { throw new BrainException("No brain here."); });
            bool cut = up("kill", null, 2000, ask => { throw new System.Net.WebException("The connection was cut."); });
            rig.Now += 2000;
            int asks;
            lock (rig.Asks) asks = rig.Asks.Count;
            bool rested = !Reactions.React("kill");
            lock (rig.Asks) rested = rested && rig.Asks.Count == asks;
            bool back = up("kill", null, Reactions.SlowAsk, ask => "back on time, finally");
            string[] fed;
            lock (rig.Fed) fed = rig.Fed.ToArray();
            bool onlyHers = fed.Length == 4 && fed[0] == "quick|that boss just FOLDED" && fed[1] == "quick|dub secured, no notes" && fed[2] == "quick|who even taught them to aim" && fed[3] == "quick|back on time, finally";
            ReactMust(!slow && !failed && !cut && rested && back && onlyHers,
                "A slow or failing brain put something up, or wasn't asked less: slow " + slow + ", failed " + failed + ", cut " + cut + ", rested " + rested + ", back " + back + ", " + ReactShown(rig));
            checks.Add("PASS live reactions show nothing, never a fixed line, when her brain answers after 2.5 s or fails, and a brain late three times running is only asked every 30 s until it's quick again");
            Func<string> gameWas = Commentary.Game;
            int thread = Thread.CurrentThread.ManagedThreadId, fedBefore;
            lock (rig.Fed) fedBefore = rig.Fed.Count;
            try
            {
                rig.Now += Reactions.SlowAsk;
                rig.Quick = ask => "this moment was from the old game";
                Commentary.Game = delegate { return Thread.CurrentThread.ManagedThreadId == thread ? "Hollow Abyss" : "Another game"; };
                ReactMust(Reactions.React("death"), "The queued game change check did not start.");
                ReactSettle(0);
                lock (rig.Fed) ReactMust(rig.Fed.Count == fedBefore, "A queued reaction followed a moment into another game.");
            }
            finally { Commentary.Game = gameWas; }
            checks.Add("PASS a reaction keeps the game where its moment happened and drops it if the game changes before its worker starts");
        }

        // Her brain's look follows when it lands in time and is dropped when it's late, and a slow brain is asked less.
        private void SmokeReactBrain(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            Reactions.BrainLate = 400;
            rig.Brain = "That sniper had your number.";
            // Her look reads pictures, so it takes a moment longer than her quick line.
            rig.BrainWait = 100;
            ReactMust(Commentary.Moment("death", null, rig.Frame, rig.Frame), "A death didn't get her brain's look.");
            ReactMust(ReactFed(rig, 2), "Her brain's look didn't follow the moment: " + ReactShown(rig));
            ReactSettle(100);
            ReactMust(rig.Fed.Count == 2 && rig.Fed[0].StartsWith("quick|", StringComparison.Ordinal) && rig.Fed[1] == "brain|That sniper had your number." && feed.Texts[feed.Count - 1] == "That sniper had your number.",
                "Her brain's look didn't follow her quick line: " + ReactShown(rig));
            rig.Now += 60000;
            rig.Brain = "Took you long enough to notice.";
            rig.BrainWait = 700;
            lock (rig.Fed) rig.Fed.Clear();
            ReactMust(Commentary.Moment("death", null, rig.Frame, rig.Frame), "A second death didn't get her brain's look.");
            ReactSettle(1200);
            ReactMust(rig.Fed.Count == 1 && rig.Fed[0].StartsWith("quick|", StringComparison.Ordinal), "A late look went up: " + ReactShown(rig));
            rig.BrainWait = 0;
            Reactions.Reset();
            for (int late = 0; late < 3; late++) Reactions.Looked(3000);
            bool slow = Reactions.Slow && Reactions.Asking(rig.Now);
            Reactions.Asked(rig.Now);
            bool waits = !Reactions.Asking(rig.Now + 1000) && Reactions.Asking(rig.Now + Reactions.SlowAsk);
            Reactions.Looked(100);
            ReactMust(slow && waits && !Reactions.Slow && Reactions.Asking(rig.Now + 1000), "A slow brain wasn't asked less, or a quick one again was: " + slow + " " + waits);
            checks.Add("PASS live reactions and her brain's look: its line follows the quick one when it lands in time and is dropped when it's late, and a brain late three times running is only asked every 30 s until it's quick again");
        }

        // Out loud at most once every 8 s, never over her own voice or theirs, and Mute her and her quiet key keep it to text.
        private void SmokeReactVoice(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            Func<string, int, bool, bool> spoken = delegate(string kind, int advance, bool aloud)
            {
                rig.Now += advance;
                int said;
                lock (rig.Said) said = rig.Said.Count;
                if (!ReactUp(rig, kind)) return false;
                lock (rig.Said) return (rig.Said.Count > said) == aloud;
            };
            bool first = spoken("kill", 0, true);
            bool gapKept = spoken("death", 2000, false);
            bool afterGap = spoken("win", 6100, true);
            voiceUntil = clock.Elapsed.TotalSeconds + 5;
            bool overHer = spoken("loss", 8100, false);
            voiceUntil = 0;
            micTalked = Environment.TickCount;
            bool overThem = spoken("advancement", 8100, false);
            micTalked = Environment.TickCount - 5000;
            pushing = true;
            bool overPush = spoken("kill", 8100, false);
            pushing = false;
            ToggleShush();
            CloseTalk();
            bool muted = shushed && spoken("death", 8100, false);
            ToggleShush();
            CloseTalk();
            Message quiet = Message.Create(Handle, 0x0312, new IntPtr(QuietKeyId), IntPtr.Zero);
            WndProc(ref quiet);
            CloseTalk();
            bool quietKey = shushed && spoken("win", 10100, false);
            quiet = Message.Create(Handle, 0x0312, new IntPtr(QuietKeyId), IntPtr.Zero);
            WndProc(ref quiet);
            CloseTalk();
            bool back = !shushed && spoken("loss", 10100, true);
            ReactMust(first && gapKept && afterGap && overHer && overThem && overPush && muted && quietKey && back,
                "Her voice for reactions went wrong: first " + first + ", gap " + gapKept + "/" + afterGap + ", over her " + overHer + ", over them " + overThem + "/" + overPush + ", muted " + muted + ", quiet key " + quietKey + ", back " + back + ", said " + string.Join(" / ", rig.Said.ToArray()) + ", fed " + ReactShown(rig));
            checks.Add("PASS live reactions out loud: one at most every 8 s, never over her own voice, their voice or their push-to-talk key, and Mute her and her quiet key keep every line as text in the feed");
        }

        // Reduced motion: no glitch and no slide. With motion on, a line glitches in and the rest slide up, then settle.
        private void SmokeReactMotion(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            string[] kinds = { "kill", "death", "win", "loss", "advancement" };
            preferences.Motion = false;
            foreach (string kind in kinds)
            {
                rig.Now += 300;
                ReactMust(ReactUp(rig, kind), "A " + kind + " didn't get a quick line with motion off: " + ReactShown(rig));
            }
            bool still = feed.Count == Reactions.Most && !feed.Motion && !feed.Tearing && !feed.Sliding;
            Reactions.Reset();
            feed.Clear();
            preferences.Motion = true;
            foreach (string kind in kinds)
            {
                rig.Now += 300;
                ReactMust(ReactUp(rig, kind), "A " + kind + " didn't get a quick line with motion on: " + ReactShown(rig));
            }
            bool moving = feed.Count == Reactions.Most && feed.Motion && feed.Tearing && feed.Sliding;
            rig.Now += 400;
            feed.Step();
            bool settled = !feed.Tearing && !feed.Sliding;
            bool torn = false;
            using (Bitmap plate = ReactionFeed.Plate("did you SEE that??", false, 1))
            using (Bitmap ripped = ReactionFeed.Torn(plate, 1, 1, 67))
                for (int y = 0; y < plate.Height && !torn; y++)
                    for (int x = 0; x < plate.Width && !torn; x++)
                        if (plate.GetPixel(x, y) != ripped.GetPixel(x, y)) torn = true;
            ReactMust(still && moving && settled && torn, "Reduced motion wasn't kept: still " + still + ", moving " + moving + ", settled " + settled + ", glitch drawn " + torn);
            checks.Add("PASS live reactions and reduced motion: with motion off lines go up with no glitch and jump to their slots; with it on they glitch in and the rest slide up, then settle");
        }

        // Only while it's on, her comments run and she's watching: Comments Off, the switch off, a hide they asked for, a nap or her
        // own game job mean none. The switch is saved, and settings from before it start with it on.
        private void SmokeReactSwitch(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            Commentary.Pace = Commentary.Off;
            bool offPace = !Reactions.React("kill") && !Commentary.Moment("kill", null, rig.Frame, rig.Frame);
            Commentary.Pace = Commentary.Events;
            manualHidden = hidden = true;
            bool offHidden = !Reactions.React("death");
            manualHidden = hidden = false;
            napping = true;
            bool offNap = !Reactions.React("win");
            napping = false;
            job = new Job("play minecraft");
            working = "On it. Esc stops me.";
            bool offPlaying = job.Playing && !Reactions.React("loss");
            job = null;
            working = null;
            mainframe.Sync();
            bool shownOn = mainframe.ReactionsShown && ReactionsOn;
            mainframe.FlipReactions();
            bool savedOff = preferences.NoReactions && LoadPreferences().NoReactions && !mainframe.ReactionsShown && !Reactions.Running && !Reactions.React("advancement");
            mainframe.FlipReactions();
            bool savedOn = !preferences.NoReactions && !LoadPreferences().NoReactions && mainframe.ReactionsShown && Reactions.Running && ReactUp(rig, "advancement");
            bool oldOn;
            using (MemoryStream old = new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{\"CommentPace\":1}")))
                oldOn = !((Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(old)).NoReactions && !new Preferences().NoReactions && !Preferences.Fresh().NoReactions;
            ReactMust(offPace && offHidden && offNap && offPlaying && shownOn && savedOff && savedOn && oldOn,
                "Live reactions ran when they shouldn't, or the switch wasn't saved: comments off " + offPace + ", hidden " + offHidden + ", nap " + offNap + ", her game " + offPlaying + ", shown " + shownOn + ", off " + savedOff + ", on " + savedOn + ", old settings " + oldOn);
            checks.Add("PASS Live reactions switch: on by default in new and old settings, saved both ways from Settings > GAMES, and no reactions with Comments off, the switch off, a hide they asked for, a nap or a game she's playing herself");
        }

        // Big words on screen: a win, a loss, a death or a kill she can read, never a sign, a menu or a small line, and a banner that
        // stays up counts once. Their own kills in Minecraft's log count too.
        private void SmokeReactBanners(System.Collections.Generic.List<string> checks, ReactRig rig)
        {
            string kindWrong = null;
            string[,] words = { { "VICTORY!", "win" }, { "Victory Royale", "win" }, { "DEFEAT", "loss" }, { "Game Over", "loss" }, { "YOU DIED", "death" }, { "Eliminated by xXSniperXx", "death" }, { "DOUBLE KILL", "kill" }, { "Headshot", "kill" },
                { "Victory Road", null }, { "Press any key to defeat the boss", null }, { "Settings", null }, { "", null } };
            for (int word = 0; word < words.GetLength(0); word++)
                if (Banners.Kind(words[word, 0]) != words[word, 1]) kindWrong = kindWrong ?? words[word, 0] + " read as " + Banners.Kind(words[word, 0]);
            ReactMust(kindWrong == null && Banners.Fresh("win", rig.Now) && !Banners.Fresh("win", rig.Now + 5000) && Banners.Fresh("win", rig.Now + 20000), "Banner words were read wrong: " + kindWrong);
            string player = null;
            GameLog.Parse("[12:01:05] [Render thread/INFO]: Setting user: Steve_99", ref player);
            GameEvent kill = GameLog.Parse("[12:03:00] [Render thread/INFO]: [System] [CHAT] Alex was slain by Steve_99", ref player);
            GameEvent died = GameLog.Parse("[12:03:01] [Server thread/INFO]: Steve_99 was slain by Alex", ref player);
            GameEvent other = GameLog.Parse("[12:03:02] [Render thread/INFO]: [System] [CHAT] Alex was slain by Zombie", ref player);
            ReactMust(kill != null && kill.Kind == "kill" && kill.Detail.Contains("Alex") && died != null && died.Kind == "death" && other != null && other.Kind == "chat",
                "Minecraft's log didn't tell their kill from their death: " + (kill == null ? "-" : kill.Kind) + ", " + (died == null ? "-" : died.Kind) + ", " + (other == null ? "-" : other.Kind));
            checks.Add("PASS live reactions can tell a win, a loss, a death and a kill from big words on screen and never from a sign or a menu line, count a banner that stays up once, and read their own kills in Minecraft's log");
            if (!Ocr.Ready) checks.Add("LIMIT live reactions' banner reading needs Windows OCR, which isn't ready here; a person must check a VICTORY or YOU DIED screen gets its line");
            else
            {
                string read = null, small = null, saidWords = null, smallWords = null;
                long readIn = 0;
                Thread reader = new Thread(delegate()
                {
                    Func<string, int, Bitmap> banner = delegate(string text, int size)
                    {
                        Bitmap shot = new Bitmap(1280, 720, PixelFormat.Format32bppArgb);
                        using (Graphics paper = Graphics.FromImage(shot))
                        using (Font big = new Font("Arial", size, FontStyle.Bold, GraphicsUnit.Pixel))
                        using (StringFormat middle = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                        {
                            paper.Clear(Color.FromArgb(24, 20, 30));
                            paper.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
                            paper.DrawString(text, big, Brushes.White, new RectangleF(0, 0, 1280, 720), middle);
                        }
                        return shot;
                    };
                    using (Bitmap warm = banner("WARM UP", 80))
                    using (Bitmap warmMiddle = Banners.Middle(warm)) { string warmWords; Banners.Read(warmMiddle, 6000, out warmWords); }
                    using (Bitmap won = banner("VICTORY", 96))
                    {
                        Stopwatch reading = Stopwatch.StartNew();
                        using (Bitmap wonMiddle = Banners.Middle(won)) read = Banners.Read(wonMiddle, 500, out saidWords);
                        readIn = reading.ElapsedMilliseconds;
                    }
                    using (Bitmap sign = banner("VICTORY ROAD 2 KM", 16))
                    using (Bitmap signMiddle = Banners.Middle(sign)) small = Banners.Read(signMiddle, 3000, out smallWords);
                });
                reader.IsBackground = true;
                reader.Start();
                ReactMust(reader.Join(20000), "Reading a banner never finished.");
                ReactMust(small == null && readIn < 1000, "A small sign was read as a banner, or a banner read was slow: " + small + " (" + smallWords + "), " + readIn + " ms");
                if (read == "win") checks.Add("PASS live reactions read a big VICTORY across the middle of the screen as a win in " + readIn + " ms, with a small sign left alone");
                else checks.Add("LIMIT live reactions' banner reading: Windows OCR here didn't read a drawn VICTORY in 500 ms (" + (saidWords ?? "nothing") + "); a person must check a real VICTORY or YOU DIED screen gets its line");
            }
            checks.Add("LIMIT live reactions over a real borderless game: a person must check the feed shows on the right of the game a third of the way down, glitches in and fades, never takes a click or focus, follows the game to a second monitor, and that exclusive full screen hides it");
            checks.Add("LIMIT live reactions out loud: a person must hear at most one reaction every 8 s in a real game, never over her voice or theirs, and none with Mute her or her quiet key");
        }

        private static void SmokeGameWindows(System.Collections.Generic.List<string> checks, Func<string> find)
        {
            Func<System.Collections.Generic.List<OpenWindow>> windowsWere = Hands.Windows;
            try
            {
                System.Collections.Generic.List<OpenWindow> windows = new System.Collections.Generic.List<OpenWindow>();
                Hands.Windows = delegate { return windows; };
                foreach (string editor in new[] { "notepad", "Notepad++", "Code", "WINWORD", "EXCEL", "soffice.bin", "AcroRd32" })
                {
                    windows.Clear();
                    windows.Add(new OpenWindow(IntPtr.Zero, "Minecraft.txt", editor));
                    if (find() != null || Computer.GameWindow(new Sight { Window = new IntPtr(9), Title = "Minecraft.txt", Program = editor })) throw new Exception("A document was taken for a game.");
                }
                windows.Add(new OpenWindow(IntPtr.Zero, "Minecraft 26.3", "javaw"));
                if (find() != "Minecraft 26.3") throw new Exception("A document hid a real game's title.");
                checks.Add("PASS game detection skips editor and document windows and still finds a real game behind them");
            }
            finally { Hands.Windows = windowsWere; }
        }

        private static void SmokeGameHolds(System.Collections.Generic.List<string> checks)
        {
            Action<short, bool, bool> keyWas = Computer.SendKey;
            Action<int, int> mouseWas = Computer.SendMouse;
            Func<Rectangle, byte[]> grayWas = Computer.GrayFrame;
            Func<IntPtr> frontWas = Computer.Front;
            Func<bool> escapeWas = Computer.Escape;
            Action haltWas = Computer.Halted;
            bool flinchedWas = Computer.Flinched;
            System.Collections.Generic.HashSet<short> down = new System.Collections.Generic.HashSet<short>();
            int buttons = 0, jumps = 0, frontReads = 0, grayReads = 0;
            Sight heldSight = new Sight { Window = new IntPtr(7), Bounds = new Rectangle(0, 0, 1280, 720) };
            try
            {
                Computer.Escape = delegate { return false; };
                Computer.Halted = delegate { };
                Computer.Flinched = false;
                Computer.SendKey = delegate(short code, bool up, bool extended) { if (up) down.Remove(code); else { down.Add(code); if (code == 0x20) jumps++; } };
                Computer.SendMouse = delegate(int flags, int data) { buttons |= flags & 0x2A; buttons &= ~((flags & 0x54) >> 1); };
                Computer.GrayFrame = delegate(Rectangle area) { return new byte[Computer.GrayWidth * Computer.GrayHeight]; };
                foreach (bool walkingHold in new[] { false, true })
                {
                    Computer.Arm(); frontReads = 0;
                    Computer.Front = delegate { return ++frontReads < 5 ? new IntPtr(7) : new IntPtr(8); };
                    string released = walkingHold ? Computer.Walk("w", "30", "yes", heldSight) : Computer.MouseHold("right", "30", "w", "no", heldSight);
                    if (!released.Contains("no longer in front") || down.Count != 0 || buttons != 0) throw new Exception("A window switch left game input held.");
                }
                Computer.Front = delegate { throw new Exception("A windowless sight checked the foreground."); };
                Sight noWindow = new Sight { Bounds = heldSight.Bounds };
                if (!Computer.Walk("s", "0.01", "no", noWindow).StartsWith("Moved") || !Computer.MouseHold("left", "0.01", null, "no", noWindow).StartsWith("Held")) throw new Exception("A windowless hold stopped working.");
                checks.Add("PASS game holds release on a faked window switch and still run with a windowless sight");
                Computer.Front = delegate { return new IntPtr(7); };
                foreach (string stopWord in new[] { "yes", "true", "no", "false" })
                {
                    grayReads = 0;
                    Computer.GrayFrame = delegate(Rectangle area) { byte[] gray = new byte[Computer.GrayWidth * Computer.GrayHeight]; if (++grayReads > 1) for (int grayIndex = 0; grayIndex < gray.Length; grayIndex++) gray[grayIndex] = 255; return gray; };
                    string stoppedHold = Computer.MouseHold("left", "0.15", null, stopWord, heldSight);
                    if (stoppedHold.Contains("crosshair changed") != (stopWord == "yes" || stopWord == "true")) throw new Exception("A stop boolean changed the hold's meaning.");
                }
                Computer.GrayFrame = delegate(Rectangle area) { return new byte[Computer.GrayWidth * Computer.GrayHeight]; };
                foreach (string jumpWord in new[] { "yes", "true", "no", "false" })
                {
                    jumps = 0;
                    Computer.Walk("w", "0.8", jumpWord, heldSight);
                    if ((jumps > 0) != (jumpWord == "yes" || jumpWord == "true") || down.Count != 0) throw new Exception("A jump boolean changed the walk's meaning.");
                }
                checks.Add("PASS stop and jump accept true and false with the same behaviour as yes and no");
                using (ManualResetEvent pressedHold = new ManualResetEvent(false))
                {
                    Computer.SendMouse = delegate(int flags, int data) { buttons |= flags & 0x2A; buttons &= ~((flags & 0x54) >> 1); if ((flags & 0x2A) != 0) pressedHold.Set(); };
                    Thread closingHold = new Thread(delegate() { Computer.MouseHold("right", "30", "shift+w", "no", heldSight); });
                    closingHold.IsBackground = true;
                    closingHold.Start();
                    bool startedHold = pressedHold.WaitOne(1000);
                    Stopwatch closingTime = Stopwatch.StartNew();
                    Computer.Close();
                    long closingMs = closingTime.ElapsedMilliseconds;
                    if (!closingHold.Join(1000) || !startedHold || down.Count != 0 || buttons != 0 || closingMs > 1100) throw new Exception("Closing didn't release held input promptly.");
                    Computer.Arm();
                    if (!Computer.Interrupted) throw new Exception("A queued job restarted during close.");
                }
                checks.Add("PASS closing interrupts a long hold, waits for its release and prevents a queued job from rearming");
                typeof(Computer).GetField("closing", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static).SetValue(null, false);
                Computer.Arm();
                using (ManualResetEvent takingFrame = new ManualResetEvent(false))
                using (ManualResetEvent finishFrame = new ManualResetEvent(false))
                {
                    int slowFrames = 0;
                    Computer.GrayFrame = delegate(Rectangle slowArea) { if (++slowFrames > 1) { takingFrame.Set(); finishFrame.WaitOne(3000); } return new byte[Computer.GrayWidth * Computer.GrayHeight]; };
                    Thread slowWalk = new Thread(delegate() { Computer.Walk("w", "30", "no", heldSight); }) { IsBackground = true };
                    slowWalk.Start();
                    try
                    {
                        if (!takingFrame.WaitOne(1000)) throw new Exception("The fake held walk didn't reach its frame.");
                        Stopwatch timeoutClose = Stopwatch.StartNew();
                        Computer.Close();
                        if (timeoutClose.ElapsedMilliseconds > 1100 || down.Count != 0 || !slowWalk.IsAlive) throw new Exception("Closing waited for a stuck capture or left its key held.");
                    }
                    finally { finishFrame.Set(); slowWalk.Join(1000); }
                }
                checks.Add("PASS closing waits at most a second and releases input even while a game capture is stuck");
            }
            finally
            {
                typeof(Computer).GetField("closing", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static).SetValue(null, false);
                Computer.SendKey = keyWas; Computer.SendMouse = mouseWas; Computer.GrayFrame = grayWas; Computer.Front = frontWas;
                Computer.Halted = haltWas; Computer.Flinched = flinchedWas; Computer.Arm(); Computer.Escape = escapeWas;
            }
        }

        // A tool call written a little off from what it asked for still runs, and one that can't be read costs a turn, not the job.
        private static void SmokeLooseCalls(System.Collections.Generic.List<string> checks)
        {
            string[] loose =
            {
                "{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"a\",\"name\":\"walk\",\"input\":{\"seconds\":2.5,\"keys\":[\"shift\",\"w\"],\"jump\":true}}]}",
                "{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"b\",\"name\":\"look\",\"input\":{\"x\":\"640\",\"y\":\"360\"}}]}"
            };
            ClaudeReply walked = Brain.Parsed(loose[0]), looked = Brain.Parsed(loose[1]);
            if (walked.Content[0].Input.Seconds != "2.5" || walked.Content[0].Input.Keys != "shift+w" || walked.Content[0].Input.Jump != "true") throw new Exception("A loose tool call wasn't read: " + walked.Content[0].Input.Keys);
            if (looked.Content[0].Input.X != 640 || looked.Content[0].Input.Y != 360) throw new Exception("Numbers in quotes weren't read.");
            ClaudeReply odd = Brain.Parsed("{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"text\",\"text\":\"Going.\"},{\"type\":\"tool_use\",\"id\":\"c\",\"name\":\"walk\",\"input\":{\"keys\":{\"odd\":1}}}]}");
            ClaudeReply worse = Brain.Parsed("{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"d\",\"name\":\"walk\",\"input\":{\"seconds\":[1,2]}}]}");
            if (worse.Content[0].Name != "walk" || worse.Raw.IndexOf("\"seconds\":[1,2]", StringComparison.Ordinal) < 0 || odd == null) throw new Exception("A tool call that can't be read cost the job.");
            if (Brain.Loosened("{\"text\":\"she said \\\"seconds\\\": 6 to me\"}") != "{\"text\":\"she said \\\"seconds\\\": 6 to me\"}") throw new Exception("Words someone said were changed as if they were a tool call.");
            ClaudeReply mixedCalls = Brain.Parsed("{\"content\":[{\"type\":\"tool_use\",\"name\":\"walk\",\"input\":{\"keys\":\"s\",\"seconds\":[1,2]}},{\"type\":\"tool_use\",\"name\":\"mouse_hold\",\"input\":{\"button\":\"right\",\"seconds\":2,\"stop\":true}},{\"type\":\"tool_use\",\"name\":\"type\",\"input\":{\"text\":\"x = {1}\"}}]}");
            if (mixedCalls.Content[0].Input != null || mixedCalls.Content[1].Input.Button != "right" || mixedCalls.Content[1].Input.Seconds != "2" || mixedCalls.Content[1].Input.Stop != "true" || mixedCalls.Content[2].Input.Text != "x = {1}") throw new Exception("One unreadable call changed its siblings' arguments.");
            ClaudeReply badInput = Brain.Parsed("{\"content\":[{\"type\":\"tool_use\",\"name\":\"walk\",\"input\":[1,2]},{\"type\":\"tool_use\",\"name\":\"walk\",\"input\":{\"keys\":\"a\"}}]}");
            if (badInput.Content[0].Input != null || badInput.Content[1].Input.Keys != "a") throw new Exception("An unreadable input lost a readable sibling.");
            checks.Add("PASS unreadable arguments stay unreadable while valid and recoverable sibling calls keep theirs");
            checks.Add("PASS a tool call written a little off still runs, and one she can't read costs a turn instead of the job");
        }

        // A job teleports her onto the task panel like "teleport somewhere", and the panel fading teleports her back (Lachy, 5 Nov).
        // The test runs her real animation, which every other check skips, and calls the end of each way out rather than waiting.
        private void SmokePanelTeleport(System.Collections.Generic.List<string> checks)
        {
            if (hidden || !preferences.Motion) { checks.Add("LIMIT panel teleport: she's hidden or Motion is off here, so a job doesn't send her to the panel"); return; }
            bool instantWas = instant;
            Point home = anchor;
            Ledge homeSeat = seat;
            Job first = new Job("open notepad and type hi"), second = new Job("open notepad and type bye"), third = new Job("open notepad and close it");
            Action trip;
            Action finish = delegate { trip = outro; outro = null; if (trip != null) trip(); };
            try
            {
                instant = false;
                JobOn(first);
                Point pointerAt = PointerHome(PanelSeat());
                bool leaving = !onPanel && panelTrip != null && outro == panelTrip && (clip == leave || clip == perchLeave) && anchor == home;
                Action tripWas = outro;
                bool once = SitOnPanel() && outro == tripWas && !onPanel;
                finish();
                bool landed = onPanel && panelTrip == null && clip == perchArrive && Hip().Y == taskPanel.Plate.Top && PointerHome() == pointerAt;
                if (!leaving || !once || !landed) throw new Exception("A job didn't teleport her onto the panel: leaving " + leaving + ", one trip " + once + ", landed " + landed + (clip == perchArrive ? " with her perched arrival." : " without her perched arrival."));
                JobOff(first, "done", "Opened Notepad and typed hi.");
                // The panel grows its result row as the job ends, so her seat can move before the trip back.
                Point onTheSeat = anchor;
                taskPanel.Stop();
                HoldPanel();
                bool goingBack = !onPanel && homeTrip != null && outro == homeTrip && clip == perchLeave && anchor == onTheSeat;
                JobOn(second);
                bool keptHome = panelHome == home && panelSeat == homeSeat && panelTrip != null && outro == panelTrip;
                finish();
                if (!goingBack || !keptHome || !onPanel) throw new Exception("The panel fading didn't teleport her back, or a job on her way back lost where she was: back " + goingBack + ", kept " + keptHome + ", on the panel " + onPanel + ".");
                JobOff(second, "done", "Opened Notepad and typed bye.");
                taskPanel.Stop();
                HoldPanel();
                finish();
                bool backHome = !onPanel && homeTrip == null && anchor == home && seat == homeSeat && (clip == perchArrive || clip == arrive || clip == dangle);
                if (!backHome) throw new Exception("After the panel teleport she didn't land back where she was.");
                JobOn(third);
                LeavePanel(false);
                finish();
                if (onPanel || panelTrip != null || anchor != home || taskPanel.Room != 0) throw new Exception("Leaving the panel on her way there didn't call the teleport off.");
                checks.Add("PASS panel teleport: a job's start glitches her out where she is and lands her on the task panel, a second ask on the way starts no second trip, her pointer starts beside where she lands, the panel fading teleports her back where she was, a job on her way back keeps that spot, and leaving on the way calls it off");
            }
            finally
            {
                instant = instantWas;
                if (working != null || pointing) JobOff(third, "done", "Smoke teleport.");
                taskPanel.Stop();
                LeavePanel(true);
                outro = null;
                homeTrip = null;
            }
        }

        // A Claude job that runs for hours folds its older turns into a note and carries on.
        private static void SmokeLongJob(System.Collections.Generic.List<string> checks)
        {
            Func<Rectangle?, Picture> shootWas = Computer.Shoot;
            Func<Sight> glimpseWas = Computer.Glimpse;
            Func<Target> focusWas = Computer.Focus;
            Func<Point, Target> underWas = Computer.Under;
            Func<string, ToolArguments, Picture, string> useWas = Computer.Use;
            Func<IntPtr> frontWas = Computer.Front;
            byte[] jpeg = { 1, 2, 3 };
            try
            {
                Computer.Shoot = delegate(Rectangle? region) { return new Picture { Jpeg = jpeg, Size = new Size(1280, 720), Area = new Rectangle(0, 0, 1280, 720) }; };
                Computer.Glimpse = delegate { return new Sight { Window = new IntPtr(9), Title = "Notepad", Program = "notepad" }; };
                Computer.Focus = delegate { return null; };
                Computer.Under = delegate(Point at) { return null; };
                Computer.Front = delegate { return new IntPtr(9); };
                Computer.Use = delegate(string name, ToolArguments args, Picture picture) { return "Clicked."; };
                int turn = 0, longest = 0;
                string note = null, asked = null;
                Job job = new Job("sort out a very long list");
                int folded = 0;
                job.Aside = delegate(string system, string user) { asked = user; return ++folded == 1 ? "Done the first half, carry on from line 50." : ""; };
                job.Drive = delegate(string system, string tools, string messages)
                {
                    turn++;
                    longest = Math.Max(longest, Regex.Matches(messages, "\"role\":\"assistant\"").Count);
                    if (turn == Computer.LongTalk / 2) { job.Change("use the blue column"); job.Tell("keep the headings"); }
                    if (turn > Computer.LongTalk / 2 && (!messages.Contains("use the blue column") || !messages.Contains("keep the headings"))) throw new Exception("Folding lost their new instructions.");
                    if (messages.IndexOf("carry on from line 50", StringComparison.Ordinal) >= 0) note = messages;
                    if (turn > Computer.LongTalk) return Brain.Parsed("{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"All sorted.\"}]}");
                    return Brain.Parsed("{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"t" + turn + "\",\"name\":\"left_click\",\"toolset_name\":\"computer\",\"input\":{\"coordinate\":[5,5]}}]}");
                };
                string ended = job.Run();
                if (ended != "All sorted." || note == null || asked == null || asked.IndexOf("sort out a very long list", StringComparison.Ordinal) < 0 || longest > Computer.LongTalk / 2 + 1) throw new Exception("A long job didn't fold: " + ended + " at " + longest + " turns.");
                checks.Add("PASS a long job folds its older turns into a note to itself and carries on, so she can run for hours");
                if (folded < 2 || !asked.Contains("use the blue column") || !asked.Contains("keep the headings")) throw new Exception("The fold's summary missed their new instructions.");
                checks.Add("PASS corrections and additions survive folding even when its summary is empty");
                int badTurns = 0;
                Job badJob = new Job("read this list");
                badJob.Drive = delegate(string badSystem, string badTools, string badMessages)
                {
                    if (++badTurns == 1) return Brain.Parsed("{\"content\":[{\"type\":\"tool_use\",\"id\":\"bad\",\"name\":\"walk\",\"input\":{\"keys\":\"s\",\"seconds\":[1,2]}}]}");
                    if (!badMessages.Contains("couldn't read this call's arguments")) throw new Exception("An unreadable call ran with defaults.");
                    return Brain.Parsed("{\"content\":[{\"type\":\"text\",\"text\":\"Read it.\"}]}");
                };
                if (badJob.Run() != "Read it." || badJob.Steps.Count != 0) throw new Exception("An unreadable call performed a step.");
                checks.Add("PASS an unreadable game call reports its arguments instead of running with defaults");
            }
            finally
            {
                Computer.Shoot = shootWas;
                Computer.Glimpse = glimpseWas;
                Computer.Focus = focusWas;
                Computer.Under = underWas;
                Computer.Use = useWas;
                Computer.Front = frontWas;
            }
        }

        // What she learns in a game stays between sessions: each game has its own notes, and they're in every prompt after.
        private static void SmokeGameNotes(System.Collections.Generic.List<string> checks)
        {
            string[,] titles = { { "Minecraft 26.3 - Singleplayer", "Minecraft" }, { "Minecraft* 26.3 - Multiplayer (LAN)", "Minecraft" }, { "Cyberpunk 2077 (C) 2020 by CD Projekt RED", "Cyberpunk 2077" }, { "Counter-Strike 2", "Counter-Strike 2" }, { "The Witcher 3: Wild Hunt", "The Witcher 3: Wild Hunt" }, { "VALORANT  ", "VALORANT" }, { "Roblox", "Roblox" } };
            for (int i = 0; i < titles.GetLength(0); i++)
                if (GameNotes.Name(titles[i, 0]) != titles[i, 1]) throw new Exception("Game title read wrong: " + titles[i, 0] + " as " + GameNotes.Name(titles[i, 0]));
            string folderWas = GameNotes.Folder, folder = Path.Combine(Path.GetTempPath(), "capri-notes-" + Guid.NewGuid().ToString("N"));
            GameNotes.Folder = folder;
            try
            {
                if (GameNotes.Brief(null) != "" || GameNotes.Learn(null, "x").IndexOf("didn't work", StringComparison.Ordinal) < 0) throw new Exception("Game notes acted with no game open.");
                string plain = GameNotes.Brief("Some Indie Game");
                if (plain.IndexOf("Some Indie Game", StringComparison.Ordinal) < 0 || plain.IndexOf("learned", StringComparison.Ordinal) >= 0) throw new Exception("A new game's brief is wrong: " + plain);
                if (GameNotes.Learn("Minecraft", "  logs break\nin about 3 seconds by hand ") != "Learned that for next time." || GameNotes.Learn("Minecraft", "Logs break in about 3 seconds BY HAND") != "You already knew that.") throw new Exception("Learning a line went wrong.");
                string brief = GameNotes.Brief("Minecraft");
                if (brief.IndexOf("Survival and crafting", StringComparison.Ordinal) < 0 || brief.IndexOf("- logs break in about 3 seconds by hand", StringComparison.Ordinal) < 0 || brief.IndexOf("not orders", StringComparison.Ordinal) < 0) throw new Exception("Her brief lost something: " + brief);
                if (GameNotes.Brief("CS2").IndexOf("Tactical shooter", StringComparison.Ordinal) < 0 || GameNotes.Brief("Cyberpunk 2077").IndexOf("Open-world", StringComparison.Ordinal) < 0 || GameNotes.Brief("Roblox").IndexOf("Every experience", StringComparison.Ordinal) < 0 || GameNotes.Brief("BloonsTD6").IndexOf("comma, period and slash", StringComparison.Ordinal) < 0 || GameNotes.Brief("Kingdom Rush").IndexOf("Tower defense", StringComparison.Ordinal) < 0 || GameNotes.Brief("Age of Empires IV").IndexOf("Strategy game", StringComparison.Ordinal) < 0) throw new Exception("A kind of game wasn't known.");
                for (int i = 0; i < 400; i++) GameNotes.Learn("Long Game", "Fact number " + i + " about this very long game that she keeps on learning from");
                string longBrief = GameNotes.Brief("Long Game");
                if (longBrief.Length > 4600 || longBrief.IndexOf("Fact number 399 ", StringComparison.Ordinal) < 0 || longBrief.IndexOf("Fact number 0 ", StringComparison.Ordinal) >= 0) throw new Exception("A long notes file wasn't cut to its newest lines.");
                if (GameNotes.Reflected("Terraria", "nothing") != 0 || GameNotes.Reflected("Terraria", "<think>hm</think>- Torches stop slimes spawning nearby.\n- Dig sideways to escape.") != 2 || GameNotes.Reflected("Terraria", "- one\n- Line two is here. - Line three is here. - Line four is here. - Line five is here.") > 3) throw new Exception("Her reflection's lines weren't saved.");
                if (Computer.Toolset.IndexOf("{\"name\":\"learn\",", StringComparison.Ordinal) < 0 || Computer.Toolset.IndexOf("\"level\":", StringComparison.Ordinal) < 0 || Computer.Moves("learn{\"text\": \"e opens the crate\"}").Count != 1) throw new Exception("Her learn tool isn't listed.");
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> opened = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> { new System.Collections.Generic.KeyValuePair<string, ToolArguments>("open_app", new ToolArguments { Name = "Minecraft" }) };
                if (!Hands.Partly("play minecraft and punch a tree until you have 3 logs", opened) || Hands.Partly("play minecraft", opened) || Hands.Partly("open minecraft please", opened)) throw new Exception("Opening a game wasn't told from doing something in it.");
                opened[0] = new System.Collections.Generic.KeyValuePair<string, ToolArguments>("open_app", new ToolArguments { Name = "Rock and Roll Racing" });
                if (Hands.Partly("open rock and roll racing", opened)) throw new Exception("An app with and in its name was split.");
                checks.Add("PASS each game has its own notes she writes herself: titles read as one game, the same line once, newest notes in every prompt, what kind of game it is, and opening a game told from playing it");
            }
            finally
            {
                GameNotes.Folder = folderWas;
                if (Directory.Exists(folder)) Directory.Delete(folder, true);
            }
        }

        private static void SmokeClickStops(System.Collections.Generic.List<string> checks)
        {
            if (!Computer.Failed(Computer.NoClick) || !Hands.Failed(Computer.NoClick)) throw new Exception("The reply after missed coordinates wasn't kept as a failure.");
            Picture scaled;
            using (Bitmap screen = new Bitmap(2560, 1440, PixelFormat.Format24bppRgb))
            {
                using (Graphics paint = Graphics.FromImage(screen)) paint.Clear(Color.SteelBlue);
                scaled = Picture.Of(screen, new Rectangle(-2560, -180, 2560, 1440));
            }
            using (MemoryStream read = new MemoryStream(scaled.Jpeg))
            using (Bitmap sent = new Bitmap(read))
                if (sent.Size != scaled.Size || sent.Size != new Size(1280, 720)) throw new Exception("The sent screenshot and its coordinate size differ.");
            ToolArguments center = new ToolArguments { Coordinate = new double[] { 640, 360 } };
            if (Computer.Landing(center, scaled) != new Point(-1280, 540)) throw new Exception("A scaled screenshot lost its screen point or monitor offset.");
            bool member;
            ToolArguments gridPoint = new ToolArguments { X = 75, Y = 25 };
            if (Computer.Planned("click", gridPoint, scaled, new System.Collections.Generic.List<ReadWord>(), out member) != "left_click" || !member || Computer.Landing(gridPoint, scaled) != new Point(-640, 180)) throw new Exception("A grid coordinate in a scaled screenshot landed on the wrong screen point.");
            checks.Add("PASS scaled screenshots: the JPEG and coordinate size agree, and pixel and grid coordinates keep the monitor's screen offset");
            Func<Rectangle?, Picture> shootWas = Computer.Shoot;
            Func<Sight> glimpseWas = Computer.Glimpse, lookWas = Computer.Look;
            Func<Target> focusWas = Computer.Focus;
            Func<Point, Target> underWas = Computer.Under;
            Func<string, ToolArguments, Picture, string> useWas = Computer.Use;
            Func<IntPtr> frontWas = Computer.Front;
            Func<string> gameWas = Computer.GameOpen;
            Picture shownWas = Computer.Shown;
            bool streamWas = Computer.Streaming;
            try
            {
                Computer.Shoot = delegate { return new Picture { Jpeg = new byte[] { 1, 2, 3 }, Size = scaled.Size, Area = scaled.Area }; };
                Computer.Glimpse = Computer.Look = delegate { return new Sight { Window = new IntPtr(7), Title = "Minecraft", Program = "javaw", Bounds = scaled.Area }; };
                Computer.Front = delegate { return new IntPtr(7); };
                Computer.Focus = delegate { return null; };
                Computer.Under = delegate { return null; };
                Computer.GameOpen = delegate { return null; };
                System.Collections.Generic.List<Point> clicks = new System.Collections.Generic.List<Point>();
                int misses = 0;
                Computer.Use = delegate(string name, ToolArguments args, Picture picture)
                {
                    Point? at = Computer.Landing(args, picture);
                    if (args.Coordinate != null && !at.HasValue) { misses++; return Computer.Member(name, args, picture); }
                    if (args.Coordinate != null) clicks.Add(at.Value);
                    return "Clicked.";
                };
                foreach (bool grid in new[] { false, true })
                {
                    foreach (bool stream in new[] { false, true })
                    {
                        Computer.Streaming = stream;
                        int turns = 0, delivered = 0;
                        misses = 0;
                        clicks.Clear();
                        Job stuck = new Job("play minecraft and click Play");
                        if (grid)
                            stuck.Seer = delegate(byte[] picture, string system, string user)
                            {
                                if (++turns > 2) throw new Exception("A grid brain kept clicking outside the screenshot.");
                                if (turns == 2 && (!user.Contains("Use x and y from 0 to 100 on the grid.") || user.Contains("which is 1280x720"))) throw new Exception("A grid brain got pixel limits after an invalid coordinate.");
                                return "click{\"x\":200,\"y\":50}\nclick{\"x\":50,\"y\":50}";
                            };
                        else
                            stuck.Drive = delegate(string system, string tools, string messages)
                            {
                                if (++turns > 2) throw new Exception("A computer brain kept clicking outside the screenshot.");
                                delivered = Math.Max(delivered, Regex.Matches(messages, Regex.Escape(Computer.OffScreen)).Count);
                                return Brain.Parsed("{\"content\":[{\"type\":\"tool_use\",\"id\":\"miss\",\"name\":\"left_click\",\"toolset_name\":\"computer\",\"input\":{\"coordinate\":[5000,10]}},{\"type\":\"tool_use\",\"id\":\"later\",\"name\":\"left_click\",\"toolset_name\":\"computer\",\"input\":{\"coordinate\":[640,360]}}],\"stop_reason\":\"tool_use\"}");
                            };
                        string reply = stuck.Run();
                        if (reply != Computer.NoClick || stuck.Outcome != "stopped" || turns != 2 || misses != 2 || clicks.Count != 0 || stuck.Report().Failed != 2 || (!grid && delivered != 1)) throw new Exception("Two off-screenshot coordinates didn't stop the ask with a reply: " + reply + " / " + turns + " turns / " + misses + " misses.");
                        if (stuck.Run() != Computer.NoClick || turns != 2 || misses != 2) throw new Exception("An ask that couldn't see where to click started clicking again.");
                    }
                    Computer.Streaming = false;
                    misses = 0;
                    clicks.Clear();
                    int recoveryTurns = 0;
                    Job recovered = new Job("play minecraft and click Play");
                    if (grid)
                        recovered.Seer = delegate(byte[] picture, string system, string user)
                        {
                            if (++recoveryTurns > 4) throw new Exception("A grid brain didn't finish after a valid coordinate.");
                            return new[] { "click{\"x\":200,\"y\":50}", "click{\"x\":50,\"y\":50}", "click{\"x\":200,\"y\":50}", "done{\"text\":\"Left it there.\"}" }[recoveryTurns - 1];
                        };
                    else
                        recovered.Drive = delegate(string system, string tools, string messages)
                        {
                            if (++recoveryTurns > 4) throw new Exception("A computer brain didn't finish after a valid coordinate.");
                            if (recoveryTurns == 4) return Brain.Parsed("{\"content\":[{\"type\":\"text\",\"text\":\"Left it there.\"}],\"stop_reason\":\"end_turn\"}");
                            return Brain.Parsed("{\"content\":[{\"type\":\"tool_use\",\"id\":\"try\",\"name\":\"left_click\",\"toolset_name\":\"computer\",\"input\":{\"coordinate\":" + (recoveryTurns == 2 ? "[640,360]" : "[5000,10]") + "}}],\"stop_reason\":\"tool_use\"}");
                        };
                    if (recovered.Run() != "Left it there." || recovered.Outcome != "done" || recoveryTurns != 4 || misses != 2 || clicks.Count != 1 || clicks[0] != new Point(-1280, 540)) throw new Exception("A valid coordinate didn't reset the misses, or a new ask kept the old ask's misses.");
                }
                checks.Add("PASS off-screenshot clicks: computer and grid brains stop after two consecutive misses with a plain reply, skip later clicks, stay stopped on stream, and reset after a valid coordinate or a new ask");
            }
            finally
            {
                Computer.Shoot = shootWas;
                Computer.Glimpse = glimpseWas;
                Computer.Look = lookWas;
                Computer.Focus = focusWas;
                Computer.Under = underWas;
                Computer.Use = useWas;
                Computer.Front = frontWas;
                Computer.GameOpen = gameWas;
                Computer.Shown = shownWas;
                Computer.Streaming = streamWas;
            }
        }

        private static void SmokeSighted(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> written = Computer.Moves("Sure!\nlook{\"x\": 75, \"y\": 50}\nwalk{\"keys\": \"w\", \"seconds\": 1}\nclick{x: 50, y: 48}\n<think>click{\"x\": 1, \"y\": 1}</think>");
            if (written.Count != 3 || written[0].Key != "look" || written[0].Value.X != 75 || written[1].Value.Seconds != "1" || written[2].Value.Y != 48) throw new Exception("Written moves weren't read: " + written.Count);
            System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> plainClick = Computer.Moves("click 50 48");
            if (plainClick.Count != 1 || plainClick[0].Key != "click" || plainClick[0].Value.X != 50 || Computer.Moves("I'd click the button").Count != 0) throw new Exception("A plain written click wasn't read.");
            System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> bracedMoves = Computer.Moves("type{\"text\":\"x = {1}, \\\"two\\\" and \\\\three\"}\npress{\"keys\":\"enter\"}");
            if (bracedMoves.Count != 2 || bracedMoves[0].Value.Text != "x = {1}, \"two\" and \\three" || bracedMoves[1].Key != "press" || bracedMoves[1].Value.Keys != "enter") throw new Exception("Braces or escapes in typed words swallowed a move.");
            checks.Add("PASS written moves keep braces and escaped quotes inside strings and leave the next call separate");
            byte[] jpeg;
            using (Bitmap plain = new Bitmap(320, 180))
            {
                using (Graphics paint = Graphics.FromImage(plain)) paint.Clear(Color.Black);
                jpeg = Jpeg(plain, 320);
            }
            string words;
            System.Collections.Generic.List<ReadWord> readWords;
            byte[] gridded = Computer.Gridded(new Picture { Jpeg = jpeg, Size = new Size(320, 180), Area = new Rectangle(0, 0, 320, 180) }, out words, out readWords);
            using (System.IO.MemoryStream read = new System.IO.MemoryStream(gridded))
            using (Bitmap back = new Bitmap(read))
                if (back.Width != 320 || back.Height != 180 || back.GetPixel(32, 90).GetBrightness() < 0.1f || back.GetPixel(40, 150).GetBrightness() > 0.1f) throw new Exception("Her grid wasn't drawn on the picture.");
            byte[] junk = { 1, 2, 3 };
            if (Computer.Gridded(new Picture { Jpeg = junk }, out words, out readWords) != junk) throw new Exception("A picture she can't read wasn't passed along as it came.");
            bool member;
            ToolArguments spot = new ToolArguments { X = 25, Y = 50 };
            Picture shown = new Picture { Jpeg = jpeg, Size = new Size(1280, 720), Area = new Rectangle(0, 0, 1920, 1080) };
            if (Computer.Planned("right_click", spot, shown, readWords, out member) != "right_click" || !member || spot.Coordinate[0] != 320 || spot.Coordinate[1] != 360) throw new Exception("The grid's numbers didn't become pixels.");
            ToolArguments turn = new ToolArguments { X = 75, Y = 50 };
            if (Computer.Planned("look", turn, shown, readWords, out member) != "look" || member || turn.X != 960) throw new Exception("A look's numbers didn't become pixels.");
            System.Collections.Generic.List<ReadWord> onScreen = new System.Collections.Generic.List<ReadWord> { new ReadWord { Text = "Tou Died!", Box = new Rectangle(522, 175, 231, 38) }, new ReadWord { Text = "fiespawn", Box = new Rectangle(584, 399, 110, 22) }, new ReadWord { Text = "Title Screen", Box = new Rectangle(560, 463, 161, 20) } };
            ToolArguments named = new ToolArguments { Text = "Respawn" };
            Computer.Planned("click", named, shown, onScreen, out member);
            if (named.Coordinate == null || named.Coordinate[0] != 639 || named.Coordinate[1] != 410) throw new Exception("Clicking misread words missed.");
            ToolArguments partWords = new ToolArguments { Text = "title" };
            Computer.Planned("click", partWords, shown, onScreen, out member);
            if (partWords.Coordinate == null || partWords.Coordinate[1] != 473) throw new Exception("Clicking part of the words missed.");
            ToolArguments gone = new ToolArguments { Text = "Multiplayer" };
            Computer.Planned("click", gone, shown, onScreen, out member);
            if (gone.Coordinate != null) throw new Exception("Words that aren't on screen were clicked anyway.");
            System.Collections.Generic.List<ReadWord> menuRow = new System.Collections.Generic.List<ReadWord> { new ReadWord { Text = "ZRYW", Box = new Rectangle(488, 73, 26, 8) }, new ReadWord { Text = "UPROSZCZONY", Box = new Rectangle(533, 73, 65, 8) }, new ReadWord { Text = "DEATHMATCH", Box = new Rectangle(616, 73, 61, 8) }, new ReadWord { Text = "WYSCIG", Box = new Rectangle(695, 73, 36, 8) }, new ReadWord { Text = "ZBROJEN", Box = new Rectangle(735, 73, 40, 8) } };
            System.Collections.Generic.List<ReadWord> menuLabels = Ocr.Labels("ZRYW UPROSZCZONY DEATHMATCH WYSCIG ZBROJEN", menuRow);
            if (menuLabels.Count != 4 || menuLabels[2].Text != "DEATHMATCH" || menuLabels[3].Text != "WYSCIG ZBROJEN" || menuLabels[3].Box != new Rectangle(695, 73, 80, 8)) throw new Exception("A menu's row wasn't split into its buttons.");
            System.Collections.Generic.List<ReadWord> plainLine = new System.Collections.Generic.List<ReadWord> { new ReadWord { Text = "Thanks", Box = new Rectangle(10, 10, 60, 20) }, new ReadWord { Text = "a", Box = new Rectangle(76, 10, 10, 20) }, new ReadWord { Text = "lot", Box = new Rectangle(92, 10, 30, 20) } };
            if (Ocr.Labels("Thanks a lot", plainLine).Count != 1) throw new Exception("A plain sentence was split as if it were a menu.");
