            bool lapsed = moods.Scene.Box == HudBox.None;
            double blinkedAt = 0;
            for (double step = when; step < when + 12; step += 0.03) { moods.Step(step); blinkedAt += moods.Scene.Open < 0.5f ? 1 : 0; }
            if (!booted || !struck || !healed || !startled || !settled || !grinning || !ungrinned || !narrowed || !talking || !faded || !heardThem || !lapsed || blinkedAt == 0) throw new Exception("Her HUD's moods went wrong: boot " + booted + ", hit " + struck + "/" + healed + ", surprise " + startled + "/" + settled + ", happy " + grinning + "/" + ungrinned + ", focus " + narrowed + ", talk " + talking + "/" + faded + ", heard " + heardThem + "/" + lapsed + ", blink " + blinkedAt);
            checks.Add("PASS her HUD's moods play and end: it boots to her eyes, a hit tears the frame, surprise widens her eyes with a burst of small ones, happy swaps to her grin, focus narrows them, her line swaps to her portrait with her mouth moving and fades back, LISTENING lapses, and she blinks");
            HudLife life = new HudLife();
            int frames = 0;
            double spent = 0, at = 0;
            using (HudPaint paint = new HudPaint(1))
            using (Bitmap hud = new Bitmap(paint.Canvas.Width, paint.Canvas.Height, PixelFormat.Format32bppPArgb))
            using (Graphics pen = Graphics.FromImage(hud))
            {
                life.Start(0);
                while (at < 60)
                {
                    if (life.Step(at))
                    {
                        Stopwatch took = Stopwatch.StartNew();
                        paint.Draw(pen, life.Scene);
                        spent += took.Elapsed.TotalSeconds;
                        frames++;
                    }
                    at += Math.Max(0.015, Math.Min(4, life.Next(at)));
                }
            }
            if (frames < 30 || frames > 600 || spent / 60 > 0.02) throw new Exception("Her HUD isn't light enough idle: " + frames + " frames a minute cost " + (spent / 60).ToString("P2") + " of a core.");
            checks.Add("PASS her idle HUD redraws only when something moves: " + frames + " frames in a minute, " + (spent / 60).ToString("P2") + " of a core to draw them");
            checks.Add("LIMIT Gaming Mode here uses a made-up game: a real game's window, borderless over a real one, exclusive full screen and mouse-look with the HUD up need a manual check");
        }

        private static string LocalReply(string content)
        {
            return "{\"choices\":[{\"message\":{\"content\":" + Voice.Quote(content) + "},\"finish_reason\":\"stop\"}]}";
        }

        private void SmokeProviders(System.Collections.Generic.List<string> checks, string output)
        {
            Preferences preferencesWas = preferences;
            Cloud remoteWas = brain.Remote;
            Engine localWas = brain.Local;
            Pick pickWas = brain.LocalPick, fitWas = fit;
            Machine machineWas = machine;
            string modelWas = brain.Model, addressWas, keyWas, logWas = Brain.LogPath;
            brain.GetServer(out addressWas, out keyWas);
            string[] modelsWas = providerModels;
            System.Collections.Generic.List<string> cloudWas = cloudModels;
            Func<string, string> thinkWas = Think;
            bool findingWas = finding, signalsWas = signals.Enabled, settingsWas = mainframe.SettingsShown;
            bool ollamaWas = ollamaRunning, typedWas = localAddressTyped;
            byte[] savedWas = File.Exists(settingsPath) ? File.ReadAllBytes(settingsPath) : null;
            string catalog = "{\"data\":[{\"id\":\"vendor/alpha\"},{\"id\":\"vendor/beta\"}]}";
            const string keyA = "opaque-provider-test-A", keyB = "sk-ant-provider-test-B";
            System.Collections.Generic.List<System.Net.Sockets.TcpListener> servers = new System.Collections.Generic.List<System.Net.Sockets.TcpListener>();
            System.Collections.Generic.List<ManualResetEvent> gates = new System.Collections.Generic.List<ManualResetEvent>();
            Func<string[], System.Collections.Generic.List<string>, ManualResetEvent, string, string> serve = delegate(string[] replies, System.Collections.Generic.List<string> asked, ManualResetEvent release, string headers)
            {
                System.Net.Sockets.TcpListener server;
                string address = FakeServer(replies, asked, out server, headers: headers, release: release);
                servers.Add(server);
                return address;
            };
            Func<System.Collections.Generic.List<string>, int> count = delegate(System.Collections.Generic.List<string> asked) { lock (asked) return asked.Count; };
            Func<string, string, string, Brain> head = delegate(string address, string key, string model)
            {
                Brain one = new Brain { Model = model };
                one.SetServer(address, key);
                return one;
            };
            Action settle = delegate
            {
                Stopwatch waited = Stopwatch.StartNew();
                while (waited.ElapsedMilliseconds < 300) { Application.DoEvents(); Thread.Sleep(5); }
            };
            try
            {
                signals.Stop();
                finding = true;
                preferences = Preferences.Fresh();
                preferences.Tiered = true;
                preferences.Silent = true;
                preferences.MainframeSize = 100;
                brain.Remote = null;
                brain.Local = null;
                brain.SetServer(null, null);
                brain.Model = null;
                mainframe.ShowSettings(false);
                ShowTiers();
                mainframe.OpenProvider();
                foreach (string bad in new[] { "", "file:///tmp/model", "ftp://example.com", "https://user:secret@example.com/v1", "https://example.com/v1?key=secret", "https://example.com/#secret", "https://bad host/v1", "https://example.com\\other" })
                {
                    mainframe.TypeProvider(bad, keyA);
                    mainframe.ConnectProvider();
                    if (!mainframe.ProviderNote.StartsWith("That address doesn't work.", StringComparison.Ordinal) || brain.Server != null || preferences.BrainProvider != null || !mainframe.ProviderMaskedAndEmpty) throw new Exception("A bad provider address was accepted or its key stayed visible.");
                }
                UseProvider("http://example.com/v1", keyA);
                if (!mainframe.ProviderNote.StartsWith("Use https://", StringComparison.Ordinal)) throw new Exception("A key was allowed over remote plain HTTP.");
                UseProvider("http://localhost:1234", "first\nsecond");
                if (mainframe.ProviderNote != "That key doesn't work. Paste it on one line.") throw new Exception("A multiline provider key was accepted.");
                if (Brain.ServerAddress("https://openrouter.ai/api/v1/") != "https://openrouter.ai/api" || Brain.ServerAddress("localhost:1234/v1/chat/completions") != "http://localhost:1234") throw new Exception("A provider base URL lost its path or version.");
                checks.Add("PASS provider addresses reject other schemes, credentials, queries, fragments, spaces and backslashes; remote keys require HTTPS and one line");

                System.Collections.Generic.List<string> a = new System.Collections.Generic.List<string>(), b = new System.Collections.Generic.List<string>();
                ManualResetEvent refreshGate = new ManualResetEvent(true);
                gates.Add(refreshGate);
                string addressA = serve(new[] { catalog, LocalReply("Provider A answered."), catalog, catalog }, a, refreshGate, "") + "/provider";
                string addressB = serve(new[] { catalog, LocalReply("Provider B answered."), catalog, catalog, catalog, LocalReply("Local answered.") }, b, null, "");
                mainframe.TypeProvider(addressA + "/v1", keyA);
                mainframe.ConnectProvider();
                WaitVoice(delegate { return brain.Server == addressA && mainframe.ProviderNote == "Provider connected."; }, "The provider panel did not connect.");
                if (brain.Remote != null || brain.ServerKey != keyA || !mainframe.ProviderMaskedAndEmpty || mainframe.BrainChoices.Length != 2) throw new Exception("The provider panel lost its key, models or dispatch.");
                ToolStripMenuItem stale = (ToolStripMenuItem)((ContextMenuStrip)typeof(Mainframe).GetField("modelMenu", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(mainframe)).Items[0];
                mainframe.PickBrain(1);
                if (brain.Model != "vendor/beta" || preferences.ProviderModel != "vendor/beta") throw new Exception("The provider model picker did not keep its choice.");
                if (head(brain.Server, brain.ServerKey, brain.Model).Ask("hello test") != "Provider A answered.") throw new Exception("The provider did not answer a chat.");
                Preferences reloaded = LoadPreferences();
                if (Voice.Unprotect(reloaded.BrainProvider) != addressA + "\n" + keyA || reloaded.ProviderModel != "vendor/beta" || !reloaded.ProviderOn || File.ReadAllText(settingsPath).Contains(keyA)) throw new Exception("The provider address and key were not saved as one DPAPI pair.");
                preferences = reloaded;
                brain.SetServer(null, null);
                LoadProvider();
                brain.Remote = TierCloud();
                if (brain.Server != addressA || brain.ServerKey != keyA || brain.Model != "vendor/beta" || brain.Remote != null) throw new Exception("The saved provider did not reload together.");
                UseBrain(new[] { "old-ollama" }, new Machine { Ram = 8L << 30 }, null);
                if (brain.Server != addressA || brain.Model != "vendor/beta") throw new Exception("A late local scan replaced the chosen provider.");
                ChooseTier(2);
                if (brain.Server != null || brain.ServerKey != null) throw new Exception("A cloud tier left the custom provider active.");
                string[] beforeRefresh = providerModels;
                ChooseTier(0);
                WaitVoice(delegate { return count(a) == 3 && providerModels != beforeRefresh; }, "Returning to NORMAL did not refresh the saved provider.");
                if (brain.Server != addressA || brain.ServerKey != keyA || brain.Model != "vendor/beta") throw new Exception("Returning to NORMAL mismatched the saved provider pair.");
                refreshGate.Reset();
                FindBrain();
                WaitVoice(delegate { return count(a) == 4; }, "The provider refresh did not reach the held socket.");
                UseProvider(addressB, keyB);
                WaitVoice(delegate { return brain.Server == addressB && brain.ServerKey == keyB; }, "The second provider did not connect.");
                refreshGate.Set();
                settle();
                if (brain.Server != addressB || brain.ServerKey != keyB || brain.Model != "vendor/alpha") throw new Exception("An old refresh replaced the new provider pair.");
                stale.PerformClick();
                if (brain.Model != "vendor/alpha") throw new Exception("An old provider menu changed the new provider's model.");
                if (head(brain.Server, brain.ServerKey, brain.Model).Ask("hello test") != "Provider B answered.") throw new Exception("A prefixed key bypassed its own address.");
                foreach (string request in a) if (!request.Contains("Authorization: Bearer " + keyA) || request.Contains(keyB)) throw new Exception("Provider A received the wrong key.");
                foreach (string request in b) if (!request.Contains("Authorization: Bearer " + keyB) || request.Contains(keyA) || request.IndexOf("x-api-key:", StringComparison.OrdinalIgnoreCase) >= 0) throw new Exception("Provider B did not get only its own Bearer key.");
                if (!a[0].StartsWith("GET /provider/v1/models ", StringComparison.Ordinal) || !a[1].StartsWith("POST /provider/v1/chat/completions ", StringComparison.Ordinal) || !a[1].Contains("\"model\":\"vendor\\/beta\"")) throw new Exception("Provider requests lost the base path or selected model.");
                checks.Add("PASS add a provider, list and pick its models, chat, and reload its encrypted address/key pair; opaque and recognised key prefixes go only to their supplied address");
                checks.Add("PASS tier changes restore the same provider pair and an older refresh keeps its own key without replacing a newer provider");

                ChooseLocalBrain(null, "ollama-test", null);
                if (preferences.ProviderOn || brain.Server != null || ProviderAddress != addressB) throw new Exception("Choosing a local model lost the saved provider or left it active.");
                mainframe.OpenProvider();
                mainframe.TypeProvider(addressA, keyA);
                if (mainframe.ProviderSavedEnabled) throw new Exception("Use saved offered a key beside another address.");
                mainframe.TypeProvider(addressB, "");
                if (!mainframe.ProviderSavedEnabled || !mainframe.ProviderMaskedAndEmpty) throw new Exception("The saved provider did not show an empty masked key field.");
                mainframe.PressProvider("Use saved");
                WaitVoice(delegate { return brain.Server == addressB && brain.ServerKey == keyB; }, "Use saved did not reconnect its paired address and key.");
                string keptPair = preferences.BrainProvider;
                System.Collections.Generic.List<string> unsaved = new System.Collections.Generic.List<string>();
                string unsavedAddress = serve(new[] { catalog }, unsaved, null, "");
                using (FileStream locked = new FileStream(settingsPath, FileMode.Open, FileAccess.Read, FileShare.None))
                {
                    UseProvider(unsavedAddress, keyA);
                    WaitVoice(delegate { return mainframe.ProviderNote == "Couldn't save the provider address and key."; }, "A provider save failure was not reported.");
                    if (brain.Server != addressB || brain.ServerKey != keyB || preferences.BrainProvider != keptPair) throw new Exception("A failed save replaced the current provider pair.");
                    ForgetProvider();
                    if (brain.Server != null || brain.ServerKey != null || preferences.BrainProvider != null || mainframe.ProviderNote != "Stopped using it. Couldn't remove the saved provider.") throw new Exception("A failed provider removal kept the key active or claimed it was removed.");
                }
                ForgetProvider();
                if (LoadPreferences().BrainProvider != null) throw new Exception("Retrying Forget did not remove the saved provider.");
                UseProvider(addressB, keyB);
                WaitVoice(delegate { return brain.Server == addressB && brain.ServerKey == keyB; }, "Re-entering the provider did not connect.");
                checks.Add("PASS choosing a local model stops the provider, Use saved reconnects the paired credentials, and a failed settings write keeps the prior pair");

                mainframe.TypeProvider(addressB + "/v1", "");
                mainframe.ConnectProvider();
                WaitVoice(delegate { return brain.Server == addressB && brain.ServerKey == null && mainframe.ProviderNote == "Provider connected."; }, "The keyless local server did not connect.");
                if (head(brain.Server, brain.ServerKey, brain.Model).Ask("hello test") != "Local answered.") throw new Exception("The keyless server did not answer.");
                for (int i = 4; i < b.Count; i++) if (b[i].IndexOf("Authorization:", StringComparison.OrdinalIgnoreCase) >= 0 || b[i].Contains(keyA) || b[i].Contains(keyB)) throw new Exception("An empty provider key reused a saved key.");
                mainframe.PressProvider("Forget");
                if (preferences.BrainProvider != null || preferences.ProviderOn || brain.Server != null || brain.ServerKey != null || brain.Model != null || LoadPreferences().BrainProvider != null) throw new Exception("Forgetting left a saved or active provider.");
                if (mainframe.ProviderSavedEnabled) throw new Exception("Use saved stayed enabled after forgetting its key.");
                UseSavedProvider();
                if (brain.Server != null || count(b) != 6) throw new Exception("A forgotten provider was reused.");
                checks.Add("PASS a local server sends no key, blank replaces a saved key, and Forget removes the provider from memory and settings");

                ManualResetEvent held = new ManualResetEvent(false);
                gates.Add(held);
                System.Collections.Generic.List<string> pending = new System.Collections.Generic.List<string>();
                string pendingAddress = serve(new[] { catalog }, pending, held, "");
                UseProvider(pendingAddress, keyA);
                WaitVoice(delegate { return count(pending) == 1; }, "Provider discovery did not reach the held socket.");
                ForgetProvider();
                held.Set();
                settle();
                if (brain.Server != null || brain.ServerKey != null || preferences.BrainProvider != null || LoadPreferences().BrainProvider != null || mainframe.ProviderNote != "Provider forgotten.") throw new Exception("A late model list restored a forgotten provider.");
                checks.Add("PASS forgetting during model discovery prevents its late reply from saving or restoring the key");

                ManualResetEvent chatGate = new ManualResetEvent(true), chatDone = new ManualResetEvent(false);
                gates.Add(chatGate);
                gates.Add(chatDone);
                System.Collections.Generic.List<string> chatting = new System.Collections.Generic.List<string>();
                string truncated = "{\"choices\":[{\"message\":{\"content\":\"\",\"reasoning_content\":\"thinking\"},\"finish_reason\":\"length\"}]}";
                string chatAddress = serve(new[] { catalog, truncated, LocalReply("Should not retry.") }, chatting, chatGate, "");
                UseProvider(chatAddress, keyA);
                WaitVoice(delegate { return brain.Server == chatAddress; }, "The chat provider did not connect.");
                chatGate.Reset();
                Think = delegate(string text)
                {
                    try { return brain.Complete(chatAddress, "vendor/alpha", new System.Collections.Generic.List<ChatMessage> { new ChatMessage("user", text) }, false, new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>(), null, 90, -1, false, named: "vendor/alpha", key: keyA); }
                    finally { chatDone.Set(); }
                };
                Hear("hello provider test");
                WaitVoice(delegate { return count(chatting) == 2; }, "The chat did not reach the held socket.");
                int turn = asking;
                ForgetProvider();
                chatGate.Set();
                WaitVoice(delegate { return chatDone.WaitOne(0); }, "Forgetting did not stop the provider chat.");
                settle();
                if (asking <= turn || talkState != TalkState.Off || reply != null || brain.ServerKey != null || count(chatting) != 2) throw new Exception("A forgotten provider retried or returned a late chat.");
                checks.Add("PASS forgetting a provider cancels its active chat, closes her reply and prevents a reasoning retry or late answer");

                System.Collections.Generic.List<string> moved = new System.Collections.Generic.List<string>(), destination = new System.Collections.Generic.List<string>();
                string other = serve(new[] { LocalReply("Wrong address.") }, destination, null, "");
                string redirect = serve(new[] { "!302 {}", "!302 {}" }, moved, null, "Location: " + other + "/stolen\r\n");
                int refused = 0;
                try { Brain.ServerModels(redirect, keyA); } catch (BrainException) { refused++; }
                try { head(redirect, keyA, "vendor/alpha").Ask("hello test"); } catch (BrainException) { refused++; }
                if (refused != 2 || count(destination) != 0) throw new Exception("A provider redirect carried its key elsewhere.");
                Brain.LogPath = Path.Combine(output, "provider-errors.txt");
                System.Collections.Generic.List<string> errors = new System.Collections.Generic.List<string>();
                string echoed = "!400 {\"error\":{\"message\":\"Rejected " + keyA + "\"}}";
                string failure = serve(new[] { echoed, echoed }, errors, null, "");
                int scrubbed = 0;
                try { Brain.ServerModels(failure, keyA); }
                catch (BrainException error) { if (!error.Message.Contains(keyA) && !(error.Detail ?? "").Contains(keyA)) scrubbed++; }
                try { head(failure, keyA, "vendor/alpha").Ask("hello test"); }
                catch (BrainException error) { if (!error.Message.Contains(keyA) && !(error.Detail ?? "").Contains(keyA)) scrubbed++; }
                System.Net.Sockets.TcpListener streamServer;
                string streamAddress = FakeServer(new[] { "data: {\"error\":{\"message\":\"Rejected " + keyA + "\"}}\n\n" }, errors, out streamServer, contentType: "text/event-stream");
                servers.Add(streamServer);
                try { head(streamAddress, keyA, "vendor/alpha").Ask("hello test"); }
                catch (BrainException error) { if (!error.Message.Contains(keyA) && !(error.Detail ?? "").Contains(keyA)) scrubbed++; }
                if (scrubbed != 3 || File.Exists(Brain.LogPath) && File.ReadAllText(Brain.LogPath).Contains(keyA) || mainframe.TextStatus.Contains(keyA) || mainframe.ProviderNote.Contains(keyA)) throw new Exception("A provider key reached an error, log or Mainframe label.");
                checks.Add("PASS provider model lists and chats reject redirects and redact echoed keys from errors and logs");

                System.Collections.Generic.List<string> sideRequests = new System.Collections.Generic.List<string>();
                string sideAddress = serve(new[] { LocalReply("An aside."), LocalReply("A picture."), LocalReply("Quick view."), LocalReply("A file picture."), LocalReply("## Today\n- They like chess.") }, sideRequests, null, "");
                Brain side = head(sideAddress, keyA, "vendor/alpha");
                Func<string, bool> seesWas = Brain.LocalSees;
                string transcriptWas = Brain.TranscriptPath, memoriesWas = Brain.MemoriesPath;
                try
                {
                    Brain.LocalSees = delegate { return false; };
                    if (side.Aside("Speak", "hello test", 90) != "An aside." || side.See(new byte[] { 1, 2, 3 }, "Look", "What is here?", 90) != "A picture." || side.Quick("Look", "What changed?", 90, new byte[] { 1, 2, 3 }) != "Quick view.") throw new Exception("A provider side request or picture used another brain.");
                    string fileView = (string)typeof(Brain).GetMethod("FileSight", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(side, new object[] { new byte[] { 1, 2, 3 } });
                    if (fileView != "A file picture.") throw new Exception("A provider picture file was sent to Ollama's eyes.");
                    Brain.TranscriptPath = Path.Combine(output, "provider-fold");
                    Directory.CreateDirectory(Brain.TranscriptPath);
                    Brain.MemoriesPath = Path.Combine(Brain.TranscriptPath, "memories.md");
                    File.WriteAllText(Brain.MemoriesPath, "");
                    File.WriteAllText(Path.Combine(Brain.TranscriptPath, "unfolded.txt"), "2026-11-04 20:00 You: We played chess today.\n");
                    if (side.Fold() != null || !File.ReadAllText(Brain.MemoriesPath).Contains("They like chess.")) throw new Exception("A provider memory fold lost its credentials.");
                    // Requests written by .NET's JSON writer escape the slash (vendor\/alpha) and hand-written ones don't; both are the same name.
                    foreach (string request in sideRequests) if (!request.Contains("Authorization: Bearer " + keyA) || !request.Contains("\"model\":\"vendor/alpha\"") && !request.Contains("\"model\":\"vendor\\/alpha\"")) throw new Exception("A provider side request lost its own key or model.");
                    if (count(sideRequests) != 5) throw new Exception("A provider side request used another address.");
                    for (int i = 1; i <= 3; i++) if (!sideRequests[i].Contains("image_url") || !sideRequests[i].Contains("data:image/jpeg;base64,AQID") || sideRequests[i].Contains("\"images\"")) throw new Exception("A provider picture used Ollama's image format.");
                }
                finally { Brain.LocalSees = seesWas; Brain.TranscriptPath = transcriptWas; Brain.MemoriesPath = memoriesWas; }
                checks.Add("PASS side requests, memory folding, screen pictures and picture files keep the selected provider's address, Bearer key and model");

                ManualResetEvent sideGate = new ManualResetEvent(false);
                gates.Add(sideGate);
                System.Collections.Generic.List<string> sideRetry = new System.Collections.Generic.List<string>();
                string sideRetryAddress = serve(new[] { truncated, LocalReply("Should not retry.") }, sideRetry, sideGate, "");
                Brain parent = head(sideRetryAddress, keyA, "vendor/alpha");
                System.Threading.Tasks.Task<string> sideChat = System.Threading.Tasks.Task.Run(delegate { return parent.Aside("Speak", "hello test", 90, true); });
                WaitVoice(delegate { return count(sideRetry) == 1; }, "The side request did not reach its held socket.");
                parent.SetServer(null, null);
                sideGate.Set();
                WaitVoice(delegate { return sideChat.IsCompleted; }, "The side request did not stop after forgetting its key.");
                settle();
                WebException stopped = sideChat.IsFaulted ? sideChat.Exception.GetBaseException() as WebException : null;
                if (stopped == null || stopped.Status != WebExceptionStatus.RequestCanceled || count(sideRetry) != 1) throw new Exception("A copied brain reused its parent's forgotten provider key.");
                checks.Add("PASS a copied brain checks its parent's provider before retrying, so a forgotten key is never reused by a side request");

                foreach (int dpi in new[] { 96, 144, 192 })
                {
                    mainframe.LayoutScale(dpi, 100);
                    mainframe.ShowProvider("http://localhost:1234", true, "vendor/long-model-name", new[] { "vendor/long-model-name" });
                    string problem = mainframe.TiersProblem;
                    if (problem != null) throw new Exception("Provider BRAIN rows overlap at " + dpi + " DPI: " + problem);
                }
                mainframe.LayoutScale(96, 100);
                foreach (float zoom in new[] { 1f, 1.5f, 2f })
                {
                    string problem = mainframe.ProviderAt(zoom);
                    if (problem != null) throw new Exception("Provider panel rows overlap at scale " + zoom + ": " + problem);
                }
                checks.Add("PASS provider BRAIN controls and address/key panel fit at 100%, 150% and 200%, including refusal and forget messages");
            }
            finally
            {
                ++providerListing;
                ++cloudListing;
                foreach (ManualResetEvent gate in gates) gate.Set();
                foreach (System.Net.Sockets.TcpListener server in servers) server.Stop();
                brain.Cancel();
                ++asking;
                CloseTalk();
                mainframe.CloseProvider();
                preferences = preferencesWas;
                brain.Remote = remoteWas;
                brain.Local = localWas;
                brain.LocalPick = pickWas;
                brain.SetServer(addressWas, keyWas);
                brain.Model = modelWas;
                providerModels = modelsWas;
                cloudModels = cloudWas;
                Think = thinkWas;
                finding = findingWas;
                machine = machineWas;
                fit = fitWas;
                ollamaRunning = ollamaWas;
                localAddressTyped = typedWas;
                signals.Enabled = signalsWas;
                Brain.LogPath = logWas;
                ShowTiers();
                mainframe.LayoutScale(0, 0);
                if (remoteWas != null) mainframe.ShowCloud(remoteWas, cloudWas);
                mainframe.ShowSettings(settingsWas);
                if (savedWas == null) File.Delete(settingsPath); else File.WriteAllBytes(settingsPath, savedWas);
            }
        }

        private static void SmokeLocalBrains(System.Collections.Generic.List<string> checks)
        {
            for (int port = 1; port <= 65535; port++)
            {
                Uri host = new Uri(Brain.LocalHost(port));
                if (host.Scheme != "http" || host.Host != "127.0.0.1" || host.Port != port || host.UserInfo.Length != 0 || host.AbsolutePath != "/") throw new Exception("A local probe built another host.");
            }
            foreach (string bad in new[] { "https://127.0.0.1:1234", "http://example.com:1234", "http://192.168.1.2:1234", "http://127.0.0.1.example.com:1234", "http://user@127.0.0.1:1234", "http://127.0.0.1:1234/?key=test", "http://127.0.0.1:1234/#test", "http://127.0.0.1:1234/elsewhere", "0", "65536", "" })
                if (Brain.LocalPort(bad) != 0) throw new Exception("A nonlocal server address was accepted.");
            foreach (string good in new[] { "1234", "http://localhost:1234", "http://127.0.0.1:1234/v1", "http://[::1]:1234/v1/" })
                if (Brain.LocalPort(good) != 1234) throw new Exception("A loopback server address was lost.");
            if (Brain.ServerName(1234) != "LM Studio" || Brain.ServerName(1337) != "Jan" || Brain.ServerName(5001) != "KoboldCpp" || Brain.ServerName(8080) != "llama.cpp") throw new Exception("The local servers lost their names.");
            string models = "{\"data\":[{\"id\":\"my/model\",\"capabilities\":{\"vision\":true}},{\"id\":\"text\",\"capabilities\":[\"tools\"]},{\"id\":\"unknown\"},{\"id\":\"my/model\"},{\"id\":\"\"},null]}";
            System.Collections.Generic.List<Cloud> parsed = Brain.ReadLocalModels(1234, models);
            Brain sight = new Brain();
            if (parsed.Count != 3 || parsed[0].Model != "my/model" || !sight.Sighted(parsed[0]) || sight.Sighted(parsed[1]) || !sight.Sighted(parsed[2])) throw new Exception("Local model ids or their stated vision support were lost.");
            checks.Add("PASS local brains: every default port builds http://127.0.0.1:<port>, addresses stay on loopback, server labels and arbitrary model ids parse, and missing vision metadata stays unknown");
            foreach (string loopbackHost in new[] { "localhost", "127.0.0.2", "[::1]" })
            {
                string typedHost = "http://" + loopbackHost + ":1234";
                Cloud preservedHost = new Cloud(1234, "same-model", typedHost + "/v1/");
                System.Collections.Generic.List<Cloud> hostModels = Brain.ReadLocalModels(1234, models, typedHost);
                if (Brain.LocalAddress(typedHost + "/v1/") != typedHost || preservedHost.Host != typedHost || hostModels[0].Host != typedHost || preservedHost.Source == new Cloud(1234, "same-model").Source) throw new Exception("A typed loopback host became 127.0.0.1.");
            }
            checks.Add("PASS local discovery and model identity preserve localhost, other loopback IPv4 addresses and IPv6 loopback");
            System.Net.Sockets.TcpListener fake = null;
            try
            {
                System.Collections.Generic.List<string> asked = new System.Collections.Generic.List<string>();
                string address = FakeServer(new[] { models, LocalReply("Still here."), LocalReply("A blue square."), "!400 {\"error\":{\"message\":\"image input is not supported\"}}" }, asked, out fake);
                int localPort = Brain.LocalPort(address);
                System.Collections.Generic.List<Cloud> found = Brain.LocalModels(localPort);
                if (found.Count != 3) throw new Exception("The local model probe lost a model.");
                Brain local = new Brain { Model = "unknown", Remote = new Cloud(localPort, "unknown") };
                if (local.Ask("hello") != "Still here." || local.See(new byte[] { 1, 2, 3 }, "Look", "What's here?", 90) != "A blue square.") throw new Exception("The local chat or picture did not answer.");
                bool blind = false;
                try { local.See(new byte[] { 1 }, "Look", "Again", 90); }
                catch (BrainException unseen) { blind = unseen.Message == Brain.Sightless(local.Remote); }
                if (!blind || local.Sighted(local.Remote) || !local.Sighted(new Cloud(localPort == 1234 ? 1337 : 1234, "unknown"))) throw new Exception("The local image rejection was not kept per server and model.");
                int before = asked.Count;
                try { local.See(new byte[] { 1 }, "Look", "Again", 90); }
                catch (BrainException) { }
                if (asked.Count != before) throw new Exception("A known text model was sent another picture.");
                foreach (string sent in asked) if (sent.IndexOf("Authorization:", StringComparison.OrdinalIgnoreCase) >= 0 || sent.IndexOf("x-api-key:", StringComparison.OrdinalIgnoreCase) >= 0) throw new Exception("A local server received a key header.");
                if (!asked[0].StartsWith("GET /v1/models ", StringComparison.Ordinal) || asked[1].IndexOf("\"model\":\"unknown\"", StringComparison.Ordinal) < 0 || asked[2].IndexOf("data:image/jpeg;base64,AQID", StringComparison.Ordinal) < 0) throw new Exception("Local requests did not use the OpenAI API.");
                fake.Stop();
                Stopwatch unreachable = Stopwatch.StartNew();
                int unreachableCount = Brain.LocalModels(localPort).Count;
                if (unreachableCount != 0 || unreachable.ElapsedMilliseconds > 2500) throw new Exception("An unreachable local port returned " + unreachableCount + " models in " + unreachable.ElapsedMilliseconds + " ms.");
                asked.Clear();
                address = FakeServer(new[] { models }, asked, out fake, 200, 25, true);
                Stopwatch dripped = Stopwatch.StartNew();
                if (Brain.LocalModels(Brain.LocalPort(address)).Count != 0 || dripped.ElapsedMilliseconds > 2500) throw new Exception("A stalled model list outlived its probe timeout.");
                fake.Stop();
                address = FakeServer(new[] { "" }, asked, out fake, 302, 0, false, 0, "application/json", "Location: http://127.0.0.1:1/v1/models\r\n");
                if (Brain.LocalModels(Brain.LocalPort(address)).Count != 0) throw new Exception("A redirected model list was accepted.");
                fake.Stop();
                checks.Add("PASS local probes and pictures: fake models and chat work without a key, an unknown model gets a picture, image rejection becomes Sightless for that server, and unreachable, stalled and redirected model lists return quickly with nothing");

                asked.Clear();
                string streamed = "data: {\"choices\":[{\"index\":0,\"delta\":{\"content\":\"Still \"}}]}\n\ndata: {\"choices\":[{\"index\":0,\"delta\":{\"content\":\"here.\"},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n";
                string toolStream = "data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"function\":{\"name\":\"media\",\"arguments\":\"{\\\"action\\\":\"}}]}}]}\n\ndata: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"function\":{\"arguments\":\"\\\"next\\\"}\"}}]},\"finish_reason\":\"tool_calls\"}]}\n\ndata: [DONE]\n\n";
                address = FakeServer(new[] { streamed, toolStream, streamed }, asked, out fake, 200, 1, true, 0, "text/event-stream");
                Brain streaming = new Brain { Model = "stream-model", Remote = new Cloud(Brain.LocalPort(address), "stream-model") };
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> calls = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>();
                if (streaming.Aside("Chat", "hello", 90) != "Still here.") throw new Exception("Streamed text did not join.");
                streaming.Step("Tools", "Next song", Hands.Tools, Hands.ClaudeTools, Hands.Listing, calls);
                if (calls.Count != 1 || calls[0].Key != "media" || calls[0].Value.Action != "next" || streaming.Quick("Look", "This", 90, new byte[] { 1, 2 }) != "Still here.") throw new Exception("Streamed tool arguments or pictures were lost.");
                foreach (string sent in asked) if (sent.IndexOf("\"stream\":true", StringComparison.Ordinal) < 0 || sent.IndexOf("Authorization:", StringComparison.OrdinalIgnoreCase) >= 0) throw new Exception("A local stream had the wrong request.");
                fake.Stop();
                checks.Add("PASS local streaming uses the shared OpenAI reader: bytewise text joins, split native tool arguments survive, and pictures stream without an authorization header");

                asked.Clear();
                address = FakeServer(new[] { "!400 {\"error\":{\"message\":\"streaming is not supported\"}}", LocalReply("Still here."), LocalReply("Good to see you.") }, asked, out fake);
                Brain unstreamed = new Brain { Model = "plain", Remote = new Cloud(Brain.LocalPort(address), "plain") };
                if (unstreamed.Ask("hello") != "Still here." || unstreamed.Ask("how are you?") != "Good to see you." || asked.Count != 3 || asked[0].IndexOf("\"stream\":true", StringComparison.Ordinal) < 0 || asked[1].IndexOf("\"stream\":", StringComparison.Ordinal) >= 0 || asked[2].IndexOf("\"stream\":", StringComparison.Ordinal) >= 0) throw new Exception("A local server without streaming did not fall back to ordinary completions.");
                fake.Stop();
                checks.Add("PASS local servers without streaming: an unsupported stream retries as an ordinary OpenAI completion, and the next chat keeps that form");

                asked.Clear();
                address = FakeServer(new[] { "!400 {\"error\":{\"message\":\"This model does not support tools\"}}", LocalReply("media{\"action\":\"next\"}"), LocalReply("Skipped it."), LocalReply("media{\"action\":\"next\"}"), LocalReply("Skipped again."), LocalReply("media{\"action\":\"next\"}"), LocalReply("Track's skipped, all done.") }, asked, out fake);
                Brain written = new Brain { Model = "written", Remote = new Cloud(Brain.LocalPort(address), "written") };
                int acted = 0;
                written.Act = delegate(string name, ToolArguments arguments) { if (name != "media" || arguments.Action != "next") throw new Exception("The written tool changed."); acted++; return "Skipped to the next track."; };
                written.Ask("search the web for combos");
                written.Ask("bring up combos");
                if (acted != 2 || asked.Count != 5 || asked[0].IndexOf("\"tools\":", StringComparison.Ordinal) < 0 || asked[1].IndexOf("\"tools\":", StringComparison.Ordinal) >= 0 || asked[3].IndexOf("\"tools\":", StringComparison.Ordinal) >= 0 || asked[1].IndexOf("To use one, reply with only the call", StringComparison.Ordinal) < 0) throw new Exception("Local written tools did not fall back and stay working.");
                Action haltedWas = Computer.Halted;
                Computer.Halted = delegate { };
                try
                {
                    written.Act = delegate(string name, ToolArguments arguments) { Computer.Arm(); Computer.Interrupt("Dropped it."); return "Dropped it."; };
                    string stoppedReply = written.Ask("search the web for drift");
                    if (stoppedReply != "Dropped it." || asked.Count != 6) throw new Exception("Her brain retold a job they stopped: " + stoppedReply);
                    checks.Add("PASS a job they stopped is said as it is, with no brain call to retell it");
                }
                finally { Computer.Arm(); Computer.Halted = haltedWas; }
                fake.Stop();
                asked.Clear();
                address = FakeServer(new[] { LocalReply("media{\"action\":\"next\"}") }, asked, out fake);
                written.Remote = new Cloud(Brain.LocalPort(address), "written");
                calls.Clear();
                written.Step("Tools", "Next song", Hands.Tools, Hands.ClaudeTools, Hands.Listing, calls);
                if (asked.Count != 1 || asked[0].IndexOf("\"tools\":", StringComparison.Ordinal) < 0) throw new Exception("Another local server inherited the written-tool fallback.");
                checks.Add("PASS local written tools: a rejected native tool call retries with Hands' written form, runs it and remembers the fallback; another server with the same model starts with native tools");
            }
            catch (System.Net.Sockets.SocketException unavailable) { checks.Add("LIMIT local brain transport checks: loopback sockets unavailable here (" + unavailable.SocketErrorCode + ")"); }
            finally { if (fake != null) fake.Stop(); }
        }

        private void SmokeLocalPicker(System.Collections.Generic.List<string> checks)
        {
            Cloud wasRemote = brain.Remote;
            Engine wasLocal = brain.Local;
            Pick wasPick = brain.LocalPick;
            string wasModel = brain.Model, wasAddress = preferences.LocalAddress, wasServerModel = preferences.LocalModel, wasOllama = preferences.Model;
            int wasPort = preferences.BrainPort, wasTier = preferences.Tier;
            string wasBrainAddress = preferences.BrainAddress;
            bool wasAddressTyped = localAddressTyped;
            try
            {
                preferences.Tier = 0;
                mainframe.TypeLocalAddress("http://localhost:43210/v1");
                if (preferences.LocalAddress != "http://localhost:43210" || LoadPreferences().LocalAddress != preferences.LocalAddress || mainframe.LocalAddressShown != preferences.LocalAddress) throw new Exception("The local server field did not save and show its address.");
                mainframe.ShowServers(new System.Collections.Generic.List<Cloud> { new Cloud(1234, "same-model"), new Cloud(1337, "same-model") }, new[] { "ollama-test" }, Engine.Picks[0]);
                mainframe.ShowOllama(new[] { "ollama-test" }, "ollama-test");
                if (string.Join("|", mainframe.BrainChoices) != "Ollama · ollama-test|Built-in · " + Engine.Picks[0].Name + "|LM Studio · same-model|Jan · same-model") throw new Exception("Local models did not share the Ollama picker.");
                mainframe.PickBrain(2);
                Cloud kept = TierCloud();
                if (brain.Remote == null || brain.Remote.Port != 1234 || brain.Model != "same-model" || mainframe.Status.IndexOf("LM Studio · same-model", StringComparison.Ordinal) < 0 || LoadPreferences().BrainPort != 1234 || kept == null || kept.Port != 1234) throw new Exception("The selected local model did not save or show its name.");
                Brain.ReadLocalModels(1234, "{\"data\":[{\"id\":\"same-model\",\"capabilities\":{\"vision\":false}}]}");
                if (Unseeing() != Brain.Sightless(brain.Remote)) throw new Exception("A local model's reported lack of vision did not reach Unseeing.");
                mainframe.PickBrain(3);
                if (brain.Remote.Port != 1337 || Unseeing() != null) throw new Exception("Equal model ids on different servers collapsed.");
                string longName = "my-local-model-" + new string('x', 120);
                mainframe.TypeCustomModel(longName);
                if (brain.Remote.Model != longName || mainframe.Status.IndexOf(longName, StringComparison.Ordinal) < 0 || LoadPreferences().LocalModel != longName) throw new Exception("A local model's full name was not kept in BRAIN.");
                mainframe.PickBrain(0);
                if (brain.Remote != null || brain.Local != null || preferences.BrainPort != 0 || brain.Model != "ollama-test") throw new Exception("The picker did not return to Ollama.");
                mainframe.PickBrain(1);
                if (brain.Local != engine || brain.Remote != null) throw new Exception("The picker did not return to the built-in brain.");
                mainframe.TypeLocalAddress("http://[::1]:1234/v1");
                brain.Model = null; brain.Remote = null; brain.Local = null;
                mainframe.TypeCustomModel("manual-v6");
                Cloud savedV6 = TierCloud();
                if (brain.Remote == null || brain.Remote.Host != "http://[::1]:1234" || savedV6 == null || savedV6.Host != brain.Remote.Host || LoadPreferences().BrainAddress != brain.Remote.Host || LoadPreferences().LocalAddress != brain.Remote.Host) throw new Exception("Manual IPv6 selection did not preserve its host across saving.");
                checks.Add("PASS entering an address and model selects a local brain without discovery and keeps its IPv6 host in preferences");
                System.Net.Sockets.TcpListener manualServer = null;
                try
                {
                    System.Collections.Generic.List<string> manualRequests = new System.Collections.Generic.List<string>();
                    string manualAddress = FakeServer(new[] { "!404 {}", LocalReply("Manual model answered.") }, manualRequests, out manualServer);
                    if (Brain.LocalModels(Brain.LocalPort(manualAddress)).Count != 0) throw new Exception("A 404 model list returned models.");
                    mainframe.TypeLocalAddress(manualAddress);
                    brain.Model = null; brain.Remote = null; brain.Local = null;
                    mainframe.TypeCustomModel("manual-model");
                    if (brain.Remote == null || brain.Model != "manual-model" || brain.Aside("Chat", "hello", 90) != "Manual model answered." || manualRequests.Count != 2 || !manualRequests[1].StartsWith("POST /v1/chat/completions ", StringComparison.Ordinal)) throw new Exception("A server with no model list could not connect by hand.");
                    checks.Add("PASS a local server with /v1/models returning 404 answers after entering its address and model by hand");
                }
                catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT manual local model transport: loopback sockets unavailable"); }
                finally { if (manualServer != null) manualServer.Stop(); }
                SmokeBrainLayout(checks);
                checks.Add("PASS local brain picker: Ollama, built-in, LM Studio and Jan share it, equal model ids keep their server, the address and selection save, and BRAIN shows the selected model's name");
            }
            finally
            {
                brain.Remote = wasRemote; brain.Local = wasLocal; brain.LocalPick = wasPick; brain.Model = wasModel;
                preferences.LocalAddress = wasAddress; preferences.LocalModel = wasServerModel; preferences.Model = wasOllama; preferences.BrainPort = wasPort; preferences.Tier = wasTier;
                preferences.BrainAddress = wasBrainAddress; localAddressTyped = wasAddressTyped;
                SavePreferences();
                mainframe.ShowServers(new System.Collections.Generic.List<Cloud>(), null, null);
                mainframe.Sync();
            }
        }

        private static string SentBody(string request) { return request.Substring(request.IndexOf("\r\n\r\n", StringComparison.Ordinal) + 4); }

        private static void SmokeCloudBrains(System.Collections.Generic.List<string> checks)
        {
            if (Cloud.KindOf("AIza-test") != "google" || Cloud.KindOf("AQ.Ab8-test") != "google" || Cloud.KindOf("sk-or-test") != "openrouter" || Cloud.KindOf("sk-nous-test") != null || Cloud.KindOf(null) != null || Cloud.KindOf("sk-proj-test") != "openai") throw new Exception("New brain keys reached the wrong provider.");
            if (Brain.Address("google", "/models") != "https://generativelanguage.googleapis.com/v1beta/openai/models" || Brain.Address("openrouter", "/chat/completions") != "https://openrouter.ai/api/v1/chat/completions") throw new Exception("A new brain has the wrong address.");
            bool unknownAddress = false;
            try { Brain.Address(null, "/models"); } catch (BrainException) { unknownAddress = true; }
            if (!unknownAddress) throw new Exception("An unknown brain key fell through to OpenAI.");
            checks.Add("PASS Gemini and OpenRouter keys have their own endpoints, OpenRouter precedes sk-, and unconfirmed Nous keys never fall through to OpenAI");

            System.Collections.Generic.List<string> prefixedModels = Brain.ReadCloudModels("google", "{\"data\":[{\"id\":\"models/gemini-90-pro\"},{\"id\":\"models/gemini-embedding-90\"},{\"id\":\"models/gemini-90-flash\"},{\"id\":\"gemini-90-flash\"}]}");
            if (string.Join("|", prefixedModels) != "gemini-90-flash|gemini-90-pro") throw new Exception("Gemini's models/ names didn't come through as chat models: " + string.Join("|", prefixedModels));
            checks.Add("PASS Gemini models listed as models/gemini-... come through by their bare names, once each");

            string googleCatalog = "{\"data\":[null,{\"id\":\"gemini-90.2-flash\"},{\"id\":\"gemini-90.10-flash\"},{\"id\":\"gemini-91-flash-preview\"},{\"id\":\"gemini-90.10-flash-lite\"},{\"id\":\"gemini-91-pro\"},{\"id\":\"gemini-embedding-90\"},{\"id\":\"gemini-91-flash-image\"},{\"id\":\"gemini-91-live\"},{\"id\":\"gemini-91-flash-tts\"},{\"id\":\"gemini-91-native-audio\"},{\"id\":\"gemini-91.5-transcribe\"},{\"id\":\"gemini-nano-banana-91\"},{\"id\":\"gemini-omni-91-flash\"},{\"id\":\"gemini-90.10-flash\"}]}";
            string routerCatalog = "{\"data\":[{\"id\":\"example/vision-text:free\",\"architecture\":{\"input_modalities\":[\"text\"],\"output_modalities\":[\"text\"]},\"supported_parameters\":[\"tools\"]},{\"id\":\"google/gemini-90-flash\",\"architecture\":{\"input_modalities\":[\"text\",\"image\"],\"output_modalities\":[\"text\"]},\"supported_parameters\":[\"tools\"]},{\"id\":\"example/eyes:free\",\"architecture\":{\"input_modalities\":[\"text\",\"image\"],\"output_modalities\":[\"text\"]},\"supported_parameters\":[\"max_tokens\"]},{\"id\":\"example/vision:free\",\"architecture\":{\"input_modalities\":[\"text\",\"image\"],\"output_modalities\":[\"text\"]},\"supported_parameters\":[\"tools\",\"max_tokens\"]},{\"id\":\"example/embedding\",\"architecture\":{\"output_modalities\":[\"embeddings\"]}},{\"id\":\"example/unknown:free\"}]}";
            System.Collections.Generic.List<string> googleModels = Brain.ReadCloudModels("google", googleCatalog);
            System.Collections.Generic.List<string> routerModels = Brain.ReadCloudModels("openrouter", routerCatalog);
            if (googleModels.Count != 5 || Brain.DefaultCloudModel("google", googleModels) != "gemini-90.10-flash" || Brain.DefaultCloudModel("google", new System.Collections.Generic.List<string> { "gemini-91-pro", "gemini-91-flash-lite" }) != "gemini-91-flash-lite") throw new Exception("Gemini didn't choose an available Flash model or filtered its list incorrectly.");
            if (routerModels.Count != 5 || Brain.DefaultCloudModel("openrouter", routerModels) != "example/vision:free" || Brain.DefaultCloudModel("openrouter", new System.Collections.Generic.List<string> { "google/gemini-90-flash", "example/eyes:free" }) != "example/eyes:free" || Brain.DefaultCloudModel("openrouter", new System.Collections.Generic.List<string> { "google/gemini-90-flash", "example/vision-text:free" }) != "example/vision-text:free") throw new Exception("OpenRouter didn't prefer free seeing models, then other free models.");
            Brain googleBrain = new Brain { Remote = new Cloud("AIza-test", "gemini-90.10-flash"), Model = "gemini-90.10-flash" };
            Brain routerBrain = new Brain { Remote = new Cloud("sk-or-test", "example/vision:free"), Model = "example/vision:free" };
            if (googleBrain.Remote.Name != "Gemini" || googleBrain.Remote.Company != "Google AI" || routerBrain.Remote.Company != "OpenRouter" || !googleBrain.Sighted(googleBrain.Remote) || !routerBrain.Sighted(routerBrain.Remote) || googleBrain.Drives || routerBrain.Drives || !Brain.HasTools(routerBrain.Remote)) throw new Exception("The new brains have the wrong identity or job path.");
            if (routerBrain.Sighted(new Cloud("sk-or-test", "example/vision-text:free")) || routerBrain.Sighted(new Cloud("sk-or-test", "example/unknown:free")) || !routerBrain.Sighted(new Cloud("sk-or-test", "example/eyes:free")) || Brain.HasTools(new Cloud("sk-or-test", "example/eyes:free")) || Brain.HasTools(new Cloud("sk-or-test", "example/unknown:free"))) throw new Exception("OpenRouter guessed vision or tools from a model's name.");
            if (googleBrain.Looker(googleBrain.Model) != googleBrain.Model || routerBrain.Looker(routerBrain.Model) != routerBrain.Model) throw new Exception("A cloud brain borrowed another provider's eyes.");
            checks.Add("PASS dynamic model defaults: stable Flash versions sort numerically, non-chat Gemini models stay out (embedding, image, live, speech, transcription, Nano Banana and Omni), and OpenRouter prefers free vision with tools using its advertised capabilities");
            foreach (string brokenCatalog in new[] { "not json", "{}", "{\"data\":[]}" })
            {
                bool explainedCatalog = false;
                try { Brain.ReadCloudModels("google", brokenCatalog); }
                catch (BrainException catalogError) { explainedCatalog = catalogError.Told && catalogError.Message.StartsWith("Google AI", StringComparison.Ordinal); }
                if (!explainedCatalog) throw new Exception("A bad model list failed without a plain reason.");
            }
            checks.Add("PASS invalid, missing and empty model lists explain what went wrong");

            string savedGoogle = Brain.Google, savedRouter = Brain.OpenRouter;
            System.Net.Sockets.TcpListener googleFake = null, routerFake = null;
            try
            {
                System.Collections.Generic.List<string> googleAsked = new System.Collections.Generic.List<string>();
                System.Collections.Generic.List<string> routerAsked = new System.Collections.Generic.List<string>();
                string functionReply = "{\"choices\":[{\"message\":{\"tool_calls\":[{\"type\":\"function\",\"function\":{\"name\":\"done\",\"arguments\":\"{\\\"text\\\":\\\"Finished.\\\"}\"}}]}}]}";
                Brain.Google = FakeServer(new[] { googleCatalog, LocalReply("Hello."), functionReply, LocalReply("A screen."), LocalReply("An aside."), LocalReply("Two frames.") }, googleAsked, out googleFake) + "/v1beta/openai";
                Brain.OpenRouter = FakeServer(new[] { routerCatalog, functionReply, LocalReply("A screen."), LocalReply("An aside."), LocalReply("done{\"text\":\"Finished.\"}"), "!404 {\"error\":{\"message\":\"No endpoints found that support tool use\"}}", LocalReply("done{\"text\":\"Finished.\"}"), LocalReply("done{\"text\":\"Finished again.\"}"), LocalReply("Another provider's model.") }, routerAsked, out routerFake) + "/api/v1";
                if (Brain.CloudModels("AIza-test").Count != 5) throw new Exception("Gemini's model list kept models that can't chat.");
                Brain.CloudModels("sk-or-test");
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> googleCalls = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>();
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> routerCalls = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>();
                if (googleBrain.Ask("Hello") != "Hello.") throw new Exception("Gemini chat didn't reach the compatible API.");
                googleBrain.Step("Job", "Finish", Computer.Tools, Computer.ClaudeTools, Computer.Listing, googleCalls);
                routerBrain.Step("Job", "Finish", Computer.Tools, Computer.ClaudeTools, Computer.Listing, routerCalls);
                if (googleCalls.Count != 1 || routerCalls.Count != 1 || googleCalls[0].Key != "done" || routerCalls[0].Value.Text != "Finished.") throw new Exception("A new provider's tool calls weren't read.");
                if (googleBrain.See(new byte[] { 1, 2, 3 }, "Look", "Screen", 90, true) != "A screen." || googleBrain.Aside("Job", "Think", 90, true) != "An aside." || googleBrain.Quick("Look", "Frames", 90, new byte[] { 1 }, new byte[] { 2 }) != "Two frames.") throw new Exception("Gemini lost a sight, aside or quick call.");
                routerBrain.Remote.Model = routerBrain.Model = "example/eyes:free";
                if (routerBrain.See(new byte[] { 1, 2, 3 }, "Job", "Screen", 90, true) != "A screen." || routerBrain.Aside("Job", "Think", 90, true) != "An aside.") throw new Exception("A seeing OpenRouter brain needed native tools to work.");
                routerCalls.Clear();
                if (Computer.Moves(routerBrain.Step("Job", "Finish", Computer.Tools, Computer.ClaudeTools, Computer.Listing, routerCalls)).Count != 1) throw new Exception("OpenRouter didn't use written tools when its model lacked tools.");
                routerBrain.Remote.Model = routerBrain.Model = "example/vision:free";
                routerBrain.Step("Job", "Finish", Computer.Tools, Computer.ClaudeTools, Computer.Listing, routerCalls);
                routerBrain.Step("Job", "Finish again", Computer.Tools, Computer.ClaudeTools, Computer.Listing, routerCalls);
                routerBrain.Remote.Model = routerBrain.Model = "google/gemini-90-flash";
                if (routerBrain.Aside("Chat", "Hello", 90) != "Another provider's model.") throw new Exception("A routed Gemini model left OpenRouter.");
                if (googleAsked.Count != 6 || routerAsked.Count != 9) throw new Exception("New providers made unexpected extra requests.");
                for (int googleIndex = 0; googleIndex < googleAsked.Count; googleIndex++)
                {
                    string googleRequest = googleAsked[googleIndex];
                    if (!googleRequest.StartsWith(googleIndex == 0 ? "GET /v1beta/openai/models " : "POST /v1beta/openai/chat/completions ", StringComparison.Ordinal) || !googleRequest.Contains("Authorization: Bearer AIza-test") || googleRequest.Contains("sk-or-test") || googleRequest.Contains("X-Title:") || googleRequest.Contains("max_completion_tokens") || googleRequest.Contains("chat_template_kwargs")
                        || (googleIndex > 0 && !googleRequest.Contains("\"reasoning_effort\":\"low\""))) throw new Exception("A Gemini request used another provider's route, key or settings.");
                }
                for (int routerIndex = 0; routerIndex < routerAsked.Count; routerIndex++)
                {
                    string routerRequest = routerAsked[routerIndex];
                    if (!routerRequest.StartsWith(routerIndex == 0 ? "GET /api/v1/models " : "POST /api/v1/chat/completions ", StringComparison.Ordinal) || !routerRequest.Contains("Authorization: Bearer sk-or-test") || !routerRequest.Contains("X-Title: Azure") || routerRequest.Contains("AIza-test") || routerRequest.Contains("Referer:") || routerRequest.Contains("max_completion_tokens") || routerRequest.Contains("chat_template_kwargs") || routerRequest.Contains("reasoning_effort")) throw new Exception("An OpenRouter request used another provider's route, key or settings.");
                }
                if (!googleAsked[2].Contains("\"tools\":") || !routerAsked[1].Contains("\"tools\":") || !googleAsked[3].Contains("data:image/jpeg;base64,AQID") || !routerAsked[2].Contains("data:image/jpeg;base64,AQID") || routerAsked[4].Contains("\"tools\":") || !routerAsked[5].Contains("\"tools\":") || routerAsked[6].Contains("\"tools\":") || routerAsked[7].Contains("\"tools\":")) throw new Exception("Pictures, advertised tools or the fallback after a rejected tool call were wrong.");
                checks.Add("PASS Gemini and OpenRouter chat, tools, screenshots, asides and quick calls stay on their provider; only OpenRouter sends X-Title: Azure, and tool rejection falls back to written moves");
            }
            catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT Gemini and OpenRouter transport: loopback sockets unavailable"); }
            finally
            {
                Brain.Google = savedGoogle; Brain.OpenRouter = savedRouter;
                if (googleFake != null) googleFake.Stop();
                if (routerFake != null) routerFake.Stop();
            }
            // Google turns an AQ. key's Bearer token away at its model list but takes it for chat, so x-goog-api-key is only the model
            // list's way in, and a way in that's turned away too is forgotten.
            System.Net.Sockets.TcpListener doorFake = null;
            try
            {
                System.Collections.Generic.List<string> doorAsked = new System.Collections.Generic.List<string>();
                string twoKeys = "!400 {\"error\":{\"message\":\"Multiple authentication credentials received. Please pass only one.\",\"status\":\"INVALID_ARGUMENT\"}}";
                string noBearer = "!400 [{\"error\":{\"code\":400,\"message\":\"Missing Authorization header.\",\"status\":\"INVALID_ARGUMENT\"}}]";
                string nowhere = "!400 [{\"error\":{\"code\":400,\"message\":\"User location is not supported for the API use.\",\"status\":\"FAILED_PRECONDITION\"}}]";
                string invalidKey = "!400 {\"error\":{\"code\":400,\"message\":\"API key not valid. Please pass a valid API key.\",\"status\":\"INVALID_ARGUMENT\"}}";
                Brain.Google = FakeServer(new[] { twoKeys, googleCatalog, LocalReply("Bearer still opens chat."), googleCatalog, twoKeys, noBearer, LocalReply("Back on Bearer."), nowhere, invalidKey }, doorAsked, out doorFake) + "/v1beta/openai";
                Brain.CloudModels("AQ.door-test");
                Brain doorBrain = new Brain { Remote = new Cloud("AQ.door-test", "gemini-90.10-flash"), Model = "gemini-90.10-flash" };
                string doorReply = doorBrain.Ask("Hello");
                Brain.CloudModels("AQ.door-test");
                Brain shutBrain = new Brain { Remote = new Cloud("AQ.shut-test", "gemini-90.10-flash"), Model = "gemini-90.10-flash" };
                string shutLine = null;
                try { shutBrain.Ask("Hello"); } catch (BrainException shut) { shutLine = shut.Told ? shut.Message : null; }
                string backReply = shutBrain.Ask("Hello again");
                Brain plainBrain = new Brain { Remote = new Cloud("AIza-door-test", "gemini-90.10-flash"), Model = "gemini-90.10-flash" };
                string nowhereLine = null, invalidLine = null;
                try { plainBrain.Ask("Hello"); } catch (BrainException unserved) { nowhereLine = unserved.Told ? unserved.Message : null; }
                try { plainBrain.Ask("Hello"); } catch (BrainException rejected) { invalidLine = rejected.Told ? rejected.Message : null; }
                if (shutLine != Brain.NewKey || invalidLine != Brain.NewKey || nowhereLine != Brain.Unserved) throw new Exception("Google's key and region errors reached her as: " + shutLine + " / " + invalidLine + " / " + nowhereLine);
                string[] doorSent;
                lock (doorAsked) doorSent = doorAsked.ToArray();
                bool doorRight = doorReply == "Bearer still opens chat." && backReply == "Back on Bearer." && doorSent.Length == 9
                    && doorSent[0].StartsWith("GET /v1beta/openai/models ", StringComparison.Ordinal) && doorSent[0].Contains("Authorization: Bearer AQ.door-test") && doorSent[1].Contains("x-goog-api-key: AQ.door-test") && !doorSent[1].Contains("Authorization:")
                    && doorSent[2].StartsWith("POST /v1beta/openai/chat/completions ", StringComparison.Ordinal) && doorSent[2].Contains("Authorization: Bearer AQ.door-test") && !doorSent[2].Contains("x-goog-api-key:")
                    && doorSent[3].StartsWith("GET /v1beta/openai/models ", StringComparison.Ordinal) && doorSent[3].Contains("x-goog-api-key: AQ.door-test") && !doorSent[3].Contains("Authorization:")
                    && doorSent[4].Contains("Authorization: Bearer AQ.shut-test") && doorSent[5].Contains("x-goog-api-key: AQ.shut-test") && !doorSent[5].Contains("Authorization:")
                    && doorSent[6].Contains("Authorization: Bearer AQ.shut-test") && !doorSent[6].Contains("x-goog-api-key:");
                if (!doorRight) throw new Exception("A Gemini AQ. key took the wrong way in: " + doorReply + " / " + backReply + " / " + doorSent.Length + " requests");
                if (Brain.Redacted("bad key AQ.Ab8RN6Kabc_d-e") != "bad key [redacted]") throw new Exception("An AQ. key wasn't redacted: " + Brain.Redacted("bad key AQ.Ab8RN6Kabc_d-e"));
                checks.Add("PASS Gemini keys that start AQ. stay out of her logs; one Google turns away as a Bearer token at the model list lists with x-goog-api-key from then on while chat keeps its Bearer token, and a way in that's turned away too is forgotten");
                checks.Add("PASS a Gemini key Google turns away for its credentials or a missing Authorization header says to make a new Google AI Studio key, and a place Google doesn't serve says so, instead of her brain couldn't answer");
            }
            catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT Gemini AQ. keys: loopback sockets unavailable"); }
            finally
            {
                Brain.Google = savedGoogle;
                if (doorFake != null) doorFake.Stop();
            }
            string plainLogWas = Brain.LogPath;
            string accented = Path.Combine(Path.GetDirectoryName(plainLogWas), "O\u015Bka");
            Directory.CreateDirectory(accented);
            File.WriteAllText(Path.Combine(accented, "voice.txt"), "heard");
            string plainFile;
            Brain.LogPath = Path.Combine(accented, "errors.txt");
            try { plainFile = LocalVoice.Plain(Path.Combine(accented, "voice.txt")); }
            finally { Brain.LogPath = plainLogWas; }
            if (LocalVoice.Plain("cpu") != "cpu" || plainFile.IndexOf('\u015B') >= 0 || File.ReadAllText(plainFile) != "heard") throw new Exception("A folder with a special letter didn't get a plain path: " + plainFile);
            Directory.Delete(Path.GetDirectoryName(plainFile));
            checks.Add("PASS a folder with a letter like \u015B reaches her voice library through a plain-named junction, because a path it can't read would end her with nothing logged");
            int checkedLimits = 0;
            foreach (string limitedKey in new[] { "AIza-test", "sk-or-test" })
            {
                System.Net.Sockets.TcpListener limitedFake = null;
                try
                {
                    System.Collections.Generic.List<string> limitedAsked = new System.Collections.Generic.List<string>();
                    string limitedReply = "!429 {\"error\":{\"status\":\"RESOURCE_EXHAUSTED\",\"message\":\"Rate limit reached. Check your billing plan.\"}}";
                    // Glued to a word, the echoed key has no shape her redaction knows, so only CloudModels handing its key to the
                    // error scrubs it: these test keys start like real ones, which redaction alone would hide.
                    if (Brain.Redacted("for project_" + limitedKey) != "for project_" + limitedKey) throw new Exception("The echoed test key has a shape redaction already knows.");
                    string limitedUrl = FakeServer(new[] { limitedReply, limitedReply, "!401 {\"error\":{\"message\":\"Rejected " + limitedKey + "\"}}", "!400 {\"error\":{\"message\":\"Cannot list models for project_" + limitedKey + "\"}}", "!404 {}" }, limitedAsked, out limitedFake);
                    Brain.Google = limitedUrl; Brain.OpenRouter = limitedUrl;
                    int explainedLimits = 0;
                    try { Brain.CloudModels(limitedKey); } catch (BrainException listLimit) { if ((listLimit.Message == Brain.Busy || listLimit.Message == Brain.BusyWatching) && listLimit.Told) explainedLimits++; }
                    Brain limitedBrain = new Brain { Remote = new Cloud(limitedKey, "test"), Model = "test" };
                    try { limitedBrain.Aside("Chat", "Hello", 90); } catch (BrainException chatLimit) { if ((chatLimit.Message == Brain.Busy || chatLimit.Message == Brain.BusyWatching) && Brain.Stalled(chatLimit)) explainedLimits++; }
                    bool rejectedKey = false;
                    try { Brain.CloudModels(limitedKey); } catch (BrainException badKey) { rejectedKey = badKey.Told && badKey.Message == (limitedKey == "AIza-test" ? Brain.NewKey : Brain.Rejected("OpenRouter")); }
                    bool scrubbedKey = false, missingList = false;
                    try { Brain.CloudModels(limitedKey); } catch (BrainException echoedKey) { scrubbedKey = echoedKey.Message.Contains("project_[redacted]") && !echoedKey.Message.Contains(limitedKey); }
                    try { Brain.CloudModels(limitedKey); } catch (BrainException missingModels) { missingList = missingModels.Told && missingModels.Message.Contains("couldn't find its model list"); }
                    if (explainedLimits != 2 || !rejectedKey || !scrubbedKey || !missingList || limitedAsked.Count != 5) throw new Exception("A new provider hid a model-list error, repeated a key or retried a rate limit immediately.");
                    checkedLimits++;
                }
                catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT new brain rate limits: loopback sockets unavailable"); }
                finally
                {
                    Brain.Google = savedGoogle; Brain.OpenRouter = savedRouter;
                    if (limitedFake != null) limitedFake.Stop();
                }
            }
            if (checkedLimits == 2) checks.Add("PASS new providers share NVIDIA's rate-limit message and retry handling, explain missing model lists and rejected keys (a Gemini one asks for a new Google AI Studio key), and scrub keys echoed in errors");
            System.Net.Sockets.TcpListener movedFake = null, redirectFake = null;
            try
            {
                System.Collections.Generic.List<string> movedAsked = new System.Collections.Generic.List<string>();
                System.Collections.Generic.List<string> redirectAsked = new System.Collections.Generic.List<string>();
                string redirectAddress = FakeServer(new[] { LocalReply("Wrong provider.") }, redirectAsked, out redirectFake);
                Brain.OpenRouter = FakeServer(new[] { "{}", "{}" }, movedAsked, out movedFake, 302, 0, false, 0, "application/json", "Location: " + redirectAddress + "/\r\n");
                int stoppedRedirects = 0;
                try { Brain.CloudModels("sk-or-test"); } catch (BrainException movedList) { if (movedList.Message.Contains("key wasn't sent")) stoppedRedirects++; }
                try { routerBrain.Aside("Chat", "Hello", 90); } catch (BrainException movedChat) { if (movedChat.Message.Contains("key wasn't sent")) stoppedRedirects++; }
                if (stoppedRedirects != 2 || movedAsked.Count != 2 || redirectAsked.Count != 0) throw new Exception("An authenticated model list or chat followed a redirect.");
                checks.Add("PASS model lists and chats do not forward a brain key when a provider redirects them");
            }
            catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT brain redirect checks: loopback sockets unavailable"); }
            finally { Brain.OpenRouter = savedRouter; if (movedFake != null) movedFake.Stop(); if (redirectFake != null) redirectFake.Stop(); }
            checks.Add("LIMIT live Gemini and OpenRouter authentication, model availability and tool execution need provider keys");
        }

