                checks.Add("PASS job allowances: Short keeps local steps, built-in jobs, local server tools, game pictures, asides and comments at their own defaults; Long raises smaller jobs, while deep game turns keep 16000 tokens, and Auto keeps 4096 for other driving");

                // An ask longer than Auto memory's 4K window restarts her built-in brain once with room for it (_mamad and sniix, 3 Nov).
                Brain.MemorySize = 0; Brain.ReplyLength = 0; Brain.Recall = 8;
                if (Brain.Room("request (6073 tokens) exceeds the available context size (4096 tokens), try increasing it", 4096, 90) != 8192 || Brain.Room("request (4538 tokens) exceeds the available context size (4096 tokens), try increasing it", 4096, 4096) != 8192
                    || Brain.Room("the request exceeds the available context size, try increasing it", 4096, 90) != 8192 || Brain.Room("request (15000 tokens) exceeds the available context size (8192 tokens), try increasing it", 8192, 2048) != 0)
                    throw new Exception("An overflowing ask picked the wrong memory size.");
                string overflowData = Path.Combine(Path.GetTempPath(), "capri-overflow-" + Guid.NewGuid().ToString("N"));
                Func<ProcessStartInfo, Process> spawnWas = Engine.Spawn;
                Engine roomy = new Engine(overflowData);
                System.Collections.Generic.List<string> windows = new System.Collections.Generic.List<string>();
                System.Collections.Generic.List<string> roomAsked = new System.Collections.Generic.List<string>();
                System.Collections.Generic.List<System.Net.Sockets.TcpListener> engines = new System.Collections.Generic.List<System.Net.Sockets.TcpListener>();
                string tooLong = "!400 {\"error\":{\"code\":400,\"message\":\"request (6073 tokens) exceeds the available context size (4096 tokens), try increasing it\",\"type\":\"exceed_context_size_error\",\"n_prompt_tokens\":6073,\"n_ctx\":4096}}";
                try
                {
                    ProcessStartInfo files = roomy.StartInfo(Engine.Picks[2], false, false, 1);
                    string modelFile = Regex.Match(files.Arguments, "-m \"([^\"]+)\"").Groups[1].Value;
                    Directory.CreateDirectory(Path.GetDirectoryName(files.FileName));
                    Directory.CreateDirectory(Path.GetDirectoryName(modelFile));
                    File.WriteAllText(files.FileName, "");
                    File.WriteAllText(modelFile, "");
                    string healthy = "{\"status\":\"ok\"}";
                    string loading = "!503 {\"error\":{\"message\":\"Loading model\",\"type\":\"unavailable_error\",\"code\":503}}";
                    string[][] launches = { new[] { healthy, tooLong }, new[] { healthy, answer }, new[] { healthy, tooLong }, new[] { healthy, loading, healthy, answer } };
                    Engine.Spawn = delegate(ProcessStartInfo info)
                    {
                        windows.Add(Regex.Match(info.Arguments, @" -c (\d+) ").Groups[1].Value);
                        System.Net.Sockets.TcpListener served;
                        FakeServer(launches[Math.Min(windows.Count, launches.Length) - 1], roomAsked, out served, port: int.Parse(Regex.Match(info.Arguments, @"--port (\d+)").Groups[1].Value));
                        engines.Add(served);
                        return Process.Start(new ProcessStartInfo("ping.exe", "-n 30 127.0.0.1") { UseShellExecute = false, CreateNoWindow = true });
                    };
                    Brain overflowing = new Brain { Model = "test", Local = roomy, LocalPick = Engine.Picks[2] };
                    string fits = overflowing.Aside("Talk", "Hello", 90);
                    if (fits != "Done." || string.Join(" ", windows.ToArray()) != "4096 8192" || Brain.Window != 8192) throw new Exception("An ask longer than Auto memory didn't restart her brain with room for it: " + fits + " / " + string.Join(" ", windows.ToArray()));
                    Brain.MemorySize = 4096;
                    string picked = null;
                    try { overflowing.Aside("Talk", "Hello", 90); }
                    catch (BrainException error) { picked = error.Message; }
                    if (picked != "That was too long for my brain's 4K memory. Pick a bigger Memory size under BRAIN in Capri Mainframe." || string.Join(" ", windows.ToArray()) != "4096 8192 4096") throw new Exception("An ask longer than a memory size they picked didn't say how to give her more: " + picked + " / " + string.Join(" ", windows.ToArray()));
                    checks.Add("PASS long asks: an ask longer than Auto memory's 4K restarts her built-in brain once with 8K and answers, and one longer than a size they picked says to pick a bigger Memory size instead of llama-server's own words");
                    // An ask that lands while her brain is still loading, like during another ask's restart, waits for it (Lean, 3 Nov).
                    Brain.MemorySize = 8192;
                    string waited = overflowing.Aside("Talk", "Hello", 90);
                    if (waited != "Done." || string.Join(" ", windows.ToArray()) != "4096 8192 4096 8192") throw new Exception("An ask that came while her brain was loading didn't wait for it: " + waited + " / " + string.Join(" ", windows.ToArray()));
                    checks.Add("PASS loading brain: an ask that gets llama-server's 503 Loading model, like one sent during another ask's restart, waits for her brain to load and asks once more");
                }
                finally
                {
                    Engine.Spawn = spawnWas;
                    roomy.Stop();
                    foreach (System.Net.Sockets.TcpListener served in engines) served.Stop();
                    Brain.Grown = 0;
                    try { Directory.Delete(overflowData, true); } catch (IOException) { } catch (UnauthorizedAccessException) { }
                }
            }
            catch (System.Net.Sockets.SocketException unavailable) { checks.Add("LIMIT brain request settings: loopback sockets unavailable here (" + unavailable.SocketErrorCode + ")"); }
            finally
            {
                if (fake != null) fake.Stop();
                Brain.MemorySize = wasMemory; Brain.ReplyLength = wasReply; Brain.Recall = wasRecall;
                Brain.Ollama = wasOllama; Brain.OpenAi = wasOpenAi; Brain.Anthropic = wasClaude; Brain.DeepSeek = wasDeep; Brain.Nvidia = wasNvidia; Brain.Google = wasGoogle; Brain.OpenRouter = wasRouter;
            }
        }

        private static void SmokeReplyScroll(System.Collections.Generic.List<string> checks)
        {
            int replySizeWas = Brain.ReplyLength;
            try
            {
                foreach (int scrollSize in new[] { 2, 3 })
                {
                    Brain.ReplyLength = scrollSize;
                    string longReply = new string('x', Brain.ReplySizes[scrollSize] * 5) + " END";
                    if (Brain.Clean(longReply) != longReply) throw new Exception("A chosen reply size cut the returned text.");
                    foreach (float scrollScale in new[] { 1f, 1.5f, 2f })
                    using (SpeechBox scrollBox = new SpeechBox())
                    {
                        Rectangle scrollArea = new Rectangle(-1280, 80, 1280, 640);
                        Point scrollHead = new Point(-500, 100), scrollFeet = new Point(-500, 600), scrollAt;
                        scrollBox.State = TalkState.Online;
                        scrollBox.Reply = longReply;
                        scrollBox.Revealed = longReply.Length;
                        using (Bitmap scrollFirst = scrollBox.Render(scrollScale, scrollHead, scrollFeet, scrollArea, false, out scrollAt))
                            if (!scrollArea.Contains(new Rectangle(scrollAt, scrollFirst.Size)) || !scrollBox.Scrollable || scrollBox.FirstLine != 0) throw new Exception("A long reply left the screen or could not scroll.");
                        int scrollRead = scrollBox.VisibleLines;
                        while (scrollBox.FirstLine + scrollBox.VisibleLines < scrollBox.TotalLines)
                        {
                            int scrollPrevious = scrollBox.FirstLine;
                            scrollBox.ScrollRows(scrollBox.VisibleLines);
                            using (Bitmap scrollPage = scrollBox.Render(scrollScale, scrollHead, scrollFeet, scrollArea, false, out scrollAt))
                                if (!scrollArea.Contains(new Rectangle(scrollAt, scrollPage.Size)) || scrollBox.FirstLine <= scrollPrevious || scrollBox.FirstLine > scrollRead) throw new Exception("Paging skipped lines or left the screen.");
                            scrollRead = scrollBox.FirstLine + scrollBox.VisibleLines;
                        }
                        if (scrollRead != scrollBox.TotalLines || scrollBox.Reply != longReply) throw new Exception("The reply's last lines were unreachable.");
                        scrollBox.ScrollRows(int.MinValue);
                        if (scrollBox.FirstLine != 0) throw new Exception("Scrolling up lost the reply's first lines.");
                        scrollBox.Reply = "Short reply.";
                        using (Bitmap scrollShort = scrollBox.Render(scrollScale, scrollHead, scrollFeet, scrollArea, false, out scrollAt))
                            if (scrollBox.Scrollable || scrollBox.FirstLine != 0) throw new Exception("A new reply inherited the previous scroll position.");
                        string copiedReply = null;
                        int plainHeight;
                        scrollBox.Prompt = "";
                        scrollBox.Copying = delegate(string copiedWords) { copiedReply = copiedWords; };
                        using (Bitmap copyBefore = scrollBox.Render(scrollScale, scrollHead, scrollFeet, scrollArea, false, out scrollAt)) plainHeight = copyBefore.Height;
                        scrollBox.CopyReply();
                        using (Bitmap copyAfter = scrollBox.Render(scrollScale, scrollHead, scrollFeet, scrollArea, false, out scrollAt))
                            if (copiedReply != "Short reply." || copyAfter.Height <= plainHeight) throw new Exception("Right click didn't copy her reply or say so.");
                        scrollBox.Reply = "Next reply.";
                        using (Bitmap copyNext = scrollBox.Render(scrollScale, scrollHead, scrollFeet, scrollArea, false, out scrollAt))
                            if (copyNext.Height != plainHeight) throw new Exception("The copied note stayed on her next reply.");
                    }
                }
                checks.Add("PASS 2K and 8K replies keep all text, fit the screen at 100%, 150% and 200%, page through every line and scroll back to the start");
                checks.Add("PASS right click copies her whole reply, the bubble says so, and her next reply starts clean");
            }
            finally { Brain.ReplyLength = replySizeWas; }
        }

        private void SmokeBrainSettings(System.Collections.Generic.List<string> checks)
        {
            int wasMemory = Brain.MemorySize, wasReply = Brain.ReplyLength;
            try
            {
                SetMemorySize(0); SetReplyLength(0); mainframe.Sync();
                Preferences old;
                using (MemoryStream earlier = new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{\"Recall\":16}"))) old = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(earlier);
                if (mainframe.BrainSettings != "Auto | Auto" || old.MemorySize != 0 || old.ReplyLength != 0 || new Preferences().MemorySize != 0 || new Preferences().ReplyLength != 0) throw new Exception("New and old settings did not keep Auto.");
                string[] memoryNames = { "Auto", "4K", "8K", "16K", "32K", "64K" };
                string[] replyNames = { "Auto", "256", "2K", "8K" };
                for (int memory = 0; memory < Brain.MemorySizes.Length; memory++)
                {
                    mainframe.SlideMemorySize(memory);
                    if (MemorySize != Brain.MemorySizes[memory] || LoadPreferences().MemorySize != MemorySize || !mainframe.BrainSettings.StartsWith(memoryNames[memory] + " | ", StringComparison.Ordinal)) throw new Exception("Memory size did not save or show its choice.");
                }
                for (int reply = 0; reply < replyNames.Length; reply++)
                {
                    mainframe.SlideReplyLength(reply);
                    if (ReplyLength != reply || LoadPreferences().ReplyLength != reply || mainframe.BrainSettings != "64K | " + replyNames[reply]) throw new Exception("Reply length did not save or show its choice.");
                }
                mainframe.SlideMemorySize(0); mainframe.SlideReplyLength(0);
                if (mainframe.BrainSettings != "Auto | Auto" || LoadPreferences().MemorySize != 0 || LoadPreferences().ReplyLength != 0) throw new Exception("The brain settings did not return to Auto.");
                checks.Add("PASS BRAIN controls: Memory size and Reply length start on Auto in new and old settings; every choice moves its Setting control, saves to Preferences and shows again, and Auto restores the existing defaults");
            }
            finally { SetMemorySize(wasMemory); SetReplyLength(wasReply); mainframe.Sync(); }
        }

        private void SmokeBrainLayout(System.Collections.Generic.List<string> checks)
        {
            SmokeMainframePictures(checks);
            bool wasSettings = mainframe.SettingsShown;
            bool wasSimple = simpleTest, wasAdvanced = preferences.AdvancedSettings, wasCheckIns = preferences.CheckIns;
            int wasSize = preferences.MainframeSize;
            foreach (int storedSize in new[] { 0, 100, 125, 150, 175, 200, -1, 50, 110, 250, int.MaxValue })
            {
                Preferences upgraded;
                string storedJson = "{\"MainframeSize\":" + storedSize + "}";
                using (MemoryStream storedFrame = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(storedJson))) upgraded = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(storedFrame);
                if (upgraded.MainframeSize != Preferences.FrameSize(storedSize)) throw new Exception("An old Mainframe size did not become a supported choice.");
            }
            using (MemoryStream missingFrame = new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{}")))
                if (((Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(missingFrame)).MainframeSize != 0) throw new Exception("Settings from before Mainframe size did not start on Auto.");
            checks.Add("PASS Mainframe size upgrades: missing and unsupported saved sizes become Auto, and every supported size is kept");
            try
            {
                simpleTest = false;
                preferences.AdvancedSettings = false;
                mainframe.ShowSettings(true);
                foreach (int size in new[] { 100, 125, 150, 175, 200 })
                {
                    mainframe.SizeMainframe(size);
                    string crowded = mainframe.Overlap() ?? (mainframe.PageClamped ? null : mainframe.Outside());
                    if (crowded != null) throw new Exception("BRAIN controls at " + size + "% overlap or leave the page: " + crowded);
                    Control gamingToggle = null, gamingCaption = null, gamingDisclaimer = null, gamingClip = null, gamingMoments = null, gamingHands = null, gamingEnd = null;
                    foreach (Control gamingControl in mainframe.Controls)
                    {
                        if (gamingControl.Text == "Gaming Mode") gamingToggle = gamingControl;
                        if (gamingControl.Text == "\"Hey Capri, activate gaming mode\" turns it on.") gamingCaption = gamingControl;
                        if (gamingControl.Text == "Works best on MAX INTELLIGENCE.") gamingDisclaimer = gamingControl;
                        if (gamingControl.Text == "Clip my games") gamingClip = gamingControl;
                        if (gamingControl.Text == "Save big moments") gamingMoments = gamingControl;
                        if (gamingControl.Text == "Fast hands in games") gamingHands = gamingControl;
                        if (gamingControl.Text == "She reacts to your game until you close it.") gamingEnd = gamingControl;
                    }
                    if (gamingToggle == null || gamingCaption == null || gamingDisclaimer == null || gamingClip == null || gamingMoments == null || gamingHands == null || gamingEnd == null
                        || !gamingCaption.Visible || !gamingDisclaimer.Visible
                        || gamingToggle.Bottom > gamingEnd.Top || gamingEnd.Bottom > gamingCaption.Top || gamingCaption.Bottom > gamingDisclaimer.Top || gamingDisclaimer.Bottom > gamingHands.Top
                        || gamingHands.Bottom > gamingClip.Top || gamingClip.Bottom > gamingMoments.Top
                        || !(gamingToggle.AccessibleName ?? "").Contains(gamingCaption.Text) || !(gamingToggle.AccessibleName ?? "").Contains(gamingDisclaimer.Text))
                        throw new Exception("Gaming Mode captions or rows do not fit at " + size + "%.");
                }
                checks.Add("PASS BRAIN layout: every setting stays on its scrollable page at 100%, 125%, 150%, 175% and 200%, with no overlaps or controls poking out");
                checks.Add("PASS Gaming Mode Settings: its three lines sit below the switch and above the other game rows, reach screen readers, and stay inside the page without overlaps at every Mainframe size");
                System.Collections.Generic.List<string> frameProblems = new System.Collections.Generic.List<string>();
                foreach (bool frameFallback in new[] { false, true })
                    foreach (int frameDpi in new[] { 96, 144, 192, 96 })
                        foreach (int frameText in new[] { 100, 225 })
                            foreach (int framePercent in new[] { 0, 100, 175, 200, 100 })
                            {
                                mainframe.LayoutScale(frameDpi, frameText, frameFallback);
                                mainframe.SizeMainframe(framePercent);
                                foreach (bool frameSimple in new[] { false, true })
                                    foreach (bool framePage in new[] { false, true })
                                    {
                                        simpleTest = frameSimple;
                                        mainframe.ShowSettings(framePage);
                                        int frameWidth = (int)Math.Round((framePage ? 760 : 380) * frameDpi / 96f * frameText / 100f * mainframe.Zoom);
                                        string frameProblem = mainframe.TextFits() ?? mainframe.Overlap() ?? (framePage && mainframe.ClientSize.Width == frameWidth ? mainframe.Outside() : null);
                                        if (framePage)
                                        {
                                            frameProblem = frameProblem ?? mainframe.BrainFits();
                                            foreach (bool frameCheckIns in new[] { false, true })
                                            {
                                                preferences.CheckIns = frameCheckIns;
                                                mainframe.Sync();
                                                frameProblem = frameProblem ?? mainframe.CareFits();
                                            }
                                        }
                                        bool frameWidthFits = frameWidth > SystemInformation.MaxWindowTrackSize.Width || mainframe.ClientSize.Width == frameWidth;
                                        if (frameProblem != null || !frameWidthFits) frameProblems.Add(frameDpi + " DPI, text " + frameText + "%, size " + framePercent + "%, " + (framePage ? frameSimple ? "Simple Settings" : "Advanced Settings" : "Brain and Voice") + (frameFallback ? ", fallback font" : "") + ": " + (frameProblem ?? "width scaled twice"));
                                    }
                            }
                if (frameProblems.Count > 0) throw new Exception("Mainframe layout, " + frameProblems.Count + " problems:\r\n" + string.Join("\r\n", frameProblems.ToArray()));
                checks.Add("PASS Mainframe text: every control on both pages, including tier hints and flags, switch names, slider choices and input cues, fits without overlaps at Auto, 100%, 175% and 200% size on simulated 100%, 150% and 200% DPI with 100% and 225% text and fallback fonts; returning to 100% keeps the original scale");
                checks.Add("PASS BRAIN Settings layout: Husk, Thinking, Extra request JSON, Verbosity and the following rows fit in order and fold in Simple Settings, while Mainframe colours and Head pats stay available at every simulated DPI, text and Mainframe size");
                checks.Add("PASS care Settings layout: seven toggle/time rows and Edit check-in lines sit directly under Check in on me in Advanced Settings and fold out of Simple Settings with no gap; both master states, accessible parent names, dimming and editable controls pass with her own and fallback fonts at every simulated DPI, text and Mainframe size");
                checks.Add("LIMIT Mainframe display scaling: simulated pixel layouts do not confirm Windows text-setting notifications, real monitor moves, or high-DPI rendering; Windows may constrain simulated windows wider than this desktop, so those check text and overlaps without the viewport-edge check");
            }
            catch (System.Runtime.InteropServices.ExternalException) { checks.Add("LIMIT Mainframe text measurement: Windows text rendering is unavailable on this desktop"); }
            finally { simpleTest = wasSimple; preferences.AdvancedSettings = wasAdvanced; preferences.CheckIns = wasCheckIns; mainframe.LayoutScale(0, 0); mainframe.SizeMainframe(wasSize); mainframe.ShowSettings(wasSettings); SavePreferences(); }
        }

        private void SmokeMainframePictures(System.Collections.Generic.List<string> checks)
        {
            bool wasPage = mainframe.SettingsShown, wasAdvanced = preferences.AdvancedSettings, wasSimple = simpleTest;
            int wasSize = preferences.MainframeSize;
            string output = Path.GetDirectoryName(Brain.LogPath);
            try
            {
                mainframe.LayoutScale(96, 100);
                mainframe.SizeMainframe(100);
                simpleTest = true;
                string[] names = { "mainframe-main.png", "mainframe-settings.png", "mainframe-advanced.png" };
                for (int page = 0; page < names.Length; page++)
                {
                    preferences.AdvancedSettings = page == 2;
                    mainframe.ShowSettings(page != 0);
                    mainframe.Settle();
                    mainframe.Update();
                    using (Bitmap picture = new Bitmap(mainframe.ClientSize.Width, mainframe.ClientSize.Height))
                    {
                        mainframe.DrawToBitmap(picture, new Rectangle(Point.Empty, picture.Size));
                        picture.Save(Path.Combine(output, names[page]), System.Drawing.Imaging.ImageFormat.Png);
                    }
                    if (!File.Exists(Path.Combine(output, names[page]))) throw new Exception("The Mainframe picture was not saved: " + names[page]);
                }
                checks.Add("PASS Mainframe pictures: main, Simple Settings and Advanced Settings saved at 100%");
            }
            finally
            {
                simpleTest = wasSimple;
                preferences.AdvancedSettings = wasAdvanced;
                mainframe.LayoutScale(0, 0);
                mainframe.SizeMainframe(wasSize);
                mainframe.ShowSettings(wasPage);
            }
        }

        private void SmokeLanguageBounds(ToolStripDropDown menu, Rectangle area, bool[] seen)
        {
            // A Mainframe across two screens drops the menu on the one under its button, so each menu has to fit the screen it's on.
            if (Screen.AllScreens.Length > 1) area = Screen.FromRectangle(menu.Bounds).WorkingArea;
            if (!menu.Visible || !area.Contains(menu.Bounds)) throw new Exception("The language menu leaves its screen: " + menu.Bounds + " in " + area);
            foreach (ToolStripItem item in menu.Items)
            {
                if (!item.Available) continue;
                Rectangle bounds = new Rectangle(menu.PointToScreen(item.Bounds.Location), item.Size);
                if (!item.Visible || !area.Contains(bounds) || !menu.ClientRectangle.Contains(item.Bounds)) throw new Exception("A language item is clipped: " + item.Text + " at " + bounds + " in " + area);
                ToolStripMenuItem choice = item as ToolStripMenuItem;
                if (choice == null) continue;
                if (choice.HasDropDownItems)
                {
                    choice.ShowDropDown();
                    try { SmokeLanguageBounds(choice.DropDown, area, seen); }
                    finally { choice.HideDropDown(); }
                    continue;
                }
                int row = -1;
                for (int i = 0; i < Brain.Languages.GetLength(0); i++) if ((string)choice.Tag == Brain.Languages[i, 1]) { row = i; break; }
                if (row < 0) throw new Exception("A language item has no language: " + choice.Text);
                string name = Brain.Languages[row, 0], english = Brain.Languages[row, 1];
                if (choice.Text != (name == english ? name : name + " (" + english + ")") || choice.Checked != (english == Language)) throw new Exception("A language label or tick is wrong: " + choice.Text);
                seen[row] = true;
            }
        }

        // A menu longer than its screen stays on the screen with her arrows, opens with its tick in view, and scrolls on the wheel
        // wherever Windows sends it, to its last row and back, without the Mainframe page moving behind it (Ashy, 6 Nov).
        private void SmokeLongMenus(System.Collections.Generic.List<string> checks)
        {
            BindingFlags inner = BindingFlags.Instance | BindingFlags.NonPublic;
            foreach (ToolStripDropDown drop in new ToolStripDropDown[] { menu, playerMenu })
                if (!Mainframe.MenuLook.HasArrows(drop)) throw new Exception("Her right-click or player menu has no arrows of hers.");
            foreach (ContextMenuStrip drop in mainframe.Dropdowns)
                if (!Mainframe.MenuLook.HasArrows(drop)) throw new Exception("A Mainframe menu has no arrows of hers: " + (drop.Items.Count > 0 ? drop.Items[0].Text : "empty"));
            if (callPanel != null && !Mainframe.MenuLook.HasArrows((ToolStripDropDown)typeof(CallPanel).GetField("apps", inner).GetValue(callPanel))) throw new Exception("The call panel's app menu has no arrows of hers.");
            Point atWas = mainframe.Location;
            bool shownWas = mainframe.Visible;
            FormWindowState stateWas = mainframe.WindowState;
            ContextMenuStrip list = (ContextMenuStrip)typeof(Mainframe).GetMethod("Dropdown", inner).Invoke(mainframe, null);
            ContextMenuStrip nest = new ContextMenuStrip { Renderer = new Mainframe.MenuLook() };
            try
            {
                mainframe.WindowState = FormWindowState.Normal;
                mainframe.Show();
                ToolStripItem[] rows = new ToolStripItem[300];
                for (int i = 0; i < rows.Length; i++) rows[i] = new ToolStripMenuItem("Model " + i) { Checked = i == 250 };
                list.Items.AddRange(rows);
                Func<ToolStripDropDown, int> first = delegate(ToolStripDropDown drop)
                {
                    for (int i = 0; i < drop.Items.Count; i++) if (drop.Items[i].Bounds.Top >= drop.DisplayRectangle.Top) return i;
                    return -1;
                };
                Action<IntPtr, Point, int> wheel = delegate(IntPtr window, Point at, int notches)
                {
                    Native.PostMessage(window, 0x020A, new IntPtr((notches * 120) << 16), new IntPtr((at.Y << 16) | (at.X & 0xFFFF)));
                    Application.DoEvents();
                };
                bool looked = false;
                // Every screen, then back the other way, so a menu first fitted to a tall screen has to fit a shorter one.
                List<Screen> screens = new List<Screen>(Screen.AllScreens);
                for (int i = screens.Count - 2; i >= 0; i--) screens.Add(screens[i]);
                foreach (Screen screen in screens)
                    foreach (bool low in new[] { false, true })
                    {
                        Rectangle area = screen.WorkingArea;
                        mainframe.Location = new Point(area.Left + 20, low ? Math.Max(area.Top, area.Bottom - mainframe.Height - 20) : area.Top + 20);
                        list.Show(mainframe, new Point(28, 162));
                        Application.DoEvents();
                        string where = " (screen " + area + ", Mainframe " + (low ? "low)" : "high)");
                        Rectangle work = Screen.FromRectangle(list.Bounds).WorkingArea;
                        if (!list.Visible || !work.Contains(list.Bounds)) throw new Exception("A long menu ran off its screen: " + list.Bounds + " in " + work + where);
                        Label up = Mainframe.MenuLook.Arrow(list, true), down = Mainframe.MenuLook.Arrow(list, false);
                        float s = list.DeviceDpi / 96f;
                        if (!Mainframe.MenuLook.Scrolls(list) || !up.Visible || !down.Visible || up.Height < 12 * s || down.Height < 12 * s) throw new Exception("A long menu's arrows are missing or too small: " + up.Height + " and " + down.Height + " px" + where);
                        if (rows[250].Bounds.Top < list.DisplayRectangle.Top || rows[250].Bounds.Bottom > list.DisplayRectangle.Bottom) throw new Exception("A long menu opened without its ticked row in view: row 250 at " + rows[250].Bounds + ", view " + list.DisplayRectangle + ", first row " + first(list) + ", menu " + list.Bounds + ", up " + up.Enabled + ", down " + down.Enabled + ", dpi " + list.DeviceDpi + where);
                        if (!looked)
                        {
                            looked = true;
                            using (Bitmap shot = new Bitmap(list.Width, list.Height))
                            {
                                list.DrawToBitmap(shot, new Rectangle(Point.Empty, shot.Size));
                                Color panel = Mainframe.MenuLook.Panel;
                                int lit = 0;
                                for (int y = down.Top; y < down.Bottom; y++)
                                    for (int x = down.Left + down.Width / 3; x < down.Right - down.Width / 3; x++)
                                    {
                                        Color seen = shot.GetPixel(x, y);
                                        if (Math.Abs(seen.R - panel.R) + Math.Abs(seen.G - panel.G) + Math.Abs(seen.B - panel.B) > 150) lit++;
                                    }
                                if (lit < 6) throw new Exception("A long menu's down arrow doesn't show on her panel (" + lit + " bright pixels).");
                            }
                            int pageWas = (int)typeof(Mainframe).GetField("pageScroll", inner).GetValue(mainframe);
                            int from = first(list);
                            wheel(mainframe.Handle, mainframe.PointToScreen(new Point(8, 8)), -1);
                            if (first(list) <= from) throw new Exception("A wheel turn sent to the Mainframe didn't scroll the open menu.");
                            if ((int)typeof(Mainframe).GetField("pageScroll", inner).GetValue(mainframe) != pageWas) throw new Exception("A wheel turn scrolled the Mainframe page behind an open menu.");
                            from = first(list);
                            wheel(list.Handle, new Point(list.Left + list.Width / 2, list.Top + list.Height / 2), -1);
                            if (first(list) <= from) throw new Exception("A wheel turn over the menu didn't scroll it.");
                            wheel(list.Handle, new Point(list.Left + list.Width / 2, list.Top + list.Height / 2), 150);
                            if (first(list) != 0 || up.Enabled) throw new Exception("Wheeling up didn't reach the menu's first row: " + first(list));
                            wheel(list.Handle, new Point(list.Left + list.Width / 2, list.Top + list.Height / 2), -150);
                            if (rows[299].Bounds.Bottom > list.DisplayRectangle.Bottom || down.Enabled) throw new Exception("Wheeling down didn't reach the menu's last row.");
                            for (int i = 0; i < 5; i++) Mainframe.MenuLook.Step(list, true);
                            if (rows[299].Bounds.Bottom < list.DisplayRectangle.Bottom - rows[299].Height) throw new Exception("Scrolling at the last row went past it.");
                        }
                        list.Close();
                    }
                ToolStripMenuItem games = new ToolStripMenuItem("Games");
                for (int i = 0; i < 300; i++) games.DropDownItems.Add("Game " + i);
                nest.Items.Add(games);
                nest.Show(mainframe, new Point(28, 162));
                games.ShowDropDown();
                Application.DoEvents();
                ToolStripDropDown sub = games.DropDown;
                if (!Mainframe.MenuLook.HasArrows(sub) || !Mainframe.MenuLook.Scrolls(sub) || Mainframe.MenuLook.Arrow(sub, false).Height < 12 * sub.DeviceDpi / 96f) throw new Exception("A long submenu WinForms made has no arrows of hers.");
                int subFrom = first(sub);
                wheel(sub.Handle, new Point(sub.Left + sub.Width / 2, sub.Top + sub.Height / 2), -2);
                if (first(sub) <= subFrom || first(nest) != 0) throw new Exception("A wheel turn over a long submenu didn't scroll it alone.");
                checks.Add("PASS long menus: a 300-row menu fits its screen on every screen with the Mainframe high or low, shows her arrows at a clickable size, opens with its ticked row in view, scrolls on a wheel turn sent to the Mainframe or the menu without moving the page, stops at its first and last rows, and a long submenu WinForms makes gets the same; her right-click, player and Mainframe menus all have it");
            }
            finally
            {
                list.Close();
                nest.Close();
                list.Dispose();
                nest.Dispose();
                mainframe.Location = atWas;
                mainframe.WindowState = stateWas;
                if (!shownWas) mainframe.Hide();
            }
        }

        // Their plan as her brain: Claude Code and Codex run hidden with her prompt on stdin, none of their own tools, no MCP servers,
        // nothing saved and no API key from the environment; a screenshot goes along as a picture; a signed-out app, a used-up plan
        // and a missing app each get her plain line; a reply they talk over ends the app at once; and My plan sits on MAX
        // INTELLIGENCE's rung with the plan in use ticked.
        private void SmokePlanBrain(System.Collections.Generic.List<string> checks)
        {
            string claudeWas = PlanBrain.ClaudeOverride, codexWas = PlanBrain.CodexOverride, folderWas = PlanBrain.FolderOverride;
            string keyWas = Environment.GetEnvironmentVariable("ANTHROPIC_API_KEY");
            string root = Path.Combine(Path.GetTempPath(), "capri-plan-" + Guid.NewGuid().ToString("N")), runs = Path.Combine(root, "runs");
            try
            {
                if (Cloud.KindOf(Plans.ClaudeKey) != "claudecode" || Cloud.KindOf(Plans.CodexKey) != "codex") throw new Exception("Her plans aren't their own kinds of brain.");
                Cloud claudePlan = new Cloud(Plans.ClaudeKey, "haiku"), codexPlan = new Cloud(Plans.CodexKey, "default");
                if (!claudePlan.Plan || claudePlan.Name != "Claude Code" || claudePlan.Company != "Anthropic" || codexPlan.Name != "Codex" || codexPlan.Company != "OpenAI") throw new Exception("Her plans have the wrong names.");
                if (Brain.HasTools(claudePlan) || Brain.HasTools(codexPlan)) throw new Exception("A plan brain was sent native tools instead of her written ones.");
                if (!Brain.ModelFits("claudecode", "sonnet") || Brain.ModelFits("claudecode", "gpt-5") || !Brain.ModelFits("codex", "default") || Brain.DefaultCloudModel("claudecode", Plans.Models("claudecode")) != "haiku") throw new Exception("Her plan models are wrong.");
                Directory.CreateDirectory(runs);
                PlanBrain.FolderOverride = runs;
                PlanBrain.ClaudeOverride = Path.Combine(root, "missing.cmd");
                try { Brain.CloudModels(Plans.ClaudeKey); throw new Exception("A missing Claude Code was picked."); }
                catch (BrainException missing) { if (missing.Message != Plans.Missing("claudecode")) throw new Exception("A missing Claude Code said: " + missing.Message); }
                // Pretend apps: each keeps its arguments, what it was sent and the environment it got, then answers like the real one.
                string claude = Path.Combine(root, "claude.cmd"), codex = Path.Combine(root, "codex.cmd");
                Action<string, bool> claudeSays = delegate(string json, bool slow)
                {
                    File.WriteAllText(claude, "@echo off\r\necho %* > \"%~dp0claude-args.txt\"\r\necho [%ANTHROPIC_API_KEY%][%CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC%] > \"%~dp0claude-env.txt\"\r\nfindstr \"^\" > \"%~dp0claude-stdin.txt\"\r\n"
                        + (slow ? "ping -n 8 127.0.0.1 > nul\r\n" : "") + "echo {\"type\":\"system\",\"subtype\":\"init\",\"tools\":[]}\r\necho " + json + "\r\n", Encoding.ASCII);
                };
                // Its own folder is kept before shift moves %0 along.
                File.WriteAllText(codex, "@echo off\r\nsetlocal\r\nset \"here=%~dp0\"\r\nset \"out=\"\r\necho %* > \"%here%codex-args.txt\"\r\n:next\r\nif \"%~1\"==\"\" goto read\r\nif \"%~1\"==\"-o\" set \"out=%~2\"\r\nshift\r\ngoto next\r\n:read\r\nfindstr \"^\" > \"%here%codex-stdin.txt\"\r\n> \"%out%\" echo Codex says hi.\r\n", Encoding.ASCII);
                PlanBrain.ClaudeOverride = claude;
                PlanBrain.CodexOverride = codex;
                Environment.SetEnvironmentVariable("ANTHROPIC_API_KEY", "sk-ant-not-their-plan");
                claudeSays("{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"Hey choom.\"}", false);
                Brain onClaude = new Brain { Remote = claudePlan, Model = "haiku" };
                string said = onClaude.Aside("You are Capri. Keep it short.", "say hi", 90);
                string args = File.ReadAllText(Path.Combine(root, "claude-args.txt")), sent = File.ReadAllText(Path.Combine(root, "claude-stdin.txt")), env = File.ReadAllText(Path.Combine(root, "claude-env.txt")).Trim();
                if (said != "Hey choom.") throw new Exception("Claude Code's reply came out as " + said);
                foreach (string flag in new[] { "-p ", "--tools \"\"", "--strict-mcp-config", "--no-session-persistence", "--setting-sources project", "--input-format stream-json", "--output-format stream-json", "--append-system-prompt-file", "--model haiku", "--safe-mode", "--disable-slash-commands" })
                    if (args.IndexOf(flag, StringComparison.Ordinal) < 0) throw new Exception("Claude Code ran without " + flag + ": " + args);
                if (sent.IndexOf("\"type\":\"user\"", StringComparison.Ordinal) < 0 || sent.IndexOf("say hi", StringComparison.Ordinal) < 0) throw new Exception("Claude Code wasn't sent her message: " + sent);
                if (env != "[][1]") throw new Exception("Claude Code got an API key or its extra traffic: " + env);
                if (Directory.GetDirectories(runs).Length != 0) throw new Exception("A plan run left its files behind.");
                // An older Claude Code without --safe-mode answers on a second go without it.
                File.WriteAllText(claude, "@echo off\r\necho %* > \"%~dp0claude-args.txt\"\r\necho %* | findstr /c:\"--safe-mode\" > nul\r\nif not errorlevel 1 (\r\necho error: unknown option '--safe-mode' 1>&2\r\nexit /b 1\r\n)\r\nfindstr \"^\" > \"%~dp0claude-stdin.txt\"\r\necho {\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"Hey older choom.\"}\r\n", Encoding.ASCII);
                said = onClaude.Aside("You are Capri.", "say hi", 90);
                args = File.ReadAllText(Path.Combine(root, "claude-args.txt"));
                PlanBrain.Retry();
                if (said != "Hey older choom." || args.IndexOf("--safe-mode", StringComparison.Ordinal) >= 0 || args.IndexOf("--disable-slash-commands", StringComparison.Ordinal) < 0) throw new Exception("An older Claude Code didn't answer without --safe-mode: " + said + " / " + args);
                claudeSays("{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"Hey choom.\"}", false);
                // A screenshot goes along as a picture.
                if (onClaude.See(new byte[] { 1, 2, 3 }, "Look", "What's on screen?", 90) != "Hey choom.") throw new Exception("Claude Code's look didn't come back.");
                sent = File.ReadAllText(Path.Combine(root, "claude-stdin.txt"));
                if (sent.IndexOf("\"type\":\"image\"", StringComparison.Ordinal) < 0 || sent.IndexOf("AQID", StringComparison.Ordinal) < 0) throw new Exception("Her screenshot didn't reach Claude Code.");
                // Signed out, out of plan, and the check when they pick it.
                claudeSays("{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":true,\"result\":\"Failed to authenticate: OAuth session expired and could not be refreshed\"}", false);
                try { onClaude.Aside("You are Capri.", "say hi", 90); throw new Exception("A signed-out Claude Code answered."); }
                catch (BrainException signedOut) { if (!signedOut.Told || signedOut.Message != "Claude Code isn't signed in. Run claude and sign in.") throw new Exception("A signed-out Claude Code said: " + signedOut.Message); }
                try { PlanBrain.Check("claudecode"); throw new Exception("Picking a signed-out Claude Code passed its check."); }
                catch (BrainException picked) { if (picked.Message != "Claude Code isn't signed in. Run claude and sign in.") throw new Exception("Picking a signed-out Claude Code said: " + picked.Message); }
                claudeSays("{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":true,\"result\":\"You've hit your usage limit. Resets 5pm\"}", false);
                try { onClaude.Aside("You are Capri.", "say hi", 90); throw new Exception("A used-up plan answered."); }
                catch (BrainException limited) { if (limited.Message != "Your Claude plan is out of messages for now.") throw new Exception("A used-up plan said: " + limited.Message); }
                // Codex: her prompt and rules on stdin, a read-only sandbox, nothing kept, and its own model unless they picked one.
                Brain onCodex = new Brain { Remote = codexPlan, Model = "default" };
                said = onCodex.Aside("You are Capri.", "say hi", 90);
                args = File.ReadAllText(Path.Combine(root, "codex-args.txt"));
                sent = File.ReadAllText(Path.Combine(root, "codex-stdin.txt"));
                if (said != "Codex says hi.") throw new Exception("Codex's reply came out as " + said);
                foreach (string flag in new[] { "exec ", "--skip-git-repo-check", "--ephemeral", "--sandbox read-only", " -o ", "features.shell_tool=false", "features.browser_use=false", "features.plugins=false" })
                    if (args.IndexOf(flag, StringComparison.Ordinal) < 0) throw new Exception("Codex ran without " + flag + ": " + args);
                if (args.IndexOf(" -m ", StringComparison.Ordinal) >= 0 || !args.TrimEnd().EndsWith(" -", StringComparison.Ordinal)) throw new Exception("Codex was given a model or no stdin prompt: " + args);
                if (sent.IndexOf("<instructions>", StringComparison.Ordinal) < 0 || sent.IndexOf("You are Capri.", StringComparison.Ordinal) < 0 || sent.IndexOf("say hi", StringComparison.Ordinal) < 0) throw new Exception("Codex wasn't sent her rules and message: " + sent);
                onCodex.See(new byte[] { 1, 2, 3 }, "Look", "What's on screen?", 90);
                if (File.ReadAllText(Path.Combine(root, "codex-args.txt")).IndexOf(" -i ", StringComparison.Ordinal) < 0) throw new Exception("Her screenshot didn't reach Codex.");
                // Talked over: the app ends at once.
                claudeSays("{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"Too late.\"}", true);
                Stopwatch stopping = Stopwatch.StartNew();
                long stoppedIn = -1;
                try
                {
                    PlanBrain.Think("claudecode", "haiku", new System.Collections.Generic.List<ChatMessage> { new ChatMessage("user", "hi") }, delegate { return stopping.ElapsedMilliseconds > 400; });
                    throw new Exception("A talked-over plan reply finished anyway.");
                }
                catch (WebException cut)
                {
                    stoppedIn = stopping.ElapsedMilliseconds;
                    if (cut.Status != WebExceptionStatus.RequestCanceled || stoppedIn > 2500) throw new Exception("A talked-over plan reply took " + stoppedIn + " ms to stop.");
                }
                // My plan on MAX INTELLIGENCE's rung, with the plan in use ticked and named.
                foreach (int dpi in new[] { 96, 144, 192 })
                {
                    mainframe.LayoutScale(dpi, 100);
                    mainframe.ShowTiers(2, null, Plans.Plan("claudecode"), null, true);
                    mainframe.ShowCloud(claudePlan, Plans.Models("claudecode"));
                    string problem = mainframe.TiersProblem;
                    if (problem != null) throw new Exception("BRAIN with My plan doesn't fit at " + dpi + " DPI: " + problem);
                }
                mainframe.LayoutScale(96, 100);
                if (!mainframe.PlanTicked(0) || mainframe.PlanTicked(1)) throw new Exception("My plan didn't tick the plan in use.");
                if (mainframe.TextStatus != "tier 2 | Claude Code · haiku | Using your Claude plan · Claude Code on this PC | Using your Claude plan | Forget") throw new Exception("BRAIN showed " + mainframe.TextStatus);
                checks.Add("PASS your plan as her brain: Claude Code and Codex run hidden with her prompt on stdin, none of their own tools, no MCP servers, nothing saved and no API key from the environment; a screenshot goes along as a picture; signed out, out of plan and not installed each get her plain line; a reply talked over ends the app " + stoppedIn + " ms after it starts; and My plan fits MAX INTELLIGENCE's rung at 100%, 150% and 200%");
            }
            finally
            {
                PlanBrain.ClaudeOverride = claudeWas;
                PlanBrain.CodexOverride = codexWas;
                PlanBrain.FolderOverride = folderWas;
                Environment.SetEnvironmentVariable("ANTHROPIC_API_KEY", keyWas);
                mainframe.LayoutScale(96, 100);
                ShowTiers();
                if (brain.Remote != null) mainframe.ShowCloud(brain.Remote, cloudModels);
                try { Directory.Delete(root, true); }
                catch (IOException) { }
                catch (UnauthorizedAccessException) { }
            }
        }

        // Her own lines in their language: her brain's numbered translations come back in batches and are kept in lines-<language>.txt,
        // her pat lines and sys labels use them, English and her brain's own replies stay as they are, and a bad or failed reply
        // leaves its lines in English.
        private void SmokeSaid(System.Collections.Generic.List<string> checks)
        {
            string languageWas = Brain.Language, folderWas = Said.Folder, heardWas = heard, promptWas = box.Prompt;
            Func<string, string, string> askWas = Said.Ask;
            Func<bool> readyWas = Said.Ready;
            string folder = Path.Combine(Path.GetTempPath(), "capri-said-" + Guid.NewGuid().ToString("N"));
            int asks = 0;
            string rules = null;
            try
            {
                Directory.CreateDirectory(folder);
                Said.Folder = folder;
                Said.Reload();
                Said.Ready = delegate { return false; };
                // A pretend brain: each numbered line comes back with [es] in front, and a label keeps its mark, which she strips.
                Said.Ask = delegate(string system, string user)
                {
                    asks++;
                    rules = system;
                    StringBuilder back = new StringBuilder("Here you go:\n");
                    foreach (string row in user.Split('\n'))
                    {
                        Match numbered = Regex.Match(row, @"^([0-9]+)\. (\(label\) )?(.+)$");
                        if (numbered.Success) back.Append(numbered.Groups[1].Value).Append(". ").Append(numbered.Groups[2].Value).Append("[es] ").Append(numbered.Groups[3].Value).Append('\n');
                    }
                    return back.ToString();
                };
                Brain.Language = null;
                if (Said.In(PetLines[0]) != PetLines[0] || Said.Label("pets you") != "pets you") throw new Exception("English changed her own lines.");
                Brain.Language = "Spanish";
                if (Said.In(PetLines[0]) != PetLines[0]) throw new Exception("A line she hasn't translated yet wasn't left in English.");
                Said.Work();
                if (asks < 3) throw new Exception("Her lines weren't sent in batches: " + asks + " asks.");
                if (rules == null || !rules.Contains("into Spanish") || !rules.Contains("choom")) throw new Exception("Her translation rules lost the language or her slang.");
                string pet = Said.In(PetLines[0]), hello = Said.In(Brain.Greetings[0]), label = Said.Label("pets you");
                if (pet != "[es] " + PetLines[0] || hello != "[es] " + Brain.Greetings[0] || label != "[es] pets you") throw new Exception("Her lines weren't in their language: " + pet + " / " + hello + " / " + label);
                if (Said.In("Some reply her brain wrote.") != "Some reply her brain wrote." || Said.Knows("Some reply her brain wrote.")) throw new Exception("A line she doesn't know was learnt or changed.");
                if (Said.In(pet) != pet || Said.Learn(pet) != pet || Said.Knows(pet)) throw new Exception("A translated line was sent again.");
                // Her file keeps them, and a fresh start reads them back without asking her brain.
                string[] rows = File.ReadAllLines(Said.PathFor("Spanish"), Encoding.UTF8);
                if (Array.IndexOf(rows, PetLines[0] + "\t[es] " + PetLines[0]) < 0 || Array.IndexOf(rows, "pets you\t[es] pets you") < 0) throw new Exception("Her translations weren't kept in " + Said.PathFor("Spanish") + ".");
                int before = asks;
                Said.Reload();
                if (Said.In(PetLines[1]) != "[es] " + PetLines[1] || asks != before) throw new Exception("Her kept translations weren't read back.");
                // A line made in code is learnt the first time she says it, then translated.
                string told = "Copied my error log just now, choom.";
                if (Said.Learn(told) != told || !Said.Knows(told)) throw new Exception("A Tell line wasn't learnt.");
                Said.Work();
                if (Said.In(told) != "[es] " + told) throw new Exception("A learnt line wasn't translated.");
                // Her bubble: a pat says its line in Spanish under a Spanish label, and her brain's reply after "> sys: " stays as it came.
                heard = "pets you";
                box.Prompt = "> sys: ";
                Answer(++asking, PetLines[2], TalkState.Talking, true);
                UpdateTalk(clock.Elapsed.TotalSeconds);
                if (reply != "[es] " + PetLines[2] || box.Heard != "[es] pets you") throw new Exception("Her pat came out as " + reply + " under " + box.Heard + ".");
                Answer(++asking, "Hola, choom. Tu cerebro nuevo funciona.", TalkState.Talking, true, true);
                if (reply != "Hola, choom. Tu cerebro nuevo funciona." || Said.Knows(reply)) throw new Exception("Her brain's reply was changed or sent to translate: " + reply);
                // A bad reply leaves its lines in English: an empty line, one far too long, a number out of range and no number at all.
                Said.Ask = delegate(string system, string user) { asks++; return "1. \n2. " + new string('x', 400) + "\n99. Nope\nNo numbers here"; };
                Brain.Language = "French";
                Said.Work();
                if (Said.In(PetLines[0]) != PetLines[0] || Said.In(PetLines[1]) != PetLines[1]) throw new Exception("A bad reply changed her lines: " + Said.In(PetLines[0]));
                // A brain that can't answer stops the pass, and her lines stay English.
                Said.Ask = delegate { throw new WebException("Offline."); };
                Brain.Language = "German";
                Said.Work();
                if (Said.In(PetLines[0]) != PetLines[0]) throw new Exception("A failed reply changed her line.");
                checks.Add("PASS her own lines: her brain translates her pat lines, hellos and sys labels in batches, she keeps them in lines-<language>.txt and reads them back, a pat comes out in Spanish under a Spanish label, lines from code are learnt as she says them, English and her brain's replies stay as they are, and bad or failed replies leave English");
            }
            finally
            {
                Brain.Language = languageWas;
                Said.Folder = folderWas;
                Said.Ask = askWas;
                Said.Ready = readyWas;
                Said.Reload();
                heard = heardWas;
                box.Prompt = promptWas;
                asking++;
                CloseTalk();
                try { Directory.Delete(folder, true); }
                catch (IOException) { }
                catch (UnauthorizedAccessException) { }
            }
        }

        private void SmokeLanguages(System.Collections.Generic.List<string> checks)
        {
            int sizeWas = MainframeSize;
            Point atWas = mainframe.Location;
            bool shownWas = mainframe.Visible, settingsWas = mainframe.SettingsShown;
            FormWindowState stateWas = mainframe.WindowState;
            string languageWas = Brain.Language, savedWas = preferences.Language;
            ContextMenuStrip menu = null;
            try
            {
                mainframe.WindowState = FormWindowState.Normal;
                mainframe.Show();
                mainframe.ShowSettings(true);
                mainframe.SizeMainframe(100);
                foreach (int percent in new[] { 100, 150, 200 })
                {
                    mainframe.LayoutScale(percent * 96 / 100, 100);
                    foreach (Screen screen in Screen.AllScreens)
                    {
                        Rectangle area = screen.WorkingArea;
                        int right = Math.Max(area.Left, area.Right - mainframe.Width), bottom = Math.Max(area.Top, area.Bottom - mainframe.Height);
                        foreach (Point at in new[] { area.Location, new Point(right, area.Top), new Point(area.Left, bottom), new Point(right, bottom), new Point((area.Left + right) / 2, (area.Top + bottom) / 2), new Point(area.Right - mainframe.Width / 2, area.Bottom - mainframe.Height / 2), new Point(area.Left - mainframe.Width / 2, area.Top - mainframe.Height / 2) })
                        {
                            mainframe.Location = at;
                            Rectangle work = Screen.FromControl(mainframe).WorkingArea;
                            foreach (string language in new[] { "English", "Persian", "Japanese" })
                            {
                                Brain.Language = language == "English" ? null : language;
                                mainframe.Sync();
                                menu = mainframe.ShowLanguages();
                                if ((string)menu.Items[0].Tag != "English" || menu.Items[1].Available != (language != "English") || (string)menu.Items[1].Tag != language) throw new Exception("The language shortcuts are wrong.");
                                bool[] seen = new bool[Brain.Languages.GetLength(0)];
                                try { SmokeLanguageBounds(menu, work, seen); }
                                catch (Exception error) { throw new Exception("Language menu at " + percent + "%, Mainframe " + at + ": " + error.Message, error); }
                                finally { menu.Close(); }
                                for (int row = 0; row < seen.Length; row++) if (!seen[row]) throw new Exception("The language menu is missing " + Brain.Languages[row, 1] + " at " + percent + "%.");
                            }
                        }
                    }
                }
                Brain.Language = null;
                mainframe.Sync();
                menu = mainframe.ShowLanguages();
                Brain.Language = "Persian";
                mainframe.Sync();
                if (!menu.Visible || !menu.Items[1].Available || !mainframe.LanguageIs("Persian")) throw new Exception("Sync lost the open language menu.");
                SmokeLanguageBounds(menu, Screen.FromControl(mainframe).WorkingArea, new bool[Brain.Languages.GetLength(0)]);
                Brain.Language = null;
                mainframe.Sync();
                if (menu.Items[1].Available || !mainframe.LanguageIs("English")) throw new Exception("Sync left the current-language shortcut open for English.");
                SmokeLanguageBounds(menu, Screen.FromControl(mainframe).WorkingArea, new bool[Brain.Languages.GetLength(0)]);
                mainframe.LayoutScale(96, 100);
                if (menu.Visible) throw new Exception("Scaling left the language menu open with old fonts.");
                menu.Close();
                for (int row = 0; row < Brain.Languages.GetLength(0); row++)
                {
                    string language = Brain.Languages[row, 1];
                    Brain.Language = language == "English" ? null : language;
                    mainframe.Sync();
                    if (!mainframe.LanguageIs(language) || (string)menu.Items[1].Tag != language || menu.Items[1].Available != (language != "English")) throw new Exception("Sync lost the current language: " + language);
                    foreach (ToolStripMenuItem item in Mainframe.LanguageItems(menu.Items))
                        if (item.Checked != ((string)item.Tag == language)) throw new Exception("Sync left the wrong language ticked: " + item.Text);
                }
                ToolStripMenuItem persian = null;
                foreach (ToolStripMenuItem item in Mainframe.LanguageItems(menu.Items)) if ((string)item.Tag == "Persian" && item.Owner != menu) persian = item;
                if (persian == null) throw new Exception("Persian has no submenu item.");
                persian.PerformClick();
                if (Language != "Persian" || LoadPreferences().Language != "Persian" || !mainframe.LanguageIs("Persian") || (string)menu.Items[1].Tag != "Persian") throw new Exception("The Persian menu item did not select, save and tick Persian.");
                menu = mainframe.ShowLanguages();
                ((ToolStripMenuItem)menu.Items[0]).PerformClick();
                menu.Close();
                if (Language != "English" || LoadPreferences().Language != "English" || !mainframe.LanguageIs("English") || menu.Items[1].Available) throw new Exception("The English shortcut did not select, save and tick English.");
                checks.Add("PASS language menu: every language has its native and English name, every menu and item fits Mainframe's screen at 100%, 150% and 200% from each corner, the centre and partly off screen, English and the current language stay at the top, Sync updates every tick and the open shortcut, scaling closes old menus, and Persian and English can be picked and saved");
            }
            finally
            {
                if (menu != null) menu.Close();
                Brain.Language = languageWas;
                preferences.Language = savedWas;
                SavePreferences();
                PointEars();
                mainframe.LayoutScale(0, 0);
                mainframe.SizeMainframe(sizeWas);
                mainframe.Sync();
                mainframe.ShowSettings(settingsWas);
                mainframe.Location = atWas;
                mainframe.WindowState = stateWas;
                if (!shownWas) mainframe.Hide();
            }
        }

        private static void SmokeOpening(System.Collections.Generic.List<string> checks)
        {
            Func<System.Collections.Generic.List<InstalledApp>> openingCatalog = Hands.Catalog;
            Func<System.Collections.Generic.List<OpenWindow>> openingWindows = Hands.Windows;
            Func<OpenWindow, string, bool> openingSteer = Hands.Steer;
            Func<IntPtr> openingForeground = Hands.Foreground;
            Func<string, string> openingResult = Hands.Opened;
            Func<string, string> openingBrowser = Hands.BrowserPath;
            Action<string> openingRun = Hands.Run;
            Action<string, string> openingBrowse = Hands.Browse;
            Func<string, bool> openingExists = Hands.Exists;
            Func<string, System.Collections.Generic.KeyValuePair<string, ToolArguments>> openingPlan = Hands.Plan;
            try
            {
                System.Collections.Generic.List<OpenWindow> openingShown = new System.Collections.Generic.List<OpenWindow> { new OpenWindow(new IntPtr(501), "Calculator help - Opera", "opera") };
                System.Collections.Generic.List<string> openingLaunched = new System.Collections.Generic.List<string>();
                IntPtr openingFront = new IntPtr(501);
                int openingFocused = 0, openingReads = 0;
                Hands.Plan = delegate { return new System.Collections.Generic.KeyValuePair<string, ToolArguments>(); };
                Hands.Exists = delegate { return false; };
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Calculator", "calculator-package!App"), new InstalledApp("Paint", "paint-package!App"), new InstalledApp("Slow Game", "steam://rungameid/123") }; };
                Hands.Forget();
                Hands.Windows = delegate { openingReads++; return openingShown; };
                Hands.Foreground = delegate { return openingFront; };
                Hands.Steer = delegate(OpenWindow openingTarget, string openingAction) { if (openingAction != "switch_to") throw new Exception("Opening used the wrong window action."); openingFocused++; openingFront = openingTarget.Handle; return true; };
                Hands.Opened = delegate(string openingName) { return Hands.BringOpened(openingName, 30); };
                Hands.Run = delegate(string openingId)
                {
                    openingLaunched.Add(openingId);
                    if (openingId == "calculator-package!App" && openingShown.Count == 1) openingShown.Add(new OpenWindow(new IntPtr(502), "Calculator", "ApplicationFrameHost"));
                    if (openingId == "paint-package!App") openingShown.Add(new OpenWindow(new IntPtr(503), "Untitled - Paint", "ApplicationFrameHost"));
                };
                if (Hands.Do("open_app", new ToolArguments { Name = "Calculator" }) != "Opened Calculator." || openingFront != new IntPtr(502)) throw new Exception("The packaged app stayed behind the browser's matching page title.");
                openingFront = new IntPtr(501);
                if (Hands.Do("open_app", new ToolArguments { Name = "Calculator" }) != "Opened Calculator." || openingFront != new IntPtr(502)) throw new Exception("The already open app stayed behind.");
                if (Hands.Do("open_app", new ToolArguments { Name = "Paint" }) != "Opened Paint." || openingFront != new IntPtr(503)) throw new Exception("Paint's host process hid its window.");
                openingFront = new IntPtr(501);
                Hands.Steer = delegate { return false; };
                string openingBehind = Hands.Do("open_app", new ToolArguments { Name = "Calculator" });
                if (openingBehind != "Opened Calculator, but it's behind Opera." || Hands.Pulled(openingBehind) != openingBehind || !Computer.Failed(openingBehind)) throw new Exception("A failed foreground change was reported as success.");
                string openingSlow = Hands.Do("open_app", new ToolArguments { Name = "Slow Game" });
                int openingFinishedReads = openingReads, openingFinishedFocus = openingFocused;
                openingShown.Add(new OpenWindow(new IntPtr(504), "Slow Game", "slowgame"));
                Thread.Sleep(40);
                if (openingSlow != "Opened Slow Game, but its window hasn't appeared yet." || openingReads != openingFinishedReads || openingFocused != openingFinishedFocus) throw new Exception("A slow launch kept watching or took focus later.");
                checks.Add("PASS opening apps: packaged windows match their titles, an existing window comes forward, a denied switch names the app still in front, and a slow launch stops looking before its window arrives");
                checks.Add("LIMIT opening apps: foreground attachment, minimized windows and real launch timing need an interactive Windows desktop; these windows and launches are stand-ins");

                Hands.Steer = delegate(OpenWindow browserTarget, string browserAction) { openingFront = browserTarget.Handle; return browserAction == "switch_to"; };
                foreach (string browserChoice in new[] { "Chrome", "Edge", "Firefox", "Opera", "Opera GX", "Brave", "Vivaldi" })
                {
                    string browserExe = @"C:\Browsers\" + browserChoice + "\\" + Hands.BrowserProgram(browserChoice) + ".exe";
                    string browserSent = null, browserAddress = null;
                    openingShown.Clear();
                    openingShown.Add(new OpenWindow(new IntPtr(510), "Old tab - " + browserChoice, Hands.BrowserProgram(browserChoice)));
                    Hands.BrowserPath = delegate(string browserWanted) { return browserWanted == browserChoice ? browserExe : null; };
                    Hands.Browse = delegate(string browserFile, string browserUrl) { browserSent = browserFile; browserAddress = browserUrl; };
                    openingFront = new IntPtr(501);
                    string browserResult = Hands.Do("open_website", new ToolArguments { Site = "youtube", Search = "cats", Browser = browserChoice });
                    if (browserSent != browserExe || browserAddress != Hands.Address("youtube", "cats") || openingFront != new IntPtr(510) || browserResult != "Searched youtube.com for cats in " + browserChoice + ".") throw new Exception("The chosen browser was lost: " + browserChoice);
                    ProcessStartInfo browserStart = Hands.BrowserLaunch(browserExe, browserAddress);
                    if (browserStart.FileName != browserExe || !browserStart.UseShellExecute || browserStart.Arguments != (browserChoice == "Firefox" ? "-new-tab " : "") + "\"" + browserAddress + "\"") throw new Exception("The browser didn't receive a link for a new tab.");
                    foreach (string browserAsk in new[] { "open youtube in " + browserChoice, "search for cats on youtube in " + browserChoice, "in " + browserChoice + " open reddit" })
                    {
                        string browserTool;
                        ToolArguments browserArgs;
                        bool browserSearch = browserAsk.StartsWith("search", StringComparison.Ordinal);
                        string browserSite = browserAsk.StartsWith("in ", StringComparison.Ordinal) ? "reddit" : "youtube";
                        if (!Hands.Direct(browserAsk, out browserTool, out browserArgs) || browserTool != "open_website" || browserArgs.Browser != browserChoice.ToLowerInvariant() || browserArgs.Site != browserSite || browserArgs.Search != (browserSearch ? "cats" : null)) throw new Exception("Direct lost a browser: " + browserAsk);
                        if (!Hands.Heard("Hey Capri, " + browserAsk, out browserTool, out browserArgs) || browserTool != "open_website" || browserArgs.Browser != browserChoice.ToLowerInvariant() || browserArgs.Site != browserSite || browserArgs.Search != (browserSearch ? "cats" : null)) throw new Exception("Heard lost a browser: " + browserAsk);
                    }
                    if (!Hands.Valid("open_website", new ToolArguments { Site = "youtube", Browser = browserChoice })) throw new Exception("A supported browser was invalid.");
                }
                foreach (string browserTerm in new[] { "chrome hearts", "edge of tomorrow", "firefox", "opera gx theme", "brave", "vivaldi", "cats in chrome hearts", "\"cats in chrome\"" })
                {
                    string termTool;
                    ToolArguments termArgs;
                    if (!Hands.Direct("search youtube for " + browserTerm, out termTool, out termArgs) || termTool != "open_website" || termArgs.Browser != null || termArgs.Search != browserTerm
                        || !Hands.Heard("search youtube for " + browserTerm, out termTool, out termArgs) || termArgs.Browser != null || termArgs.Search != browserTerm) throw new Exception("A search term became a browser: " + browserTerm);
                }
                openingShown.Clear();
                OpenWindow namedChrome = new OpenWindow(new IntPtr(513), "Page - Google Chrome", "chrome");
                openingShown.Add(namedChrome);
                if (Hands.OpenedWindow(openingShown, "Google Chrome") != namedChrome) throw new Exception("The full browser name in All apps didn't match its window.");
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> browserRescue = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> { new System.Collections.Generic.KeyValuePair<string, ToolArguments>("open_website", new ToolArguments { Site = "Calculator", Browser = "chrome" }) };
                Hands.Rescue("open Calculator in chrome", browserRescue);
                if (browserRescue.Count != 1 || browserRescue[0].Key != "open_website" || browserRescue[0].Value.Browser != "chrome") throw new Exception("An installed app overrode an explicit browser.");
                Hands.BrowserPath = delegate { return null; };
                int fallbackBefore = openingLaunched.Count;
                string browserFallback = Hands.Do("open_website", new ToolArguments { Site = "reddit", Browser = "Brave" });
                if (browserFallback != "Opened reddit.com in your default browser because Brave isn't installed." || openingLaunched.Count != fallbackBefore + 1 || openingLaunched[fallbackBefore] != Hands.Address("reddit", null) || Hands.Pulled(browserFallback) != browserFallback) throw new Exception("A missing browser didn't fall back and say so.");
                if (Hands.Valid("open_website", new ToolArguments { Site = "youtube", Browser = "unknown" }) || !Hands.Valid("open_website", new ToolArguments { Site = "youtube" }) || Hands.Read("{\"site\":\"youtube\",\"browser\":\"edge\"}").Browser != "edge") throw new Exception("The optional browser didn't survive validation and JSON.");
                string writtenBrowserTool;
                ToolArguments writtenBrowserArgs;
                if (!Hands.Typed("open_website{site:youtube,browser:firefox}", out writtenBrowserTool, out writtenBrowserArgs, true) || writtenBrowserArgs.Browser != "firefox") throw new Exception("The written browser argument was lost.");
                if (Hands.BrowserCommand("\"C:\\Program Files\\Opera GX\\opera.exe\" --flag") != @"C:\Program Files\Opera GX\opera.exe" || Hands.BrowserCommand(@"C:\Browsers\firefox.exe -url") != @"C:\Browsers\firefox.exe" || Hands.BrowserCommand("not a browser") != null) throw new Exception("A registered browser command wasn't read correctly.");
                if (Hands.Tools.IndexOf("\"browser\"", StringComparison.Ordinal) < 0 || Computer.Tools.IndexOf("\"browser\"", StringComparison.Ordinal) < 0 || Computer.Toolset.IndexOf("\"browser\"", StringComparison.Ordinal) < 0 || CursorJob("open_website", new ToolArguments { Site = "youtube", Search = "cats", Browser = "edge" }).IndexOf("browser \"edge\"", StringComparison.Ordinal) < 0) throw new Exception("A chat or job route omitted browser choice.");
                checks.Add("PASS browser choice: all seven browsers keep their exe, link and foreground target, Direct and Heard keep named browsers before and after requests, search terms stay intact, missing browsers fall back explicitly, and chat and job schemas and cursor jobs keep the argument");
                checks.Add("LIMIT browser choice: real Windows registrations and each browser's tab handoff need an installed browser; these launch checks use stand-ins");
            }
            finally
            {
                Hands.Catalog = openingCatalog; Hands.Windows = openingWindows; Hands.Steer = openingSteer; Hands.Foreground = openingForeground;
                Hands.Opened = openingResult; Hands.BrowserPath = openingBrowser; Hands.Run = openingRun; Hands.Browse = openingBrowse; Hands.Exists = openingExists; Hands.Plan = openingPlan; Hands.Forget();
            }
        }

        private void SmokeVault(System.Collections.Generic.List<string> checks)
        {
            string folder = Path.Combine(Path.GetTempPath(), "capri-vault-" + Guid.NewGuid().ToString("N"));
            string oldPath = Brain.MemoryPath, oldOwn = ownNotes, oldFolder = Brain.VaultFolder, oldVault = preferences.Vault;
            try
            {
                string me = Path.Combine(folder, "own", "me.md"), inVault = Path.Combine(folder, "vault"), note = Path.Combine(inVault, VaultNote);
                Directory.CreateDirectory(Path.GetDirectoryName(me));
                Directory.CreateDirectory(inVault);
                File.WriteAllText(me, Brain.NotesHead + "- They like cats\n");
                ownNotes = Brain.MemoryPath = me;
                Brain.VaultFolder = null;
                SetVault(note);
                if (Brain.MemoryPath != note || Brain.VaultFolder != inVault || !VaultHere || preferences.Vault != note || !File.ReadAllText(note).Contains("- They like cats")) throw new Exception("Her notes didn't move into the vault.");
                File.AppendAllText(note, "- They play chess\n");
                SetVault("");
                if (Brain.MemoryPath != me || VaultHere || preferences.Vault != null || !File.ReadAllText(me).Contains("- They play chess")) throw new Exception("What she learned in the vault didn't come back with her.");
                File.WriteAllText(note, "# Theirs\n- They like cats\n");
                SetVault(note);
                string merged = File.ReadAllText(note);
                if (!merged.StartsWith("# Theirs", StringComparison.Ordinal) || merged.IndexOf("- They like cats", StringComparison.Ordinal) != merged.LastIndexOf("- They like cats", StringComparison.Ordinal) || !merged.Contains("- They play chess")) throw new Exception("A note already in the vault lost its lines or got doubled ones.");
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, string>> vaults = VaultsIn("{\"vaults\":{\"a1\":{\"path\":" + Voice.Quote(inVault) + ",\"ts\":1},\"b2\":{\"path\":" + Voice.Quote(Path.Combine(folder, "gone")) + ",\"ts\":2}}}");
                if (vaults.Count != 1 || vaults[0].Key != "vault" || vaults[0].Value != inVault || VaultsIn("not json").Count != 0 || NotesIn("") != null || NotesIn(note) != note || NotesIn(inVault) != Path.Combine(inVault, "me.md")) throw new Exception("Her Obsidian vault list read wrong.");
                checks.Add("PASS Memory vault: her notes move into a vault and come back with what she learned there, a note already in it keeps its lines, and only real vaults are listed");
            }
            finally
            {
                Brain.MemoryPath = oldPath;
                ownNotes = oldOwn;
                Brain.VaultFolder = oldFolder;
                preferences.Vault = oldVault;
                try { Directory.Delete(folder, true); } catch (IOException) { } catch (UnauthorizedAccessException) { }
            }
        }

        private static void SmokeReportedLogic(System.Collections.Generic.List<string> checks)
        {
            Func<System.Collections.Generic.List<OpenWindow>> windowsBefore = Hands.Windows;
            Func<OpenWindow, string, bool> steerBefore = Hands.Steer;
            System.Collections.Generic.List<OpenWindow> open = new System.Collections.Generic.List<OpenWindow>();
            System.Collections.Generic.List<string> closed = new System.Collections.Generic.List<string>();
            try
            {
                Hands.Windows = delegate { return open; };
                Hands.Steer = delegate(OpenWindow target, string action) { closed.Add(target.Program + ":" + action); return true; };
                string[] systemNames = { "taskhostw", "Taskmgr", "svchost", "explorer", "csrss", "winlogon", "wininit", "dwm", "smss", "services", "lsass", "sihost", "ShellExperienceHost" };
                foreach (string systemName in systemNames)
                {
                    OpenWindow systemWindow = new OpenWindow(new IntPtr(open.Count + 1), "task chrome discord", systemName);
                    open.Add(systemWindow);
                    foreach (string guess in new[] { "task", "host", "chrome", "discord", "win", "explore" })
                        if (Hands.CloseScore(systemWindow, guess, "end task " + guess) != 0) throw new Exception("A loose name reached " + systemName + ".");
                    if (Hands.CloseScore(systemWindow, systemName.ToLowerInvariant(), "end task") != 0) throw new Exception("A guessed exact name reached " + systemName + ".");
                    string exact = Hands.Do("app_window", new ToolArguments { Name = systemName + ".exe", Action = "close", Asked = "end task " + systemName + ".exe" });
                    if (!exact.StartsWith("Closed ", StringComparison.Ordinal) || closed[closed.Count - 1] != systemName + ":close") throw new Exception("An exact request did not reach " + systemName + ".");
                }
                closed.Clear();
                open.Add(new OpenWindow(new IntPtr(100), "New tab", "chrome"));
                open.Add(new OpenWindow(new IntPtr(101), "Friends", "Discord"));
                foreach (string command in new[] { "end task", "end the task", "end task chrome", "end task for discord" })
                {
                    string tool;
                    ToolArguments arguments;
                    if (!Hands.Direct(command, out tool, out arguments) || tool != "app_window" || arguments.Action != "close" || arguments.Asked != command) throw new Exception("The end-task request was read wrong: " + command);
                    string answer = Hands.Do(tool, arguments);
                    if ((command == "end task" || command == "end the task") && (answer != "Which app, choom?" || closed.Count != 0)) throw new Exception("An unnamed task closed an app.");
                }
                if (string.Join(",", closed.ToArray()) != "chrome:close,Discord:close") throw new Exception("A named end-task request closed the wrong app.");
                foreach (string stop in new[] { "end task", "end the task" })
                {
                    string stopTool;
                    ToolArguments stopArgs;
                    if (Asides.Plain(stop, out stopTool, out stopArgs) != AsideKind.Stop) throw new Exception("End task did not stop her current job.");
                }
                foreach (string alias in new[] { "Task Manager", "File Explorer", "Windows Explorer" })
                    if (!Hands.Do("app_window", new ToolArguments { Name = alias, Action = "close", Asked = "close " + alias }).StartsWith("Closed ", StringComparison.Ordinal)) throw new Exception("An exact Windows app name was lost.");
                checks.Add("PASS end task: an unnamed task ends her current job or asks which app; named Chrome and Discord close, loose program and title matches never reach Windows components, guessed exact names stay unmatched, and exact process names, .exe names, Task Manager and File Explorer still work");
            }
            finally { Hands.Windows = windowsBefore; Hands.Steer = steerBefore; }

            int[] held = new int[256];
            held[0x11] = 1;
            held[0x57] = 1;
            held[0x27] = 3;
            System.Collections.Generic.List<string> released = new System.Collections.Generic.List<string>();
            InputRelease.Release(held, 0x2A, delegate(short code, bool up, bool extended) { released.Add(code + ":" + up + ":" + extended); }, delegate(int flags, int data) { released.Add("mouse:" + flags + ":" + data); });
            if (string.Join(",", released.ToArray()) != "17:True:False,39:True:True,87:True:False,mouse:84:0") throw new Exception("Input recovery released the wrong keys or buttons.");
            released.Clear();
            InputRelease.Release(new int[256], 0, delegate(short code, bool up, bool extended) { released.Add("key"); }, delegate(int flags, int data) { released.Add("mouse"); });
            if (released.Count != 0) throw new Exception("Input recovery touched input she did not hold.");
            checks.Add("PASS input recovery releases only her recorded keys and mouse buttons, keeps extended-key flags, and leaves an empty ledger alone");
            checks.Add("LIMIT forced termination, including killing the whole process tree, and driver crashes need an isolated desktop; no real keys, buttons or processes are stopped by this check");

            if (!new Preferences().OnTop || !Preferences.Fresh().OnTop) throw new Exception("Always on top did not start on.");
            foreach (string saved in new[] { "{}", "{\"OnTop\":false}", "{\"OnTop\":true}" })
            {
                DataContractJsonSerializer settings = new DataContractJsonSerializer(typeof(Preferences));
                using (MemoryStream input = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(saved)))
                using (MemoryStream output = new MemoryStream())
                {
                    Preferences loaded = (Preferences)settings.ReadObject(input);
                    bool expected = !saved.Contains("false");
                    if (loaded.OnTop != expected) throw new Exception("Older settings changed Always on top.");
                    settings.WriteObject(output, loaded);
                    output.Position = 0;
                    if (((Preferences)settings.ReadObject(output)).OnTop != expected) throw new Exception("Saving changed Always on top.");
                }
            }
            checks.Add("PASS Always on top starts on, missing older settings stay on, and an explicit off or on survives a save and reload");

            Ledge narrow = new Ledge { Left = 0, Right = 220 }, wide = new Ledge { Left = 300, Right = 1320 };
            System.Collections.Generic.List<Ledge> ledges = new System.Collections.Generic.List<Ledge> { narrow, wide };
            int narrowPicks = 0;
            for (int sample = 0; sample < 1000; sample++) if (WanderSpot(ledges, 240, (sample + 0.5) / 1000) == narrow) narrowPicks++;
            if (narrowPicks != 100) throw new Exception("Short ledges still get the same chance as long ledges.");
            foreach (Rectangle monitor in new[] { new Rectangle(0, 0, 1920, 1080), new Rectangle(-2560, -1440, 2560, 1440), new Rectangle(1920, 0, 1280, 720), new Rectangle(400, 250, 800, 600) })
            {
                System.Collections.Generic.HashSet<Point> points = new System.Collections.Generic.HashSet<Point>();
                for (int across = 0; across <= 9; across++)
                    for (int down = 0; down <= 9; down++)
                    {
                        Point point = WanderPoint(monitor, 240, across / 10.0, down / 10.0);
                        bool beside = point.X < monitor.Left + monitor.Width / 3 || point.X >= monitor.Right - monitor.Width / 3;
                        if (!monitor.Contains(point) || !beside || point.Y < monitor.Top + monitor.Height / 3 || point.Y > monitor.Bottom - monitor.Height / 4) throw new Exception("Teleporting in a game landed on the crosshair, the health bars or off the screen: " + point);
                        points.Add(point);
                    }
                if (points.Count != 100) throw new Exception("Teleporting in a game collapsed onto a few spots.");
            }
            if (CommentHold(400, 1) <= CommentHold(100, 1) || CommentHold(1000, 1) <= CommentHold(400, 1) || CommentHold(100, 0) * 4 != CommentHold(100, 2)) throw new Exception("Comment reading time did not follow its length and setting.");
            checks.Add("PASS teleports weight ledges by usable width, and with something full screen she lands beside it, clear of the crosshair and the health bars, on primary, negative and secondary monitors");
            checks.Add("PASS comment reading time grows with the whole line and follows Quick, Normal and Long without a ceiling for long comments");
        }

        private void SmokeComments(System.Collections.Generic.List<string> checks)
        {
            bool silentBefore = preferences.Silent;
            int timeBefore = preferences.BubbleTime;
            try
            {
                CloseTalk();
                preferences.Silent = true;
                preferences.BubbleTime = 1;
                string longComment = string.Join(" ", new string[600]).Replace(" ", "That was close. ");
                Remark("watching", longComment, true);
                double now = clock.Elapsed.TotalSeconds;
                replyStart = now - longComment.Length / pace - 1;
                UpdateTalk(now);
                if (!box.Scrollable) throw new Exception("The comment check did not exercise a scrolling bubble.");
                double due = replyDone + CommentHold(longComment.Length, BubbleTime);
                UpdateTalk(due - 0.1);
                if (box.Leaving >= 0) throw new Exception("A comment left before its reading time.");
                UpdateTalk(due + 0.1);
                if (box.Leaving < 0) throw new Exception("A scrolling comment stayed forever.");
                UpdateTalk(due + 0.4);
                if (talkState != TalkState.Off || box.Visible) throw new Exception("The comment did not leave without a click.");
                Remark("watching", "A short comment.", true);
                replyStart = now - 10;
                UpdateTalk(now);
                double shortDue = replyDone + CommentHold(reply.Length, BubbleTime);
                voiceUntil = shortDue + 5;
                UpdateTalk(shortDue + 1);
                if (box.Leaving >= 0) throw new Exception("A comment left during her own voice.");
                UpdateTalk(shortDue + 6);
                if (box.Leaving < 0) throw new Exception("A comment stayed after her voice and reading time.");
                CloseTalk();
                Begin(++asking, longComment, TalkState.Talking, null);
                replyStart = now - longComment.Length / pace - 1;
                UpdateTalk(now);
                UpdateTalk(now + 300);
                if (!box.Scrollable || box.Leaving >= 0) throw new Exception("An ordinary scrolling answer lost its reading controls.");
                checks.Add("PASS comments, including scrolling screen and game remarks, leave after reading and speech without a click; ordinary scrolling answers keep their reading controls");
            }
            finally { preferences.Silent = silentBefore; preferences.BubbleTime = timeBefore; CloseTalk(); }
        }

        private void SmokeVoiceWaits(System.Collections.Generic.List<string> checks)
        {
            bool waitsSilent = preferences.Silent, waitsDue = voiceCheckDue;
            try
            {
                CloseTalk();
                preferences.Silent = true;
                voiceCheckDue = true;
                talkState = TalkState.Thinking;
                int waitsTicket = asking;
                CheckVoiceReady();
                if (!voiceCheckDue || asking != waitsTicket) throw new Exception("A voice check cut in on something they asked.");
                CloseTalk();
                CheckVoiceReady();
                if (voiceCheckDue) throw new Exception("A voice check never ran once she was free.");
                checks.Add("PASS the voice check after her voice lands waits for what she's answering, so it can't cancel what they asked");
            }
            finally { preferences.Silent = waitsSilent; voiceCheckDue = waitsDue; CloseTalk(); }
            // Thrown with her server voice slow to answer, her yelp used to sit as an empty bubble for up to 8 s (5 Nov throw demo).
            Func<string, byte[]> yelpSpeakWas = Speak, yelpFreeWas = FreeSpeak;
            bool yelpSilentWas = preferences.Silent, yelpQuietWas = preferences.Quiet, yelpHdWas = preferences.HdVoice, yelpServedWas = preferences.ServerVoice, yelpHiddenWas = hidden, yelpDockedWas = docked;
            int yelpWaitWas = VoiceWait, yelpFreeWaitWas = FreeWait;
            try
            {
                CloseTalk();
                hidden = docked = false;
                preferences.Silent = preferences.Quiet = preferences.HdVoice = preferences.ServerVoice = false;
                VoiceWait = 3000;
                FreeWait = 8000;
                short[] yelpSamples = new short[8000];
                for (int at = 0; at < yelpSamples.Length; at++) yelpSamples[at] = (short)(5000 * Math.Sin(at * 0.05));
                byte[] yelpWav = Voice.Wave(yelpSamples, 16000);
                Speak = FreeSpeak = delegate { Thread.Sleep(1800); return yelpWav; };
                const string yelpLine = "Hey, put me down!";
                Stopwatch yelpTook = Stopwatch.StartNew();
                Yelp("throws you", yelpLine, true);
                while (reply != yelpLine && yelpTook.ElapsedMilliseconds < 4000) { Application.DoEvents(); Thread.Sleep(5); }
                long yelpShown = yelpTook.ElapsedMilliseconds;
                while (voiceUntil == 0 && yelpTook.ElapsedMilliseconds < 6000) { Application.DoEvents(); Thread.Sleep(5); }
                if (reply != yelpLine || yelpShown > YelpWait + 700 || voiceUntil == 0) throw new Exception("A voiced yelp with a slow voice sat empty or lost its voice: words after " + yelpShown + " ms, voiced " + (voiceUntil != 0) + ", reply " + reply);
                checks.Add("PASS a voiced yelp shows its words within a second while a slow voice loads, and her voice follows once it's ready");
            }
            finally
            {
                Speak = yelpSpeakWas; FreeSpeak = yelpFreeWas;
                preferences.Silent = yelpSilentWas; preferences.Quiet = yelpQuietWas; preferences.HdVoice = yelpHdWas; preferences.ServerVoice = yelpServedWas;
                hidden = yelpHiddenWas; docked = yelpDockedWas;
                VoiceWait = yelpWaitWas; FreeWait = yelpFreeWaitWas;
                CloseTalk();
            }
        }

        private static void WaitVoice(Func<bool> done, string problem)
        {
            Stopwatch waited = Stopwatch.StartNew();
            while (!done() && waited.ElapsedMilliseconds < 4500) { Application.DoEvents(); Thread.Sleep(5); }
            if (!done()) throw new Exception(problem);
        }

        private void SmokeLineChanges(System.Collections.Generic.List<string> checks)
        {
            Func<string, byte[]> speakWas = Speak, freeWas = FreeSpeak;
            bool signalsWas = signals.Enabled, quietWas = preferences.Quiet, silentWas = preferences.Silent, hdWas = preferences.HdVoice, servedWas = preferences.ServerVoice;
            bool chattingWas = chatting, localWas = local, hiddenWas = hidden, shushedWas = shushed, dockedWas = docked;
            Job jobWas = job;
            string workingWas = working, modelWas = voice.Model, savedModelWas = preferences.VoiceModel;
            int pitchWas = VoiceFx.Pitch, speedWas = VoiceFx.Speed, robotWas = VoiceFx.Robot, glitchWas = VoiceFx.Glitch;
            int savedPitchWas = preferences.VoicePitch, savedSpeedWas = preferences.VoiceSpeed, savedRobotWas = preferences.VoiceRobot, savedGlitchWas = preferences.VoiceGlitch;
            int waitWas = VoiceWait, freeWaitWas = FreeWait, typingWas = preferences.Typing;
            VoiceFx.Layering layersWas = VoiceFx.Layers, savedLayers = LayersOf(preferences);
            CloneWindow clonesWas = cloneWindow, clonesHere = null;
            bool talkingWas = cloneTalking, hideFullWas = preferences.HideFullScreen, fullHiddenWas = fullScreenHidden, throughWas = fullThrough;
            double cloneAtWas = cloneTalkAt;
            int micWas = micTalked;
            int offWas = voiceOffTurn;
            bool keepOffWas = keepVoiceOff, changingWas = changingVoice;
            string cloudWas = preferences.CloudVoice;
            string[] serverWas = { server.Url, server.Api, server.Model, server.Speaker, server.Key };
            string[] savedServer = { preferences.ServerUrl, preferences.ServerApi, preferences.ServerModel, preferences.ServerSpeaker, preferences.ServerKey };
            string[] savedAside = { preferences.AsideUrl, preferences.AsideApi, preferences.AsideModel, preferences.AsideSpeaker, preferences.AsideKey };
            Func<bool> fullWas = FullScreen;
            try
            {
                signals.Stop();
                CloseTalk(); Hush();
                voiceChanges.Clear(); ownLines.Clear(); voicePreview = null;
                FullScreen = delegate { return false; };
                hidden = shushed = docked = chatting = local = false;
                preferences.Quiet = preferences.Silent = preferences.HdVoice = preferences.ServerVoice = false;
                preferences.Typing = 2;
                job = null; working = null;
                VoiceWait = FreeWait = 20;
                VoiceFx.Pitch = VoiceFx.Robot = VoiceFx.Glitch = 0; VoiceFx.Speed = 100; VoiceFx.Layers = VoiceFx.Layering.Off;
                short[] samples = new short[16000];
                for (int at = 0; at < samples.Length; at++) samples[at] = (short)(5000 * Math.Sin(at * 0.05));
                byte[] wav = Voice.Wave(samples, 16000);
                Speak = FreeSpeak = delegate { return wav; };
                Begin(++asking, "The first line is still playing.", TalkState.Talking, wav);
                voice.Play(wav);
                int ticket = asking, answer = answerTurn;
                double until = voiceUntil;
                SetVoicePitch(3);
                HearVoiceStyle();
                ChooseVoiceModel("next-line-model");
                CheckNextLine();
                if (!voice.Busy || voiceUntil != until || asking != ticket || answerTurn != answer || reply != "The first line is still playing." || voice.Model != modelWas || voicePreview == null || voiceChanges.Count != 1)
                    throw new Exception("A voice setting or its preview cut the current line.");
                WaitVoice(delegate { return !voice.Busy && clock.Elapsed.TotalSeconds >= until; }, "The fake setting line did not finish.");
                CloseTalk();
                CheckNextLine();
                WaitVoice(delegate { return reply == StyleLine && voiceUntil > 0; }, "The held voice preview did not play next.");
                if (voice.Model != "next-line-model" || voiceChanges.Count != 0 || voicePreview != null || VoiceFx.Pitch != 3) throw new Exception("A held voice setting was lost.");
                checks.Add("PASS a voice setting and its preview leave a fake line playing to the end, then apply and preview the next line");
                CloseTalk();

                Begin(++asking, "Keep this line before her comment.", TalkState.Talking, wav);
                voice.Play(wav);
                ticket = asking; until = voiceUntil;
                SayOwn("check-in", "Her queued check-in.");
                Remark("watching", "Her queued prepared comment.", false, wav, true);
                CheckNextLine();
                if (!voice.Busy || asking != ticket || voiceUntil != until || ownLines.Count != 2 || reply != "Keep this line before her comment.") throw new Exception("Her own comment replaced a playing line.");
                WaitVoice(delegate { return !voice.Busy && clock.Elapsed.TotalSeconds >= until; }, "The fake comment line did not finish.");
                CloseTalk();
                hidden = true; CheckNextLine();
                if (ownLines.Count != 2 || asking != ticket) throw new Exception("A queued comment brought her back while hidden.");
                hidden = false;
                CheckNextLine();
                WaitVoice(delegate { return reply == "Her queued check-in." && voiceUntil > 0; }, "Her queued check-in never spoke.");
                ticket = asking; until = voiceUntil;
                CheckNextLine();
                if (asking != ticket || voiceUntil != until || ownLines.Count != 1) throw new Exception("A second own line cut off the queued check-in.");
                voice.Play(wav);
                int audio = audioTurn;
                BargeIn();
                if (voice.Busy || voiceUntil != 0 || audioTurn == audio) throw new Exception("Talking over her didn't stop her at once.");
                CloseTalk();
                CheckNextLine();
                if (reply != "Her queued prepared comment." || ownLines.Count != 0 || voiceUntil <= 0) throw new Exception("A prepared comment was lost while it waited.");
                checks.Add("PASS check-ins and prepared comments wait in order, leave the current line alone, and talking over her still stops her at once");
                CloseTalk();

                chatting = true;
                VoiceFx.Pitch = VoiceFx.Robot = VoiceFx.Glitch = 0; VoiceFx.Speed = 100; VoiceFx.Layers = VoiceFx.Layering.Off;
                speaker.Open(16000); speaker.Play(samples);
                short[] piece = new short[320];
                SetVoicePitch(4); SetVoiceSpeed(120); SetVoiceRobot(20); SetVoiceGlitch(10); SetVoiceLayers(layersWas.Turned(true));
                CheckNextLine();
                if (VoiceFx.Pitch != 0 || VoiceFx.Speed != 100 || VoiceFx.Robot != 0 || VoiceFx.Glitch != 0 || VoiceFx.Layers.On || ChatVoice(piece) != piece || voiceChanges.Count != 5 || !speaker.Busy)
                    throw new Exception("A style change rebuilt the live voice partway through a line.");
                WaitVoice(delegate { return !speaker.Busy; }, "The fake streamed line did not finish.");
                CheckNextLine();
                ChatVoice(piece);
                if (VoiceFx.Pitch != 4 || VoiceFx.Speed != 120 || VoiceFx.Robot != 20 || VoiceFx.Glitch != 10 || !VoiceFx.Layers.On || chatFx == null || chatFx.Pitch != 4 || voiceChanges.Count != 0)
                    throw new Exception("The next streamed line missed its new style.");
                Hush(); chatting = false;
                checks.Add("PASS pitch, speed, robot, glitch and layers keep the live line's style, then reach the next streamed line");

                voice.Play(wav);
                voiceUntil = 0;
                speech = null; talkState = TalkState.Off; micTalked = Environment.TickCount - 5000;
                if (ReactionVoiceFree()) throw new Exception("A reaction ignored sound still on the speakers.");
                clonesHere = new CloneWindow(new Rectangle(0, 0, 300, 300), clock, idle, walk, grin, glitch, preferences.Size, Width, 1);
                cloneWindow = clonesHere;
                ticket = asking;
                int clone = ++cloneTurn;
                CloneLine(new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<int, string>> { new System.Collections.Generic.KeyValuePair<int, string>(1, "A clone line waits.") }, 0, clone);
                if (!voice.Busy || asking != ticket) throw new Exception("A clone line cut sound still on the speakers.");
                cloneTurn++;
                voice.Stop();
                cloneWindow = clonesWas; clonesHere.Dispose(); clonesHere = null;
                checks.Add("PASS reactions and clone lines wait for sound still playing past its estimate");

                working = "Waiting for her answer's voice.";
                talkState = TalkState.Online;
                if (!ReactionVoiceFree()) throw new Exception("The pending answer check started with reactions blocked.");
                answerVoice = asking;
                if (ReactionVoiceFree()) throw new Exception("A reaction spoke while an answer's audio was still being made.");
                answerVoice = -1;
                hdSpeaking = asking;
                if (ReactionVoiceFree()) throw new Exception("A reaction spoke while HD answer audio was still being made.");
                hdSpeaking = -1;
                working = null;
                CloseTalk();
                checks.Add("PASS reactions wait for pending answer audio during a job after its text appears");

                voice.Play(wav);
                ticket = asking;
                ChooseVoiceTier(false);
                ChooseVoiceModel("muted-next-model");
                Silence(false);
                CheckNextLine();
                if (!preferences.Silent || !LoadPreferences().Silent || !preferences.Quiet || voice.Model != "muted-next-model" || asking != ticket || voiceChanges.Count != 0 || voicePreview != null || Voicing)
                    throw new Exception("A queued voice choice undid a newer voice OFF.");
                ChooseVoiceTier(false);
                if (preferences.Silent) throw new Exception("A new voice choice after OFF could not turn her voice on.");
                CloseTalk();
                preferences.Quiet = false;
                voice.Play(wav);
                ticket = asking;
                UseVoiceServer("http://127.0.0.1:9", "muted-next-voice", null, null, VoiceServer.OpenAi);
                Silence(false);
                CheckNextLine();
                if (!preferences.Silent || !LoadPreferences().Silent || !preferences.ServerVoice || server.Url != "http://127.0.0.1:9" || server.Model != "muted-next-voice" || asking != ticket || voiceChanges.Count != 0 || voicePreview != null || Voicing)
                    throw new Exception("A queued voice server undid a newer voice OFF.");
                preferences.Silent = preferences.Quiet = preferences.ServerVoice = false;
                CloseTalk();
                checks.Add("PASS queued voice and server choices keep their settings after a newer OFF without speaking, and a later voice choice can turn her voice back on");

                voice.Play(wav);
                ChooseVoiceModel("older-queued-model");
                voice.Stop();
                ChooseVoiceModel("newer-queued-model");
                CheckNextLine();
                if (voice.Model != "newer-queued-model" || voiceChanges.Count != 0) throw new Exception("An older queued setting replaced a newer choice after speech ended.");
                checks.Add("PASS settings keep their order when speech ends before the waiting settings are applied");

                Begin(++asking, "Keep playing while settings change.", TalkState.Talking, wav);
                voice.Play(wav);
                Action[] changes = {
                    ToggleSpeaking, delegate { ChooseVoiceTier(true); }, delegate { ChooseLocalBrain(null, "line-guard-check", null); },
                    delegate { ChooseModel("line-guard-check"); }, delegate { ChooseTier((preferences.Tier + 1) % 3); }, ForgetText, ForgetVoice,
                    delegate { ChooseVoice("line-guard-check"); }, delegate { ChooseVoiceModel("line-guard-check"); }, ToggleHdCpu, ChooseHd,
                    delegate { ChooseVoiceStyle(LocalVoice.Styles[0].Name); }, delegate { UseVoiceServer("http://127.0.0.1:9", "line-guard-check", null, null, VoiceServer.OpenAi); }, ToggleCallMode
                };
                ticket = asking; until = voiceUntil;
                foreach (Action change in changes) change();
                if (voiceChanges.Count != changes.Length || !voice.Busy || asking != ticket || voiceUntil != until) throw new Exception("A voice, brain or call setting stopped the current line.");
                preferences.HideFullScreen = true; fullScreenHidden = false;
                CheckFullScreen(true);
                if (!gaming.Asked && (hidden || fullScreenHidden || !voice.Busy)) throw new Exception("Automatic full-screen hiding cut her voice.");
                preferences.HideFullScreen = hideFullWas; fullScreenHidden = fullHiddenWas; fullThrough = throughWas;
                PassThrough();
                HearVoiceStyle(); SayOwn("check-in", "This waits for her voice.");
