                if (jobFree != 0 || jobWords != Voice.Spoken(working.Replace("Esc", "Escape")) || asking != jobTicket || reply != null) throw new Exception("The job's chosen voice changed its words or the reply turn.");
                voiceUntil = 0;
                SayAside("Got it.", speakingJob);
