        private static void SmokeSound(System.Collections.Generic.List<string> checks, string output)
        {
            bool waveWas = Speaker.SkipWave;
            int loudnessWas = Voice.Loudness;
            string logWas = Brain.LogPath;
            string log = Path.Combine(output, "speaker-check.txt");
            try
            {
                Brain.LogPath = log;
                File.WriteAllText(log, "");
                Speaker.SkipWave = true;
                Voice.Loudness = 50;
                if (Marshal.SizeOf(typeof(WaveFormat)) != 18 || (int)Marshal.OffsetOf(typeof(WaveFormat), "Extra") != 16) throw new Exception("Her PCM format doesn't match Windows' WAVEFORMATEX.");
                foreach (int soundRate in new[] { 16000, 22050, 24000, 44100, 48000 })
                {
                    System.Collections.Generic.List<SoundCheck> outputs = new System.Collections.Generic.List<SoundCheck>();
                    using (Speaker outputSpeaker = new Speaker(false, delegate(int openedRate)
                    {
                        SoundCheck openedSound = new SoundCheck(); outputs.Add(openedSound);
                        return new SoundOut(openedRate, openedSound, openedSound);
                    }))
                    {
                        try
                        {
                            Voice outputVoice = new Voice(outputSpeaker);
                            short[] sound = new short[soundRate / 10];
                            for (int soundAt = 0; soundAt < sound.Length; soundAt++) sound[soundAt] = 12000;
                            outputVoice.Play(Voice.Wave(sound, soundRate));
                            WaitSound(delegate { return outputSpeaker.ModernPlayed >= sound.Length; }, "Finished speech never reached the fallback's buffer.");
                            if (outputs.Count != 1 || outputs[0].Flags != SoundOut.ConvertFlags || outputs[0].Rate != soundRate || outputs[0].StartedEmpty || outputs[0].Peak != 6000) throw new Exception("Speech bypassed WASAPI, started empty, or applied volume twice.");
                            long fedBeforeClear = outputSpeaker.ModernFed;
                            outputSpeaker.Clear();
                            outputSpeaker.Play(sound);
                            WaitSound(delegate { return outputSpeaker.ModernFed >= fedBeforeClear + sound.Length && outputs[0].Starts == 2; }, "Clear lost the next voice line.");
                            if (outputs[0].Resets != 1 || outputs[0].StartedEmpty) throw new Exception("Clear didn't refill before restarting speech.");
                            outputs[0].Fail = "padding";
                            WaitSound(delegate { return outputSpeaker.ModernFailure != null; }, "A lost WASAPI device stayed alive.");
                            outputSpeaker.Play(sound);
                            WaitSound(delegate { return outputs.Count == 2 && outputSpeaker.ModernPlayed >= sound.Length; }, "The next voice chunk didn't reopen a failed stream.");
                            outputVoice.Play(Voice.Wave(sound, soundRate));
                            WaitSound(delegate { return outputs.Count == 2 && outputSpeaker.ModernPlayed >= sound.Length * 2; }, "A second finished voice line did not join the open stream.");
                            outputVoice.Stop();
                            if (outputSpeaker.Modern) throw new Exception("Stopping a voice left its stream open.");
                        }
                        finally { outputSpeaker.Close(); foreach (SoundCheck used in outputs) used.Dispose(); }
                    }
                }
                checks.Add("PASS finished speech uses Speaker and WASAPI at 16, 22.05, 24, 44.1 and 48 kHz, requests PCM and rate conversion, applies her volume once, fills before starting, survives Clear followed by another line, and reopens after a lost stream or a stopped voice");
                foreach (string operation in new[] { "start", "padding", "get buffer", "release buffer", "stop", "reset" })
                {
                    using (SoundCheck broken = new SoundCheck())
                    using (SoundOut brokenStream = new SoundOut(24000, broken, broken))
                    {
                        if (operation == "stop" || operation == "reset")
                        {
                            brokenStream.Write(new short[2400]);
                            WaitSound(delegate { return broken.Starts > 0; }, "The test stream didn't start.");
                            broken.Fail = operation;
                            brokenStream.Clear();
                        }
                        else
                        {
                            broken.Fail = operation;
                            try { brokenStream.Write(new short[2400]); }
                            catch (VoiceException) { }
                        }
                        WaitSound(delegate { return !brokenStream.Alive; }, "WASAPI " + operation + " failed silently.");
                        if (brokenStream.Failure == null || !brokenStream.Failure.Contains(operation) || !brokenStream.Failure.Contains("88890004")) throw new Exception("A WASAPI error lost its operation or HRESULT.");
                    }
                }
                using (SoundCheck stalledSound = new SoundCheck { Drain = false, Muted = true })
                using (SoundOut stalledStream = new SoundOut(24000, stalledSound, stalledSound))
                {
                    stalledStream.Write(new short[2400]);
                    WaitSound(delegate { return !stalledStream.Alive; }, "A buffer that never drains stayed alive.");
                    if (!stalledStream.Failure.Contains("stopped draining") || stalledSound.VolumeChanges != 0) throw new Exception("A stalled stream wasn't diagnosed, or changed their mute.");
                    stalledSound.Muted = false; stalledSound.Volume = 0;
                    if (SoundOut.Quiet(stalledSound) == null) throw new Exception("Zero session volume wasn't diagnosed.");
                }
                string logged = File.ReadAllText(log);
                if (!logged.Contains("session is muted") || !logged.Contains("stopped draining") || !logged.Contains("release buffer failed") || !logged.Contains("submitted") || !logged.Contains("drained")) throw new Exception("A silent speaker failure left no useful error log.");
                checks.Add("PASS WASAPI logs failed writes, starts, stops, resets and padding calls with their HRESULT and sample counts; a buffer that never drains fails visibly, and session mute and zero volume are diagnosed without changing them");
                short[] original = new short[4800];
                for (int originalAt = 0; originalAt < original.Length; originalAt++) original[originalAt] = (short)(9000 * Math.Sin(originalAt * 0.04));
                byte[] fishWave = Voice.Wave(original, 48000);
                short[] fishSound = VoiceServer.Sound(fishWave, "audio/wav", "Fish Audio");
                if (fishSound.Length != 2400 || Speaker.Loudness(fishSound, 0, fishSound.Length) < 0.1 || !VoiceServer.SoundFormat(fishWave).Contains("48000 Hz") || VoiceServer.SoundFormat(new byte[0]) != "unrecognized audio format") throw new Exception("Fish Audio's rate conversion or format diagnosis went wrong.");
                bool fishUnreadable = false;
                try { VoiceServer.Sound(new byte[] { 102, 76, 97, 67, 0, 0 }, "audio/flac", "Fish Audio"); }
                catch (VoiceException fishError) { fishUnreadable = fishError.Message.Contains("FLAC, 6 bytes") && fishError.Message.Contains("Windows couldn't decode"); }
                if (!fishUnreadable) throw new Exception("An undecodable Fish reply lost its format and size.");
                checks.Add("PASS Fish Audio WAV replies are decoded and resampled from 48 kHz to 24 kHz, and unreadable audio is described by its format and size without logging its contents");
            }
            finally { Speaker.SkipWave = waveWas; Voice.Loudness = loudnessWas; Brain.LogPath = logWas; }
        }

        private static void SmokeHardwareSound(System.Collections.Generic.List<string> checks)
        {
            if (OnGitHub) { checks.Add("LIMIT unattended smoke leaves real audio devices closed; fake sound clients cover playback, and real WASAPI speakers need a live check"); return; }
            bool hardwareWaveWas = Speaker.SkipWave;
            using (Speaker hardwareSpeaker = new Speaker(false))
            {
                try
                {
                    Speaker.SkipWave = true;
                    Voice hardwareVoice = new Voice(hardwareSpeaker);
                    foreach (int hardwareRate in new[] { 24000, 22050 })
                    {
                        hardwareVoice.Play(Voice.Wave(new short[hardwareRate / 10], hardwareRate));
                        Stopwatch hardwareWait = Stopwatch.StartNew();
                        while (hardwareSpeaker.ModernPlayed < hardwareRate / 10 && hardwareSpeaker.ModernFailure == null && hardwareWait.ElapsedMilliseconds < 1500) Thread.Sleep(10);
                        if (!hardwareSpeaker.Modern || hardwareSpeaker.ModernFailure != null || hardwareSpeaker.ModernPlayed < hardwareRate / 10)
                        {
                            checks.Add("LIMIT WASAPI hardware at " + hardwareRate + " Hz: " + (hardwareSpeaker.ModernFailure ?? "submitted " + hardwareSpeaker.ModernFed + ", drained " + hardwareSpeaker.ModernPlayed + " samples"));
                            return;
                        }
                    }
                    hardwareVoice.Stop();
                    checks.Add("PASS finished WAV speech reaches WASAPI and its buffers drain at 24 and 22.05 kHz across two voice lines");
                    checks.Add("LIMIT WASAPI hardware check used silence; actual audibility, Windows mixer settings and the tester's speakers need a listening check");
                }
                catch (VoiceException error) { checks.Add("LIMIT her WASAPI speakers didn't play here: " + error.Message); }
                finally { Speaker.SkipWave = hardwareWaveWas; }
            }
        }

        // A pretend PC for her voice in your mic: VB-CABLE at cableRate and one mic humming 440 Hz at 0.25, on the test's clock.
        private const string MixMicId = "{0.0.1.00000000}.{stand-in-mic}";

        private static StandInDevices MixPc(double[] now, int cableRate, int micRate)
        {
            StandInDevices pc = new StandInDevices();
            pc.Clock = delegate { return now[0]; };
            pc.CableThere = new MixDevice("{0.0.0.00000000}.{stand-in-cable}", "CABLE Input (VB-Audio Virtual Cable)", "{0.0.1.00000000}.{stand-in-cable-out}");
            pc.Mics.Add(new MixDevice(MixMicId, "Microphone (stand-in)"));
            pc.DefaultMic = MixMicId;
            pc.CableRate = cableRate;
            pc.MicRate = micRate;
            return pc;
        }

        // Runs a mix on the test's clock, waking it as WASAPI would: when the mic's packet lands, when the cable takes a period,
        // and every 10 ms while neither is open, each wake a moment late like a real one. during runs first at each wake.
        private static void RunMix(MicMix mix, StandInDevices pc, double[] now, double seconds, Action<double> during)
        {
            double end = now[0] + seconds;
            while (now[0] < end)
            {
                double next = now[0] + 0.01;
                lock (pc.Opened) foreach (StandInMic heard in pc.Opened) if (!heard.Disposed) next = Math.Min(next, heard.NextPacket);
                lock (pc.Cables) foreach (StandInCable playing in pc.Cables) if (!playing.Disposed) next = Math.Min(next, playing.NextTake);
                now[0] = Math.Min(end, next) + 0.0002;
                if (during != null) during(now[0]);
                mix.Step();
            }
        }

        // A steady tone as her speakers hand it over.
        private static short[] Hum(int rate, double hertz, double level, double seconds)
        {
            short[] hum = new short[(int)(rate * seconds)];
            for (int i = 0; i < hum.Length; i++) hum[i] = (short)Math.Round(level * 32767 * Math.Sin(2 * Math.PI * hertz * i / rate));
            return hum;
        }

        private static double[] hannWindow = new double[0];
        private static double hannTotal;

        // How strong hertz is over a stretch of sound, as a sine's amplitude where 1 is full scale: Goertzel with a Hann window.
        private static double ToneIn(float[] sound, int rate, double hertz, double from, double seconds)
        {
            int start = (int)(from * rate), count = Math.Min((int)(seconds * rate), sound.Length - start);
            if (count < 16) return 0;
            if (hannWindow.Length != count)
            {
                hannWindow = new double[count];
                hannTotal = 0;
                for (int i = 0; i < count; i++) hannTotal += hannWindow[i] = 0.5 - 0.5 * Math.Cos(2 * Math.PI * i / (count - 1));
            }
            double turn = 2 * Math.Cos(2 * Math.PI * hertz / rate), one = 0, two = 0;
            for (int i = 0; i < count; i++)
            {
                double next = sound[start + i] * hannWindow[i] + turn * one - two;
                two = one;
                one = next;
            }
            return 2 * Math.Sqrt(Math.Max(0, one * one + two * two - turn * one * two)) / hannTotal;
        }

        // The strongest frequency within spread Hz of near, to 0.05 Hz.
        private static double PeakIn(float[] sound, int rate, double near, double spread, double from, double seconds)
        {
            double best = near, strongest = -1;
            for (double hertz = near - spread; hertz <= near + spread; hertz += 0.05)
            {
                double strength = ToneIn(sound, rate, hertz, from, seconds);
                if (strength > strongest) { strongest = strength; best = hertz; }
            }
            return best;
        }

        // The strongest stray tone: at every 100 Hz, and 37 Hz past each, up to near Nyquist, 20 Hz or more from any tone meant to be
        // there. A glitch each packet or chunk would show at 100 Hz steps.
        private static double StrayIn(float[] sound, int rate, double from, double seconds, params double[] tones)
        {
            double most = 0;
            for (double hertz = 100; hertz < rate * 0.47; hertz += 100)
                foreach (double probe in new[] { hertz, hertz + 37 })
                {
                    bool meant = false;
                    foreach (double tone in tones) meant |= Math.Abs(probe - tone) < 20;
                    if (!meant) most = Math.Max(most, ToneIn(sound, rate, probe, from, seconds));
                }
            return most;
        }

        private static string Khz(int rate) { return (rate / 1000.0).ToString("0.#", System.Globalization.CultureInfo.InvariantCulture); }

        private static string Db(double level) { return (20 * Math.Log10(Math.Max(1e-9, level))).ToString("0", System.Globalization.CultureInfo.InvariantCulture); }

        // Her voice in your mic (F66) on stand-in devices and a pretend clock: no real device opens.
        private void SmokeMicLoudness(System.Collections.Generic.List<string> checks)
        {
            int loudnessWas = preferences.MicLoudness, sizeWas = preferences.MainframeSize, speakerWas = Voice.Loudness;
            bool simpleWas = simpleTest, advancedWas = preferences.AdvancedSettings, hdWas = preferences.HdVoice, settingsWas = mainframe.SettingsShown;
            MicMix mixWas = micMix;
            double[] now = { 0 };
            StandInDevices pc = MixPc(now, 48000, 48000);
            using (MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true })
            {
                try
                {
                    micMix = mix;
                    mix.Loudness = MicLoudness;
                    mix.Step();
                    mainframe.ShowVoiceInMic();
                    for (int step = 0; step < 16; step++)
                    {
                        mainframe.SlideMicLoudness(step);
                        int expected = 50 + step * 10;
                        if (MicLoudness != expected || mix.Loudness != expected || LoadPreferences().MicLoudness != expected || mainframe.MicLoudnessShown != expected + "%" || Voice.Loudness != speakerWas)
                            throw new Exception("Her mic loudness slider did not save or reach the mix at " + expected + "%.");
                    }
                    mainframe.SlideMicLoudness(5);
                    if (SelfKnow.Setting("Mainframe.cs", "Her voice in your mic: loudness") == null) throw new Exception("Her mic loudness has no help line.");
                    foreach (int size in new[] { 100, 150, 200 })
                        foreach (bool simple in new[] { false, true })
                            foreach (bool hd in new[] { false, true })
                            {
                                preferences.AdvancedSettings = false;
                                simpleTest = simple;
                                preferences.HdVoice = hd;
                                mainframe.SizeMainframe(size);
                                mainframe.ShowSettings(true);
                                string problem = mainframe.VoiceInMicFits() ?? mainframe.Overlap() ?? mainframe.Outside() ?? mainframe.TextFits();
                                if (problem != null || mainframe.MicLoudnessShown != "100%") throw new Exception("Her mic loudness row does not fit at " + size + "%: " + problem);
                            }
                    DataContractJsonSerializer json = new DataContractJsonSerializer(typeof(Preferences));
                    foreach (string saved in new[] { "{}", "{\"MicLoudness\":-10}", "{\"MicLoudness\":999}", "{\"MicLoudness\":126}" })
                        using (MemoryStream input = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(saved)))
                        {
                            Preferences loaded = (Preferences)json.ReadObject(input);
                            int expected = saved == "{}" ? 100 : saved.Contains("-10") ? 50 : saved.Contains("999") ? 200 : 130;
                            if (loaded.MicLoudness != expected || new Preferences().MicLoudness != 100) throw new Exception("Her mic loudness default or saved range is wrong.");
                        }
                    checks.Add("PASS the mic loudness slider saves all 16 steps from 50% to 200%, updates the running mix, defaults to 100% in new and old settings, clamps saved values, and fits Simple and Advanced Settings with HD on or off at 100, 150 and 200%");
                }
                finally
                {
                    micMix = mixWas;
                    preferences.MicLoudness = loudnessWas;
                    preferences.AdvancedSettings = advancedWas;
                    preferences.HdVoice = hdWas;
                    simpleTest = simpleWas;
                    mainframe.SizeMainframe(sizeWas);
                    SavePreferences();
                    mainframe.ShowSettings(settingsWas);
                }
            }
        }

        private static void MixLog(string path, int count, double seconds)
        {
            WaitSound(delegate { return !MicAnswer.Writing && !MicMix.Noting; }, "Her cable delivery log did not finish.");
            // Her log is written on the thread pool under Brain's lock, so a read under the same lock can't meet a write.
            string text;
            lock (typeof(Brain)) text = File.ReadAllText(path);
            MatchCollection reports = Regex.Matches(text, @"\| mic delivery \| - \| answer=\d+ speakers=([0-9.]+) s cable=([0-9.]+) s");
            if (reports.Count != count) throw new Exception("Her cable log wrote " + reports.Count + " lines for " + count + " answers.");
            foreach (Match report in reports)
            {
                double given = double.Parse(report.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture);
                double reached = double.Parse(report.Groups[2].Value, System.Globalization.CultureInfo.InvariantCulture);
                if (Math.Abs(given - seconds) > 0.001 || Math.Abs(reached - seconds) > 0.001) throw new Exception("Her cable log lost speech: " + report.Value);
            }
        }

        private static void SmokeMicDelivery(System.Collections.Generic.List<string> checks, string output)
        {
            MicMix currentWas = MicMix.Current;
            string logWas = Brain.LogPath;
            int loudnessWas = Voice.Loudness;
            bool waveWas = Speaker.SkipWave;
            try
            {
                WaitSound(delegate { return !MicAnswer.Writing && !MicMix.Noting; }, "Earlier cable notes did not finish.");
                Voice.Loudness = 100;
                foreach (int room in new[] { 0, 128, 256, 512 })
                  foreach (bool separate in new[] { false, true })
                {
                    string path = Path.Combine(output, (separate ? "mic-queued-lines-" : "mic-whole-answer-") + room + ".txt");
                    Brain.LogPath = path;
                    // A note from the last mix can still be going into the new log on the thread pool (5 Nov, run 9).
                    lock (typeof(Brain)) File.WriteAllText(path, "");
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 48000);
                    pc.Level = 0;
                    pc.CableRoom = room;
                    using (MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true })
                    using (Speaker outputSpeaker = new Speaker(true))
                    {
                        mix.Step();
                        MicMix.Current = mix;
                        int start = pc.Cables[0].Kept.Length;
                        short[] whole = new short[14400];
                        Voice lines = new Voice(outputSpeaker);
                        for (int line = 0; line < 3; line++)
                        {
                            short[] samples = new short[4800];
                            for (int at = 0; at < samples.Length; at++) samples[at] = (short)(((at / (line + 2)) & 1) == 0 ? 2048 : -2048);
                            Array.Copy(samples, 0, whole, line * samples.Length, samples.Length);
                            if (separate) lines.Play(Voice.Wave(samples, 48000));
                        }
                        if (!separate) lines.Play(Voice.Wave(whole, 48000));
                        RunMix(mix, pc, now, 0.1, null);
                        lines.Finish();
                        RunMix(mix, pc, now, 0.3, null);
                        float[] got = pc.Cables[0].Kept;
                        if (got.Length < start + whole.Length || pc.Cables[0].Starved != 0 || mix.CableLosses != 0) throw new Exception("The cable did not keep the full three-line answer without gaps.");
                        for (int at = 0; at < whole.Length; at++)
                            if (Math.Abs(got[start + at] - whole[at] / 2048.0 * MicMix.Speaking) > 0.00001) throw new Exception("The cable lost or reordered sample " + at + " of a three-line answer.");
                        for (int at = start + whole.Length; at < got.Length; at++)
                            if (Math.Abs(got[at]) > 0.00001) throw new Exception("The cable repeated part of an answer.");
                        MixLog(path, separate ? 3 : 1, separate ? 0.1 : 0.3);
                    }
                }
                checks.Add("PASS every sample of a three-line answer reaches the stand-in cable in order without gaps, repeats or starvation, as one WAV and as three queued WAVs, with 50 ms buffers and buffers of 128, 256 and 512 frames; normal completion keeps the tail, and each answer logs once after the cable accepts it");

                Brain.LogPath = Path.Combine(output, "mic-rate-changes.txt");
                File.WriteAllText(Brain.LogPath, "");
                foreach (int rate in new[] { 16000, 24000, 44100 })
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 48000);
                    pc.Level = 0;
                    using (MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true })
                    using (Speaker outputSpeaker = new Speaker(true))
                    {
                        mix.Step();
                        MicMix.Current = mix;
                        outputSpeaker.BeginAnswer();
                        foreach (int from in new[] { 24000, rate, 16000 })
                        {
                            outputSpeaker.Open(from);
                            outputSpeaker.Play(Hum(from, from == rate ? 1000 : 700, 0.1, 0.3));
                        }
                        outputSpeaker.EndAnswer();
                        RunMix(mix, pc, now, 1.05, null);
                        float[] got = pc.Cables[0].Kept;
                        int[] sources = { 24000, rate, 16000 };
                        for (int line = 0; line < sources.Length; line++)
                        {
                            double hertz = sources[line] == rate ? 1000 : 700;
                            double level = ToneIn(got, 48000, hertz, 0.07 + line * 0.3, 0.2) / Math.Sqrt(2);
                            if (Math.Abs(level / MicMix.Speaking - 1) > 0.03) throw new Exception("A speaker rate change lost line " + (line + 1) + ".");
                        }
                    }
                }
                checks.Add("PASS queued voice keeps its order across speaker rate changes at 16, 24 and 44.1 kHz");

                Speaker.SkipWave = true;
                Voice.Loudness = 50;
                Brain.LogPath = Path.Combine(output, "mic-loudness.txt");
                File.WriteAllText(Brain.LogPath, "");
                foreach (int percent in new[] { 50, 200 })
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 48000);
                    pc.Level = 0.1;
                    using (SoundCheck heard = new SoundCheck())
                    using (MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true })
                    using (Speaker outputSpeaker = new Speaker(false, delegate(int rate) { return new SoundOut(rate, heard, heard); }))
                    {
                        mix.Loudness = percent;
                        mix.Step();
                        MicMix.Current = mix;
                        short[] samples = Hum(24000, 1000, 0.1, 0.6), before = (short[])samples.Clone();
                        Voice lines = new Voice(outputSpeaker);
                        lines.Play(Voice.Wave(samples, 24000));
                        WaitSound(delegate { return outputSpeaker.ModernPlayed >= samples.Length; }, "The stand-in speakers did not get the whole answer.");
                        int peak = 0;
                        foreach (short sample in Voice.Louder(samples)) peak = Math.Max(peak, Math.Abs((int)sample));
                        if (heard.Peak != peak || heard.VolumeChanges != 0 || Voice.Loudness != 50) throw new Exception("Cable loudness changed her speakers.");
                        for (int at = 0; at < samples.Length; at++) if (samples[at] != before[at]) throw new Exception("Cable loudness changed her source samples.");
                        RunMix(mix, pc, now, 0.7, null);
                        float[] got = pc.Cables[0].Kept;
                        double voiceLevel = ToneIn(got, 48000, 1000, 0.15, 0.3) / Math.Sqrt(2), micLevel = ToneIn(got, 48000, 440, 0.15, 0.3);
                        if (Math.Abs(voiceLevel / (MicMix.Speaking * percent / 100) - 1) > 0.03 || Math.Abs(micLevel / pc.Level - 1) > 0.02)
                            throw new Exception("Cable loudness changed the wrong level at " + percent + "%.");
                        mix.Take(new object(), Hum(24000, 1000, 0.9, 0.4), 24000);
                        RunMix(mix, pc, now, 0.5, null);
                        foreach (float sample in pc.Cables[0].Kept)
                            if (float.IsNaN(sample) || float.IsInfinity(sample) || Math.Abs(sample) >= SoftLimiter.Ceiling) throw new Exception("Cable loudness clipped the mix.");
                    }
                }
                checks.Add("PASS cable loudness at 50% and 200% scales her voice by that amount below the limiter, keeps her speaker PCM and the user's mic level unchanged, and keeps loud peaks below the limiter ceiling");
            }
            finally { MicMix.Current = currentWas; Brain.LogPath = logWas; Voice.Loudness = loudnessWas; Speaker.SkipWave = waveWas; }
        }

        private static void SmokeCallMic(System.Collections.Generic.List<string> checks)
        {
            MicMix currentWas = MicMix.Current;
            double[] now = { 0 };
            StandInDevices pc = MixPc(now, 48000, 48000);
            using (MicMix mix = new MicMix(pc, delegate { return now[0]; }))
            {
                try
                {
                    mix.Step();
                    MicMix.Current = mix;
                    object speaker = new object();
                    MicMix.Hear(speaker, Hum(24000, 1000, 0.2, 1), 24000);
                    if (mix.Waiting != 0) throw new Exception("Her off-call voice waited for the cable.");
                    RunMix(mix, pc, now, 0.6, null);
                    if (ToneIn(pc.Cables[0].Kept, 48000, 1000, 0.2, 0.3) > 0.001 || Math.Abs(ToneIn(pc.Cables[0].Kept, 48000, 440, 0.2, 0.3) / pc.Level - 1) > 0.03) throw new Exception("The off-call cable lost the user's mic or gained her voice.");
                    mix.Call = true;
                    MicMix.Hear(speaker, Hum(24000, 1000, 0.2, 3), 24000);
                    RunMix(mix, pc, now, 0.5, null);
                    // Waiting only counts what hasn't started, and this line has, so her own level shows it's still going out.
                    if (ToneIn(pc.Cables[0].Kept, 48000, 1000, 0.7, 0.3) < 0.1 || mix.Output == 0) throw new Exception("Call mode did not send her queued voice to the cable.");
                    int micOpens = mix.MicOpens, cableOpens = mix.CableOpens;
                    mix.Call = false;
                    if (mix.Waiting != 0 || mix.Output != 0) throw new Exception("Ending a call kept her queued voice or its level.");
                    MicMix.Hear(speaker, Hum(24000, 1000, 0.2, 1), 24000);
                    RunMix(mix, pc, now, 0.5, null);
                    if (ToneIn(pc.Cables[0].Kept, 48000, 1000, 1.2, 0.3) > 0.001 || Math.Abs(ToneIn(pc.Cables[0].Kept, 48000, 440, 1.2, 0.3) / pc.Level - 1) > 0.03 || mix.Waiting != 0) throw new Exception("Her voice reached the cable after the call ended.");
                    mix.Call = true;
                    RunMix(mix, pc, now, 0.5, null);
                    if (ToneIn(pc.Cables[0].Kept, 48000, 1000, 1.7, 0.3) > 0.001 || mix.MicOpens != micOpens || mix.CableOpens != cableOpens) throw new Exception("A new call replayed old voice or reopened the devices.");
                    if (!MicMix.PickLine(MicMix.CableEnd).Contains("Calls only")) throw new Exception("The mic note lost its call limit.");
                }
                finally { MicMix.Current = currentWas; }
            }
            checks.Add("PASS her cable voice is off outside call mode, plays during calls, drops queued voice on exit and stays empty on re-entry, while the user's mic and both open devices stay live");
        }

        private static void SmokeVoiceInMic(System.Collections.Generic.List<string> checks, string output)
        {
            string logWas = Brain.LogPath;
            int loudnessWas = Voice.Loudness;
            MicMix currentWas = MicMix.Current;
            try
            {
                Brain.LogPath = Path.Combine(output, "mic-mix-check.txt");
                File.WriteAllText(Brain.LogPath, "");
                Voice.Loudness = 100;
                // Their mic at 440 Hz, her line at 1000 Hz from 24 kHz, and voice chat streaming in at 700 Hz from 16 kHz: each comes
                // out at its own level and pitch, with nothing else in there, at every cable rate from a mic at every rate.
                double worstStray = 0;
                foreach (int cableRate in new[] { 48000, 44100, 16000 })
                    foreach (int micRate in new[] { 48000, 44100, 16000 })
                    {
                        double[] now = { 0 };
                        StandInDevices pc = MixPc(now, cableRate, micRate);
                        pc.Phase = 0.0037;
                        MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                        object lines = new object(), chat = new object();
                        mix.Step();
                        if (!mix.Mixing || pc.Opened.Count != 1 || pc.Cables.Count != 1 || mix.Problem != null) throw new Exception("Her mic mix didn't open the stand-in mic and cable at " + Khz(cableRate) + " kHz: " + mix.Problem);
                        mix.Take(lines, Hum(24000, 1000, 0.2, 3), 24000);
                        short[] streamed = Hum(16000, 700, 0.15, 3);
                        int sent = 0;
                        // Voice chat comes in 50 ms chunks, each a little ahead of when it plays.
                        RunMix(mix, pc, now, 2.6, delegate(double at)
                        {
                            while (sent < streamed.Length && sent < (at + 0.1) * 16000)
                            {
                                short[] chunk = new short[Math.Min(800, streamed.Length - sent)];
                                Array.Copy(streamed, sent, chunk, 0, chunk.Length);
                                mix.Take(chat, chunk, 16000);
                                sent += chunk.Length;
                            }
                        });
                        float[] got = pc.Cables[0].Kept;
                        double micLevel = ToneIn(got, cableRate, 440, 1, 1), herLevel = ToneIn(got, cableRate, 1000, 1, 1), chatLevel = ToneIn(got, cableRate, 700, 1, 1);
                        double micHz = PeakIn(got, cableRate, 440, 3, 1, 1), herHz = PeakIn(got, cableRate, 1000, 3, 1, 1), chatHz = PeakIn(got, cableRate, 700, 3, 1, 1);
                        double stray = StrayIn(got, cableRate, 1, 1, 440, 1000, 700);
                        worstStray = Math.Max(worstStray, stray);
                        string seen = Khz(micRate) + " to " + Khz(cableRate) + " kHz: mic " + micLevel.ToString("0.0000") + " at " + micHz.ToString("0.00") + " Hz, her " + herLevel.ToString("0.0000") + " at " + herHz.ToString("0.00") + " Hz, chat " + chatLevel.ToString("0.0000") + " at " + chatHz.ToString("0.00") + " Hz, stray " + stray.ToString("0.00000") + ", " + got.Length + " frames, short " + mix.Starved + "/" + pc.Cables[0].Starved;
                        if (Math.Abs(micLevel / 0.25 - 1) > 0.03 || Math.Abs(herLevel / 0.2 - 1) > 0.03 || Math.Abs(chatLevel / 0.15 - 1) > 0.03 || Math.Abs(micHz - 440) > 0.5 || Math.Abs(herHz - 1000) > 0.25 || Math.Abs(chatHz - 700) > 0.25
                            || stray > 0.0025 || got.Length < 2.55 * cableRate || got.Length > 2.65 * cableRate || mix.Starved != 0 || pc.Cables[0].Starved != 0)
                            throw new Exception("Her mic mix came out wrong from " + seen);
                        mix.Stop();
                        if (!pc.Opened[0].Disposed || !pc.Cables[0].Disposed || mix.Mixing) throw new Exception("Stopping her mic mix kept a device open.");
                    }
                // Going down to 16 kHz a 12 kHz tone doesn't fold back to 4 kHz, and going up from 16 kHz a 6 kHz tone doesn't image at 10 kHz.
                double alias, image, imaged;
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 16000, 48000);
                    pc.Hums[MixMicId] = 12000;
                    MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                    mix.Step();
                    RunMix(mix, pc, now, 1.6, null);
                    alias = ToneIn(pc.Cables[0].Kept, 16000, 4000, 0.5, 1);
                    mix.Stop();
                }
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 16000);
                    pc.Hums[MixMicId] = 6000;
                    MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                    mix.Step();
                    RunMix(mix, pc, now, 1.6, null);
                    image = ToneIn(pc.Cables[0].Kept, 48000, 10000, 0.5, 1);
                    imaged = ToneIn(pc.Cables[0].Kept, 48000, 6000, 0.5, 1);
                    mix.Stop();
                }
                if (alias > 0.0025 || image > 0.0025 || Math.Abs(imaged / 0.25 - 1) > 0.05) throw new Exception("Her mic mix aliased or imaged: " + alias.ToString("0.00000") + " at 4 kHz, " + image.ToString("0.00000") + " at 10 kHz, 6 kHz at " + imaged.ToString("0.0000"));
                checks.Add("PASS her voice in your mic: their mic and her voice reach the cable at their own levels and pitches at 48, 44.1 and 16 kHz, from mics at each rate and her voice at 24 and 16 kHz, voice chat's chunks join seamlessly, stray tones stay under " + Db(worstStray) + " dB, and nothing aliases or images (" + Db(Math.Max(alias, image)) + " dB)");
                // Too loud: the mic and her voice each at 0.8 peak at 1.6 together, and the limiter keeps every sample under its ceiling
                // without crushing them.
                float loudest = 0;
                double loudness = 0;
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 48000);
                    pc.Hums[MixMicId] = 300;
                    pc.Level = 0.8;
                    MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                    mix.Step();
                    mix.Take(new object(), Hum(24000, 700, 0.8, 2), 24000);
                    RunMix(mix, pc, now, 1.6, null);
                    float[] got = pc.Cables[0].Kept;
                    foreach (float sample in got) loudest = Math.Max(loudest, Math.Abs(sample));
                    for (int i = 48000 / 2; i < 48000 * 3 / 2; i++) loudness += got[i] * got[i];
                    loudness = Math.Sqrt(loudness / 48000);
                    mix.Stop();
                }
                // A mix peaking at 0.75 comes out exactly as it went in.
                float[] quiet = new float[4800], quietWas = new float[4800];
                for (int i = 0; i < quiet.Length; i++) quiet[i] = quietWas[i] = (float)(0.75 * Math.Sin(2 * Math.PI * 440 * i / 48000));
                new SoftLimiter(48000).Run(quiet, quiet.Length);
                bool untouched = true;
                for (int i = 0; i < quiet.Length; i++) untouched &= quiet[i] == quietWas[i];
                if (loudest >= SoftLimiter.Ceiling || loudness < 0.35 || !untouched) throw new Exception("Her mic mix's limiter let a 1.6x mix peak at " + loudest.ToString("0.000") + ", crushed it to " + loudness.ToString("0.000") + ", or changed a quiet one (" + untouched + ").");
                checks.Add("PASS her voice in your mic's limiter keeps a mix of 1.6 times full scale under " + SoftLimiter.Ceiling.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture) + " (it peaked just under that and stayed at " + loudness.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture) + " RMS), and a mix peaking at 0.75 goes through untouched");
                // A click on the mic reaches the cable within 60 ms at each rate, however its packets fall against the cable's.
                double slowest = 0, quickest = 1;
                foreach (int cableRate in new[] { 48000, 44100, 16000 })
                    foreach (double phase in new[] { 0.0003, 0.0051, 0.0097 })
                    {
                        double[] now = { 0 };
                        StandInDevices pc = MixPc(now, cableRate, 48000);
                        pc.Level = 0;
                        pc.Phase = phase;
                        pc.Click = 72000;
                        MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                        mix.Step();
                        RunMix(mix, pc, now, 2, null);
                        float[] got = pc.Cables[0].Kept;
                        int peak = 0;
                        for (int i = 1; i < got.Length; i++) if (Math.Abs(got[i]) > Math.Abs(got[peak])) peak = i;
                        double took = pc.Cables[0].PlayedAt(peak) - pc.Opened[0].HeardAt(72000);
                        mix.Stop();
                        // Going down to 16 kHz spreads the click over three samples, so it peaks lower there.
                        if (double.IsNaN(took) || took <= 0 || took > 0.06 || Math.Abs(got[peak]) < 0.1) throw new Exception("A click on the mic took " + (took * 1000).ToString("0.0") + " ms to reach a " + Khz(cableRate) + " kHz cable, with packets " + phase * 1000 + " ms out of step.");
                        slowest = Math.Max(slowest, took);
                        quickest = Math.Min(quickest, took);
                    }
                checks.Add("PASS her voice in your mic: a click on the mic reaches the cable in " + (quickest * 1000).ToString("0") + " to " + (slowest * 1000).ToString("0") + " ms at 48, 44.1 and 16 kHz however its packets fall, under the 60 ms target");
                // A mic whose clock runs fast or slow against the cable's, by as much as a cheap one's, ends up matched to it exactly:
                // it never runs dry or piles up, and a click at the end still comes through in time.
                System.Collections.Generic.List<string> steered = new System.Collections.Generic.List<string>();
                foreach (double off in new[] { 300e-6, -300e-6, 1500e-6, -1500e-6 })
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 48000);
                    pc.Fast = 1 + off;
                    pc.Phase = 0.0051;
                    pc.Level = 0.1;
                    pc.Click = (long)(39 * 48000 * pc.Fast);
                    MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                    mix.Step();
                    RunMix(mix, pc, now, 40, null);
                    float[] got = pc.Cables[0].Kept;
                    int peak = 38 * 48000;
                    for (int i = peak; i < got.Length; i++) if (Math.Abs(got[i]) > Math.Abs(got[peak])) peak = i;
                    double took = pc.Cables[0].PlayedAt(peak) - pc.Opened[0].HeardAt(pc.Click), steer = mix.Steered;
                    long starved = mix.Starved;
                    int dry = pc.Cables[0].Starved;
                    mix.Stop();
                    steered.Add((off * 1e6).ToString("+0;-0") + " steered " + (steer * 1e6).ToString("+0;-0") + " ppm, " + (took * 1000).ToString("0") + " ms");
                    if (starved != 0 || dry != 0 || Math.Abs(steer / off - 1) > 0.05 || double.IsNaN(took) || took > 0.06)
                        throw new Exception("A mic " + (off * 1e6).ToString("0") + " ppm off wasn't matched: " + steered[steered.Count - 1] + ", " + starved + " frames short, " + dry + " short periods.");
                }
                checks.Add("PASS her voice in your mic matches a mic whose clock is 300 or 1500 ppm fast or slow against the cable's within 40 s (" + string.Join("; ", steered.ToArray()) + "), so it never runs dry or piles up");
                // A busy PC hands over the mic's packets up to 8 ms late. A late one waits on the cable's spare period, so nothing
                // runs short or clicks and the mic still sounds right.
                string shaken;
                {
                    double[] now = { 0 };
                    StandInDevices pc = MixPc(now, 48000, 44100);
                    pc.Late = 0.008;
                    pc.Fast = 1.0003;
                    pc.Phase = 0.0037;
                    pc.Click = (long)(19 * 44100 * pc.Fast);
                    MicMix mix = new MicMix(pc, delegate { return now[0]; }) { Call = true };
                    mix.Step();
                    RunMix(mix, pc, now, 20, null);
                    float[] got = pc.Cables[0].Kept;
                    double micLevel = ToneIn(got, 48000, 440, 10, 1), stray = StrayIn(got, 48000, 10, 1, 440);
                    int peak = 18 * 48000;
                    for (int i = peak; i < got.Length; i++) if (Math.Abs(got[i]) > Math.Abs(got[peak])) peak = i;
                    double took = pc.Cables[0].PlayedAt(peak) - pc.Opened[0].HeardAt(pc.Click);
                    long starved = mix.Starved;
                    int dry = pc.Cables[0].Starved;
                    mix.Stop();
                    shaken = "mic at " + micLevel.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) + ", stray tones " + Db(stray) + " dB, a click in " + (took * 1000).ToString("0") + " ms";
