                        using (CallFonts fonts = new CallFonts(scale))
                        {
                            CallView shown = new CallView { App = app, Listening = true, Discord = true, Who = app.Caption, Said = "We can hear you.", SaidAt = DateTime.UtcNow };
                            panel.Take(shown);
                            panel.CheckLayout(graphics);
                            if (panel.SourceName != app.Caption) throw new Exception("The call panel lost " + app.Caption + ".");
                            CallPanel.CheckCaption(graphics, new CallCaption(), fonts, new RectangleF(0, 0, 440 * scale, 54 * scale), scale, app.Caption);
                            CallPanel.Fits(graphics, CallPill.Speaker(app), fonts.Name, new RectangleF(0, 0, 162 * scale, 22 * scale), "call app in the pill");
                            if (app.Name == "Zoom" && (CallInk.Tip(2, shown) != "Turn Zoom off" || CallPanel.Status(shown) != "She hears you and Zoom.")) throw new Exception("Zoom's call panel still named Discord.");
                        }
                    }
                checks.Add("PASS the call mode row fits Advanced and Simple Settings at 100, 150 and 200 percent; fixed apps, Roblox and a cut long name fit the panel's tile with its menu chevron, the captions and the pill");
            }
            finally
            {
                picker.Dispose();
                mainframe.CloseMix();
                CallApps.Left(300, owner);
                CallApps.Sounds = soundsWas; CallApps.Processes = processesWas; CallApps.Everyday = everydayWas;
                CallApps.Restore(appsWas, lastWas);
                preferences.CallApp = appWas; preferences.CallAppName = nameWas; CallApps.Choose(appWas, nameWas);
                callSession.Change(onWas); preferences.CallMode = savedOn;
                callWho = whoWas; callSaid = saidWas; callSaidAt = saidAtWas;
                callCaptionRun = captionRunWas; callCaptionAt = captionAtWas;
                callCaptions.Clear(); foreach (CallPart part in captionsWas) callCaptions.Enqueue(part);
                simpleTest = simpleWas;
                SavePreferences(); mainframe.ShowCallApp(); mainframe.ShowSettings(settingsWas);
            }
        }

        private void SmokeLegacyAccessCodes(System.Collections.Generic.List<string> checks)
        {
            const string legacy = "CAPRI-0123-4567-89AB-CDEF";
            Cloud legacyCloud = new Cloud(legacy, "claude-sonnet-5-5");
            Cloud realKey = new Cloud("sk-ant-test", "claude-sonnet-5-5");
            if (Cloud.KindOf(legacy) != null || legacyCloud.Kind != null || legacyCloud.Claude
                || realKey.Kind != "anthropic" || !realKey.Claude || realKey.Model != "claude-sonnet-5-5"
                || Brain.ClaudeAddress(realKey.Key, "/messages") != Brain.Anthropic + "/v1/messages")
                throw new Exception("A legacy Capri access-code string was treated as a provider, or a user's Anthropic key changed.");
            checks.Add("PASS legacy Capri access-code strings are not recognized as providers; user-supplied Anthropic keys retain their model and use Anthropic directly");
        }

        internal void StartSmokeTest(string output, SmokeOptions options)
        {
            // A video full screen on another monitor is full screen to Windows too, and the test shouldn't depend on what's on the PC.
            Native.FakedGaming = false;
            // The checks hold her thread for seconds at a time, and Windows swaps a window that long unanswered for a ghost of it.
            // On 5 Nov dwm ghosted the minimised Mainframe again and again through the sections while it flipped between minimised
            // and restored from outside, so the test keeps Windows' ghosts out of it.
            Native.DisableProcessWindowsGhosting();
            Directory.CreateDirectory(output);
            SmokeRun.Start(output, options);
            Action<string> smokeStep = delegate(string name) { TestStep = name; File.WriteAllText(Path.Combine(output, "smoke-step.txt"), name); };
            smokeStep("startup");
            SmokeInput smokeInput = new SmokeInput();
            Application.AddMessageFilter(smokeInput);
            FormClosed += delegate { Application.RemoveMessageFilter(smokeInput); };
            Hands.Opened = delegate { return ""; };
            Func<string> findGame = Computer.GameOpen;
            Computer.GameOpen = delegate { return null; };
            Brain.LocalSees = delegate { return true; };
            Shown += delegate
            {
                System.Threading.Tasks.Task<System.Collections.Generic.List<string>> ocrCheck = null;
                if (SmokeRun.EnterSection("CheckOcr")) ocrCheck = System.Threading.Tasks.Task.Run(delegate
                {
                    System.Collections.Generic.List<string> ocrResults = new System.Collections.Generic.List<string>();
                    try { CheckOcr(ocrResults, output); }
                    finally { File.WriteAllLines(Path.Combine(output, "ocr-test.txt"), ocrResults); }
                    return ocrResults;
                });
                System.Windows.Forms.Timer test = new System.Windows.Forms.Timer();
                test.Interval = 500;
                int step = SmokeRun.NextStep;
                int thoughts = 0;
                byte[] tone = null;
                string voiced = null;
                ManualResetEvent voiceReady = new ManualResetEvent(false);
                double textAt = 0;
                bool voiceSent = false;
                double voiceDeadline = 0;
                int errorVoice = 0;
                Cloud errorRemote = null;
                ManualResetEvent replyReady = null;
                System.Collections.Generic.List<string> asked = new System.Collections.Generic.List<string>();
                HttpListener fakeAgent = null;
                string agentHost = null;
                int agentPatience = Voice.Patience;
                ManualResetEvent agentMade = new ManualResetEvent(false);
                string madeAgent = null;
                int agentThread = 0;
                bool agentTimeouts = false;
                Exception agentProblem = null;
                Exception agentServerProblem = null;
                CancellationTokenSource agentStop = new CancellationTokenSource();
                bool agentStarted = false;
                double agentDeadline = 0;
                string agentRequest = "starting the listener";
                Action<string> handsRun = null;
                Func<System.Collections.Generic.List<InstalledApp>> handsCatalog = null;
                Form backdrop = null;
                System.Collections.Generic.List<string> earsLog = new System.Collections.Generic.List<string>();
                Func<short[], string> realHearing = null;
                Func<Dictation> realMake = null;
                string[] realEars = null;
                ManualResetEvent realEarsDone = new ManualResetEvent(false);
                Func<string, string> realThink = null;
                System.Collections.Generic.List<string> glanceAsked = new System.Collections.Generic.List<string>();
                System.Net.Sockets.TcpListener glanceFake = null;
                Action resetGlance = null;
                double glanceDeadline = 0;
                double linkDeadline = 0;
                short[][] earLine = null;
                System.Collections.Generic.List<string> checks = SmokeRun.Checks();
                bool sectionsRun = false;
                FormClosed += delegate
                {
                    agentStop.Cancel();
                    if (fakeAgent != null) fakeAgent.Close();
                    test.Stop();
                    test.Dispose();
                };
                bool stepping = false;
                test.Tick += delegate
                {
                    // A step that waits with DoEvents must not start the next tick inside itself.
                    if (stepping) return;
                    stepping = true;
                    try
                    {
                        if (ocrCheck != null)
                        {
                            if (!ocrCheck.IsCompleted) return;
                            try
                            {
                                checks.AddRange(ocrCheck.GetAwaiter().GetResult());
                                using (Bitmap uiOcr = new Bitmap(400, 200))
                                using (Font uiFont = new Font("Arial", 28, FontStyle.Regular, GraphicsUnit.Pixel))
                                {
                                    using (Graphics uiDrawing = Graphics.FromImage(uiOcr)) { uiDrawing.Clear(Color.White); uiDrawing.DrawString("Capri", uiFont, Brushes.Black, 30, 40); }
                                    Stopwatch uiTime = Stopwatch.StartNew();
                                    bool uiReady = Ocr.Ready;
                                    if (Ocr.Words(uiOcr, 1, 10000).Count != 0 || Ocr.Lines(uiOcr, 1, 10000).Count != 0 || Ocr.Sharpened(uiOcr, new Rectangle(Point.Empty, uiOcr.Size), 4) != null || uiTime.ElapsedMilliseconds > 250)
                                        throw new Exception("OCR waited or processed a bitmap on the UI thread.");
                                    checks.Add("PASS OCR runs on a worker; its synchronous calls return immediately on the UI thread (engine ready: " + uiReady + ")");
                                }
                            }
                            catch (Exception error) { TestFailed = true; checks.Add("FAIL section CheckOcr: " + error.Message); }
                            finally { ocrCheck = null; SmokeRun.LeaveSection("CheckOcr", checks); }
                        }
                        if (!sectionsRun)
                        {
                            RunSmokeSections(checks, output, findGame);
                            SmokeRun.ValidateSelection(checks);
                            sectionsRun = true;
                        }
