                    }
                    catch (Exception error)
                    {
                        TestFailed = true;
                        SmokeRun.StepFailed(step, error, checks);
                    }
                    finally { stepping = false; }
                };
                test.Start();
            };
        }

        private sealed class StageLog : IGameStage
        {
            internal readonly System.Collections.Generic.List<string> Shown = new System.Collections.Generic.List<string>();
            public void Say(string line) { lock (Shown) Shown.Add("say " + line); }
            public void Hear(string words, bool thinking) { lock (Shown) Shown.Add("hear " + words + " " + thinking); }
            public void Mood(GameMood mood) { lock (Shown) Shown.Add("mood " + mood); }
        }

        private static void SmokeMomentComments(System.Collections.Generic.List<string> checks)
        {
            Func<bool> momentSettingWas = Commentary.Moments, momentFreeWas = Commentary.Free, momentSeesWas = Commentary.Sees;
            Func<string> momentKeepWas = Commentary.Keep, momentGameWas = Commentary.Game;
            Func<int> momentClockWas = Commentary.Clock;
            Func<string, string, byte[][], string> momentSeeWas = Commentary.See;
            Action<string, string, GameMood> momentSpeakWas = Commentary.Speak;
            IGameStage momentStageWas = Commentary.Stage;
            int momentPaceWas = Commentary.Pace, momentLateWas = Commentary.Late;
            string momentLogWas = Brain.LogPath;
            string momentLog = Path.Combine(Path.GetTempPath(), "capri-moment-check-" + Guid.NewGuid().ToString("N") + ".log");
            ManualResetEvent momentGo = new ManualResetEvent(false);
            Action<bool, string> momentMust = delegate(bool fine, string why) { if (!fine) throw new Exception(why); };
            Action<Func<bool>> momentWait = delegate(Func<bool> done)
            {
                Stopwatch momentWaiting = Stopwatch.StartNew();
                while (!done() && momentWaiting.ElapsedMilliseconds < 4000) Thread.Sleep(5);
                momentMust(done(), "A big moment check did not finish.");
            };
            try
            {
                bool momentFlag;
                string momentLine = "Skeleton got you from across the ravine.";
                foreach (string momentTagged in new[] { "[clip] " + momentLine, "Skeleton got you [clip] from across the ravine.", momentLine + " [CLIP] [clip]" })
                    momentMust(Commentary.Line(momentTagged, new string[0], out momentFlag) == momentLine && momentFlag, "A clip tag leaked into her line or was lost.");
                momentMust(Commentary.Line("[clip]", new string[0], out momentFlag) == "" && momentFlag, "A tag on its own was spoken or lost.");
                momentMust(Commentary.Line(momentLine, new string[0], out momentFlag) == momentLine && !momentFlag, "An unflagged line changed or asked for a clip.");
                foreach (string momentFiltered in new[] { "[clip] SKIP", "[clip] Nice one!", "[clip] Nothing's really changed between those two shots." })
                    momentMust(Commentary.Line(momentFiltered, new string[0], out momentFlag) == "" && momentFlag, "A filtered reaction lost its clip flag or was spoken.");
                momentMust(Commentary.Line("[clip] " + momentLine, new[] { momentLine }, out momentFlag) == "" && momentFlag, "A repeated reaction lost its clip flag.");
                checks.Add("PASS big moment tags: start, middle, end and repeated tags are stripped, a tag alone stays silent, unflagged text is untouched, and filtered reactions retain the flag");

                bool momentSetting = false, momentClips = false;
                Commentary.Moments = delegate { return momentSetting && momentClips; };
                string momentRules = Commentary.Rules;
                for (int momentCombination = 0; momentCombination < 4; momentCombination++)
                {
                    momentSetting = (momentCombination & 1) != 0;
                    momentClips = (momentCombination & 2) != 0;
                    momentMust(momentSetting && momentClips ? Commentary.Rules.StartsWith(momentRules, StringComparison.Ordinal) && Commentary.Rules.Contains("[clip]") : Commentary.Rules == momentRules && !Commentary.Rules.Contains("[clip]"), "The clip instruction did not follow both switches.");
                }
                checks.Add("PASS big moment rules: only Save big moments with clips on adds the instruction to judge and flag a moment");

                int momentNow = 1000000, momentCalls = 0, momentDeciding = 0, momentFailure = 0;
                int momentUi = Thread.CurrentThread.ManagedThreadId;
                bool momentWorker = false;
                string momentAnswer = "", momentSystem = "";
                System.Collections.Generic.List<string> momentSpoken = new System.Collections.Generic.List<string>();
                StageLog momentStage = new StageLog();
                Func<int> momentShown = delegate { lock (momentStage.Shown) return momentStage.Shown.Count; };
                Func<int> momentSaid = delegate { lock (momentSpoken) return momentSpoken.Count; };
                Commentary.Reset();
                Commentary.Pace = Commentary.Events;
                Commentary.Late = 6000;
                Commentary.Stage = momentStage;
                Commentary.Game = delegate { return "Minecraft"; };
                Commentary.Free = delegate { return true; };
                Commentary.Sees = delegate { return true; };
                Commentary.Clock = delegate { return momentNow; };
                Commentary.See = delegate(string momentPrompt, string momentAsk, byte[][] momentFrames)
                {
                    momentDeciding = Thread.CurrentThread.ManagedThreadId;
                    momentSystem = momentPrompt;
                    return momentAnswer;
                };
                Commentary.Speak = delegate(string momentSaying, string momentKind, GameMood momentMood) { lock (momentSpoken) momentSpoken.Add(momentSaying); };
                Commentary.Keep = delegate
                {
                    momentWorker = Thread.CurrentThread.IsBackground && Thread.CurrentThread.ManagedThreadId != momentUi && Thread.CurrentThread.ManagedThreadId != momentDeciding;
                    Interlocked.Increment(ref momentCalls);
                    if (!momentGo.WaitOne(4000)) throw new Exception("The moment save was not released.");
                    if (momentFailure == 2) throw new IOException("moment check exception");
                    return momentFailure == 1 ? "moment check failed" : null;
                };
                Action<string, int> momentReact = delegate(string momentReply, int momentAdvance)
                {
                    momentAnswer = momentReply;
                    momentNow = unchecked(momentNow + momentAdvance);
                    momentMust(Commentary.Trigger("kill", null, new byte[] { 1, 2, 3 }, null), "A big moment did not get a look.");
                    momentWait(delegate { return !Commentary.Thinking; });
                };
                momentReact("[clip] That creeper waited for you specifically.", 0);
                momentWait(delegate { return Interlocked.CompareExchange(ref momentCalls, 0, 0) == 1 && momentSaid() == 1; });
                momentMust(momentWorker && momentSystem.Contains("[clip]") && momentShown() == 0, "A save ran on her UI or deciding thread, or announced before it finished.");
                momentReact("Skeleton stole your diamonds. [clip]", 10000);
                momentWait(delegate { return momentSaid() == 2; });
                momentReact("Lava ate the whole inventory.", 10000);
                momentWait(delegate { return momentSaid() == 3; });
                momentMust(momentCalls == 1 && momentShown() == 0, "A nearby flag extended a pending save, or an unflagged line saved.");
                momentGo.Set();
                momentWait(delegate { return momentShown() == 1; });
                momentReact("[clip]", 10000);
                momentWait(delegate { return momentShown() == 2; });
                momentMust(momentCalls == 2 && momentSaid() == 3, "A tag alone spoke, or a new moment at 30 seconds did not save.");
                lock (momentStage.Shown)
                    foreach (string momentNotice in momentStage.Shown) momentMust(momentNotice == "say > sys: clipped", "A saved moment had more than a quiet HUD notice.");
                lock (momentSpoken)
                    foreach (string momentVoice in momentSpoken) momentMust(!momentVoice.Contains("[clip]") && !momentVoice.Contains("sys:"), "A tag or clip notice was spoken.");
                checks.Add("PASS big moment saves: a flag calls Keep once on a separate worker, flags ten seconds apart save once without extending, an unflagged line does not save, pending saves let comments continue, and a tag alone saves at 30 seconds with only a quiet HUD notice after success");

                bool momentCanLog = true;
                try { File.WriteAllText(momentLog, ""); }
                catch (IOException) { momentCanLog = false; }
                catch (UnauthorizedAccessException) { momentCanLog = false; }
                if (!momentCanLog) checks.Add("LIMIT big moment failure checks need a writable temporary log");
                else
                {
                    Brain.LogPath = momentLog;
                    for (int momentFault = 1; momentFault <= 2; momentFault++)
                    {
                        momentFailure = momentFault;
                        momentReact("[clip]", 30000);
                        string momentExpected = momentFault == 1 ? "moment check failed" : "moment check exception";
                        momentWait(delegate
                        {
                            try { return File.ReadAllText(momentLog).Contains(momentExpected); }
                            catch (IOException) { return false; }
                        });
                        momentMust(momentShown() == 2 && momentSaid() == 3, "A failed automatic save interrupted them.");
                    }
                    momentReact("Obsidian saved your last heart.", 10000);
                    momentWait(delegate { return momentSaid() == 4; });
                    momentFailure = 0;
                    momentReact("[clip]", 20000);
                    momentWait(delegate { return momentShown() == 3; });
                    momentMust(momentCalls == 5 && momentSaid() == 4, "A failed save stopped the next comment or clip.");
                    checks.Add("PASS big moment failures: returned errors and thrown exceptions are logged without a HUD or spoken notice, and the next comment and save still run");
                }
                int momentBeforeOff = momentCalls;
                momentSetting = false;
                momentReact("[clip]", 30000);
                momentMust(!momentSystem.Contains("[clip]") && momentCalls == momentBeforeOff, "Save big moments off still asked for or saved a moment.");
                momentSetting = true;
                momentClips = false;
                momentReact("[clip]", 30000);
                momentMust(!momentSystem.Contains("[clip]") && momentCalls == momentBeforeOff, "Clips off still asked for or saved a moment.");
                momentClips = true;
                Commentary.Pace = Commentary.Off;
                momentMust(!Commentary.Trigger("kill", null, null, null) && momentCalls == momentBeforeOff, "Comments off still judged or saved a moment.");
                checks.Add("PASS big moments stay off when either switch is off, and comments off means no judging or automatic saves");
            }
            finally
            {
                momentGo.Set();
                Commentary.Moments = momentSettingWas;
                Commentary.Keep = momentKeepWas;
                Commentary.Free = momentFreeWas;
                Commentary.Sees = momentSeesWas;
                Commentary.Game = momentGameWas;
                Commentary.Clock = momentClockWas;
                Commentary.See = momentSeeWas;
                Commentary.Speak = momentSpeakWas;
                Commentary.Stage = momentStageWas;
                Commentary.Pace = momentPaceWas;
                Commentary.Late = momentLateWas;
                Commentary.Reset();
                Brain.LogPath = momentLogWas;
                try { File.Delete(momentLog); }
                catch (IOException) { }
                catch (UnauthorizedAccessException) { }
            }
        }

        private void SmokeMomentSettings(System.Collections.Generic.List<string> checks)
        {
            bool momentClipsWereOn = preferences.ClipGames, momentsWereOn = preferences.ClipMoments;
            bool momentPageWas = mainframe.SettingsShown;
            try
            {
                using (MemoryStream momentOld = new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{}")))
                    if (((Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(momentOld)).ClipMoments || new Preferences().ClipMoments)
                        throw new Exception("Save big moments did not start off in new or older settings.");
                preferences.ClipGames = preferences.ClipMoments = false;
                mainframe.Sync();
                mainframe.ShowSettings(true);
                mainframe.FlipClipMoments();
                Preferences momentSaved = LoadPreferences();
                if (!preferences.ClipMoments || !preferences.ClipGames || !mainframe.ClipMomentsShown || !mainframe.ClipsShown || !momentSaved.ClipMoments || !momentSaved.ClipGames)
                    throw new Exception("Save big moments did not turn on, save and show both switches.");
                mainframe.FlipClipMoments();
                momentSaved = LoadPreferences();
                if (preferences.ClipMoments || mainframe.ClipMomentsShown || momentSaved.ClipMoments || !momentSaved.ClipGames)
                    throw new Exception("Save big moments did not switch off and save with clips still on.");
                mainframe.FlipClipMoments();
                mainframe.FlipClips();
                momentSaved = LoadPreferences();
                if (preferences.ClipGames || preferences.ClipMoments || mainframe.ClipsShown || mainframe.ClipMomentsShown || momentSaved.ClipGames || momentSaved.ClipMoments)
                    throw new Exception("Switching clips off left Save big moments on.");
                string momentCrowded = mainframe.Overlap() ?? mainframe.Outside();
                if (momentCrowded != null) throw new Exception("The big moment switch crowded Settings: " + momentCrowded);
                string momentHelp = SelfKnow.Matching("How does Save big moments work?");
                if (momentHelp == null || !momentHelp.StartsWith("Save big moments:", StringComparison.Ordinal) || !momentHelp.Contains("Comments off outside Gaming Mode") || !momentHelp.Contains("Videos\\Capri Clips"))
                    throw new Exception("Save big moments did not explain its switch, comments or storage.");
                checks.Add("PASS Save big moments starts off, saves and shows both switches when enabled, leaves manual clips on when disabled, follows Clip my games off, fits Settings without overlaps, and has its own help topic");
            }
            finally
            {
                preferences.ClipGames = momentClipsWereOn;
                preferences.ClipMoments = momentsWereOn;
                clips.Enable(!testing && preferences.ClipGames);
                SavePreferences();
                mainframe.Sync();
                mainframe.ShowSettings(momentPageWas);
            }
        }

        // Talking to her mid-job and her game comments, with fake heads, keys, mics and frames. Nothing here presses a key, moves
        // the mouse, opens a mic or plays a sound, so it's safe beside anything else on the screen.
        private void ListenCapriChecks(string output, System.Collections.Generic.List<string> checks)
        {
            string[] namedLines = { "what's the weather capri", "capri what time is it", "hey capri open spotify", "i was telling capri about it" };
            string[] otherLines = { "what's for dinner", "open spotify", "i love pasta", "caprese", "capricorn", "decapri", "capri123" };
            foreach (string namedLine in namedLines) if (!Hands.HeardName(namedLine)) throw new Exception("Listen for Capri missed " + namedLine);
            foreach (string otherLine in otherLines) if (Hands.HeardName(otherLine)) throw new Exception("Listen for Capri matched " + otherLine);
            foreach (string first in new[] { "c", "k" })
                foreach (string middle in new[] { "ap", "app" })
                    foreach (string last in new[] { "ri", "ree", "rie", "ry" })
                        if (!Hands.HeardName("hello " + first + middle + last + "!")) throw new Exception("Listen for Capri missed a spelling.");
            foreach (string script in new[] { "Capri", "капри", "カプリ", "卡普里", "카프리", "كابري", "कैप्री" })
                if (!Hands.HeardName("hello " + script + "!") || !Hands.HeardName(script.ToUpperInvariant())) throw new Exception("Listen for Capri missed " + script);
            foreach (string joinedName in new[] { "カプリ今何時", "卡普里现在几点", "카프리야 안녕", "Kopri, hi", "Recovery, hi", "CAPRI SUN", "Capri's here" })
                if (!Hands.HeardName(joinedName)) throw new Exception("Listen for Capri missed " + joinedName);
            if (SelfKnow.Matching("How does Listen for Capri work?") == null) throw new Exception("Listen for Capri has no help topic.");
            checks.Add("PASS Listen for Capri matches her name anywhere, all sixteen c/k and single/double p spellings, Kopri and Recovery from her recognition checks, all six scripts, adjacent Chinese/Japanese words and Korean particles; Capri Sun counts, caprese and capricorn do not");

            bool listenWas = preferences.ListenCapri, toldWas = preferences.ListenCapriTold, freeToldWas = preferences.FreeChatTold;
            bool quietWas = preferences.Quiet, silentWas = preferences.Silent, freeChatWas = FreeChatOn;
            int typingWas = preferences.Typing;
            bool? ownWas = ownEarsTest;
            Func<Dictation> dictationWas = Dictation.Make;
            Func<string, string> thinkWas = Think;
            Func<string, byte[]> speakWas = Speak, freeSpeakWas = FreeSpeak;
            Func<short[], string> hearingWas = Hearing.Run;
            Job runningWas = job;
            string workingWas = working, transcriptWas = Brain.TranscriptPath;
            bool keepingWas = Brain.Keeping, pageWas = mainframe.SettingsShown;
            bool heyWas = preferences.HeyCapri, wakeChecksWas = wakeChecks, wakeOpenWas = wakeOpen, wakeMutedWas = wakeMicMuted, shushedWas = shushed;
            Brain keeperWas = Brain.Keeper;
            Action<string> stopWas = stopTest;
            IGameStage stageWas = Commentary.Stage;
            StageLog nameStage = new StageLog();
            System.Collections.Generic.List<string> reached = new System.Collections.Generic.List<string>();
            int nameCalls = 0, nameSpeaks = 0, nameStops = 0;
            Func<int, short[]> nameWave = delegate(int amplitude)
            {
                short[] waveSamples = new short[Ears.Chunk];
                for (int waveAt = 0; waveAt < waveSamples.Length; waveAt++) waveSamples[waveAt] = (short)(Math.Sin(waveAt * Math.PI / 40) * amplitude);
                return waveSamples;
            };
            Action<Func<bool>> waitName = delegate(Func<bool> arrived)
            {
                Stopwatch nameWait = Stopwatch.StartNew();
                while (!arrived() && nameWait.ElapsedMilliseconds < 4000) { Application.DoEvents(); Thread.Sleep(5); }
                if (!arrived()) throw new Exception("Listen for Capri's stand-in reply did not arrive.");
            };
            try
            {
                StopChat();
                CloseTalk();
                job = null;
                working = null;
                preferences.ListenCapri = false;
                preferences.ListenCapriTold = false;
                preferences.FreeChatTold = true;
                preferences.Quiet = preferences.Silent = true;
                preferences.Typing = 2;
                FreeChatOn = true;
                ownEarsTest = false;
                Brain.TranscriptPath = Path.Combine(output, "listen-capri");
                Directory.CreateDirectory(Brain.TranscriptPath);
                Brain.Keeping = true;
                Brain.Keeper = null;
                Commentary.Stage = nameStage;
                StandInDictation nameDictation = new StandInDictation();
                Dictation.Make = delegate { return nameDictation; };
                Think = delegate(string fullSentence) { lock (reached) reached.Add(fullSentence); Interlocked.Increment(ref nameCalls); return "Heard the whole sentence."; };
                Speak = delegate { Interlocked.Increment(ref nameSpeaks); return null; };
                FreeSpeak = null;
                stopTest = delegate { nameStops++; };
                using (MemoryStream oldName = new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{}")))
                    if (((Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(oldName)).ListenCapri || new Preferences().ListenCapri) throw new Exception("Listen for Capri did not start off.");
                mainframe.Sync();
                mainframe.ShowSettings(true);
                mainframe.FlipListenCapri();
                if (!preferences.ListenCapri || !mainframe.ListenCapriShown || !LoadPreferences().ListenCapri) throw new Exception("Listen for Capri did not save or show its switch.");
                string nameLayout = mainframe.Overlap() ?? mainframe.Outside();
                if (nameLayout != null) throw new Exception("Listen for Capri crowded Settings: " + nameLayout);
                ToggleChat();
                if (!local || !chatting || agent != null || !earsReady || !pill.ListenForName || mainframe.VoiceNoteText != LocalListening + " Say my name anywhere in your sentence, then just keep talking.") throw new Exception("Listen for Capri did not open its own ears and explain itself once: local " + local + ", chatting " + chatting + ", agent " + (agent != null) + ", ears ready " + earsReady + ", pill " + pill.ListenForName + ", note " + mainframe.VoiceNoteText);
                int onceAsked = asking;
                string onceReply = reply;
                EarsReady(false);
                if (asking != onceAsked || reply != onceReply || mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("Listen for Capri repeated its notice.");
                ShowVoice();
                if (mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("The voice picker hid Listen for Capri's status.");
                CloseTalk();
                Func<string> nameState = delegate
                {
                    System.Text.StringBuilder state = new System.Text.StringBuilder();
                    state.Append(asking).Append('|').Append(reply).Append('|').Append(heard).Append('|').Append(talkState).Append('|').Append(box.Visible).Append('|').Append(box.Prompt).Append('|').Append(speech).Append('|').Append(voiceUntil).Append('|').Append(bargeIns).Append('|').Append(mainframe.VoiceNoteText).Append('|').Append(nameCalls).Append('|').Append(nameSpeaks).Append('|').Append(agentComment).Append('|').Append(dockWords);
                    foreach (ChatMessage message in brain.History) state.Append('|').Append(message.Role).Append(':').Append(message.Content);
                    foreach (string transcriptFile in Directory.GetFiles(Brain.TranscriptPath)) state.Append('|').Append(transcriptFile).Append(':').Append(File.ReadAllText(transcriptFile));
                    foreach (string stageLine in nameStage.Shown) state.Append('|').Append(stageLine);
                    return state.ToString();
                };
                foreach (bool busyEars in new[] { false, true })
                {
                    if (busyEars) { job = new Job("stand-in job"); working = "Working."; jobEars = true; }
                    foreach (string ignoredLine in otherLines)
                    {
                        string unchanged = nameState();
                        nameDictation.Partial(ignoredLine);
                        nameDictation.Heard(ignoredLine);
                        transcribing = true;
                        HeardLocally(chatTicket, asking, ignoredLine, null);
                        ChatHeard(ignoredLine);
                        HeardLevel(0.5);
                        if (nameState() != unchanged || transcribing || earsShut) throw new Exception("Background speech changed her state: " + ignoredLine);
                    }
                }
                checks.Add("PASS Listen for Capri drops dinner, open spotify, pasta and near-name words at Windows dictation, offline and chat callbacks, including job ears, without changing asking, reply, heard, talkState, bubble visibility, history, transcript, voice status, partial captions, brain calls or speech");
                foreach (string stopLine in new[] { "stop", "cancel", "enough", "never mind", "hands off", "arrête", "стоп" })
                {
                    int stopsBefore = nameStops;
                    HeardLocally(chatTicket, asking, stopLine, null);
                    if (nameStops != stopsBefore + 1) throw new Exception("A stop without her name did not reach the job: " + stopLine);
                }
                job = null;
                working = null;
                jobEars = false;
                CloseTalk();
                foreach (string deliveredLine in namedLines)
                {
                    int callsBefore = nameCalls;
                    HeardLocally(chatTicket, asking, deliveredLine, null);
                    waitName(delegate { return nameCalls == callsBefore + 1 && reply == "Heard the whole sentence."; });
                    lock (reached) if (reached[reached.Count - 1] != deliveredLine) throw new Exception("Her ears cut a sentence at her name.");
                    CloseTalk();
                    nameDictation.Heard(deliveredLine);
                    waitName(delegate { return nameCalls == callsBefore + 2 && reply == "Heard the whole sentence."; });
                    lock (reached) if (reached[reached.Count - 1] != deliveredLine) throw new Exception("Windows speech cut a sentence at her name.");
                    CloseTalk();
                }
                // Those lines opened her name's chat, and what follows is about her ears with none going.
                CloseNameChat();
                int pushedCalls = nameCalls;
                pushing = true;
                nameDictation.Heard("i love pasta");
                waitName(delegate { return nameCalls == pushedCalls + 1 && reply == "Heard the whole sentence."; });
                pushing = false;
                CloseTalk();
                PushHeard("what's for dinner", null);
                waitName(delegate { return nameCalls == pushedCalls + 2 && reply == "Heard the whole sentence."; });
                if (mainframe.VoiceNoteText != "Listening for Capri.") throw new Exception("Push to talk hid Listen for Capri's status.");
                CloseTalk();
                voiceUntil = clock.Elapsed.TotalSeconds + 30;
                talkState = TalkState.Talking;
                string talkingState = nameState();
                HeardLocally(chatTicket, asking, "i love pasta", null);
                if (nameState() != talkingState) throw new Exception("Background speech stopped her voice.");
                HeardLocally(chatTicket, asking, "stop", null);
                if (voiceUntil != 0 || talkState != TalkState.Off) throw new Exception("Stop without her name left her talking.");
                voiceUntil = clock.Elapsed.TotalSeconds + 30;
                talkState = TalkState.Talking;
                nameDictation.Heard("stop");
                if (voiceUntil != 0 || talkState != TalkState.Off) throw new Exception("Windows speech needed her name to stop her talking.");
                Func<int, Func<bool>, PcSound> captureWas = PcEars.Capture;
                Func<bool> speakingWas = PcEars.Speaking;
                try
                {
                    PcEars.Speaking = delegate { return false; };
                    foreach (string listeningStop in new[] { "stop listening", "quit listening", "cancel listening", "enough listening" })
                        for (int stopRoute = 0; stopRoute < 3; stopRoute++)
                        {
                            voiceUntil = clock.Elapsed.TotalSeconds + 30;
                            talkState = TalkState.Talking;
                            PcEars.Capture = delegate(int stopSeconds, Func<bool> wasStopped)
                            {
                                if (stopRoute == 0) HeardLocally(chatTicket, asking, listeningStop, null);
                                else if (stopRoute == 1) nameDictation.Heard(listeningStop);
                                else ChatHeard(listeningStop);
                                if (!wasStopped()) throw new Exception("Listen for Capri swallowed " + listeningStop);
                                return new PcSound();
                            };
                            PcEars.Text(1, null);
                        }
                }
                finally { PcEars.Capture = captureWas; PcEars.Speaking = speakingWas; CloseTalk(); }
                checks.Add("PASS Listen for Capri sends all four requested sentences whole through both local recognition paths; stop words still stop a stand-in job and her speech, and held or released push-to-talk needs no name");
                checks.Add("PASS stop, quit, cancel and enough listening reach an active PC sound capture through every speech callback without her name, even while she talks");

                Dictation sampleDictation = dictation;
                dictation = null;
                try
                {
                    int decodedLines = 0;
                    string decodedWords = "i love pasta";
                    Hearing.Run = delegate { Interlocked.Increment(ref decodedLines); return decodedWords; };
                    foreach (bool sayStop in new[] { false, true })
                    {
                        decodedWords = sayStop ? "stop" : "i love pasta";
                        CloseTalk();
                        talkState = TalkState.Talking;
                        voiceUntil = clock.Elapsed.TotalSeconds + 30;
                        spokenAt = clock.Elapsed.TotalSeconds;
                        spokenLevels = new double[400];
                        for (int levelAt = 0; levelAt < spokenLevels.Length; levelAt++) spokenLevels[levelAt] = 0.1;
                        talkOver.Reset();
                        nameOver = false;
                        room = -1;
                        lineAt = -100;
                        noiseHold = false;
                        CheckEars(clock.Elapsed.TotalSeconds);
                        int audioAsked = asking, audioBarges = bargeIns, audioCalls = nameCalls, decodedBefore = decodedLines;
                        double audioUntil = voiceUntil;
                        string audioNote = mainframe.VoiceNoteText;
                        for (int echoAt = 0; echoAt < 6; echoAt++) Gather(nameWave(1200));
                        for (int humanAt = 0; humanAt < 8; humanAt++) Gather(nameWave(humanAt % 2 == 0 ? 14000 : 20000));
                        for (int tailAt = 0; tailAt < 12; tailAt++) Gather(nameWave(1200));
                        if (asking != audioAsked || bargeIns != audioBarges || voiceUntil != audioUntil || mainframe.VoiceNoteText != audioNote) throw new Exception("A sound interrupted her before its words were checked.");
                        waitName(delegate { return decodedLines == decodedBefore + 1 && !transcribing; });
                        if (nameCalls != audioCalls || chatting == false || earsReady == false || (sayStop ? voiceUntil != 0 || bargeIns != audioBarges + 1 : voiceUntil != audioUntil || bargeIns != audioBarges || asking != audioAsked)) throw new Exception("Her audio handoff missed a stop or reacted to background speech.");
                    }
                    CloseTalk();
                    decodedWords = "i love pasta";
                    int pushedAudio = nameCalls;
                    PushStart();
                    for (int pushChunk = 0; pushChunk < 5; pushChunk++) Listen(nameWave(10000));
                    PushDone();
                    waitName(delegate { return nameCalls == pushedAudio + 1 && reply == "Heard the whole sentence."; });
                    CloseTalk();
                }
                finally { dictation = sampleDictation; Hearing.Run = hearingWas; nameOver = false; }
                checks.Add("PASS Listen for Capri gathers and transcribes a stand-in line over her own speech without an early interruption or Hearing you flash; unnamed chatter leaves her speaking, stop interrupts after recognition, and a captured push-to-talk line reaches her after key release");
                mainframe.FlipListenCapri();
                if (preferences.ListenCapri || mainframe.ListenCapriShown || LoadPreferences().ListenCapri || pill.ListenForName) throw new Exception("Listen for Capri did not switch off.");
                foreach (string ordinaryLine in new[] { "what's for dinner", "open spotify", "i love pasta" })
                {
                    int ordinaryBefore = nameCalls;
                    HeardLocally(chatTicket, asking, ordinaryLine, null);
                    waitName(delegate { return nameCalls == ordinaryBefore + 1 && reply == "Heard the whole sentence."; });
                    CloseTalk();
                }
                preferences.ListenCapri = true;
                preferences.Quiet = preferences.Silent = false;
                Func<string, byte[]> freeNameVoice;
                if (PickVoice(false, out freeNameVoice) != Speak || !ChatUsesEars(true, false, false, true) || ChatUsesEars(false, false, false, true) || !ChatUsesEars(false, true, false, true) || !ChatUsesEars(false, false, false, false)) throw new Exception("Listen for Capri changed her voice pick or the old chat routes.");
                if (TalkPill.Label(2, true, false, true) != "CAPRI" || TalkPill.Label(2, true, true, true) != "MUTED" || TalkPill.Label(2, false, false, true) != "TALK") throw new Exception("Her name pill lost the chat or mute state.");
                checks.Add("PASS Listen for Capri is off in new and old settings, saves both ways, fits Settings and has help; on it uses local ears with the selected ElevenLabs reply voice, off the old routes and ordinary sentences work, and the pill keeps mute and closed-chat labels");
                StopChat();
                CloseTalk();
                preferences.ListenCapri = false;
                chatting = true;
                local = false;
                agent = new Agent();
                ToggleListenCapri();
                if (!local || !chatting || agent != null || !pill.ListenForName) throw new Exception("Turning Listen for Capri on left the server voice link open.");
                StopChat();
                CloseTalk();
                preferences.HeyCapri = true;
                preferences.Silent = true;
                wakeChecks = true;
                wakeOpen = true;
                wakeMicMuted = shushed = false;
                HeardHeyCapri();
                wakeChecks = false;
                if (!chatting || !local || wakeOpen || !pill.ListenForName) throw new Exception("Hey Capri did not open chat under Listen for Capri.");
                string awakeState = nameState();
                nameDictation.Heard("i love pasta");
                if (!chatting || nameState() != awakeState) throw new Exception("Chat closed or answered background speech after Hey Capri.");
                ToggleChat();
                if (chatting) throw new Exception("The talk key did not close chat after Hey Capri.");
                checks.Add("PASS enabling Listen for Capri hands a stand-in ElevenLabs link to her local ears; Hey Capri still opens chat with both switches on, background speech leaves it open and unchanged, and the talk key closes it");
                // Her ears stay open on their own, she carries on around them, and only the talk key keeps them shut.
                CloseTalk();
                preferences.Silent = preferences.HeyCapri = false;
                listenAt = 0;
                KeepListening(1);
                bool closedHeld = !chatting && earsClosed;
                earsClosed = false;
                hidden = true;
                KeepListening(1);
                bool hiddenHeld = !chatting;
                hidden = false;
                preferences.Quiet = true;
                KeepListening(1);
                bool quietHeld = chatting && local;
                CloseTalk();
                StopChat();
                preferences.Quiet = false;
                earsClosed = false;
                listenAt = 0;
                KeepListening(1);
                bool openedAlone = chatting && local && !InChat && pill.ListenForName;
                CloseTalk();
                StopChat();
                KeepListening(2);
                bool retryHeld = !chatting;
                listenAt = 0;
                KeepListening(2);
                bool cameBack = chatting && local;
                CloseTalk();
                StopChat();
                talkState = TalkState.Thinking;
                working = "Working.";
                listenAt = 0;
                KeepListening(2);
                bool jobListened = chatting && local;
                working = null;
                talkState = TalkState.Off;
                CloseTalk();
                preferences.ListenCapri = false;
                bool chatCounts = InChat;
                preferences.ListenCapri = true;
                ToggleChat();
                bool shutAgain = !chatting && earsClosed;
                ToggleListenCapri();
                ToggleListenCapri();
                bool switchOpens = !earsClosed && listenAt == 0;
                CloseTalk();
                if (!closedHeld || !hiddenHeld || !quietHeld || !openedAlone || !retryHeld || !cameBack || !jobListened || !chatCounts || !shutAgain || !switchOpens) throw new Exception("Listen for Capri's ears did not look after themselves: closed " + closedHeld + ", hidden " + hiddenHeld + ", quiet " + quietHeld + ", opened " + openedAlone + ", retry " + retryHeld + ", back " + cameBack + ", chat " + chatCounts + ", shut " + shutAgain + ", switch " + switchOpens);
                checks.Add("PASS Listen for Capri opens her ears with no key, brings them back after anything but the talk key, waits while she's hidden, listens the same with ElevenLabs off, doesn't count as a conversation, and its switch reopens them");
                checks.Add("LIMIT Listen for Capri's real microphone, how each recogniser spells her name, and ElevenLabs credit billing need a live voice check");
            }
            finally
            {
                pushing = false;
                jobEars = false;
                StopChat();
                CloseTalk();
                preferences.ListenCapri = listenWas;
                preferences.ListenCapriTold = toldWas;
                preferences.FreeChatTold = freeToldWas;
                preferences.Quiet = quietWas;
                preferences.Silent = silentWas;
                preferences.Typing = typingWas;
                FreeChatOn = freeChatWas;
                ownEarsTest = ownWas;
                Dictation.Make = dictationWas;
                Think = thinkWas;
                Speak = speakWas;
                FreeSpeak = freeSpeakWas;
                Hearing.Run = hearingWas;
                job = runningWas;
                working = workingWas;
                Brain.TranscriptPath = transcriptWas;
                Brain.Keeping = keepingWas;
                Brain.Keeper = keeperWas;
                preferences.HeyCapri = heyWas;
                wakeChecks = wakeChecksWas;
                wakeOpen = wakeOpenWas;
                wakeMicMuted = wakeMutedWas;
                shushed = shushedWas;
                stopTest = stopWas;
                Commentary.Stage = stageWas;
                mainframe.Sync();
                mainframe.ShowSettings(pageWas);
                SavePreferences();
            }
        }

        // Switching her voice mid-chat keeps her ears on: each row under VOICE with Listen for Capri on, and an ElevenLabs call that
        // her voice leaves, which hands the mic to her own ears. A fake voice server answers every row, and a stand-in hears every line.
        private void VoiceSwitchChecks(string output, System.Collections.Generic.List<string> checks)
        {
            bool listenWas = preferences.ListenCapri, quietWas = preferences.Quiet, silentWas = preferences.Silent, servedWas = preferences.ServerVoice, freeChatWas = FreeChatOn;
            string urlWas = preferences.ServerUrl, apiWas = preferences.ServerApi, modelWas = preferences.ServerModel, speakerWas = preferences.ServerSpeaker, keyWas = preferences.ServerKey;
            string asideUrlWas = preferences.AsideUrl, asideApiWas = preferences.AsideApi, asideModelWas = preferences.AsideModel, asideSpeakerWas = preferences.AsideSpeaker, asideKeyWas = preferences.AsideKey;
            string cloudWas = preferences.CloudVoice, voiceKeyWas = voice.Key, transcriptWas = Brain.TranscriptPath;
            bool? ownWas = ownEarsTest;
            Func<string, string> thinkWas = Think;
            Func<string, byte[]> speakWas = Speak, freeSpeakWas = FreeSpeak;
            Func<short[], string> hearingWas = Hearing.Run;
            int switchCalls = 0;
            short[] switchTone = new short[YourVoice.Rate * 3 / 10];
            for (int toneAt = 0; toneAt < switchTone.Length; toneAt++) switchTone[toneAt] = (short)(Math.Sin(toneAt * 0.05) * 8000);
            byte[] switchWav = Voice.Wave(switchTone, YourVoice.Rate);
            System.Net.Sockets.TcpListener switchServer = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
            switchServer.Start();
            ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    while (true)
                    {
                        System.Net.Sockets.TcpClient switchClient = switchServer.AcceptTcpClient();
                        try
                        {
                            System.Net.Sockets.NetworkStream switchStream = switchClient.GetStream();
                            MemoryStream switchGot = new MemoryStream();
                            byte[] switchBuffer = new byte[65536];
                            while (true)
                            {
                                int switchRead = switchStream.Read(switchBuffer, 0, switchBuffer.Length);
                                if (switchRead <= 0) break;
                                switchGot.Write(switchBuffer, 0, switchRead);
                                string switchRequest = System.Text.Encoding.UTF8.GetString(switchGot.ToArray());
                                int switchEnd = switchRequest.IndexOf("\r\n\r\n", StringComparison.Ordinal);
                                if (switchEnd < 0) continue;
                                System.Text.RegularExpressions.Match switchLength = System.Text.RegularExpressions.Regex.Match(switchRequest, @"Content-Length:\s*(\d+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                                if (switchGot.Length >= switchEnd + 4 + (switchLength.Success ? int.Parse(switchLength.Groups[1].Value) : 0)) break;
                            }
                            byte[] switchHead = System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: " + switchWav.Length + "\r\nConnection: close\r\n\r\n");
                            switchStream.Write(switchHead, 0, switchHead.Length);
                            switchStream.Write(switchWav, 0, switchWav.Length);
                        }
                        catch (IOException) { }
                        finally { switchClient.Close(); }
                    }
                }
                catch (Exception) { }
            });
            int switchPort = ((IPEndPoint)switchServer.LocalEndpoint).Port;
            string switchA = "http://127.0.0.1:" + switchPort + "/a/v1", switchB = "http://127.0.0.1:" + switchPort + "/b/v1";
            Func<int, short[]> switchWave = delegate(int amplitude)
            {
                short[] waveSamples = new short[Ears.Chunk];
                for (int waveAt = 0; waveAt < waveSamples.Length; waveAt++) waveSamples[waveAt] = (short)(Math.Sin(waveAt * Math.PI / 40) * amplitude);
                return waveSamples;
            };
            Action<Func<bool>, int> switchPump = delegate(Func<bool> done, int limit)
            {
                Stopwatch switchWaited = Stopwatch.StartNew();
                while (!done() && switchWaited.ElapsedMilliseconds < limit) { Application.DoEvents(); Thread.Sleep(5); }
            };
            Func<string> switchState = delegate
            {
                return "chatting " + chatting + ", local " + local + ", ears ready " + earsReady + ", shut " + earsShut + ", transcribing " + transcribing + ", muted " + ears.Muted
                    + ", talk " + talkState + ", quiet " + preferences.Quiet + ", server " + preferences.ServerVoice + ", note " + mainframe.VoiceNoteText
                    + ", voice for " + (voiceUntil - clock.Elapsed.TotalSeconds).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + " s, busy " + speaker.Busy + ", name over " + nameOver
                    + ", ears on " + ears.Listening + ", hearing " + (hearingStatus == null ? "-" : hearingStatus.Text) + ", cloud " + preferences.CloudVoice + ", calls " + switchCalls
                    + ", windows speech " + (dictation != null) + ", noise hold " + noiseHold + ", room " + room.ToString("0.0000", System.Globalization.CultureInfo.InvariantCulture) + ", asking " + asking + ", chat ticket " + chatTicket;
            };
            // She says her check line through each new voice first, so each line waits for it to finish. On GitHub's runner the
            // line can start after the first 1.5 s, and talking over it is a different check. Her ears stay shut until the next
            // tick after her voice ends, so the line waits for that too.
            Action<string> switchHeard = delegate(string what)
            {
                switchPump(delegate { return false; }, 1500);
                switchPump(delegate { return talkState != TalkState.Thinking && !StillSaying && !earsShut; }, 6000);
                bool shutAtLine = earsShut;
                int before = switchCalls;
                for (int lineAt = 0; lineAt < 4; lineAt++) Gather(switchWave(0));
                for (int lineAt = 0; lineAt < 8; lineAt++) Gather(switchWave(lineAt % 2 == 0 ? 14000 : 20000));
                for (int lineAt = 0; lineAt < 12; lineAt++) Gather(switchWave(0));
                switchPump(delegate { return switchCalls > before; }, 5000);
                if (switchCalls == before) throw new Exception("Her ears stopped hearing after " + what + ": shut at the line " + shutAtLine + ", " + switchState());
            };
            try
            {
                StopChat();
                CloseTalk();
                job = null;
                working = null;
                Brain.TranscriptPath = Path.Combine(output, "voice-switch");
                Directory.CreateDirectory(Brain.TranscriptPath);
                preferences.ListenCapri = true;
                preferences.Silent = false;
                FreeChatOn = true;
                ownEarsTest = true;
                voice.Key = "sk_test_capri_switch";
                Speak = delegate { return switchWav; };
                FreeSpeak = delegate { return switchWav; };
                Think = delegate { Interlocked.Increment(ref switchCalls); return "Yeah, choom."; };
                Hearing.Run = delegate { return "capri can you hear me"; };
                UseVoiceServer(switchA, "kokoro", "af_heart", null, VoiceServer.OpenAi);
                switchPump(delegate { return false; }, 1500);
                CloseTalk();
                ToggleChat();
                switchHeard("opening");
                UseVoiceServer(switchB, "kokoro", "af_bella", null, VoiceServer.OpenAi);
                switchHeard("another voice server");
                mainframe.PickVoice(true);
                switchHeard("ElevenLabs");
                UseSavedServer(false);
                switchHeard("ElevenLabs back to the saved server");
                mainframe.PickVoice(true);
                switchPump(delegate { return false; }, 1500);
                UsePrebuilt();
                if (!chatting || !local || !earsReady) throw new Exception("ElevenLabs to her own voices shut Listen for Capri's ears: " + switchState());
                switchHeard("ElevenLabs to her own voices");
                checks.Add("PASS switching her voice with Listen for Capri on keeps her ears open: another voice server, ElevenLabs, back to the saved server, and ElevenLabs to her own voices each still hear the next line");

                StopChat();
                CloseTalk();
                preferences.ListenCapri = false;
                mainframe.PickVoice(true);
                switchPump(delegate { return false; }, 1500);
                CloseTalk();
                chatting = true;
                local = false;
                agent = new Agent();
                UseVoiceServer(switchA, "kokoro", "af_heart", null, VoiceServer.OpenAi);
                if (!chatting || !local || agent != null) throw new Exception("Switching to a voice server mid-call left the ElevenLabs call open: " + switchState());
                switchHeard("a voice server mid-call");
                StopChat();
                CloseTalk();
                mainframe.PickVoice(true);
                switchPump(delegate { return false; }, 1500);
                CloseTalk();
                chatting = true;
                local = false;
                agent = new Agent();
                UsePrebuilt();
                if (!chatting || !local || agent != null) throw new Exception("Switching to her own voices mid-call didn't hand the mic to her ears: " + switchState());
                switchHeard("her own voices mid-call");
                checks.Add("PASS switching her voice off ElevenLabs mid-call hands the mic to her own ears, which hear the next line, for a voice server and her own voices");

                transcribing = true;
                transcribingAt = Environment.TickCount - 31000;
                CheckHearing(clock.Elapsed.TotalSeconds);
                bool released = !transcribing;
                double reopenAt = clock.Elapsed.TotalSeconds;
                micReopened = -100;
                ReopenMic(reopenAt);
                bool firstQuiet = mainframe.VoiceNoteText != MicStopped;
                ReopenMic(reopenAt + 10);
                if (!released || !firstQuiet || mainframe.VoiceNoteText != MicStopped) throw new Exception("A stuck line or a mic that cut out twice went unhandled: released " + released + ", first quiet " + firstQuiet + ", note " + mainframe.VoiceNoteText);
                checks.Add("PASS a line her ears never hand back is let go after 30 s, and a mic that cuts out twice in a minute is reopened and said");
                checks.Add("LIMIT a real mic that stops sending and real speech through each voice need a live check");
            }
            finally
            {
                StopChat();
                CloseTalk();
                switchServer.Stop();
                micReopened = -100;
                preferences.ListenCapri = listenWas;
                preferences.Quiet = quietWas;
                preferences.Silent = silentWas;
                preferences.ServerVoice = servedWas;
                preferences.ServerUrl = urlWas;
                preferences.ServerApi = apiWas;
                preferences.ServerModel = modelWas;
                preferences.ServerSpeaker = speakerWas;
                preferences.ServerKey = keyWas;
                preferences.AsideUrl = asideUrlWas;
                preferences.AsideApi = asideApiWas;
                preferences.AsideModel = asideModelWas;
                preferences.AsideSpeaker = asideSpeakerWas;
                preferences.AsideKey = asideKeyWas;
                preferences.CloudVoice = cloudWas;
                LoadServer();
                FreeChatOn = freeChatWas;
                ownEarsTest = ownWas;
                voice.Key = voiceKeyWas;
                Think = thinkWas;
                Speak = speakWas;
                FreeSpeak = freeSpeakWas;
                Hearing.Run = hearingWas;
                Brain.TranscriptPath = transcriptWas;
                mainframe.Sync();
                ShowVoice();
                SavePreferences();
            }
        }

        internal void TalkChecks(System.Collections.Generic.List<string> checks)
        {
            Action<bool, string> must = delegate(bool fine, string what) { if (!fine) throw new Exception(what); };
            Action<Func<bool>> waitFor = delegate(Func<bool> done)
            {
                Stopwatch waited = Stopwatch.StartNew();
                while (!done() && waited.ElapsedMilliseconds < 4000) { Application.DoEvents(); Thread.Sleep(5); }
            };
            Action<int> settle = delegate(int milliseconds)
            {
                Stopwatch waited = Stopwatch.StartNew();
                while (waited.ElapsedMilliseconds < milliseconds) { Application.DoEvents(); Thread.Sleep(5); }
            };
            Func<int, int, short[]> wave = delegate(int length, int loudness)
            {
                short[] samples = new short[length];
                for (int i = 0; i < length; i++) samples[i] = (short)(Math.Sin(i * 0.12) * loudness);
                return samples;
            };
            Func<string, AsideKind?> kindOf = delegate(string words)
            {
                string tool;
                ToolArguments toolArgs;
                return Asides.Plain(words, out tool, out toolArgs);
            };

            foreach (string stopping in new[] { "stop", "Stop!", "stop it", "wait stop", "no stop", "okay stop now", "cancel that", "never mind", "forget it", "leave it", "that's enough", "para", "stopp" })
                must(kindOf(stopping) == AsideKind.Stop, "\"" + stopping + "\" didn't stop her job: " + kindOf(stopping));
            foreach (string question in new[] { "what are you doing", "how's it going?", "how long", "how much longer", "are you done yet", "you stuck?", "what step are you on", "how far along are you", "any progress" })
                must(kindOf(question) == AsideKind.Status, "\"" + question + "\" wasn't answered from her steps: " + kindOf(question));
            foreach (string looking in new[] { "what do you see", "what's on the screen" })
                must(kindOf(looking) == AsideKind.Screen, "\"" + looking + "\" wasn't a screen question: " + kindOf(looking));
            foreach (string other in new[] { "don't stop the music", "stop by the shop on the way", "tell me a joke", "make it blue", "i love you" })
                must(kindOf(other) != AsideKind.Stop && kindOf(other) != AsideKind.Status, "\"" + other + "\" was taken for a stop or a status question: " + kindOf(other));
            must(Asides.Guess("actually use firefox instead") == AsideKind.Change && Asides.Guess("lol that's hilarious") == AsideKind.Chat && Asides.Guess("why is the sky blue?") == AsideKind.Chat && Asides.Guess("attach the pdf as well") == AsideKind.Add,
                "Her guess with no brain went wrong: " + Asides.Guess("actually use firefox instead") + " " + Asides.Guess("lol that's hilarious") + " " + Asides.Guess("why is the sky blue?") + " " + Asides.Guess("attach the pdf as well"));
            string headLine;
            must(Asides.Read("SORT: CHANGE\nSAY: Fine, your way.", out headLine) == AsideKind.Change && headLine == "Fine, your way.", "Her fast head's reply wasn't read: " + headLine);
            must(Asides.Read("SAY: Adding it.\nSORT: add", out headLine) == AsideKind.Add && headLine == "Adding it.", "Her fast head's reply the other way round wasn't read: " + headLine);
            must(Asides.Read("**SORT:** STOP **SAY:** Dropped.", out headLine) == AsideKind.Stop && headLine == "Dropped.", "Her fast head's bold reply wasn't read: " + headLine);
            must(Asides.Read("haha you wish", out headLine) == AsideKind.Chat && headLine == "haha you wish", "A reply with no labels wasn't taken as chat: " + headLine);
            checks.Add("PASS mid-job sorting: stops, status and screen questions are told apart with no brain, a guess covers a brain that's down, and her fast head's SORT and SAY reply is read in either order");

            foreach (string[] set in new[] { Lines.OnIt, Lines.GotIt, Lines.Changed, Lines.Stopped, Lines.Busy })
            {
                string last = null;
                System.Collections.Generic.HashSet<string> drawn = new System.Collections.Generic.HashSet<string>();
                for (int draw = 0; draw < 400; draw++)
                {
                    string picked = Lines.Pick(set);
                    must(picked != last, "The same fixed line twice in a row: " + picked);
                    last = picked;
                    drawn.Add(picked);
                }
                must(drawn.Count == set.Length, "A fixed line never came up: " + drawn.Count + " of " + set.Length);
            }
            foreach (string start in Lines.OnIt) must(start.IndexOf("Esc", StringComparison.Ordinal) >= 0, "A job start line doesn't say how to stop her: " + start);
            checks.Add("PASS her fixed lines: every set draws all its lines, never the same one twice in a row, and every job start line still says Esc stops her");

            string[] noneBefore = new string[0];
            must(Brain.Unclosed("That's a bold plan. What's next?") == "That's a bold plan." && Brain.Unclosed("Creeper got you. Wanna stir up some trouble?") == "Creeper got you." && Brain.Unclosed("What kind of chaos are we in for?") == "What kind of chaos are we in for?" && Brain.Unclosed("You found diamonds? Where?") == "You found diamonds? Where?", "Her stock closers weren't cut cleanly: " + Brain.Unclosed("That's a bold plan. What's next?"));
            must(Brain.Fresh("Bored? Seriously? I've counted your desktop icons twice.", "i'm bored", noneBefore) == "I've counted your desktop icons twice.", "Their word said back wasn't cut: " + Brain.Fresh("Bored? Seriously? I've counted your desktop icons twice.", "i'm bored", noneBefore));
            must(Brain.Fresh("Iron, huh? That's a start at least.", "found iron this time", noneBefore) == "That's a start at least.", "Their word said back with a huh wasn't cut.");
            must(Brain.Fresh("Who's Jake? Never heard of him.", "tell jake hi", noneBefore) == "Who's Jake? Never heard of him." && Brain.Fresh("Diamonds? Yes.", "i found diamonds", noneBefore) == "Diamonds? Yes.", "A real question, or a line with too little left, was cut.");
            must(Brain.Fresh("Whoa, that boss never stood a chance.", "i won", new[] { "Whoa, nice shot there.", "Okay." }) == "That boss never stood a chance." && Brain.Fresh("Whoa, that boss never stood a chance.", "i won", new[] { "Okay then, go on." }) == "Whoa, that boss never stood a chance.", "Her opener wasn't cut only when she'd just used it.");
            Func<string, string> hashed = delegate(string text) { using (System.Security.Cryptography.SHA256 sha = System.Security.Cryptography.SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(new System.Text.UTF8Encoding(false).GetBytes(text))).Replace("-", "").ToLowerInvariant(); };
            must(hashed(Brain.Safety) == "5ba8ebf47c1bc3803515bd3145631cdf4e401a75bd3e1e96a34a50b2bc2c7198", "Her safety lines changed: " + hashed(Brain.Safety));
            must(Brain.Persona.IndexOf("Your initiative is balanced", StringComparison.Ordinal) >= 0 && Brain.Persona.IndexOf("Usually let the user lead", StringComparison.Ordinal) >= 0 && Brain.Persona.IndexOf("Do not force every reply into a question", StringComparison.Ordinal) >= 0 && Brain.Persona.IndexOf("Never invent names, messages, screen contents", StringComparison.Ordinal) >= 0 && Hands.Chat.IndexOf("Their Memory setting controls persistent notes", StringComparison.Ordinal) >= 0, "Azure's conversation rules lost balanced initiative, truthful replies or controlled-memory guidance.");
            must(Agent.Version >= 21 && Agent.Prompt.IndexOf("When your hands are on a job", StringComparison.Ordinal) > 0 && Agent.Prompt.StartsWith(Brain.Persona, StringComparison.Ordinal), "Voice chat's agent wasn't retuned for talking mid-job.");
            checks.Add("PASS how Azure talks: her prompt preserves balanced initiative, natural phrasing and truthful replies; voice chat's agent is retuned, and fixed safety lines remain unchanged to the byte");

            Job jobWas = job;
            string workingWas = working;
            Cloud remoteWas = brain.Remote;
            string modelWas = brain.Model;
            int headWaitWas = HeadWait;
            Func<int, bool> keyHeldWas = KeyHeld;
            Func<short[], string> hearingWas = Hearing.Run;
            Func<Sight> glimpseWas = Computer.Glimpse;
            Func<bool> fullWas = FullScreen;
            Func<Sight> lookWas = Computer.Look;
            Func<IntPtr> frontWas = Computer.Front;
            Func<Rectangle?, Picture> shootWas = Computer.Shoot;
            Func<string, ToolArguments, Picture, string> useWas = Computer.Use;
            Func<string, ToolArguments, Sight, string> actWas = Computer.Act;
            int pushVkWas = preferences.PushVk, pushModsWas = preferences.PushMods;
            bool localWas = local, earsWas = earsReady;
            bool hiddenWas = hidden, napWas = napping, napAskedWas = napAsked, shushWas = shushed, mutedWas = ears.Muted;
            hidden = napping = napAsked = shushed = false;
            ears.Muted = false;
            mainframe.CancelKeys();
            IGameStage stageWas = Commentary.Stage;
            Func<string> gameWas = Commentary.Game;
            Func<bool> freeWas = Commentary.Free;
            Func<bool> seesWas = Commentary.Sees;
            Func<string, string, byte[][], string> seeWas = Commentary.See;
            Action<string, string, GameMood> speakWas = Commentary.Speak;
            Func<byte[]> shotWas = Commentary.Shot;
            Func<int> clockWas = Commentary.Clock;
            int paceWas = Commentary.Pace, lateWas = Commentary.Late;
            GameLog logWas = Commentary.Log;
            Func<bool> reactionsWas = Reactions.On;
            string anthropicWas = Brain.Anthropic;
            string logFile = Path.Combine(Path.GetTempPath(), "capri-talk-check-" + Guid.NewGuid().ToString("N") + ".log");
            System.Net.Sockets.TcpListener fastFake = null;
