                    logged("[10:01:00] [Server thread/INFO]: Steve_99 was slain by Zombie\n[10:01:00] [Render thread/INFO]: [System] [CHAT] Steve_99 was slain by Zombie\n");
                    System.Collections.Generic.List<GameEvent> found = tail.Read();
